        "Flash Theme to iPhone": "Flash Tema ke iPhone",
        "Flashing Theme…": "Mem-flash Tema…",
        "Flashing needs a pairing file and the VPN tunnel. Pair first and connect the VPN in Sandbox → Utilities → Get Pairing File + VPN Status, then come back here.": "Flashing membutuhkan pairing file dan tunnel VPN. Pair dulu dan hubungkan VPN di Sandbox → Utilities → Get Pairing File + VPN Status, lalu kembali ke sini.",
        "Flashing needs a pairing file. Pair this iPhone first in Sandbox → Utilities → Get Pairing File.": "Flashing membutuhkan pairing file. Pair iPhone ini dulu di Sandbox → Utilities → Get Pairing File.",
        "Flashing needs the VPN tunnel. Open the Local Dev VPN app and connect first.": "Flashing membutuhkan tunnel VPN. Buka aplikasi Local Dev VPN dan hubungkan dulu.",
        "Flashing…": "Mem-flash…",
        "Folder name": "Nama folder",
        "Follow for updates, demos and new tweaks.": "Ikuti untuk update, demo, dan tweak baru.",
        "Font Weight / Style": "Ketebalan / Gaya Font",
        "Footnote": "Footnote",
        "Footnote Updated": "Footnote Diperbarui",
        "Footnote text": "Teks footnote",
        "For AppGroup scope, the target is the App Group identifier (for example group.com.example) — type it here.": "Untuk scope AppGroup, targetnya adalah pengenal App Group (contoh group.com.example) — ketik di sini.",
        "Force-close the Wallet app from the App Switcher after flashing to see the new card art.": "Tutup paksa aplikasi Wallet dari App Switcher setelah flashing untuk melihat artwork kartu baru.",
        "Forces the label shown (5G, 5G+, 5G UC, LTE, …). Limited — the label is display-only.": "Memaksa label yang ditampilkan (5G, 5G+, 5G UC, LTE, …). Terbatas — label hanya tampilan.",
        "Free Apple ID installs expire after about 7 days — reinstall with iLoader to renew.": "Instalasi Apple ID gratis kedaluwarsa setelah sekitar 7 hari — instal ulang dengan iLoader untuk memperbarui.",
        "Freed %@": "Dibebaskan %@",
        "Genuine MDM": "MDM Asli",
        "Get Pairing + VPN Tunnel": "Dapatkan Pairing + Tunnel VPN",
        "Get Pairing File": "Dapatkan Pairing File",
        "Get Pairing File + Local Dev VPN tunnel — the on-device pairing Airlift uses to reach the device.": "Get Pairing File + tunnel Local Dev VPN — pairing di perangkat yang dipakai Airlift untuk menjangkau perangkat.",
        "Get Pairing File + VPN Status": "Ambil File Pairing + Status VPN",
        "Get Started": "Mulai",
        "Go to Sandbox Tab": "Buka Tab Sandbox",
        "Go to the Apply/Revert section and tap Apply, then Respring. When the respring finishes, restart your iPhone.": "Buka bagian Apply/Revert lalu ketuk Apply, kemudian Respring. Setelah respring selesai, restart iPhone Anda.",
        "Go to the Sandbox tab and turn on Start Tweaks Feature to unlock the Tweaks tab.": "Buka tab Sandbox dan aktifkan Start Tweaks Feature untuk membuka kunci tab Tweaks.",
