        "Idle": "Idle",
        "If iOS asks, enable Developer Mode (Settings → Privacy & Security → Developer Mode) and trust the developer profile.": "Jika iOS meminta, aktifkan Developer Mode (Settings → Privacy & Security → Developer Mode) dan percayai profil pengembang.",
        "If you update or downgrade to a supported build, WorkTweaks will open normally.": "Jika Anda update atau downgrade ke build yang didukung, WorkTweaks akan terbuka normal.",
