        "Lock Screen Preview": "Pratinjau Lock Screen",
        "Locked folders are read-only (0555) with a sentinel file inside; config files are emptied and locked (0444). A Weak Lock is a locked folder missing its sentinel — tap Harden to add it.": "Folder yang terkunci bersifat hanya-baca (0555) dengan file sentinel di dalamnya; file konfigurasi dikosongkan dan dikunci (0444). Weak Lock adalah folder terkunci yang kehilangan sentinel-nya — ketuk Harden untuk menambahkannya.",
        "Locks every target below that still needs action. Whitelisted targets are always skipped.": "Mengunci semua target di bawah yang masih perlu tindakan. Target yang di-whitelist selalu dilewati.",
