        "Never share your certificate .p12 file with anyone — it contains your private signing key.": "Jangan pernah membagikan file sertifikat .p12 Anda kepada siapa pun — file itu berisi private signing key Anda.",
        "New Package": "Paket Baru",
        "New Row": "Baris Baru",
