        "Package Builder": "Package Builder",
        "Package Format": "Format Paket",
        "Packages you build or import are stored on this device, in WorkTweaks' own container. Tap a package to edit it. Deploy runs it through the same preview, resolve and backup flow as a picked package.": "Paket yang Anda buat atau impor disimpan di perangkat ini, di container WorkTweaks sendiri. Ketuk paket untuk mengeditnya. Deploy menjalankannya melalui alur pratinjau, resolve, dan cadangan yang sama seperti paket yang dipilih.",
        "Pair This iPhone": "Pair iPhone Ini",
        "Pairing & Airlift": "Pairing & Airlift",
