        "Read": "Baca",
        "Read Powerlog": "Baca Powerlog",
        "Read complete%@%@.": "Pembacaan selesai%@%@.",
        "Read-only mode — the grant did not include write access, so Clean All is disabled.": "Mode hanya-baca — grant tidak menyertakan akses tulis, jadi Clean All dinonaktifkan.",
        "Read-only: the powerlog is cloned into this app's temp folder and inspected there. Nothing is ever written to the system database. Some iOS 26 firmware restricts the powerlog sandbox token; iOS 27 reads fully.": "Hanya-baca: powerlog di-clone ke folder temp aplikasi ini dan diperiksa di sana. Tidak ada yang pernah ditulis ke database sistem. Beberapa firmware iOS 26 membatasi token sandbox powerlog; iOS 27 membaca penuh.",
        "Reading the configuration profiles…": "Membaca configuration profile…",
