        "Reading the recordings database…": "Membaca database rekaman…",
        "Reading video frames…": "Membaca frame video…",
        "Reading…": "Membaca…",
        "Rebooting now might cause a bootloop. Try pressing 'Revert Tweaks'.": "Reboot sekarang dapat menyebabkan bootloop. Coba tekan 'Kembalikan Tweaks'.",
        "Recent Requests": "Permintaan Terbaru",
