        "Resolving the target container…": "Menentukan container target…",
        "Respring": "Respring",
        "Respring did not trigger on this device.": "Respring tidak berjalan di perangkat ini.",
        "Restart Device": "Restart Perangkat",
        "Restart Required": "Perlu Restart",
        "Restore": "Pulihkan",
        "Restore (%d)": "Pulihkan (%d)",
        "Restore Backup": "Pulihkan Cadangan",
        "Restore Everything": "Pulihkan Semua",
        "Restore Result — %d succeeded, %d failed": "Hasil Pemulihan — %d berhasil, %d gagal",
        "Restore a ZIP backup": "Pulihkan cadangan ZIP",
        "Restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "Perubahan pemulihan hanya berlaku setelah perangkat dimulai ulang sepenuhnya — respring saja tidak cukup. Memilih Nanti hanya menundanya; perubahan tetap tertunda sampai Anda me-restart.",
        "Restore into…": "Pulihkan ke…",
        "Restore swaps the staged copy into the app's current container and rolls back if anything fails. Release a snapshot only after you verified the restore in the app.": "Restore menukar salinan yang di-stage ke container aplikasi saat ini dan rollback jika ada yang gagal. Release snapshot hanya setelah kamu memverifikasi restore di aplikasi.",
        "Restore the backup?": "Pulihkan cadangannya?",
        "Restore this entire backup?": "Pulihkan seluruh cadangan ini?",
        "Restoring ZIP…": "Memulihkan ZIP…",
        "Restoring the backup failed — the details are in the Log.": "Gagal memulihkan cadangan — detailnya ada di Log.",
        "Restoring writes each backed-up file back in place. Files the deploy created (they did not exist before) are deleted again.": "Pemulihan menulis setiap file cadangan kembali ke tempatnya. File yang dibuat oleh deploy (sebelumnya tidak ada) dihapus lagi.",
        "Restoring…": "Memulihkan…",
        "Result — %d succeeded, %d failed": "Hasil — %d berhasil, %d gagal",
        "Retry Flash": "Coba Flash Lagi",
        "Retry Flash Theme": "Coba Flash Tema Lagi",
        "Revert": "Kembalikan",
        "Revert Tweaks": "Kembalikan Tweaks",
        "Revert all tweaks?": "Kembalikan semua tweak?",
        "Revert and restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "Perubahan revert dan restore hanya berlaku setelah restart perangkat penuh — respring saja tidak cukup. Memilih Nanti hanya menundanya; perubahan tetap tertunda sampai Anda restart.",
        "Rewrites the entire MobileGestalt.plist from this backup. A device restart is required after restoring.": "Menulis ulang seluruh MobileGestalt.plist dari cadangan ini. Perangkat harus dimulai ulang setelah pemulihan.",
        "Running": "Berjalan",
        "Sampled": "Diambil sampel",
        "Sandbox access denied": "Akses Sandbox ditolak",
        "Sandbox extension is ready (directory grant held).": "Ekstensi sandbox sudah siap (izin direktori dipegang).",
        "Save": "Simpan",
        "Save .passthm": "Simpan .passthm",
        "Save App Group ID": "Simpan ID App Group",
        "Save Vault": "Save Vault",
        "Saved": "Tersimpan",
        "Saved %d of %d to BackUP_Data.": "%d dari %d tersimpan ke BackUP_Data.",
        "Saved: %@": "Disimpan: %@",
        "Saves the package, then shares ONE .zip file — save it in Files. Deploy imports that zip and applies it without asking for locations.": "Menyimpan paket, lalu membagikan SATU file .zip — simpan di Files. Deploy mengimpor zip itu dan menerapkannya tanpa menanyakan lokasi.",
        "Saving %d of %d (%d%%)": "Menyimpan %d dari %d (%d%%)",
        "Saving applies the edits to the database through SQLite, takes a backup of the original first, then writes the edited file back in place. Close the owning app before saving — a running app can overwrite your edits.": "Menyimpan menerapkan edit ke database lewat SQLite, mengambil cadangan dari file asli dulu, lalu menulis file yang diedit kembali ke tempatnya. Tutup aplikasi pemiliknya sebelum menyimpan — aplikasi yang berjalan bisa menimpa edit kamu.",
        "Saving rebuilds the property list from this table, takes a backup of the original first, then writes it back in place. Close the owning app before saving — a running app can overwrite your edits.": "Menyimpan membangun ulang property list dari tabel ini, mengambil cadangan dari file asli dulu, lalu menulisnya kembali ke tempatnya. Tutup aplikasi pemiliknya sebelum menyimpan — aplikasi yang berjalan bisa menimpa edit kamu.",
        "Saving writes the file in place and verifies the result by re-reading it.": "Menyimpan akan menulis file di tempatnya dan memverifikasi hasilnya dengan membacanya kembali.",
        "Saving writes the file in place, under the container's sandbox extension.": "Menyimpan akan menulis file di tempatnya, di bawah ekstensi sandbox container.",
        "Saving…": "Menyimpan…",
        "Scan": "Pindai",
        "Scan Cards": "Pindai Kartu",
        "Scan for Ad Targets": "Pindai Target Iklan",
        "Scanning %@…": "Memindai %@…",
        "Scanning…": "Memindai…",
        "Scope": "Scope",
        "Search": "Cari",
        "Search tweaks": "Cari tweak",
        "Secondary bars: %d": "Bar sekunder: %d",
        "Secondary carrier name (max 64)": "Nama operator sekunder (maks 64)",
        "Secondary network type": "Jenis jaringan sekunder",
        "Sections": "Bagian",
        "Select All": "Pilih Semua",
        "Select None": "Pilih Tidak Ada",
        "Select at least one card and attach a skin image to it before flashing.": "Pilih setidaknya satu kartu dan lampirkan gambar skin sebelum flashing.",
        "Selected app": "Aplikasi terpilih",
        "Server": "Server",
        "Set NULL": "Set NULL",
        "Set Skin": "Atur Skin",
        "Set Skin for All Cards…": "Atur Skin untuk Semua Kartu…",
        "Set the Spoofing picker (under Apple Intelligence) to iPhone 17 Pro (iPhone18,1).": "Atur pemilih Spoofing (di bawah Apple Intelligence) ke iPhone 17 Pro (iPhone18,1).",
        "Sets how many bars are drawn. Static — it does not follow the real signal.": "Mengatur berapa banyak bar yang digambar. Statis — tidak mengikuti sinyal sebenarnya.",
        "Share %@": "Bagikan %@",
        "Share Contents": "Bagikan Isi",
        "Share Full Report": "Bagikan Laporan Lengkap",
        "Showing the first %@ of %@ rows — the editor is for targeted edits, not bulk dumps.": "Menampilkan %@ baris pertama dari %@ baris — editor ini untuk edit yang ditargetkan, bukan dump massal.",
        "Shows the battery percentage in the status bar. Key: SBShowBatteryPercentage in com.apple.springboard.plist.": "Menampilkan persentase baterai di status bar. Key: SBShowBatteryPercentage di com.apple.springboard.plist.",
        "Sign In": "Masuk",
        "Signal Bars": "Bar Sinyal",
        "Signal bars (Primary)": "Bar sinyal (Utama)",
        "Signal bars (Secondary)": "Bar sinyal (Sekunder)",
        "Single-file shorthand: instead of \"files\", give \"relativePath\" and \"file\". \"scope\" is Application (bundleID = the app's bundle ID), AppGroup (bundleID = the group identifier, e.g. group.com.example) or InternalDaemon. ZIP archives may use stored or deflated entries; encrypted and ZIP64 archives are not supported. Older .deploy archives and plain folders still import.": "Singkatan satu file: sebagai ganti \"files\", berikan \"relativePath\" dan \"file\". \"scope\" adalah Application (bundleID = bundle ID aplikasi), AppGroup (bundleID = pengenal grup, contoh group.com.example) atau InternalDaemon. Arsip ZIP boleh memakai entri stored atau deflated; arsip terenkripsi dan ZIP64 tidak didukung. Arsip .deploy lama dan folder biasa masih bisa diimpor.",
        "Size": "Ukuran",
        "Sizes are measured by walking each folder. An app recreates cache as it runs, so the size grows back over time.": "Ukuran diukur dengan menelusuri setiap folder. Aplikasi membuat ulang cache saat berjalan, jadi ukurannya akan membesar lagi seiring waktu.",
        "Sizes are probed read-only (depth 4). Delete Cache removes only files under Library/Caches inside these targets — the AI models live elsewhere and are never touched.": "Ukuran diperiksa hanya-baca (kedalaman 4). Delete Cache hanya menghapus file di bawah Library/Caches di dalam target ini — model AI berada di tempat lain dan tidak pernah disentuh.",
        "Snapshots": "Snapshot",
        "Software-Oriented Features": "Fitur Berorientasi Perangkat Lunak",
        "Some tweaks — especially Apple Intelligence — only take effect after a full restart, not a respring.": "Beberapa tweak — terutama Apple Intelligence — hanya berlaku setelah restart penuh, bukan respring.",
        "Something went wrong": "Terjadi kesalahan",
        "Sound Effects": "Efek Suara",
        "Splash Ad Cache Lock": "Splash Ad Cache Lock",
        "Splash Ad Cache Lock finds the folders ad SDKs use to cache splash (launch) ads, empties them, and locks them read-only so the app cannot rebuild its splash-ad cache. Locks apply only to third-party app folders — never to system folders, Documents, or the app itself.": "Splash Ad Cache Lock menemukan folder yang dipakai SDK iklan untuk menyimpan cache iklan splash (peluncuran), mengosongkannya, dan menguncinya hanya-baca agar aplikasi tidak bisa membangun ulang cache iklan splash-nya. Kunci hanya berlaku untuk folder aplikasi pihak ketiga — tidak pernah untuk folder sistem, Documents, atau aplikasi itu sendiri.",
        "Spoofing": "Spoofing",
        "SpringBoard loads the wallpaper store when it starts — respring or restart to see the change in the wallpaper gallery.": "SpringBoard memuat wallpaper store saat dimulai — respring atau restart untuk melihat perubahan di galeri wallpaper.",
        "SpringBoard reads the footnote when it starts — respring or restart to see it on the Lock Screen.": "SpringBoard membaca footnote saat dimulai — respring atau restart untuk melihatnya di Lock Screen.",
        "Stage an app's Documents, Library/Preferences and Library/Application Support (never Caches) before its 7-day certificate expires. After reinstall, the data is restored into the app's new container — matched by bundle id, not the old container UUID.": "Stage Documents, Library/Preferences, dan Library/Application Support sebuah aplikasi (tidak pernah Caches) sebelum sertifikat 7 harinya kedaluwarsa. Setelah instal ulang, data dipulihkan ke container baru aplikasi — dicocokkan berdasarkan bundle id, bukan UUID container lama.",
        "Stage copies into the APFS vault (no extra space). ZIP backup copies first, then zips — for very large apps use the APFS vault. Both refuse while the app is still writing its database.": "Stage menyalin ke APFS vault (tanpa ruang ekstra). Cadangan ZIP menyalin dulu, lalu di-zip — untuk aplikasi yang sangat besar gunakan APFS vault. Keduanya menolak saat aplikasi masih menulis database-nya.",
        "Stage into APFS Vault": "Stage ke APFS Vault",
        "Staged %@: %d file(s), %@. Verified against the source.": "Di-stage %@: %d file, %@. Terverifikasi terhadap sumber.",
        "Staged snapshots": "Snapshot yang di-stage",
        "Staging…": "Men-stage…",
        "Start Server": "Nyalakan Server",
        "Start Tweaks Feature": "Mulai Fitur Tweaks",
        "Start the server to get its address.": "Nyalakan server untuk mendapatkan alamatnya.",
        "Still writing (%d active WAL file(s)) — close the app first": "Masih menulis (%d file WAL aktif) — tutup aplikasi dulu",
        "Stop Scan": "Berhenti Memindai",
        "Stop Server": "Hentikan Server",
        "Stopped": "Berhenti",
        "Stored as text.": "Disimpan sebagai teks.",
        "Subtype": "Subtype",
        "Supervision": "Supervisi",
        "Support": "Dukungan",
        "Supported": "Didukung",
        "Supported iOS Versions": "Versi iOS yang Didukung",
        "Supported iOS • %@": "Dukungan iOS • %@",
        "Swift implementation of the respring web view (via mond / jailbreak.party).": "Implementasi Swift dari respring web view (via mond / jailbreak.party).",
        "System": "Sistem",
        "System Caches": "Cache Sistem",
        "System Language": "Bahasa Sistem",
        "Table": "Tabel",
        "Tap Read Powerlog to load the latest battery samples.": "Ketuk Baca Powerlog untuk memuat sampel baterai terbaru.",
        "Tap Refresh to list the diagnostic reports.": "Ketuk Refresh untuk menampilkan laporan diagnostik.",
        "Tap a key to assign a custom image.": "Ketuk key untuk menetapkan gambar kustom.",
        "Target": "Target",
        "Target Path": "Path Target",
        "Target container": "Container target",
        "That file is not a pairing file.": "File itu bukan pairing file.",
        "The App Data scan is still running — ad targets appear once it finishes.": "Pemindaian App Data masih berjalan — target iklan muncul setelah selesai.",
        "The CacheExtra key knowledge — the tweak-key research the WorkTweaks tweak catalog is built on.": "Pengetahuan key CacheExtra — riset tweak-key yang menjadi dasar katalog tweak WorkTweaks.",
        "The Voice Memos container is found through the App Data scan.": "Container Voice Memos ditemukan lewat pemindaian App Data.",
        "The ZIP must be a Save Vault backup (it carries a BackupManifest.plist). Files merge in place; system bundle ids are blocked.": "ZIP harus berupa cadangan Save Vault (memuat BackupManifest.plist). File digabungkan di tempat; bundle id sistem diblokir.",
        "The backup of the original file couldn't be written, so nothing was saved.": "Cadangan file asli tidak dapat ditulis, jadi tidak ada yang disimpan.",
        "The browser asks for these credentials once, then remembers them for the session.": "Browser meminta kredensial ini sekali, lalu mengingatnya selama sesi.",
        "The bundle ID is not a valid identifier.": "Bundle ID bukan pengenal yang valid.",
        "The bundle ID of the one app this package may touch. Pick it from the App Data container scan, or type it.": "Bundle ID dari satu aplikasi yang boleh disentuh paket ini. Pilih dari pemindaian container Data Aplikasi, atau ketik sendiri.",
        "The container scan found no containers.": "Pemindaian container tidak menemukan container.",
        "The container scan is shared with App Data and runs once per app session.": "Pemindaian container dibagikan dengan App Data dan hanya berjalan sekali per sesi aplikasi.",
        "The container scan runs once per session.": "Pemindaian container hanya berjalan sekali per sesi.",
        "The core system: the sandbox escape and MobileGestalt access this whole app is built on.": "Sistem inti: sandbox escape dan akses MobileGestalt yang menjadi dasar seluruh aplikasi ini.",
        "The current MobileGestalt will be entirely replaced with this %@ backup.": "MobileGestalt saat ini akan sepenuhnya diganti dengan cadangan %@ ini.",
        "The current file is overwritten in place with the backup taken before the first byte edit.": "File saat ini ditimpa di tempatnya dengan cadangan yang dibuat sebelum edit byte pertama.",
        "The developer's GitHub profile.": "Profil GitHub pengembang.",
        "The directory is empty.": "Direktori kosong.",
        "The entry is removed from the property list on the next Save.": "Entri dihapus dari property list pada Save berikutnya.",
        "The file couldn't be read under the container's sandbox extension — the details are in the Log. Nothing was written to it.": "File tidak dapat dibaca di bawah ekstensi sandbox container — detailnya ada di Log. Tidak ada yang ditulis ke file ini.",
        "The file-based CacheData pattern method used by Enable iPadOS Mode (MobileGestaltCacheDataTweak).": "Metode pola CacheData berbasis file yang digunakan oleh Enable iPadOS Mode (MobileGestaltCacheDataTweak).",
        "The original identifiers are already registered to another developer account, which is why the Team ID suffix is required.": "Identifier asli sudah terdaftar di akun pengembang lain, itulah sebabnya suffix Team ID diperlukan.",
        "The package could not be exported.": "Paket tidak dapat diekspor.",
        "The package store is unavailable (the App Group container did not resolve).": "Penyimpanan paket tidak tersedia (container App Group tidak dapat di-resolve).",
        "The pairing file + Local Dev VPN tunnel are the transport Airlift uses to reach the device. Green = ready, gray = not ready.": "Pairing file + tunnel Local Dev VPN adalah transport yang dipakai Airlift untuk menjangkau perangkat. Hijau = siap, abu-abu = belum siap.",
        "The pathleak scan reads inodes one by one — this can take a few minutes.": "Pemindaian pathleak membaca inode satu per satu — ini bisa memakan waktu beberapa menit.",
        "The picked file could not be copied into the package.": "File yang dipilih tidak dapat disalin ke dalam paket.",
        "The row is deleted from the database on the next Save.": "Baris dihapus dari database pada Save berikutnya.",
        "The sandbox extension for this container's directory was refused — the result code is in the Log.": "Ekstensi sandbox untuk direktori container ini ditolak — kode hasilnya ada di Log.",
        "The scan of %@ found no containers. The scan's baseline and counts are in the Log.": "Pemindaian %@ tidak menemukan container. Baseline dan jumlah hasil pemindaian ada di Log.",
        "The server shares this app's Documents folder only — SaveVaultBackups, staged vaults and uploads. Nothing outside it is ever served. Keep this page open while transferring: the server stops when you leave the page or the app goes to the background.": "Server hanya membagikan folder Documents aplikasi ini — SaveVaultBackups, vault yang di-stage, dan upload. Tidak ada yang di luar itu yang pernah disajikan. Biarkan halaman ini tetap terbuka saat mentransfer: server berhenti saat kamu meninggalkan halaman atau aplikasi masuk ke background.",
        "The staging vault lives in this app's Documents and does NOT survive uninstalling WorkTweaks. Verify a restore in the app first, then release the vault.": "Vault staging berada di Documents aplikasi ini dan TIDAK bertahan jika WorkTweaks di-uninstall. Verifikasi restore di aplikasi terlebih dahulu, lalu release vault-nya.",
        "The stored package is removed. Files it already deployed, and its Deploy History receipts, are not touched.": "Paket tersimpan dihapus. File yang sudah di-deploy dan receipt Riwayat Deploy-nya tidak disentuh.",
        "Theme Information": "Informasi Tema",
        "Thermal history (%d)": "Riwayat termal (%d)",
        "These are the photos and videos in the BackUP_Data folder. Select the ones to restore, then Restore opens the share sheet — tap Save to Photos there.": "Ini adalah foto dan video di folder BackUP_Data. Pilih yang ingin dipulihkan, lalu Pulihkan akan membuka share sheet — ketuk Simpan ke Foto di sana.",
        "This app is free software under the GNU AGPL v3 license, following the licenses of the projects above.": "Aplikasi ini adalah perangkat lunak bebas di bawah lisensi GNU AGPL v3, mengikuti lisensi proyek-proyek di atas.",
        "This app's own repository — issues and contributions welcome.": "Repositori aplikasi ini sendiri — issues dan kontribusi dipersilakan.",
        "This deletes only the listed .ips / .crash / .panic files. The folders are kept.": "Ini hanya menghapus file .ips / .crash / .panic yang terdaftar. Foldernya tetap dipertahankan.",
        "This device right now": "Perangkat ini saat ini",
        "This file isn't UTF-8 text, so it can't be edited as text. It can be edited byte-by-byte in the hex editor below.": "File ini bukan teks UTF-8, jadi tidak bisa diedit sebagai teks. File ini bisa diedit byte demi byte di hex editor di bawah.",
        "This file isn't UTF-8 text, so it can't be edited here. Nothing is ever written to it from this page.": "File ini bukan teks UTF-8, jadi tidak bisa diedit di sini. Tidak ada yang pernah ditulis ke file ini dari halaman ini.",
        "This iOS Version Isn't Supported": "Versi iOS Ini Tidak Didukung",
        "This is NOT an adblock: locking only stops ad assets landing on disk. Ads downloaded live over the network when the app opens can still appear.": "Ini BUKAN pemblokir iklan: penguncian hanya menghentikan aset iklan mendarat di disk. Iklan yang diunduh langsung lewat jaringan saat aplikasi dibuka masih bisa muncul.",
        "This is the container's system-managed metadata file. iOS doesn't allow other processes to read its contents, so it can't be opened or edited here.": "Ini adalah file metadata container yang dikelola sistem. iOS tidak mengizinkan proses lain membaca isinya, jadi file ini tidak bisa dibuka atau diedit di sini.",
        "This only clears the list. It does not undo anything that was applied.": "Ini hanya menghapus daftar. Ini tidak membatalkan apa pun yang telah diterapkan.",
        "This only makes the Join Waitlist button appear. The Siri AI model may still refuse to download — that part is not solved by this method yet.": "Ini hanya membuat tombol Join Waitlist muncul. Model Siri AI mungkin masih menolak mengunduh — bagian itu belum diselesaikan oleh metode ini.",
        "This package was rejected": "Paket ini ditolak",
