        "This is the same text Filza shows for this file. CacheData is the long base64 block; its lines are 51 bytes each. The Siri line is highlighted.": "Ini teks yang sama seperti yang ditampilkan Filza untuk file ini. CacheData adalah blok base64 yang panjang; tiap barisnya 51 byte. Baris Siri disorot.",
        "Siri line: line %d": "Baris Siri: baris %d",
        "On this device the Siri line is line %d, not 104 — the guide's line number varies by device.": "Di perangkat ini baris Siri adalah baris %d, bukan 104 — nomor baris panduan berbeda-beda tiap perangkat.",
