        "1 card": "1 张卡片",
        "1. Open the Translate app, delete the downloaded English (US) language, then download it again.\n2. Go to Settings > General > Language & Region, change the region from United States to another country, then change it back to United States.\n3. Turn off Low Power Mode (Settings > Battery).\n4. Connect to Wi-Fi (and keep your iPhone charging) while Apple Intelligence finishes downloading.": "1. 打开“翻译”App，删除已下载的 English (US) 语言，然后重新下载。\n2. 前往 Settings > General > Language & Region，将地区从 United States 更改为其他国家，然后再改回 United States。\n3. 关闭低电量模式 (Settings > Battery)。\n4. 连接 Wi-Fi（并让 iPhone 保持充电），等待 Apple Intelligence 完成下载。",
        "1. Tap Scan Cards above.": "1. 点击上方的 Scan Cards。",
        "1. Use the iPhone 16 Pro subtype.\n2. Settings > Appearance > Display Zoom > Large Text, then go Back and set Text Size to Small (optional).": "1. 使用 iPhone 16 Pro 子型号。\n2. 前往 Settings > Appearance > Display Zoom > Large Text，然后返回并将 Text Size 设为 Small（可选）。",
        "2. On this iPhone, double-click the Side button (Apple Pay), authenticate with Face ID, and tap your card.": "2. 在此 iPhone 上，双击侧边按钮 (Apple Pay)，使用 Face ID 验证，然后点击您的卡片。",
        "3. Your card will appear here automatically!": "3. 您的卡片将自动出现在这里！",
        "A .tendies package is a ZIP archive containing one or more wallpaper descriptors: loose descriptor folders, a descriptors folder, or a container layout mirroring PosterBoard's data store (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Stored and deflated ZIP entries are supported — the same reader Deploy uses; encrypted and ZIP64 archives are rejected.": ".tendies 软件包是一个 ZIP 归档，包含一个或多个壁纸描述符：松散的描述符文件夹、descriptors 文件夹，或与 PosterBoard 数据存储（Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors）相同的容器布局。支持已存储和已压缩的 ZIP 条目——与 Deploy 使用相同的读取器；加密和 ZIP64 归档会被拒绝。",
        "A Deploy package replaces files inside exactly one app — the app named by its bundle ID. It cannot touch any other app: every target path is relative to that app's container, and packages with absolute or \"..\" paths are rejected whole.": "Deploy 安装包会替换恰好一个应用内的文件——即由其 Bundle ID 指定的应用。它不能触碰任何其他应用：每个目标路径都相对于该应用的容器，包含绝对路径或“..”路径的安装包将被整体拒绝。",
        "A MobileGestalt tweak app for iOS 26/27, built on the open-source projects credited below. Use at your own risk — tweaks modify system files.": "一款适用于 iOS 26/27 的 MobileGestalt 调整应用，基于下方致谢的开源项目构建。使用风险自负——调整会修改系统文件。",
        "A MobileGestalt tweak tool for iOS 26 & 27 — unlock your device's hidden features without a jailbreak, powered by the worse_query sandbox escape.": "一款适用于 iOS 26 和 27 的 MobileGestalt 调整工具——无需越狱即可解锁设备的隐藏功能，由 worse_query 沙盒逃逸驱动。",
        "A bundle ID is required — it names the one app this package may touch.": "需要 Bundle ID——它指定此安装包可以触碰的唯一应用。",
        "A package is ONE .zip file containing a manifest.json at its top level plus the payload files it names. The Package Builder exports that zip (save it in Files); Deploy imports it, resolves the target itself from the manifest, and applies it — no location picking, the destinations come from the zip.": "一个安装包就是一个 .zip 文件，在其顶层包含一个 manifest.json 以及它所列出的载荷文件。Package Builder 会导出该 zip（请保存在“文件”中）；Deploy 会导入它，根据清单自行解析目标并应用——无需选择位置，目标位置来自 zip。",
        "A partial restore can affect photos and videos. Back them up first — optional, you can skip it.": "部分恢复可能会影响照片和视频。请先备份——可选操作，您可以跳过。",
        "A respring is required before a new wallpaper appears in the gallery.": "新壁纸出现在图库之前需要执行一次 respring。",
        "A signed IPA only works on the device registered in its profile.": "已签名的 IPA 仅适用于其描述文件中注册的设备。",
        "A snapshot is also created automatically at every Apply, containing the state that Apply just produced. The Original backup is created once, the first time MobileGestalt is read successfully.": "每次执行 Apply 时也会自动创建一个快照，包含该次 Apply 刚生成的状态。Original 备份只创建一次，即首次成功读取 MobileGestalt 时。",
        "A whitelisted bundle id (and its App Groups) or exact path is never locked by Lock All. Newly whitelisted targets are restored writable right away. SMZDM is whitelisted by default — its splash cache is known to crash the app when locked.": "列入白名单的 bundle id（及其 App Groups）或精确路径永远不会被 Lock All 锁定。新列入白名单的目标会立即恢复为可写。SMZDM 默认在白名单中——锁定其开屏缓存已知会导致应用崩溃。",
        "AI Cache": "AI 缓存",
        "APFS vault: clonefile staging, zero extra space, atomic restore with rollback. ZIP backup: the same three folders as one .zip file, restored by merging in place.": "APFS vault：clonefile 暂存，不占用额外空间，支持回滚的原子恢复。ZIP 备份：相同的三个文件夹打包为一个 .zip 文件，通过原地合并恢复。",
