        "Certificates tab: create your certificate if needed. A free team can hold only one active development certificate — if creation fails with error 7460, revoke an old unused certificate there first.": "Certificates 标签页：如有需要，请创建您的证书。免费团队只能持有一个有效的开发证书——如果创建失败并出现错误 7460，请先在那里吊销一个不用的旧证书。",
