        "Flashing needs a pairing file and the VPN tunnel. Pair first and connect the VPN in Sandbox → Utilities → Get Pairing File + VPN Status, then come back here.": "刷入需要配对文件和 VPN 隧道。请先配对并在 Sandbox → Utilities → Get Pairing File + VPN Status 中连接 VPN，然后再回到这里。",
        "Flashing needs a pairing file. Pair this iPhone first in Sandbox → Utilities → Get Pairing File.": "刷入需要配对文件。请先在 Sandbox → Utilities → Get Pairing File 中配对这台 iPhone。",
        "Flashing needs the VPN tunnel. Open the Local Dev VPN app and connect first.": "刷入需要 VPN 隧道。请先打开 Local Dev VPN 应用并连接。",
