        "Imported": "已导入",
        "In the Tweaks tab, Apple Intelligence section, turn on Apple Intelligence and Siri AI Cache Patch. The cache patch is the Filza line-104 edit (one CacheData byte, 0x00 to 0x02) — done here, no Filza needed.": "在 Tweaks 标签页的 Apple Intelligence 部分，开启 Apple Intelligence 和 Siri AI Cache Patch。缓存补丁即 Filza 第 104 行编辑（一个 CacheData 字节，从 0x00 改为 0x02）——在此完成，无需 Filza。",
        "Individual Keys": "单个键",
        "Install tab → Provisioning: fill in the fields below, tap Provision, and wait for \"profile OK\". Your Team ID is shown in the app's Certificates tab.": "Install 标签页 → Provisioning：填写下方字段，点击 Provision，并等待出现 \"profile OK\"。您的 Team ID 显示在应用的 Certificates 标签页中。",
        "Installation": "安装",
        "Installed Profiles": "已安装的描述文件",
        "Installed any other way, the signed profile leaves the App Group out — and without it, the tweaks can't run. Tap Tutorials below for both step-by-step guides.": "如果以其他方式安装，签名描述文件将不包含 App Group——没有它，调整将无法运行。请点击下方的 Tutorials 查看两份分步指南。",
        "Installing into PosterBoard…": "正在安装到 PosterBoard…",
        "Internal": "内部",
        "Jetsam & Crash": "Jetsam 与崩溃",
        "Jetsam & Crash lists the reports iOS writes when it kills an app for memory (Jetsam, bug_type 298), when an app crashes (309), or on a watchdog / kernel panic (210). Open a report to see why it died, share the full file, or clean all reports to free space.": "Jetsam & Crash 列出 iOS 在因内存终止应用（Jetsam，bug_type 298）、应用崩溃（309）或看门狗/内核崩溃（210）时写入的报告。打开报告查看死亡原因，分享完整文件，或清理所有报告以释放空间。",
