        "Locked folders are read-only (0555) with a sentinel file inside; config files are emptied and locked (0444). A Weak Lock is a locked folder missing its sentinel — tap Harden to add it.": "锁定的文件夹为只读 (0555)，其中包含一个标记文件；配置文件会被清空并锁定 (0444)。Weak Lock 是指缺少标记文件的已锁定文件夹——点击 Harden 可添加标记。",
        "Locks every target below that still needs action. Whitelisted targets are always skipped.": "锁定下方所有仍需处理的目标。已列入白名单的目标始终会被跳过。",
