        "No ad targets found yet. Tap Scan above.": "尚未找到广告目标。点击上方的扫描。",
        "No backed-up photos or videos yet. Use \"Backup Your Photos & Videos Here!\" first.": "还没有已备份的照片或视频。请先使用“在此备份您的照片和视频！”。",
        "No containers were found, so there is nothing to clean.": "未找到容器，因此没有可清理的内容。",
        "No deploys yet. When a package is deployed, the files it replaced are backed up here with a receipt, ready to restore.": "还没有部署过。部署安装包时，它所替换的文件将连同收据一起备份到此处，随时可以恢复。",
        "No diagnostic reports found — nothing has been killed or crashed recently, or the reports were already cleaned.": "未找到诊断报告——最近没有应用被终止或崩溃，或者报告已被清理。",
        "No files yet.": "还没有文件。",
        "No installable profile records were found in this directory.": "此目录中未找到可安装的描述文件记录。",
        "No pairing file saved yet.": "尚未保存配对文件。",
        "No pairing file yet. Pair this iPhone first in Sandbox → Utilities → Get Pairing File — scanning and flashing need it.": "尚无配对文件。请先在 Sandbox → Utilities → Get Pairing File 中配对这台 iPhone——扫描和刷入都需要它。",
        "No recordings were found in the Voice Memos database.": "Voice Memos 数据库中未找到录音。",
        "No regular files found in this container.": "此容器中未找到常规文件。",
        "No scan yet. The scan starts automatically; if it does not, open App Data once, or type the bundle ID by hand.": "尚未扫描。扫描会自动开始；如果没有开始，请打开一次应用数据，或手动输入 Bundle ID。",
        "No skin — tap Set Skin below": "没有皮肤——点击下方的 Set Skin",
        "No snapshots yet. Apply some tweaks or tap Back Up Now.": "还没有快照。请应用一些调整，或点按“立即备份”。",
        "No stored packages yet. Build one with New Package, or import an existing .deploy / .zip / folder package to edit it here.": "还没有已存储的安装包。使用“新建安装包”创建一个，或导入现有的 .deploy / .zip / 文件夹安装包以在此编辑。",
        "No thermal events found in the powerlog.": "powerlog 中未找到散热事件。",
