        "No wallpapers imported yet. Wallpapers imported here are listed so you can remove them again — wallpapers added any other way are never touched.": "尚未导入任何壁纸。在此导入的壁纸会被列出，以便您可以再次删除它们——以其他方式添加的壁纸绝不会被触碰。",
