        "Nothing applied yet.": "尚未应用任何内容。",
        "Nothing staged yet.": "尚未暂存任何内容。",
        "Nothing was written — the stored manifest is unchanged.": "未写入任何内容——已存储的清单未更改。",
        "Nothing was written.": "未写入任何内容。",
        "Notice": "提示",
        "Numbers only.": "仅限数字。",
        "OK": "好",
        "Off": "已关闭",
        "Off in this backup": "在此备份中已关闭",
        "Old UI": "旧界面",
        "On": "已开启",
        "On a computer, download iLoader from iloader.app — the official site only — and open it.": "在电脑上，从 iloader.app 下载 iLoader——仅限官方网站——然后打开它。",
        "On in this backup": "在此备份中已开启",
        "One of the destination paths is invalid.": "其中一个目标路径无效。",
        "Only files under Library/Caches inside the listed targets are deleted. AI models are never touched, and caches regenerate when the apps run again.": "仅删除所列目标内 Library/Caches 下的文件。AI 模型绝不会被触碰，应用再次运行时缓存会重新生成。",
        "Only spoof your device model if you want to download Apple Intelligence. This may break Face ID. If you decide to unspoof and want to keep Apple Intelligence, do NOT re-enter the Apple Intelligence & Siri menu in Settings.": "仅当您想下载 Apple Intelligence 时才伪装设备型号。这可能会导致 Face ID 无法使用。如果您决定取消伪装并想继续使用 Apple Intelligence，请勿再次进入 Settings 中的 Apple Intelligence & Siri 菜单。",
        "Only the listed .ips / .crash / .panic files under DiagnosticReports (and Retired) are ever deleted. The folders themselves are kept, and nothing else is touched.": "仅删除 DiagnosticReports（及 Retired）下所列的 .ips / .crash / .panic 文件。文件夹本身会保留，其他内容一概不动。",
        "Open App Data first so the container scan runs, then come back — or tap Rescan.": "请先打开 App Data 以运行容器扫描，然后再回来——或点击 Rescan。",
        "Open Settings → Apple Intelligence & Siri and tap Join Waitlist. Wait about 15 minutes for it to be accepted.": "打开 Settings → Apple Intelligence & Siri，点击 Join Waitlist。等待约 15 分钟以获得通过。",
        "Open Signed Apps and sign in with your Apple ID.": "打开 Signed Apps 并使用您的 Apple ID 登录。",
        "Open Source": "开源",
        "Open Tutorials": "打开教程",
        "Open WorkTweaks and you're done.": "打开 WorkTweaks 即可完成。",
        "Open as Property List": "以属性列表打开",
        "Open as SQLite Database": "以 SQLite 数据库打开",
        "Open the Local Dev VPN app and connect. The tunnel shows as a utun interface on 10.7.x.x (gateway 10.7.0.1).": "打开 Local Dev VPN 应用并连接。隧道将显示为 10.7.x.x 上的 utun 接口（网关 10.7.0.1）。",
        "Opening the configuration profiles…": "正在打开配置描述文件…",
        "Opening the database…": "正在打开数据库…",
        "Opens an empty editor; the file is created when you save.": "打开一个空白编辑器；文件将在您保存时创建。",
        "Opens the database as editable tables, with a backup taken before the first save. Close the owning app before editing.": "将数据库打开为可编辑的表格，并在首次保存前进行备份。编辑前请关闭所属应用。",
        "Opens the property list as an editable key/type/value table, with a backup taken before the first save.": "将属性列表打开为可编辑的键/类型/值表格，并在首次保存前进行备份。",
        "Optional label": "可选标签",
        "Organization: %@": "组织：%@",
