        "Package": "安装包",
        "Package Builder": "安装包构建器",
        "Package Format": "安装包格式",
        "Packages you build or import are stored on this device, in WorkTweaks' own container. Tap a package to edit it. Deploy runs it through the same preview, resolve and backup flow as a picked package.": "您构建或导入的安装包存储在此设备上，位于 WorkTweaks 自己的容器中。点按一个安装包即可编辑它。Deploy 会让它经过与所选安装包相同的预览、解析和备份流程。",
        "Pair This iPhone": "配对这台 iPhone",
        "Pairing & Airlift": "配对与 Airlift",
        "Pairing cancelled.": "配对已取消。",
        "Pairing file": "配对文件",
        "Pairing file imported.": "配对文件已导入。",
        "Pairing file removed.": "配对文件已删除。",
        "Pairing file saved to the app.": "配对文件已保存到应用。",
        "Parsed from the .plist files in the ConfigurationProfiles directory. This page never installs or removes a profile.": "解析自 ConfigurationProfiles 目录中的 .plist 文件。此页面从不安装或删除描述文件。",
        "Partial — some icons may still show. Hidden through the archive's suppressed identifiers.": "部分——某些图标可能仍会显示。通过归档中被抑制的标识符隐藏。",
        "Partially Supported": "部分支持",
        "Partially Supported iOS • %@": "部分支持的 iOS • %@",
        "Passcode Theme": "密码主题",
        "Passcode Themes": "密码主题",
        "Passcode theme applied": "密码主题已应用",
        "Paste card hash": "粘贴卡片哈希",
        "Path Enumeration": "路径枚举",
        "Paths must be relative, non-empty and contain no \"..\" component.": "路径必须为相对路径、非空且不包含“..”部分。",
        "Payload files are copied into the package. Add File accepts any file — a .plist is added as a payload, and a .zip is unpacked, each file inside becoming a payload with its destination defaulting to its path inside the archive. Destinations are relative paths only; absolute paths and \"..\" are rejected, exactly like an imported package.": "载荷文件会被复制到安装包中。“添加文件”接受任何文件——.plist 文件作为载荷添加，.zip 文件会被解包，其中每个文件都成为一个载荷，其目标默认为它在压缩包内的路径。目标仅限相对路径；绝对路径和“..”会被拒绝，与导入的安装包完全相同。",
        "Persist after reboot": "重启后保留",
        "Photo Library": "照片图库",
        "Photo chosen — tap to change": "已选择照片——点击以更改",
        "Photos & Videos": "照片与视频",
        "Pick Target App": "选择目标应用",
        "Pick an app": "选择应用",
        "Pick an app to see its cache and clean it.": "选择一个应用以查看其缓存并进行清理。",
        "Pick from App Data scan…": "从应用数据扫描中选择…",
        "Pick the WorkTweaks IPA, set the Signing Bundle ID field to the same identifier, then tap Sign IPA.": "选择 WorkTweaks IPA，将 Signing Bundle ID 字段设为相同的标识符，然后点击 Sign IPA。",
        "Pick the photos and videos you want to keep, then Save. They are copied into the BackUP_Data folder inside the app. Optional — you can skip this.": "选择要保留的照片和视频，然后保存。它们将被复制到应用内的 BackUP_Data 文件夹中。可选——您可以跳过此步。",
        "Plays a soft sound when you tap menus and features. Respects the silent switch.": "点击菜单和功能时播放轻柔音效。遵循静音开关。",
        "Please Install It the Right Way": "请以正确的方式安装",
