        "Read-only mode — the grant did not include write access, so Clean All is disabled.": "只读模式——授权未包含写入权限，因此 Clean All 已禁用。",
        "Read-only: the powerlog is cloned into this app's temp folder and inspected there. Nothing is ever written to the system database. Some iOS 26 firmware restricts the powerlog sandbox token; iOS 27 reads fully.": "只读：powerlog 会被克隆到此应用的临时文件夹中并在其中检查。绝不会向系统数据库写入任何内容。部分 iOS 26 固件会限制 powerlog 沙盒令牌；iOS 27 可完整读取。",
        "Reading the configuration profiles…": "正在读取配置描述文件…",
        "Reading the property list…": "正在读取属性列表…",
        "Reading the recordings database…": "正在读取录音数据库…",
        "Reading video frames…": "正在读取视频帧…",
        "Reading…": "正在读取…",
        "Rebooting now might cause a bootloop. Try pressing 'Revert Tweaks'.": "现在重启可能会导致 bootloop。请尝试按下“还原调整”。",
        "Recent Requests": "最近请求",
        "Recent samples (%d)": "最近样本 (%d)",
        "Reference": "参考",
        "Reference & Patch Files": "参考与补丁文件",
        "Reference — APFS save-vault idea (clonefile staging, atomic swap with rollback).": "参考——APFS 保存库思路（clonefile 暂存、带回滚的原子交换）。",
        "Reference — PosterBoard wallpaper format the maker was verified against.": "参考——用于验证制作器的 PosterBoard 壁纸格式。",
        "Reference — Splash Ad Cache Lock mechanism (ad SDK cache lock, save vault, diagnostics, Wi-Fi file sharing, Voice Memos export, AI cache probes).": "参考——Splash Ad Cache Lock 机制（广告 SDK 缓存锁定、保存库、诊断、Wi-Fi 文件共享、Voice Memos 导出、AI 缓存探测）。",
        "Reference — cache data cleaner": "参考——缓存数据清理器",
        "Reference — turn on new Siri AI (CacheData line edit + device spoof)": "参考——开启新的 Siri AI（CacheData 行编辑 + 设备伪装）",
        "Reference — video-to-wallpaper (CAML) builder used by the PosterBoard wallpaper maker.": "参考——PosterBoard 壁纸制作器使用的视频转壁纸（CAML）构建器。",
        "Refresh": "刷新",
        "Refresh Status": "刷新状态",
        "Region suffix (e.g. PA/A)": "地区后缀（例如 PA/A）",
        "Release": "释放",
