        "Remove": "移除",
        "Remove / Unload Theme": "移除 / 卸载主题",
        "Remove Footnote": "删除脚注",
        "Remove Pairing File": "删除配对文件",
        "Report": "报告",
        "Reports": "报告",
        "Reports (%d)": "报告 (%d)",
        "Requires iOS %.1f+": "需要 iOS %.1f+",
        "Rescan": "重新扫描",
        "Reset": "重置",
        "Resolve Target": "解析目标",
        "Resolving the target container…": "正在解析目标容器…",
        "Respring": "Respring",
        "Respring did not trigger on this device.": "此设备上未能触发 Respring。",
        "Restart Device": "重新启动设备",
        "Restart Required": "需要重新启动",
        "Restore": "恢复",
        "Restore (%d)": "恢复（%d）",
        "Restore Backup": "恢复备份",
        "Restore Everything": "全部恢复",
        "Restore Result — %d succeeded, %d failed": "恢复结果——%d 个成功，%d 个失败",
        "Restore a ZIP backup": "恢复 ZIP 备份",
        "Restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "恢复更改只有在设备完全重新启动后才会生效——仅重新启动 SpringBoard 是不够的。选择“稍后”只是推迟它；更改将一直处于待处理状态，直到您重新启动。",
        "Restore into…": "恢复到…",
        "Restore swaps the staged copy into the app's current container and rolls back if anything fails. Release a snapshot only after you verified the restore in the app.": "恢复会将暂存副本换入应用当前容器，若有任何失败则回滚。只有在应用中验证恢复无误后，才释放快照。",
        "Restore the backup?": "要恢复备份吗？",
        "Restore this entire backup?": "要恢复整个备份吗？",
        "Restoring ZIP…": "正在恢复 ZIP…",
        "Restoring the backup failed — the details are in the Log.": "恢复备份失败——详情记录在日志中。",
        "Restoring writes each backed-up file back in place. Files the deploy created (they did not exist before) are deleted again.": "恢复会将每个已备份的文件写回原位置。部署所创建的文件（之前不存在）将被再次删除。",
        "Restoring…": "正在恢复…",
        "Result — %d succeeded, %d failed": "结果——%d 个成功，%d 个失败",
        "Retry Flash": "重试刷入",
        "Retry Flash Theme": "重试刷入主题",
        "Revert": "还原",
        "Revert Tweaks": "还原调整",
        "Revert all tweaks?": "还原所有调整？",
        "Revert and restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "还原和恢复更改仅在设备完全重启后生效——仅 respring 是不够的。选择“稍后”只是推迟，更改将一直处于待处理状态，直到您重启设备。",
        "Rewrites the entire MobileGestalt.plist from this backup. A device restart is required after restoring.": "将使用此备份重写整个 MobileGestalt.plist。恢复后需要重新启动设备。",
        "Running": "运行中",
        "Sampled": "采样时间",
        "Sandbox access denied": "Sandbox 访问被拒绝",
        "Sandbox extension is ready (directory grant held).": "沙盒扩展已就绪（已持有目录授权）。",
        "Save": "保存",
        "Save .passthm": "保存 .passthm",
        "Save App Group ID": "保存 App Group ID",
        "Save Vault": "Save Vault",
        "Saved": "已保存",
        "Saved %d of %d to BackUP_Data.": "已将 %d 个（共 %d 个）保存到 BackUP_Data。",
        "Saved: %@": "已保存：%@",
        "Saves the package, then shares ONE .zip file — save it in Files. Deploy imports that zip and applies it without asking for locations.": "保存安装包，然后分享一个 .zip 文件——请保存在“文件”中。Deploy 会导入该 zip 并应用，无需询问位置。",
        "Saving %d of %d (%d%%)": "正在保存第 %d 个，共 %d 个（%d%%）",
        "Saving applies the edits to the database through SQLite, takes a backup of the original first, then writes the edited file back in place. Close the owning app before saving — a running app can overwrite your edits.": "保存会通过 SQLite 将编辑应用到数据库，先备份原始文件，然后将编辑后的文件写回原位。保存前请关闭所属应用——正在运行的应用可能会覆盖你的编辑。",
        "Saving rebuilds the property list from this table, takes a backup of the original first, then writes it back in place. Close the owning app before saving — a running app can overwrite your edits.": "保存会根据此表重建属性列表，先备份原始文件，然后将其写回原位。保存前请关闭所属应用——正在运行的应用可能会覆盖你的编辑。",
        "Saving writes the file in place and verifies the result by re-reading it.": "保存将在原位置写入文件，并通过重新读取来验证结果。",
        "Saving writes the file in place, under the container's sandbox extension.": "保存将在原位置写入文件，使用容器的沙盒扩展。",
        "Saving…": "正在保存…",
        "Scan": "扫描",
        "Scan Cards": "扫描卡片",
        "Scan for Ad Targets": "扫描广告目标",
        "Scanning %@…": "正在扫描 %@…",
        "Scanning…": "正在扫描…",
        "Scope": "范围",
        "Search": "搜索",
        "Search tweaks": "搜索调整",
        "Secondary bars: %d": "副卡信号格：%d",
        "Secondary carrier name (max 64)": "副卡运营商名称（最多 64）",
        "Secondary network type": "副卡网络类型",
        "Sections": "分区",
        "Select All": "全选",
        "Select None": "全不选",
        "Select at least one card and attach a skin image to it before flashing.": "请至少选择一张卡片并附加皮肤图片，然后再刷入。",
        "Selected app": "已选应用",
        "Server": "服务器",
        "Set NULL": "设为 NULL",
        "Set Skin": "设置皮肤",
        "Set Skin for All Cards…": "为所有卡片设置皮肤…",
        "Set the Spoofing picker (under Apple Intelligence) to iPhone 17 Pro (iPhone18,1).": "将 Spoofing 选择器（位于 Apple Intelligence 下方）设为 iPhone 17 Pro (iPhone18,1)。",
        "Sets how many bars are drawn. Static — it does not follow the real signal.": "设置绘制多少格信号。静态——不会跟随真实信号。",
        "Share %@": "分享 %@",
        "Share Contents": "分享内容",
        "Share Full Report": "分享完整报告",
        "Showing the first %@ of %@ rows — the editor is for targeted edits, not bulk dumps.": "正在显示前 %@ 行，共 %@ 行——编辑器用于针对性编辑，而非批量导出。",
        "Shows the battery percentage in the status bar. Key: SBShowBatteryPercentage in com.apple.springboard.plist.": "在状态栏中显示电池百分比。Key：com.apple.springboard.plist 中的 SBShowBatteryPercentage。",
        "Sign In": "登录",
        "Signal Bars": "信号格",
        "Signal bars (Primary)": "信号格（主卡）",
        "Signal bars (Secondary)": "信号格（副卡）",
        "Single-file shorthand: instead of \"files\", give \"relativePath\" and \"file\". \"scope\" is Application (bundleID = the app's bundle ID), AppGroup (bundleID = the group identifier, e.g. group.com.example) or InternalDaemon. ZIP archives may use stored or deflated entries; encrypted and ZIP64 archives are not supported. Older .deploy archives and plain folders still import.": "单文件简写：用 “relativePath” 和 “file” 代替 “files”。“scope” 可以是 Application（bundleID = 应用的 Bundle ID）、AppGroup（bundleID = 组标识符，例如 group.com.example）或 InternalDaemon。ZIP 压缩包可使用存储或压缩条目；不支持加密和 ZIP64 压缩包。较旧的 .deploy 压缩包和普通文件夹仍可导入。",
        "Size": "大小",
        "Sizes are measured by walking each folder. An app recreates cache as it runs, so the size grows back over time.": "大小通过遍历每个文件夹测得。应用运行时会重新生成缓存，因此大小会随时间再次变大。",
        "Sizes are probed read-only (depth 4). Delete Cache removes only files under Library/Caches inside these targets — the AI models live elsewhere and are never touched.": "大小以只读方式探测（深度 4）。Delete Cache 仅删除这些目标内 Library/Caches 下的文件——AI 模型位于别处，绝不会被触碰。",
        "Snapshots": "快照",
        "Software-Oriented Features": "软件相关功能",
        "Some tweaks — especially Apple Intelligence — only take effect after a full restart, not a respring.": "部分调整——尤其是 Apple Intelligence——仅在完全重启后生效，respring 无效。",
        "Something went wrong": "出了点问题",
        "Sound Effects": "音效",
        "Splash Ad Cache Lock": "Splash Ad Cache Lock",
        "Splash Ad Cache Lock finds the folders ad SDKs use to cache splash (launch) ads, empties them, and locks them read-only so the app cannot rebuild its splash-ad cache. Locks apply only to third-party app folders — never to system folders, Documents, or the app itself.": "Splash Ad Cache Lock 会找到广告 SDK 用于缓存开屏（启动）广告的文件夹，将其清空并锁定为只读，使应用无法重建开屏广告缓存。锁定仅适用于第三方应用文件夹——绝不适用于系统文件夹、Documents 或应用本身。",
        "Spoofing": "伪装",
        "SpringBoard loads the wallpaper store when it starts — respring or restart to see the change in the wallpaper gallery.": "SpringBoard 启动时会加载壁纸存储——请执行 respring 或重启，以在壁纸图库中看到更改。",
        "SpringBoard reads the footnote when it starts — respring or restart to see it on the Lock Screen.": "SpringBoard 启动时会读取脚注——请执行 respring 或重启，以在锁定屏幕上看到它。",
        "Stage an app's Documents, Library/Preferences and Library/Application Support (never Caches) before its 7-day certificate expires. After reinstall, the data is restored into the app's new container — matched by bundle id, not the old container UUID.": "在应用的 7 天证书过期之前，暂存其 Documents、Library/Preferences 和 Library/Application Support（从不包括 Caches）。重装后，数据将恢复到应用的新容器中——按 bundle id 匹配，而不是旧容器 UUID。",
        "Stage copies into the APFS vault (no extra space). ZIP backup copies first, then zips — for very large apps use the APFS vault. Both refuse while the app is still writing its database.": "Stage 会复制到 APFS vault（不占用额外空间）。ZIP 备份先复制再压缩——对于非常大的应用，请使用 APFS vault。如果应用仍在写入数据库，两者都会拒绝。",
        "Stage into APFS Vault": "暂存到 APFS Vault",
        "Staged %@: %d file(s), %@. Verified against the source.": "已暂存 %@：%d 个文件，%@。已对照源验证。",
        "Staged snapshots": "已暂存的快照",
        "Staging…": "正在暂存…",
        "Start Server": "启动服务器",
        "Start Tweaks Feature": "启用 Tweaks 功能",
        "Start the server to get its address.": "启动服务器以获取其地址。",
        "Still writing (%d active WAL file(s)) — close the app first": "仍在写入（%d 个活动 WAL 文件）——请先关闭应用",
        "Stop Scan": "停止扫描",
        "Stop Server": "停止服务器",
        "Stopped": "已停止",
        "Stored as text.": "以文本形式存储。",
        "Subtype": "子型号",
        "Supervision": "监督",
        "Support": "支持",
        "Supported": "已支持",
        "Supported iOS Versions": "支持的 iOS 版本",
        "Supported iOS • %@": "支持的 iOS • %@",
        "Swift implementation of the respring web view (via mond / jailbreak.party).": "respring 网页视图的 Swift 实现（通过 mond / jailbreak.party）。",
        "System": "系统",
        "System Caches": "系统缓存",
        "System Language": "系统语言",
        "Table": "表",
        "Tap Read Powerlog to load the latest battery samples.": "点击“读取 Powerlog”以加载最新的电池样本。",
        "Tap Refresh to list the diagnostic reports.": "点击“刷新”以列出诊断报告。",
        "Tap a key to assign a custom image.": "点击一个按键以指定自定义图片。",
        "Target": "目标",
        "Target Path": "目标路径",
        "Target container": "目标容器",
        "That file is not a pairing file.": "该文件不是配对文件。",
        "The App Data scan is still running — ad targets appear once it finishes.": "App Data 扫描仍在进行——完成后会显示广告目标。",
        "The CacheExtra key knowledge — the tweak-key research the WorkTweaks tweak catalog is built on.": "CacheExtra 键知识——WorkTweaks 调整目录所基于的调整键研究。",
        "The Voice Memos container is found through the App Data scan.": "Voice Memos 容器通过 App Data 扫描找到。",
        "The ZIP must be a Save Vault backup (it carries a BackupManifest.plist). Files merge in place; system bundle ids are blocked.": "ZIP 必须是 Save Vault 备份（其中包含 BackupManifest.plist）。文件将原地合并；系统 bundle id 会被阻止。",
        "The backup of the original file couldn't be written, so nothing was saved.": "无法写入原始文件的备份，因此未保存任何内容。",
        "The browser asks for these credentials once, then remembers them for the session.": "浏览器只需输入一次这些凭据，之后会在本次会话中记住它们。",
        "The bundle ID is not a valid identifier.": "Bundle ID 不是有效的标识符。",
        "The bundle ID of the one app this package may touch. Pick it from the App Data container scan, or type it.": "此安装包可以触碰的唯一应用的 Bundle ID。请从应用数据容器扫描中选择，或手动输入。",
        "The container scan found no containers.": "容器扫描未找到任何容器。",
        "The container scan is shared with App Data and runs once per app session.": "容器扫描与 App Data 共享，每个应用会话仅运行一次。",
        "The container scan runs once per session.": "容器扫描每个会话仅运行一次。",
        "The core system: the sandbox escape and MobileGestalt access this whole app is built on.": "核心系统：整个应用所基于的沙盒逃逸和 MobileGestalt 访问。",
        "The current MobileGestalt will be entirely replaced with this %@ backup.": "当前的 MobileGestalt 将被此 %@ 备份完全替换。",
        "The current file is overwritten in place with the backup taken before the first byte edit.": "当前文件将在原位置被首次字节编辑前所做的备份覆盖。",
        "The developer's GitHub profile.": "开发者的 GitHub 个人主页。",
        "The directory is empty.": "目录为空。",
        "The entry is removed from the property list on the next Save.": "该条目将在下次保存时从属性列表中移除。",
        "The file couldn't be read under the container's sandbox extension — the details are in the Log. Nothing was written to it.": "无法在容器的沙盒扩展下读取此文件——详情记录在日志中。未向其写入任何内容。",
        "The file-based CacheData pattern method used by Enable iPadOS Mode (MobileGestaltCacheDataTweak).": "Enable iPadOS Mode 使用的基于文件的 CacheData 模式方法（MobileGestaltCacheDataTweak）。",
        "The original identifiers are already registered to another developer account, which is why the Team ID suffix is required.": "原始标识符已注册到另一个开发者账号，因此需要 Team ID 后缀。",
        "The package could not be exported.": "无法导出此安装包。",
        "The package store is unavailable (the App Group container did not resolve).": "安装包存储不可用（App Group 容器未解析）。",
        "The pairing file + Local Dev VPN tunnel are the transport Airlift uses to reach the device. Green = ready, gray = not ready.": "配对文件 + Local Dev VPN 隧道是 Airlift 用于连接设备的传输通道。绿色 = 就绪，灰色 = 未就绪。",
        "The pathleak scan reads inodes one by one — this can take a few minutes.": "pathleak 扫描逐个读取 inode——这可能需要几分钟。",
        "The picked file could not be copied into the package.": "无法将所选文件复制到安装包中。",
        "The row is deleted from the database on the next Save.": "该行将在下次保存时从数据库中删除。",
        "The sandbox extension for this container's directory was refused — the result code is in the Log.": "此容器目录的沙盒扩展被拒绝——结果代码记录在日志中。",
        "The scan of %@ found no containers. The scan's baseline and counts are in the Log.": "对 %@ 的扫描未找到任何容器。扫描的基线和计数记录在日志中。",
        "The server shares this app's Documents folder only — SaveVaultBackups, staged vaults and uploads. Nothing outside it is ever served. Keep this page open while transferring: the server stops when you leave the page or the app goes to the background.": "服务器仅共享此应用的 Documents 文件夹——SaveVaultBackups、已暂存的 vault 和上传文件。之外的内容一概不提供。传输期间请保持此页面打开：离开页面或应用进入后台时，服务器会停止。",
        "The staging vault lives in this app's Documents and does NOT survive uninstalling WorkTweaks. Verify a restore in the app first, then release the vault.": "暂存 vault 位于此应用的 Documents 中，卸载 WorkTweaks 后将不会保留。请先在应用中验证恢复结果，然后再释放 vault。",
        "The stored package is removed. Files it already deployed, and its Deploy History receipts, are not touched.": "已存储的安装包将被删除。它已部署的文件及其部署历史收据不会受到影响。",
        "Theme Information": "主题信息",
        "Thermal history (%d)": "散热历史 (%d)",
        "These are the photos and videos in the BackUP_Data folder. Select the ones to restore, then Restore opens the share sheet — tap Save to Photos there.": "这些是 BackUP_Data 文件夹中的照片和视频。选择要恢复的内容，然后“恢复”将打开分享表单——在其中点按“存储到照片”。",
        "This app is free software under the GNU AGPL v3 license, following the licenses of the projects above.": "本应用是遵循上述项目许可证的 GNU AGPL v3 自由软件。",
        "This app's own repository — issues and contributions welcome.": "本应用自己的仓库——欢迎提交 issue 和贡献。",
        "This deletes only the listed .ips / .crash / .panic files. The folders are kept.": "这只会删除所列的 .ips / .crash / .panic 文件。文件夹会保留。",
        "This device right now": "此设备当前状态",
        "This file isn't UTF-8 text, so it can't be edited as text. It can be edited byte-by-byte in the hex editor below.": "此文件不是 UTF-8 文本，因此无法作为文本进行编辑。可以在下方的十六进制编辑器中逐字节编辑。",
        "This file isn't UTF-8 text, so it can't be edited here. Nothing is ever written to it from this page.": "此文件不是 UTF-8 文本，因此无法在此编辑。此页面永远不会向其写入任何内容。",
        "This iOS Version Isn't Supported": "不支持此 iOS 版本",
        "This is NOT an adblock: locking only stops ad assets landing on disk. Ads downloaded live over the network when the app opens can still appear.": "这不是广告拦截器：锁定只会阻止广告资源落到磁盘上。打开应用时通过网络实时下载的广告仍可能出现。",
        "This is the container's system-managed metadata file. iOS doesn't allow other processes to read its contents, so it can't be opened or edited here.": "这是容器由系统管理的元数据文件。iOS 不允许其他进程读取其内容，因此无法在此打开或编辑。",
        "This only clears the list. It does not undo anything that was applied.": "这只会清除列表，不会撤销任何已应用的内容。",
        "This only makes the Join Waitlist button appear. The Siri AI model may still refuse to download — that part is not solved by this method yet.": "这只会让 Join Waitlist 按钮出现。Siri AI 模型仍可能拒绝下载——该方法尚未解决这一部分。",
        "This package was rejected": "此安装包已被拒绝",
        "This permanently deletes the contents of %@ in %@ (%@). The folders themselves stay in place.": "这将永久删除 %@ 中 %@（%@）的内容。文件夹本身会保留。",
        "This property list has no top-level entries.": "此属性列表没有顶级条目。",
        "This removes the wallpaper imported from %@ — its descriptor folder is deleted from PosterBoard's data store.": "这将删除从 %@ 导入的壁纸——其描述符文件夹会从 PosterBoard 数据存储中删除。",
        "This restores the MobileGestalt backup saved on first launch (SavedGestalt.plist).": "这将恢复首次启动时保存的 MobileGestalt 备份 (SavedGestalt.plist)。",
        "This table has no columns to edit.": "此表没有可编辑的列。",
        "Total CacheExtra keys": "CacheExtra 键总数",
        "True health": "真实健康度",
        "Try Again": "重试",
        "Turn on the Charge Limit Menu toggle (Add feature section).": "开启 Charge Limit Menu 开关（Add feature 部分）。",
        "Tutorials": "教程",
        "Tweaks": "调整",
        "Tweaks Applied": "已应用调整",
        "Tweaks UI": "Tweaks 界面",
        "Tweaks are locked": "调整已锁定",
        "Two ways to get a pairing file: Pair This iPhone (iOS 27 only) shows a 6-digit PIN — approve it in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. Or import a pairing file (.plist) from your computer manually. The pairing file is saved in the app.": "获取配对文件有两种方式：Pair This iPhone（仅限 iOS 27）会显示 6 位 PIN——请在 Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks 中批准。或者从您的电脑手动导入配对文件（.plist）。配对文件保存在应用中。",
        "Type": "类型",
