        "Warning": "警告",
        "Warning: raw byte edits have no structure validation — a wrong byte can corrupt this file or the owning app's data. A backup of the original is saved before the first edit.": "警告：原始字节编辑没有结构验证——一个错误的字节可能会损坏此文件或所属应用的数据。在首次编辑前会保存原始文件的备份。",
        "WeChat accounts": "微信账号",
        "Welcome to WorkTweaks": "欢迎使用 WorkTweaks",
        "What this does": "此功能的作用",
        "When enabled, MobileGestalt is written in-place on the same inode, which (hopefully) prevents iOS from regenerating the cache on reboot. Disable to use atomic file replacement instead.": "启用后，MobileGestalt 会在同一 inode 上原地写入，这（有望）可以防止 iOS 在重启时重新生成缓存。禁用则改用原子文件替换。",
