        "Wi-Fi File Sharing": "Wi-Fi 文件共享",
        "WorkTweaks is free software under the GNU Affero General Public License v3.0. The core (worse_query) is GPL-3.0, but the CacheExtra key knowledge from mond and the CacheData method from Nugget are AGPL-3.0 — GPLv3 code may be combined into an AGPLv3 work, and the AGPL terms then cover the combined work as a whole.": "WorkTweaks 是遵循 GNU Affero General Public License v3.0 的自由软件。核心（worse_query）为 GPL-3.0，但来自 mond 的 CacheExtra 键知识和来自 Nugget 的 CacheData 方法为 AGPL-3.0——GPLv3 代码可以合并到 AGPLv3 作品中，AGPL 条款随后涵盖整个合并作品。",
        "WorkTweaks must be installed with iLoader, or by signing the IPA with Signed Apps, so that its App Group works correctly.": "WorkTweaks 必须使用 iLoader 安装，或使用 Signed Apps 签署 IPA，这样其 App Group 才能正常工作。",
        "WorkTweaks only works when its App Group is part of the signing profile. Guides A and B make sure that happens — pick the one that fits you. Guide C turns on the new Siri AI.": "只有当 App Group 包含在签名描述文件中时，WorkTweaks 才能正常工作。指南 A 和 B 可以确保这一点——请选择适合您的一份。指南 C 用于开启新的 Siri AI。",
        "WorkTweaks v3.0 only opens on the builds listed above: the app checks your device's build at launch, and any other build gets the \"not supported\" screen instead of the app. On iOS 18 and iOS 26, only App Data and Airlift are supported (partial support). Developed and tested on iOS 27.0.1 (24A446).": "WorkTweaks v3.0 仅在上方列出的构建上打开：应用会在启动时检查您设备的构建，任何其他构建都会显示 \"not supported\" 屏幕。在 iOS 18 和 iOS 26 上，仅支持 App Data 和 Airlift（部分支持）。在 iOS 27.0.1 (24A446) 上开发和测试。",
        "Works on iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 and later patched the exploit).": "适用于 iOS 18.0 – 27.2 beta 2（iOS 27.2 beta 3 及更高版本已修复此漏洞）。",
        "Write Method": "写入方式",
        "Write access available — Clean All can delete the listed reports.": "写入权限可用——Clean All 可以删除所列报告。",
        "Writes SharedDeviceConfiguration.plist in place, keeping every other key in the file. SpringBoard reads the file when it starts, so a respring or restart is needed to see the change.": "就地写入 SharedDeviceConfiguration.plist，保留文件中的所有其他键。SpringBoard 启动时会读取该文件，因此需要执行 respring 或重启才能看到更改。",
        "Writing or verifying the file failed — the details are in the Log.": "写入或验证文件失败——详情记录在日志中。",
