        "1. Open the Translate app, delete the downloaded English (US) language, then download it again.\n2. Go to Settings > General > Language & Region, change the region from United States to another country, then change it back to United States.\n3. Turn off Low Power Mode (Settings > Battery).\n4. Connect to Wi-Fi (and keep your iPhone charging) while Apple Intelligence finishes downloading.": "1. Mở ứng dụng Translate, xóa ngôn ngữ English (US) đã tải xuống, rồi tải lại.\n2. Vào Settings > General > Language & Region, đổi vùng từ United States sang một quốc gia khác, rồi đổi lại thành United States.\n3. Tắt Chế độ nguồn điện thấp (Settings > Battery).\n4. Kết nối Wi-Fi (và giữ iPhone đang sạc) trong khi Apple Intelligence hoàn tất tải xuống.",
