        "2. On this iPhone, double-click the Side button (Apple Pay), authenticate with Face ID, and tap your card.": "2. Trên iPhone này, nhấn đúp nút Side (Apple Pay), xác thực bằng Face ID rồi chạm vào thẻ của bạn.",
        "3. Your card will appear here automatically!": "3. Thẻ của bạn sẽ tự động xuất hiện tại đây!",
        "A .tendies package is a ZIP archive containing one or more wallpaper descriptors: loose descriptor folders, a descriptors folder, or a container layout mirroring PosterBoard's data store (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Stored and deflated ZIP entries are supported — the same reader Deploy uses; encrypted and ZIP64 archives are rejected.": "Gói .tendies là một tệp ZIP chứa một hoặc nhiều mô tả hình nền: các thư mục mô tả rời, thư mục descriptors, hoặc bố cục container giống kho dữ liệu của PosterBoard (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Hỗ trợ các mục ZIP đã lưu trữ và đã nén — cùng trình đọc mà Deploy dùng; các tệp ZIP đã mã hóa và ZIP64 sẽ bị từ chối.",
        "A Deploy package replaces files inside exactly one app — the app named by its bundle ID. It cannot touch any other app: every target path is relative to that app's container, and packages with absolute or \"..\" paths are rejected whole.": "Gói Deploy thay thế các tệp bên trong đúng một ứng dụng — ứng dụng được chỉ định bởi bundle ID của nó. Nó không thể chạm vào bất kỳ ứng dụng nào khác: mọi đường dẫn đích đều tương đối so với container của ứng dụng đó, và các gói có đường dẫn tuyệt đối hoặc \"..\" sẽ bị từ chối toàn bộ.",
        "A MobileGestalt tweak app for iOS 26/27, built on the open-source projects credited below. Use at your own risk — tweaks modify system files.": "Ứng dụng tinh chỉnh MobileGestalt cho iOS 26/27, được xây dựng dựa trên các dự án mã nguồn mở được ghi công bên dưới. Sử dụng với rủi ro của riêng bạn — các tinh chỉnh sẽ sửa đổi tệp hệ thống.",
        "A MobileGestalt tweak tool for iOS 26 & 27 — unlock your device's hidden features without a jailbreak, powered by the worse_query sandbox escape.": "Công cụ tinh chỉnh MobileGestalt cho iOS 26 & 27 — mở khóa các tính năng ẩn của thiết bị mà không cần jailbreak, được hỗ trợ bởi worse_query sandbox escape.",
        "A bundle ID is required — it names the one app this package may touch.": "Cần có bundle ID — nó chỉ định ứng dụng duy nhất mà gói này được phép chạm vào.",
        "A package is ONE .zip file containing a manifest.json at its top level plus the payload files it names. The Package Builder exports that zip (save it in Files); Deploy imports it, resolves the target itself from the manifest, and applies it — no location picking, the destinations come from the zip.": "Một gói là MỘT tệp .zip chứa manifest.json ở cấp cao nhất cùng với các tệp payload mà nó liệt kê. Package Builder xuất tệp zip đó (hãy lưu trong Files); Deploy nhập nó, tự xác định đích từ manifest và áp dụng — không cần chọn vị trí, đích đến lấy từ tệp zip.",
        "A partial restore can affect photos and videos. Back them up first — optional, you can skip it.": "Khôi phục một phần có thể ảnh hưởng đến ảnh và video. Hãy sao lưu trước — tùy chọn, bạn có thể bỏ qua.",
        "A respring is required before a new wallpaper appears in the gallery.": "Cần respring trước khi hình nền mới xuất hiện trong thư viện.",
        "A signed IPA only works on the device registered in its profile.": "IPA đã ký chỉ hoạt động trên thiết bị đã đăng ký trong hồ sơ của nó.",
        "A snapshot is also created automatically at every Apply, containing the state that Apply just produced. The Original backup is created once, the first time MobileGestalt is read successfully.": "Một ảnh chụp nhanh cũng được tạo tự động mỗi lần Apply, chứa trạng thái mà lần Apply đó vừa tạo ra. Bản sao lưu Original chỉ được tạo một lần, vào lần đầu tiên MobileGestalt được đọc thành công.",
        "A whitelisted bundle id (and its App Groups) or exact path is never locked by Lock All. Newly whitelisted targets are restored writable right away. SMZDM is whitelisted by default — its splash cache is known to crash the app when locked.": "Bundle id trong danh sách trắng (và các App Groups của nó) hoặc đường dẫn chính xác sẽ không bao giờ bị Lock All khóa. Các mục tiêu mới được đưa vào danh sách trắng sẽ được khôi phục quyền ghi ngay lập tức. SMZDM được đưa vào danh sách trắng theo mặc định — bộ nhớ đệm splash của nó được biết là gây crash ứng dụng khi bị khóa.",
        "AI Cache": "Bộ nhớ đệm AI",
        "APFS vault: clonefile staging, zero extra space, atomic restore with rollback. ZIP backup: the same three folders as one .zip file, restored by merging in place.": "APFS vault: staging bằng clonefile, không tốn thêm dung lượng, khôi phục nguyên tử với rollback. Sao lưu ZIP: ba thư mục tương tự trong một tệp .zip, khôi phục bằng cách hợp nhất tại chỗ.",
