        "BackUP_Data folder, inside the WorkTweaks folder (Documents). You can browse it in the Files app.": "Thư mục BackUP_Data, bên trong thư mục WorkTweaks (Documents). Bạn có thể duyệt nó trong ứng dụng Files.",
