        "Cache Locations": "Vị trí bộ nhớ đệm",
        "Cache lives in two places inside an app's data container: Library/Caches and tmp. Only the contents of those two folders are deleted — the folders themselves stay, and Documents and the rest of Library are never touched.": "Cache nằm ở hai nơi trong container dữ liệu của ứng dụng: Library/Caches và tmp. Chỉ nội dung của hai thư mục đó bị xóa — bản thân các thư mục vẫn còn, và Documents cùng phần còn lại của Library không bao giờ bị động đến.",
        "Cancel": "Hủy",
