        "Cleaning is permanent — cache is not backed up. The app itself, its documents, and its settings are not affected.": "Việc dọn dẹp là vĩnh viễn — bộ nhớ đệm không được sao lưu. Bản thân ứng dụng, tài liệu và cài đặt của nó không bị ảnh hưởng.",
