        "Connect your iPhone to power, connect to Wi-Fi, and leave the Settings → General → iPhone Storage tab open for about 1 hour while the model downloads.": "Cắm sạc iPhone của bạn, kết nối Wi-Fi và để tab Settings → General → iPhone Storage mở trong khoảng 1 giờ trong khi mô hình đang tải xuống.",
