        "Disable Dynamic Island": "Tắt Dynamic Island",
        "Disable Dynamic Island System": "Tắt hệ thống Dynamic Island",
        "Disables the Dynamic Island system completely — not just hiding it. Key: SBSuppressDynamicIslandCompletely in the managed com.apple.springboard.plist (set = 1).": "Tắt hoàn toàn hệ thống Dynamic Island — không chỉ ẩn nó. Key: SBSuppressDynamicIslandCompletely trong com.apple.springboard.plist được quản lý (đặt = 1).",
        "Do not reboot! Your MobileGestalt.plist seems to be %@.": "Đừng khởi động lại! MobileGestalt.plist của bạn có vẻ %@.",
        "Done": "Xong",
        "Download the WorkTweaks IPA from GitHub.": "Tải IPA WorkTweaks từ GitHub.",
        "Download the latest WorkTweaks IPA from the GitHub Releases page.": "Tải IPA WorkTweaks mới nhất từ trang GitHub Releases.",
        "Drag to move, pinch to zoom. The skin is saved at 1536×969.": "Kéo để di chuyển, chụm để phóng to. Skin được lưu ở kích thước 1536×969.",
        "Dual SIM: primary is the line used for data, secondary is the other line.": "Dual SIM: chính là đường dây dùng cho dữ liệu, phụ là đường dây còn lại.",
        "Dynamic Island": "Dynamic Island",
        "Each wallpaper in the package is copied into PosterBoard's data store under a fresh identifier, so it can never clash with an existing wallpaper. A respring is required before a new wallpaper appears in the gallery.": "Mỗi hình nền trong gói được sao chép vào kho dữ liệu của PosterBoard với một định danh mới, nên không bao giờ xung đột với hình nền hiện có. Cần respring trước khi hình nền mới xuất hiện trong thư viện.",
        "Edit": "Sửa",
        "Edit Bytes": "Chỉnh sửa byte",
        "Edit Cell": "Sửa ô",
        "Edit Package": "Sửa gói",
        "Edit Value": "Sửa giá trị",
        "Edit in Theme Creator": "Chỉnh sửa trong Theme Creator",
        "Edits replace byte values only — the file's length never changes. A backup of the original is saved before the first edit.": "Chỉnh sửa chỉ thay thế giá trị byte — độ dài tệp không bao giờ thay đổi. Bản sao lưu của tệp gốc được lưu trước lần chỉnh sửa đầu tiên.",
        "Elements": "Phần tử",
        "Eligibility": "Đủ điều kiện",
        "Empty": "Trống",
        "Enter this PIN in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks.": "Nhập mã PIN này trong Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks.",
        "Enumerating containers with pathleak — this can take a while.": "Đang liệt kê các container bằng pathleak — việc này có thể mất một lúc.",
        "Enumeration": "Liệt kê",
        "Error -1 means the signed app cannot access its App Group container. Diagnostics reads the groups from your signed provisioning profile and probes them all. If it reports no signed groups, the IPA was signed without an App Group and must be re-signed with one — no name typed here can fix that.": "Lỗi -1 nghĩa là ứng dụng đã ký không thể truy cập vùng chứa App Group của nó. Chẩn đoán đọc các nhóm từ hồ sơ cấp phép đã ký và kiểm tra tất cả. Nếu không báo cáo nhóm đã ký nào, IPA đã được ký mà không có App Group và phải ký lại với App Group — nhập tên nào ở đây cũng không sửa được.",
        "Escape": "Thoát",
        "Every menu that was applied, newest first. This is a history log — clearing it only clears the list, it does not undo anything.": "Mọi menu đã được áp dụng, mới nhất lên đầu. Đây là nhật ký lịch sử — xóa nó chỉ xóa danh sách, không hoàn tác bất cứ điều gì.",
        "Exact path": "Đường dẫn chính xác",
        "Expired %@ — reinstall the app first.": "Đã hết hạn %@ — hãy cài đặt lại ứng dụng trước.",
        "Expires soon — %@. Stage now, reinstall before it ends.": "Sắp hết hạn — %@. Hãy lưu tạm ngay, cài đặt lại trước khi hết hạn.",
        "Export": "Xuất",
        "Export Selected (%d)": "Xuất mục đã chọn (%d)",
        "Export ZIP": "Xuất ZIP",
        "Export the signed IPA and install it with ESign (or any IPA installer).": "Xuất IPA đã ký rồi cài đặt bằng ESign (hoặc bất kỳ trình cài IPA nào).",
        "Exported as .m4a files with their original titles, zipped to this app's Documents/VoiceMemosExports. The recordings database is only ever read — never written.": "Xuất dưới dạng tệp .m4a với tiêu đề gốc, nén vào Documents/VoiceMemosExports của ứng dụng này. Cơ sở dữ liệu bản ghi chỉ được đọc — không bao giờ ghi.",
        "Exporting…": "Đang xuất…",
        "Extra": "Mở rộng",
        "Fake-Supervision Residue": "Dư lượng giám sát giả",
        "Fast mode selected: only targets %@ with %@.": "Đã chọn chế độ nhanh: chỉ nhắm tới %@ với %@.",
        "File": "Tệp",
        "Filename": "Tên tệp",
        "Files & Sharing": "Tệp & Chia sẻ",
