        "First Bytes": "Byte đầu tiên",
        "Fix Apple Intelligence": "Sửa Apple Intelligence",
        "Fix Apple Intelligence Here!": "Sửa Apple Intelligence tại đây!",
        "Fix Status Bar": "Sửa thanh trạng thái",
        "Fix Status Bar!": "Sửa thanh trạng thái!",
        "Flash": "Flash",
        "Flash & Language Target": "Mục tiêu Flash & Ngôn ngữ",
        "Flash Log (%d lines)": "Nhật ký Flash (%d dòng)",
        "Flash Selected Cards": "Flash các thẻ đã chọn",
        "Flash Theme to iPhone": "Flash chủ đề vào iPhone",
        "Flashing Theme…": "Đang flash chủ đề…",
        "Flashing needs a pairing file and the VPN tunnel. Pair first and connect the VPN in Sandbox → Utilities → Get Pairing File + VPN Status, then come back here.": "Flash cần tệp ghép nối và đường hầm VPN. Hãy ghép nối trước và kết nối VPN trong Sandbox → Utilities → Get Pairing File + VPN Status, rồi quay lại đây.",
        "Flashing needs a pairing file. Pair this iPhone first in Sandbox → Utilities → Get Pairing File.": "Flash cần tệp ghép nối. Hãy ghép nối iPhone này trước trong Sandbox → Utilities → Get Pairing File.",
        "Flashing needs the VPN tunnel. Open the Local Dev VPN app and connect first.": "Flash cần đường hầm VPN. Hãy mở ứng dụng Local Dev VPN và kết nối trước.",
        "Flashing…": "Đang flash…",
        "Folder name": "Tên thư mục",
        "Follow for updates, demos and new tweaks.": "Theo dõi để nhận cập nhật, bản demo và tinh chỉnh mới.",
        "Font Weight / Style": "Độ đậm / Kiểu chữ",
        "Footnote": "Footnote",
        "Footnote Updated": "Đã cập nhật Footnote",
        "Footnote text": "Văn bản footnote",
        "For AppGroup scope, the target is the App Group identifier (for example group.com.example) — type it here.": "Đối với phạm vi AppGroup, đích là mã định danh App Group (ví dụ group.com.example) — hãy nhập tại đây.",
        "Force-close the Wallet app from the App Switcher after flashing to see the new card art.": "Buộc đóng ứng dụng Wallet từ App Switcher sau khi flash để xem hình ảnh thẻ mới.",
        "Forces the label shown (5G, 5G+, 5G UC, LTE, …). Limited — the label is display-only.": "Ép nhãn hiển thị (5G, 5G+, 5G UC, LTE, …). Có giới hạn — nhãn chỉ để hiển thị.",
        "Free Apple ID installs expire after about 7 days — reinstall with iLoader to renew.": "Bản cài bằng Apple ID miễn phí hết hạn sau khoảng 7 ngày — hãy cài lại bằng iLoader để gia hạn.",
        "Freed %@": "Đã giải phóng %@",
        "Genuine MDM": "MDM thật",
        "Get Pairing + VPN Tunnel": "Lấy ghép nối + đường hầm VPN",
        "Get Pairing File": "Lấy tệp ghép nối",
        "Get Pairing File + Local Dev VPN tunnel — the on-device pairing Airlift uses to reach the device.": "Get Pairing File + đường hầm Local Dev VPN — quá trình ghép nối trên thiết bị mà Airlift dùng để tiếp cận thiết bị.",
        "Get Pairing File + VPN Status": "Lấy tệp ghép nối + Trạng thái VPN",
        "Get Started": "Bắt đầu",
        "Go to Sandbox Tab": "Mở tab Sandbox",
        "Go to the Apply/Revert section and tap Apply, then Respring. When the respring finishes, restart your iPhone.": "Đi tới phần Apply/Revert rồi nhấn Apply, sau đó Respring. Khi respring xong, hãy khởi động lại iPhone của bạn.",
        "Go to the Sandbox tab and turn on Start Tweaks Feature to unlock the Tweaks tab.": "Mở tab Sandbox và bật Start Tweaks Feature để mở khóa tab Tweaks.",
        "Good to Know": "Cần biết",
        "Grant refused — size unknown.": "Quyền bị từ chối — không rõ kích thước.",
        "Granting sandbox access…": "Đang cấp quyền truy cập sandbox…",
        "Guide A — Install with iLoader (Desktop)": "Hướng dẫn A — Cài đặt bằng iLoader (Máy tính)",
        "Guide B — Sign with Signed Apps (Mobile)": "Hướng dẫn B — Ký bằng Signed Apps (Di động)",
        "Guide C — Turn On New Siri AI": "Hướng dẫn C — Bật Siri AI mới",
        "Harden": "Củng cố",
