        "Import Pairing File": "Nhập tệp ghép nối",
        "Import ZIP Backup…": "Nhập bản sao lưu ZIP…",
        "Imported": "Đã nhập",
        "In the Tweaks tab, Apple Intelligence section, turn on Apple Intelligence and Siri AI Cache Patch. The cache patch is the Filza line-104 edit (one CacheData byte, 0x00 to 0x02) — done here, no Filza needed.": "Trong tab Tweaks, mục Apple Intelligence, hãy bật Apple Intelligence và Siri AI Cache Patch. Bản vá cache là thao tác chỉnh sửa dòng 104 trong Filza (một byte CacheData, từ 0x00 thành 0x02) — thực hiện ngay tại đây, không cần Filza.",
        "Individual Keys": "Các khóa riêng lẻ",
        "Install tab → Provisioning: fill in the fields below, tap Provision, and wait for \"profile OK\". Your Team ID is shown in the app's Certificates tab.": "Tab Install → Provisioning: điền các trường bên dưới, nhấn Provision và chờ \"profile OK\". Team ID của bạn hiển thị trong tab Certificates của ứng dụng.",
        "Installation": "Cài đặt",
        "Installed Profiles": "Hồ sơ đã cài đặt",
        "Installed any other way, the signed profile leaves the App Group out — and without it, the tweaks can't run. Tap Tutorials below for both step-by-step guides.": "Nếu cài đặt bằng cách khác, hồ sơ đã ký sẽ thiếu App Group — và nếu không có nó, các tinh chỉnh không thể chạy. Nhấn Tutorials bên dưới để xem cả hai hướng dẫn từng bước.",
        "Installing into PosterBoard…": "Đang cài vào PosterBoard…",
        "Internal": "Nội bộ",
        "Jetsam & Crash": "Jetsam & Crash",
        "Jetsam & Crash lists the reports iOS writes when it kills an app for memory (Jetsam, bug_type 298), when an app crashes (309), or on a watchdog / kernel panic (210). Open a report to see why it died, share the full file, or clean all reports to free space.": "Jetsam & Crash liệt kê các báo cáo iOS ghi khi tắt ứng dụng do bộ nhớ (Jetsam, bug_type 298), khi ứng dụng crash (309), hoặc khi watchdog / kernel panic (210). Mở báo cáo để xem lý do, chia sẻ toàn bộ tệp, hoặc dọn tất cả báo cáo để giải phóng dung lượng.",
        "Key": "Khóa",
