        "Lock Screen Footnote is unavailable": "Footnote Màn hình khóa không khả dụng",
        "Lock Screen Preview": "Xem trước Màn hình khóa",
        "Locked folders are read-only (0555) with a sentinel file inside; config files are emptied and locked (0444). A Weak Lock is a locked folder missing its sentinel — tap Harden to add it.": "Thư mục đã khóa ở chế độ chỉ đọc (0555) với một tệp sentinel bên trong; tệp cấu hình bị dọn sạch và khóa (0444). Weak Lock là thư mục đã khóa nhưng thiếu sentinel — chạm Harden để thêm.",
        "Locks every target below that still needs action. Whitelisted targets are always skipped.": "Khóa mọi mục tiêu bên dưới vẫn cần xử lý. Các mục tiêu trong danh sách trắng luôn được bỏ qua.",
