        "Nested dictionaries, arrays and Data are shown read-only — the editor never rewrites a structure it cannot show.": "Các dictionary, mảng và Data lồng nhau chỉ hiển thị ở chế độ chỉ đọc — trình chỉnh sửa không bao giờ ghi lại cấu trúc mà nó không thể hiển thị.",
