        "Old UI": "Giao diện cũ",
        "On": "Bật",
        "On a computer, download iLoader from iloader.app — the official site only — and open it.": "Trên máy tính, tải iLoader từ iloader.app — chỉ trang web chính thức — rồi mở nó.",
        "On in this backup": "Đang bật trong bản sao lưu này",
        "One of the destination paths is invalid.": "Một trong các đường dẫn đích không hợp lệ.",
        "Only files under Library/Caches inside the listed targets are deleted. AI models are never touched, and caches regenerate when the apps run again.": "Chỉ các tệp trong Library/Caches bên trong các mục tiêu được liệt kê mới bị xóa. Các mô hình AI không bao giờ bị chạm tới và bộ nhớ đệm sẽ được tạo lại khi ứng dụng chạy lại.",
        "Only spoof your device model if you want to download Apple Intelligence. This may break Face ID. If you decide to unspoof and want to keep Apple Intelligence, do NOT re-enter the Apple Intelligence & Siri menu in Settings.": "Chỉ giả mạo model thiết bị nếu bạn muốn tải xuống Apple Intelligence. Việc này có thể làm hỏng Face ID. Nếu bạn quyết định ngừng giả mạo và muốn giữ Apple Intelligence, KHÔNG vào lại menu Apple Intelligence & Siri trong Settings.",
        "Only the listed .ips / .crash / .panic files under DiagnosticReports (and Retired) are ever deleted. The folders themselves are kept, and nothing else is touched.": "Chỉ các tệp .ips / .crash / .panic được liệt kê trong DiagnosticReports (và Retired) mới bị xóa. Bản thân các thư mục được giữ lại và không chạm vào bất cứ thứ gì khác.",
        "Open App Data first so the container scan runs, then come back — or tap Rescan.": "Hãy mở App Data trước để quá trình quét vùng chứa chạy, rồi quay lại — hoặc chạm Rescan.",
        "Open Settings → Apple Intelligence & Siri and tap Join Waitlist. Wait about 15 minutes for it to be accepted.": "Mở Settings → Apple Intelligence & Siri rồi nhấn Join Waitlist. Chờ khoảng 15 phút để được chấp nhận.",
        "Open Signed Apps and sign in with your Apple ID.": "Mở Signed Apps rồi đăng nhập bằng Apple ID của bạn.",
        "Open Source": "Mã nguồn mở",
        "Open Tutorials": "Mở hướng dẫn",
        "Open WorkTweaks and you're done.": "Mở WorkTweaks là xong.",
        "Open as Property List": "Mở dưới dạng Property List",
        "Open as SQLite Database": "Mở dưới dạng cơ sở dữ liệu SQLite",
        "Open the Local Dev VPN app and connect. The tunnel shows as a utun interface on 10.7.x.x (gateway 10.7.0.1).": "Mở ứng dụng Local Dev VPN và kết nối. Đường hầm hiển thị dưới dạng giao diện utun trên 10.7.x.x (gateway 10.7.0.1).",
        "Opening the configuration profiles…": "Đang mở các hồ sơ cấu hình…",
        "Opening the database…": "Đang mở cơ sở dữ liệu…",
        "Opens an empty editor; the file is created when you save.": "Mở một trình chỉnh sửa trống; tệp sẽ được tạo khi bạn lưu.",
        "Opens the database as editable tables, with a backup taken before the first save. Close the owning app before editing.": "Mở cơ sở dữ liệu dưới dạng các bảng có thể chỉnh sửa, với bản sao lưu được tạo trước lần lưu đầu tiên. Hãy đóng ứng dụng sở hữu trước khi chỉnh sửa.",
        "Opens the property list as an editable key/type/value table, with a backup taken before the first save.": "Mở property list dưới dạng bảng khóa/kiểu/giá trị có thể chỉnh sửa, với bản sao lưu được tạo trước lần lưu đầu tiên.",
        "Optional label": "Nhãn tùy chọn",
        "Organization: %@": "Tổ chức: %@",
        "Original": "Gốc",
        "Original (%d)": "Gốc (%d)",
        "PIN": "PIN",
        "Package": "Gói",
        "Package Builder": "Trình tạo gói",
        "Package Format": "Định dạng gói",
        "Packages you build or import are stored on this device, in WorkTweaks' own container. Tap a package to edit it. Deploy runs it through the same preview, resolve and backup flow as a picked package.": "Các gói bạn tạo hoặc nhập được lưu trên thiết bị này, trong container riêng của WorkTweaks. Chạm vào một gói để chỉnh sửa. Deploy chạy gói qua cùng quy trình xem trước, xác định đích và sao lưu như một gói đã chọn.",
        "Pair This iPhone": "Ghép nối iPhone này",
        "Pairing & Airlift": "Ghép nối & Airlift",
        "Pairing cancelled.": "Đã hủy ghép nối.",
        "Pairing file": "Tệp ghép nối",
        "Pairing file imported.": "Đã nhập tệp ghép nối.",
        "Pairing file removed.": "Đã xóa tệp ghép nối.",
        "Pairing file saved to the app.": "Đã lưu tệp ghép nối vào ứng dụng.",
        "Parsed from the .plist files in the ConfigurationProfiles directory. This page never installs or removes a profile.": "Được phân tích từ các tệp .plist trong thư mục ConfigurationProfiles. Trang này không bao giờ cài đặt hay xóa hồ sơ.",
        "Partial — some icons may still show. Hidden through the archive's suppressed identifiers.": "Một phần — một số biểu tượng vẫn có thể hiển thị. Được ẩn qua các định danh bị chặn trong kho lưu trữ.",
        "Partially Supported": "Được hỗ trợ một phần",
        "Partially Supported iOS • %@": "iOS được hỗ trợ một phần • %@",
        "Passcode Theme": "Chủ đề mật mã",
        "Passcode Themes": "Chủ đề mật mã",
        "Passcode theme applied": "Đã áp dụng chủ đề mật mã",
        "Paste card hash": "Dán hash thẻ",
        "Path Enumeration": "Liệt kê đường dẫn",
        "Paths must be relative, non-empty and contain no \"..\" component.": "Đường dẫn phải tương đối, không rỗng và không chứa thành phần \"..\".",
        "Payload files are copied into the package. Add File accepts any file — a .plist is added as a payload, and a .zip is unpacked, each file inside becoming a payload with its destination defaulting to its path inside the archive. Destinations are relative paths only; absolute paths and \"..\" are rejected, exactly like an imported package.": "Các tệp payload được sao chép vào gói. Thêm tệp chấp nhận mọi tệp — tệp .plist được thêm dưới dạng payload, còn tệp .zip được giải nén, mỗi tệp bên trong trở thành một payload với đích mặc định là đường dẫn của nó trong kho lưu trữ. Đích chỉ được là đường dẫn tương đối; đường dẫn tuyệt đối và \"..\" bị từ chối, giống hệt như gói đã nhập.",
        "Persist after reboot": "Giữ nguyên sau khi khởi động lại",
        "Photo Library": "Thư viện ảnh",
        "Photo chosen — tap to change": "Đã chọn ảnh — nhấn để đổi",
        "Photos & Videos": "Ảnh & Video",
        "Pick Target App": "Chọn ứng dụng đích",
        "Pick an app": "Chọn ứng dụng",
        "Pick an app to see its cache and clean it.": "Chọn một ứng dụng để xem bộ nhớ đệm của nó và dọn dẹp.",
        "Pick from App Data scan…": "Chọn từ lần quét Dữ liệu ứng dụng…",
        "Pick the WorkTweaks IPA, set the Signing Bundle ID field to the same identifier, then tap Sign IPA.": "Chọn IPA WorkTweaks, đặt trường Signing Bundle ID thành cùng định danh đó rồi nhấn Sign IPA.",
        "Pick the photos and videos you want to keep, then Save. They are copied into the BackUP_Data folder inside the app. Optional — you can skip this.": "Chọn ảnh và video bạn muốn giữ, rồi Lưu. Chúng được sao chép vào thư mục BackUP_Data bên trong ứng dụng. Tùy chọn — bạn có thể bỏ qua bước này.",
        "Plays a soft sound when you tap menus and features. Respects the silent switch.": "Phát âm thanh nhẹ khi bạn mở menu và tính năng. Tôn trọng công tắc im lặng.",
        "Please Install It the Right Way": "Vui lòng cài đặt đúng cách",
