        "Raw max capacity": "Dung lượng tối đa thô",
        "Read": "Đọc",
        "Read Powerlog": "Đọc Powerlog",
        "Read complete%@%@.": "Đọc xong%@%@.",
        "Read-only mode — the grant did not include write access, so Clean All is disabled.": "Chế độ chỉ đọc — quyền được cấp không bao gồm quyền ghi, vì vậy Clean All bị tắt.",
        "Read-only: the powerlog is cloned into this app's temp folder and inspected there. Nothing is ever written to the system database. Some iOS 26 firmware restricts the powerlog sandbox token; iOS 27 reads fully.": "Chỉ đọc: powerlog được sao chép vào thư mục tạm của ứng dụng này và kiểm tra tại đó. Không bao giờ ghi gì vào cơ sở dữ liệu hệ thống. Một số firmware iOS 26 hạn chế token sandbox của powerlog; iOS 27 đọc đầy đủ.",
        "Reading the configuration profiles…": "Đang đọc các hồ sơ cấu hình…",
        "Reading the property list…": "Đang đọc property list…",
        "Reading the recordings database…": "Đang đọc cơ sở dữ liệu bản ghi…",
        "Reading video frames…": "Đang đọc khung hình video…",
        "Reading…": "Đang đọc…",
        "Rebooting now might cause a bootloop. Try pressing 'Revert Tweaks'.": "Khởi động lại ngay có thể gây bootloop. Hãy thử nhấn 'Khôi phục tinh chỉnh'.",
        "Recent Requests": "Yêu cầu gần đây",
        "Recent samples (%d)": "Mẫu gần đây (%d)",
        "Reference": "Tham khảo",
        "Reference & Patch Files": "Tham khảo & Tệp bản vá",
        "Reference — APFS save-vault idea (clonefile staging, atomic swap with rollback).": "Tham khảo — ý tưởng kho lưu APFS (clonefile staging, hoán đổi nguyên tử kèm rollback).",
        "Reference — PosterBoard wallpaper format the maker was verified against.": "Tham khảo — định dạng hình nền PosterBoard mà trình tạo đã được kiểm chứng theo.",
        "Reference — Splash Ad Cache Lock mechanism (ad SDK cache lock, save vault, diagnostics, Wi-Fi file sharing, Voice Memos export, AI cache probes).": "Tham khảo — cơ chế Splash Ad Cache Lock (khóa cache SDK quảng cáo, kho lưu, chẩn đoán, chia sẻ tệp Wi-Fi, xuất Voice Memos, dò cache AI).",
        "Reference — cache data cleaner": "Tham khảo — trình dọn cache data",
        "Reference — turn on new Siri AI (CacheData line edit + device spoof)": "Tham khảo — bật Siri AI mới (chỉnh sửa dòng CacheData + giả mạo thiết bị)",
        "Reference — video-to-wallpaper (CAML) builder used by the PosterBoard wallpaper maker.": "Tham khảo — trình tạo video thành hình nền (CAML) được trình tạo hình nền PosterBoard dùng.",
