        "Respring": "Respring",
        "Respring did not trigger on this device.": "Respring không kích hoạt trên thiết bị này.",
        "Restart Device": "Khởi động lại thiết bị",
        "Restart Required": "Cần khởi động lại",
        "Restore": "Khôi phục",
        "Restore (%d)": "Khôi phục (%d)",
        "Restore Backup": "Khôi phục bản sao lưu",
        "Restore Everything": "Khôi phục tất cả",
        "Restore Result — %d succeeded, %d failed": "Kết quả khôi phục — %d thành công, %d thất bại",
        "Restore a ZIP backup": "Khôi phục bản sao lưu ZIP",
        "Restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "Các thay đổi khi khôi phục chỉ có hiệu lực sau khi khởi động lại toàn bộ thiết bị — respring là không đủ. Chọn Để sau chỉ hoãn lại; các thay đổi vẫn chờ cho đến khi bạn khởi động lại.",
        "Restore into…": "Khôi phục vào…",
        "Restore swaps the staged copy into the app's current container and rolls back if anything fails. Release a snapshot only after you verified the restore in the app.": "Khôi phục sẽ hoán đổi bản sao đã lưu tạm vào vùng chứa hiện tại của ứng dụng và rollback nếu có lỗi. Chỉ giải phóng ảnh chụp sau khi bạn đã xác minh việc khôi phục trong ứng dụng.",
        "Restore the backup?": "Khôi phục bản sao lưu?",
        "Restore this entire backup?": "Khôi phục toàn bộ bản sao lưu này?",
        "Restoring ZIP…": "Đang khôi phục ZIP…",
        "Restoring the backup failed — the details are in the Log.": "Khôi phục bản sao lưu thất bại — chi tiết nằm trong Nhật ký.",
        "Restoring writes each backed-up file back in place. Files the deploy created (they did not exist before) are deleted again.": "Khôi phục ghi từng tệp đã sao lưu trở lại vị trí cũ. Các tệp do lần triển khai tạo ra (trước đó không tồn tại) sẽ bị xóa lại.",
        "Restoring…": "Đang khôi phục…",
        "Result — %d succeeded, %d failed": "Kết quả — %d thành công, %d thất bại",
        "Retry Flash": "Thử flash lại",
        "Retry Flash Theme": "Thử flash chủ đề lại",
        "Revert": "Khôi phục",
        "Revert Tweaks": "Khôi phục tinh chỉnh",
        "Revert all tweaks?": "Khôi phục tất cả tinh chỉnh?",
        "Revert and restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "Các thay đổi khôi phục chỉ có hiệu lực sau khi khởi động lại toàn bộ thiết bị — chỉ respring là không đủ. Chọn “Để sau” chỉ hoãn lại; các thay đổi vẫn chờ cho đến khi bạn khởi động lại.",
        "Rewrites the entire MobileGestalt.plist from this backup. A device restart is required after restoring.": "Ghi lại toàn bộ MobileGestalt.plist từ bản sao lưu này. Cần khởi động lại thiết bị sau khi khôi phục.",
        "Running": "Đang chạy",
        "Sampled": "Đã lấy mẫu",
        "Sandbox access denied": "Quyền truy cập Sandbox bị từ chối",
