        "Set Skin for All Cards…": "Đặt skin cho tất cả thẻ…",
        "Set the Spoofing picker (under Apple Intelligence) to iPhone 17 Pro (iPhone18,1).": "Đặt bộ chọn Spoofing (dưới Apple Intelligence) thành iPhone 17 Pro (iPhone18,1).",
        "Sets how many bars are drawn. Static — it does not follow the real signal.": "Đặt số vạch được vẽ. Tĩnh — không theo tín hiệu thực.",
        "Share %@": "Chia sẻ %@",
        "Share Contents": "Chia sẻ nội dung",
        "Share Full Report": "Chia sẻ toàn bộ báo cáo",
        "Showing the first %@ of %@ rows — the editor is for targeted edits, not bulk dumps.": "Đang hiển thị %@ hàng đầu trong số %@ hàng — trình chỉnh sửa dùng cho các chỉnh sửa có mục tiêu, không phải xuất hàng loạt.",
        "Shows the battery percentage in the status bar. Key: SBShowBatteryPercentage in com.apple.springboard.plist.": "Hiển thị phần trăm pin trên thanh trạng thái. Key: SBShowBatteryPercentage trong com.apple.springboard.plist.",
        "Sign In": "Đăng nhập",
        "Signal Bars": "Vạch sóng",
        "Signal bars (Primary)": "Vạch sóng (Chính)",
        "Signal bars (Secondary)": "Vạch sóng (Phụ)",
        "Single-file shorthand: instead of \"files\", give \"relativePath\" and \"file\". \"scope\" is Application (bundleID = the app's bundle ID), AppGroup (bundleID = the group identifier, e.g. group.com.example) or InternalDaemon. ZIP archives may use stored or deflated entries; encrypted and ZIP64 archives are not supported. Older .deploy archives and plain folders still import.": "Cách viết tắt một tệp: thay vì \"files\", hãy dùng \"relativePath\" và \"file\". \"scope\" là Application (bundleID = bundle ID của ứng dụng), AppGroup (bundleID = mã định danh nhóm, ví dụ group.com.example) hoặc InternalDaemon. Kho lưu trữ ZIP có thể dùng các mục stored hoặc deflated; không hỗ trợ kho đã mã hóa và ZIP64. Các kho .deploy cũ và thư mục thường vẫn nhập được.",
        "Size": "Kích thước",
        "Sizes are measured by walking each folder. An app recreates cache as it runs, so the size grows back over time.": "Kích thước được đo bằng cách duyệt từng thư mục. Ứng dụng sẽ tạo lại cache khi chạy nên kích thước sẽ tăng trở lại theo thời gian.",
        "Sizes are probed read-only (depth 4). Delete Cache removes only files under Library/Caches inside these targets — the AI models live elsewhere and are never touched.": "Kích thước được dò ở chế độ chỉ đọc (độ sâu 4). Delete Cache chỉ xóa các tệp trong Library/Caches bên trong các mục tiêu này — các mô hình AI nằm ở nơi khác và không bao giờ bị chạm tới.",
        "Snapshots": "Ảnh chụp nhanh",
        "Software-Oriented Features": "Tính năng phần mềm",
        "Some tweaks — especially Apple Intelligence — only take effect after a full restart, not a respring.": "Một số tinh chỉnh — đặc biệt là Apple Intelligence — chỉ có hiệu lực sau khi khởi động lại hoàn toàn, không phải respring.",
        "Something went wrong": "Đã xảy ra lỗi",
        "Sound Effects": "Hiệu ứng âm thanh",
        "Splash Ad Cache Lock": "Splash Ad Cache Lock",
        "Splash Ad Cache Lock finds the folders ad SDKs use to cache splash (launch) ads, empties them, and locks them read-only so the app cannot rebuild its splash-ad cache. Locks apply only to third-party app folders — never to system folders, Documents, or the app itself.": "Splash Ad Cache Lock tìm các thư mục mà SDK quảng cáo dùng để lưu bộ nhớ đệm quảng cáo splash (mở ứng dụng), dọn sạch chúng và khóa chỉ đọc để ứng dụng không thể tạo lại bộ nhớ đệm quảng cáo splash. Khóa chỉ áp dụng cho thư mục của ứng dụng bên thứ ba — không bao giờ áp dụng cho thư mục hệ thống, Documents hay chính ứng dụng.",
        "Spoofing": "Giả mạo",
        "SpringBoard loads the wallpaper store when it starts — respring or restart to see the change in the wallpaper gallery.": "SpringBoard tải kho hình nền khi khởi động — hãy respring hoặc khởi động lại để thấy thay đổi trong thư viện hình nền.",
        "SpringBoard reads the footnote when it starts — respring or restart to see it on the Lock Screen.": "SpringBoard đọc footnote khi khởi động — hãy respring hoặc khởi động lại để thấy nó trên Màn hình khóa.",
        "Stage an app's Documents, Library/Preferences and Library/Application Support (never Caches) before its 7-day certificate expires. After reinstall, the data is restored into the app's new container — matched by bundle id, not the old container UUID.": "Lưu tạm Documents, Library/Preferences và Library/Application Support của một ứng dụng (không bao giờ gồm Caches) trước khi chứng chỉ 7 ngày của nó hết hạn. Sau khi cài đặt lại, dữ liệu được khôi phục vào vùng chứa mới của ứng dụng — khớp theo bundle id, không phải UUID vùng chứa cũ.",
        "Stage copies into the APFS vault (no extra space). ZIP backup copies first, then zips — for very large apps use the APFS vault. Both refuse while the app is still writing its database.": "Stage sao chép vào APFS vault (không tốn thêm dung lượng). Sao lưu ZIP sao chép trước rồi mới nén — với ứng dụng rất lớn hãy dùng APFS vault. Cả hai đều từ chối khi ứng dụng vẫn đang ghi cơ sở dữ liệu.",
        "Stage into APFS Vault": "Lưu tạm vào APFS Vault",
        "Staged %@: %d file(s), %@. Verified against the source.": "Đã lưu tạm %@: %d tệp, %@. Đã xác minh với nguồn.",
        "Staged snapshots": "Ảnh chụp đã lưu tạm",
        "Staging…": "Đang lưu tạm…",
        "Start Server": "Khởi động máy chủ",
        "Start Tweaks Feature": "Bật tính năng Tweaks",
        "Start the server to get its address.": "Khởi động máy chủ để lấy địa chỉ của nó.",
        "Still writing (%d active WAL file(s)) — close the app first": "Vẫn đang ghi (%d tệp WAL đang hoạt động) — hãy đóng ứng dụng trước",
        "Stop Scan": "Dừng quét",
        "Stop Server": "Dừng máy chủ",
        "Stopped": "Đã dừng",
        "Stored as text.": "Lưu dưới dạng văn bản.",
        "Subtype": "Subtype",
        "Supervision": "Giám sát",
        "Support": "Hỗ trợ",
        "Supported": "Được hỗ trợ",
        "Supported iOS Versions": "Các phiên bản iOS được hỗ trợ",
        "Supported iOS • %@": "iOS được hỗ trợ • %@",
        "Swift implementation of the respring web view (via mond / jailbreak.party).": "Bản triển khai Swift của respring web view (qua mond / jailbreak.party).",
        "System": "Hệ thống",
        "System Caches": "Bộ nhớ đệm hệ thống",
        "System Language": "Ngôn ngữ hệ thống",
        "Table": "Bảng",
        "Tap Read Powerlog to load the latest battery samples.": "Chạm Đọc Powerlog để tải các mẫu pin mới nhất.",
        "Tap Refresh to list the diagnostic reports.": "Chạm Làm mới để liệt kê các báo cáo chẩn đoán.",
        "Tap a key to assign a custom image.": "Nhấn một phím để gán ảnh tùy chỉnh.",
        "Target": "Mục tiêu",
        "Target Path": "Đường dẫn đích",
        "Target container": "Container đích",
        "That file is not a pairing file.": "Tệp đó không phải là tệp ghép nối.",
        "The App Data scan is still running — ad targets appear once it finishes.": "Quét App Data vẫn đang chạy — các mục tiêu quảng cáo sẽ xuất hiện khi quét xong.",
        "The CacheExtra key knowledge — the tweak-key research the WorkTweaks tweak catalog is built on.": "Kiến thức về key CacheExtra — nghiên cứu key tinh chỉnh mà danh mục tinh chỉnh của WorkTweaks được xây dựng dựa trên.",
        "The Voice Memos container is found through the App Data scan.": "Vùng chứa Voice Memos được tìm qua quá trình quét App Data.",
        "The ZIP must be a Save Vault backup (it carries a BackupManifest.plist). Files merge in place; system bundle ids are blocked.": "Tệp ZIP phải là bản sao lưu Save Vault (có chứa BackupManifest.plist). Các tệp được hợp nhất tại chỗ; bundle id hệ thống bị chặn.",
        "The backup of the original file couldn't be written, so nothing was saved.": "Không thể ghi bản sao lưu của tệp gốc, vì vậy không có gì được lưu.",
        "The browser asks for these credentials once, then remembers them for the session.": "Trình duyệt chỉ hỏi các thông tin này một lần, rồi ghi nhớ chúng trong phiên.",
        "The bundle ID is not a valid identifier.": "Bundle ID không phải mã định danh hợp lệ.",
        "The bundle ID of the one app this package may touch. Pick it from the App Data container scan, or type it.": "Bundle ID của ứng dụng duy nhất mà gói này được phép chạm vào. Hãy chọn từ lần quét container Dữ liệu ứng dụng, hoặc nhập tay.",
        "The container scan found no containers.": "Quét container không tìm thấy container nào.",
        "The container scan is shared with App Data and runs once per app session.": "Quá trình quét container được dùng chung với App Data và chỉ chạy một lần mỗi phiên ứng dụng.",
        "The container scan runs once per session.": "Quét vùng chứa chỉ chạy một lần mỗi phiên.",
        "The core system: the sandbox escape and MobileGestalt access this whole app is built on.": "Hệ thống lõi: sandbox escape và quyền truy cập MobileGestalt mà toàn bộ ứng dụng này được xây dựng dựa trên.",
        "The current MobileGestalt will be entirely replaced with this %@ backup.": "MobileGestalt hiện tại sẽ được thay thế hoàn toàn bằng bản sao lưu %@ này.",
        "The current file is overwritten in place with the backup taken before the first byte edit.": "Tệp hiện tại sẽ bị ghi đè tại chỗ bằng bản sao lưu được tạo trước lần chỉnh sửa byte đầu tiên.",
        "The developer's GitHub profile.": "Hồ sơ GitHub của nhà phát triển.",
        "The directory is empty.": "Thư mục trống.",
        "The entry is removed from the property list on the next Save.": "Mục sẽ bị xóa khỏi property list ở lần Lưu tiếp theo.",
        "The file couldn't be read under the container's sandbox extension — the details are in the Log. Nothing was written to it.": "Không thể đọc tệp dưới phần mở rộng sandbox của container — chi tiết nằm trong Nhật ký. Không có gì được ghi vào tệp.",
        "The file-based CacheData pattern method used by Enable iPadOS Mode (MobileGestaltCacheDataTweak).": "Phương pháp mẫu CacheData dựa trên tệp được Enable iPadOS Mode dùng (MobileGestaltCacheDataTweak).",
        "The original identifiers are already registered to another developer account, which is why the Team ID suffix is required.": "Các định danh gốc đã được đăng ký cho một tài khoản nhà phát triển khác, đó là lý do cần hậu tố Team ID.",
        "The package could not be exported.": "Không thể xuất gói.",
        "The package store is unavailable (the App Group container did not resolve).": "Kho gói không khả dụng (container App Group không xác định được).",
        "The pairing file + Local Dev VPN tunnel are the transport Airlift uses to reach the device. Green = ready, gray = not ready.": "Tệp ghép nối + đường hầm Local Dev VPN là phương tiện mà Airlift dùng để tiếp cận thiết bị. Xanh lá = sẵn sàng, xám = chưa sẵn sàng.",
        "The pathleak scan reads inodes one by one — this can take a few minutes.": "Quét pathleak đọc từng inode một — việc này có thể mất vài phút.",
        "The picked file could not be copied into the package.": "Không thể sao chép tệp đã chọn vào gói.",
        "The row is deleted from the database on the next Save.": "Hàng sẽ bị xóa khỏi cơ sở dữ liệu ở lần Lưu tiếp theo.",
        "The sandbox extension for this container's directory was refused — the result code is in the Log.": "Phần mở rộng sandbox cho thư mục của container này đã bị từ chối — mã kết quả nằm trong Nhật ký.",
        "The scan of %@ found no containers. The scan's baseline and counts are in the Log.": "Quét %@ không tìm thấy container nào. Đường cơ sở và số lượng của lần quét nằm trong Nhật ký.",
        "The server shares this app's Documents folder only — SaveVaultBackups, staged vaults and uploads. Nothing outside it is ever served. Keep this page open while transferring: the server stops when you leave the page or the app goes to the background.": "Máy chủ chỉ chia sẻ thư mục Documents của ứng dụng này — SaveVaultBackups, các vault đã lưu tạm và tệp tải lên. Không có gì ngoài đó được phục vụ. Hãy giữ trang này mở trong khi truyền: máy chủ sẽ dừng khi bạn rời trang hoặc ứng dụng chuyển sang nền.",
        "The staging vault lives in this app's Documents and does NOT survive uninstalling WorkTweaks. Verify a restore in the app first, then release the vault.": "Vault staging nằm trong Documents của ứng dụng này và sẽ KHÔNG còn nếu gỡ cài đặt WorkTweaks. Hãy xác minh việc khôi phục trong ứng dụng trước, rồi mới giải phóng vault.",
        "The stored package is removed. Files it already deployed, and its Deploy History receipts, are not touched.": "Gói đã lưu sẽ bị xóa. Các tệp nó đã triển khai và biên nhận Lịch sử triển khai của nó không bị ảnh hưởng.",
        "Theme Information": "Thông tin chủ đề",
        "Thermal history (%d)": "Lịch sử nhiệt (%d)",
        "These are the photos and videos in the BackUP_Data folder. Select the ones to restore, then Restore opens the share sheet — tap Save to Photos there.": "Đây là ảnh và video trong thư mục BackUP_Data. Chọn những mục cần khôi phục, rồi Khôi phục sẽ mở bảng chia sẻ — chạm vào Lưu vào Ảnh tại đó.",
        "This app is free software under the GNU AGPL v3 license, following the licenses of the projects above.": "Ứng dụng này là phần mềm tự do theo giấy phép GNU AGPL v3, tuân theo giấy phép của các dự án trên.",
        "This app's own repository — issues and contributions welcome.": "Kho lưu trữ riêng của ứng dụng này — chào đón issue và đóng góp.",
        "This deletes only the listed .ips / .crash / .panic files. The folders are kept.": "Thao tác này chỉ xóa các tệp .ips / .crash / .panic được liệt kê. Các thư mục được giữ lại.",
        "This device right now": "Thiết bị này ngay bây giờ",
        "This file isn't UTF-8 text, so it can't be edited as text. It can be edited byte-by-byte in the hex editor below.": "Tệp này không phải văn bản UTF-8 nên không thể chỉnh sửa dưới dạng văn bản. Có thể chỉnh sửa từng byte trong trình chỉnh sửa hex bên dưới.",
        "This file isn't UTF-8 text, so it can't be edited here. Nothing is ever written to it from this page.": "Tệp này không phải văn bản UTF-8 nên không thể chỉnh sửa tại đây. Không có gì được ghi vào tệp này từ trang này.",
        "This iOS Version Isn't Supported": "Phiên bản iOS này không được hỗ trợ",
        "This is NOT an adblock: locking only stops ad assets landing on disk. Ads downloaded live over the network when the app opens can still appear.": "Đây KHÔNG phải trình chặn quảng cáo: khóa chỉ ngăn tài nguyên quảng cáo lưu xuống ổ đĩa. Quảng cáo được tải trực tiếp qua mạng khi mở ứng dụng vẫn có thể xuất hiện.",
        "This is the container's system-managed metadata file. iOS doesn't allow other processes to read its contents, so it can't be opened or edited here.": "Đây là tệp siêu dữ liệu do hệ thống quản lý của container. iOS không cho phép các tiến trình khác đọc nội dung của nó, vì vậy không thể mở hoặc chỉnh sửa tại đây.",
        "This only clears the list. It does not undo anything that was applied.": "Thao tác này chỉ xóa danh sách. Nó không hoàn tác bất cứ điều gì đã áp dụng.",
        "This only makes the Join Waitlist button appear. The Siri AI model may still refuse to download — that part is not solved by this method yet.": "Thao tác này chỉ làm nút Join Waitlist xuất hiện. Mô hình Siri AI vẫn có thể từ chối tải xuống — phương pháp này chưa giải quyết được phần đó.",
        "This package was rejected": "Gói này đã bị từ chối",
        "This permanently deletes the contents of %@ in %@ (%@). The folders themselves stay in place.": "Thao tác này xóa vĩnh viễn nội dung của %@ trong %@ (%@). Bản thân các thư mục vẫn còn.",
        "This property list has no top-level entries.": "Property list này không có mục cấp cao nhất nào.",
        "This removes the wallpaper imported from %@ — its descriptor folder is deleted from PosterBoard's data store.": "Thao tác này xóa hình nền đã nhập từ %@ — thư mục mô tả của nó sẽ bị xóa khỏi kho dữ liệu của PosterBoard.",
        "This restores the MobileGestalt backup saved on first launch (SavedGestalt.plist).": "Thao tác này khôi phục bản sao lưu MobileGestalt đã lưu khi khởi chạy lần đầu (SavedGestalt.plist).",
        "This table has no columns to edit.": "Bảng này không có cột nào để chỉnh sửa.",
        "Total CacheExtra keys": "Tổng số khóa CacheExtra",
        "True health": "Sức khỏe thực",
        "Try Again": "Thử lại",
        "Turn on the Charge Limit Menu toggle (Add feature section).": "Bật nút chuyển Charge Limit Menu (mục Add feature).",
        "Tutorials": "Hướng dẫn",
        "Tweaks": "Tinh chỉnh",
        "Tweaks Applied": "Đã áp dụng tinh chỉnh",
        "Tweaks UI": "Giao diện Tweaks",
        "Tweaks are locked": "Tinh chỉnh đang bị khóa",
        "Two ways to get a pairing file: Pair This iPhone (iOS 27 only) shows a 6-digit PIN — approve it in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. Or import a pairing file (.plist) from your computer manually. The pairing file is saved in the app.": "Có hai cách để lấy tệp ghép nối: Pair This iPhone (chỉ iOS 27) hiển thị mã PIN 6 chữ số — hãy phê duyệt trong Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. Hoặc nhập tệp ghép nối (.plist) từ máy tính của bạn theo cách thủ công. Tệp ghép nối được lưu trong ứng dụng.",
        "Type": "Loại",
        "Type the region suffix as shown in Settings > General > About, e.g. PA/A or LL/A. It changes the Model Number suffix after Apply.": "Nhập hậu tố vùng như hiển thị trong Settings > General > About, vd: PA/A hoặc LL/A. Nó sẽ thay đổi hậu tố Model Number sau khi áp dụng.",
        "Type: %@ (%@). %@": "Kiểu: %@ (%@). %@",
        "Type: %@. %@": "Kiểu: %@. %@",
        "Universal mode flashes ~600 files for all languages & Bold text. Selecting a specific language (e.g. Ukrainian) speeds up flashing dramatically.": "Chế độ Universal flash ~600 tệp cho mọi ngôn ngữ & Bold text. Chọn một ngôn ngữ cụ thể (ví dụ: Ukrainian) sẽ tăng tốc flash đáng kể.",
        "Unknown time": "Không rõ thời gian",
        "Unlock": "Mở khóa",
        "Unlocks the Tweaks tab. Turn this on to start using tweaks.": "Mở khóa tab Tweaks. Bật tùy chọn này để bắt đầu sử dụng Tweaks.",
        "Unsupported": "Không được hỗ trợ",
        "Unsupported iOS • %@": "iOS không được hỗ trợ • %@",
        "Use Skin": "Dùng skin",
        "Username": "Tên người dùng",
        "Utilities": "Tiện ích",
        "VPN Tunnel": "Đường hầm VPN",
        "VPN tunnel is off. Open the Local Dev VPN app and connect — flashing needs it.": "Đường hầm VPN đang tắt. Hãy mở ứng dụng Local Dev VPN và kết nối — flash cần nó.",
        "Valid until %@": "Có hiệu lực đến %@",
        "Value": "Giá trị",
        "Value: %@": "Giá trị: %@",
        "Version %@": "Phiên bản %@",
        "Video": "Video",
        "Video chosen (%.1f s) — tap to change": "Đã chọn video (%.1f giây) — nhấn để đổi",
        "Videos use the first 12 seconds. Photos become a single still frame.": "Video dùng 12 giây đầu tiên. Ảnh trở thành một khung hình tĩnh duy nhất.",
        "View Full License & Credits": "Xem toàn bộ Giấy phép & Ghi công",
        "Voice Memos": "Voice Memos",
        "Voice Memos & AI Cache": "Voice Memos & Bộ nhớ đệm AI",
        "Voltage": "Điện áp",
        "WARNING: These tweaks can break features on your device or softbrick it if misused. After Apply you choose Respring or Restart; Revert and Backup restores require a full device restart.": "CẢNH BÁO: Các tinh chỉnh này có thể làm hỏng tính năng trên thiết bị của bạn hoặc gây softbrick nếu dùng sai. Sau khi áp dụng, bạn chọn Respring hoặc Restart; việc khôi phục bằng Revert và Backup yêu cầu khởi động lại toàn bộ thiết bị.",
        "Waiting for the App Data scan…": "Đang chờ quét App Data…",
        "Wallet Cards": "Thẻ Wallet",
        "Wallpaper": "Hình nền",
        "Wallpaper name": "Tên hình nền",
        "Warning": "Cảnh báo",
        "Warning: raw byte edits have no structure validation — a wrong byte can corrupt this file or the owning app's data. A backup of the original is saved before the first edit.": "Cảnh báo: chỉnh sửa byte thô không có kiểm tra cấu trúc — một byte sai có thể làm hỏng tệp này hoặc dữ liệu của ứng dụng sở hữu. Bản sao lưu của tệp gốc được lưu trước lần chỉnh sửa đầu tiên.",
        "WeChat accounts": "Tài khoản WeChat",
        "Welcome to WorkTweaks": "Chào mừng đến với WorkTweaks",
        "What this does": "Tính năng này làm gì",
        "When enabled, MobileGestalt is written in-place on the same inode, which (hopefully) prevents iOS from regenerating the cache on reboot. Disable to use atomic file replacement instead.": "Khi bật, MobileGestalt được ghi tại chỗ trên cùng một inode, điều này (hy vọng) ngăn iOS tạo lại bộ nhớ đệm khi khởi động lại. Tắt để dùng thay thế file nguyên tử.",
        "Where it goes": "Lưu ở đâu",
        "Whitelist": "Danh sách trắng",
        "Whitelisted": "Trong danh sách trắng",
        "Whole numbers only.": "Chỉ số nguyên.",
        "Wi-Fi File Sharing": "Chia sẻ tệp Wi-Fi",
        "WorkTweaks is free software under the GNU Affero General Public License v3.0. The core (worse_query) is GPL-3.0, but the CacheExtra key knowledge from mond and the CacheData method from Nugget are AGPL-3.0 — GPLv3 code may be combined into an AGPLv3 work, and the AGPL terms then cover the combined work as a whole.": "WorkTweaks là phần mềm tự do theo GNU Affero General Public License v3.0. Lõi (worse_query) theo GPL-3.0, nhưng kiến thức về key CacheExtra từ mond và phương pháp CacheData từ Nugget theo AGPL-3.0 — mã GPLv3 có thể được kết hợp vào tác phẩm AGPLv3, và các điều khoản AGPL sau đó bao trùm toàn bộ tác phẩm kết hợp.",
        "WorkTweaks must be installed with iLoader, or by signing the IPA with Signed Apps, so that its App Group works correctly.": "WorkTweaks phải được cài đặt bằng iLoader, hoặc bằng cách ký IPA với Signed Apps, để App Group của nó hoạt động đúng.",
        "WorkTweaks only works when its App Group is part of the signing profile. Guides A and B make sure that happens — pick the one that fits you. Guide C turns on the new Siri AI.": "WorkTweaks chỉ hoạt động khi App Group của nó nằm trong hồ sơ ký. Hướng dẫn A và B đảm bảo điều đó xảy ra — hãy chọn hướng dẫn phù hợp với bạn. Hướng dẫn C bật Siri AI mới.",
        "WorkTweaks v3.0 only opens on the builds listed above: the app checks your device's build at launch, and any other build gets the \"not supported\" screen instead of the app. On iOS 18 and iOS 26, only App Data and Airlift are supported (partial support). Developed and tested on iOS 27.0.1 (24A446).": "WorkTweaks v3.0 chỉ mở trên các bản dựng được liệt kê ở trên: ứng dụng kiểm tra bản dựng của thiết bị khi khởi chạy, và bất kỳ bản dựng nào khác sẽ nhận màn hình \"not supported\" thay thế. Trên iOS 18 và iOS 26, chỉ App Data và Airlift được hỗ trợ (hỗ trợ một phần). Được phát triển và kiểm thử trên iOS 27.0.1 (24A446).",
        "Works on iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 and later patched the exploit).": "Hoạt động trên iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 trở lên đã vá khai thác này).",
        "Write Method": "Phương thức ghi",
        "Write access available — Clean All can delete the listed reports.": "Có quyền ghi — Clean All có thể xóa các báo cáo được liệt kê.",
        "Writes SharedDeviceConfiguration.plist in place, keeping every other key in the file. SpringBoard reads the file when it starts, so a respring or restart is needed to see the change.": "Ghi SharedDeviceConfiguration.plist tại chỗ, giữ nguyên mọi key khác trong tệp. SpringBoard đọc tệp khi khởi động nên cần respring hoặc khởi động lại để thấy thay đổi.",
        "Writing or verifying the file failed — the details are in the Log.": "Ghi hoặc xác minh tệp thất bại — chi tiết nằm trong Nhật ký.",
