        ", thermal table %@": ", тепловая таблица %@",
        "1 card": "1 карта",
        "1. Open the Translate app, delete the downloaded English (US) language, then download it again.\n2. Go to Settings > General > Language & Region, change the region from United States to another country, then change it back to United States.\n3. Turn off Low Power Mode (Settings > Battery).\n4. Connect to Wi-Fi (and keep your iPhone charging) while Apple Intelligence finishes downloading.": "1. Откройте приложение Translate, удалите загруженный английский (США), затем скачайте его снова.\n2. Перейдите в «Настройки» > «Основные» > «Язык и регион», смените регион с United States на другую страну, затем верните обратно на United States.\n3. Отключите режим энергосбережения (Настройки > Battery).\n4. Подключитесь к Wi-Fi (и держите iPhone на зарядке), пока Apple Intelligence завершит загрузку.",
        "1. Tap Scan Cards above.": "1. Нажмите «Scan Cards» выше.",
        "1. Use the iPhone 16 Pro subtype.\n2. Settings > Appearance > Display Zoom > Large Text, then go Back and set Text Size to Small (optional).": "1. Используйте подтип iPhone 16 Pro.\n2. Настройки > Appearance > Display Zoom > Large Text, затем вернитесь назад и установите Text Size на Small (необязательно).",
        "2. On this iPhone, double-click the Side button (Apple Pay), authenticate with Face ID, and tap your card.": "2. На этом iPhone дважды нажмите боковую кнопку (Apple Pay), подтвердите личность с помощью Face ID и коснитесь своей карты.",
        "3. Your card will appear here automatically!": "3. Ваша карта появится здесь автоматически!",
        "A .tendies package is a ZIP archive containing one or more wallpaper descriptors: loose descriptor folders, a descriptors folder, or a container layout mirroring PosterBoard's data store (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Stored and deflated ZIP entries are supported — the same reader Deploy uses; encrypted and ZIP64 archives are rejected.": "Пакет .tendies — это ZIP-архив, содержащий один или несколько дескрипторов обоев: отдельные папки дескрипторов, папку descriptors или структуру контейнера, повторяющую хранилище данных PosterBoard (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Поддерживаются сохранённые и сжатые записи ZIP — тот же читатель, что использует Deploy; зашифрованные архивы и ZIP64 отклоняются.",
        "A Deploy package replaces files inside exactly one app — the app named by its bundle ID. It cannot touch any other app: every target path is relative to that app's container, and packages with absolute or \"..\" paths are rejected whole.": "Пакет Deploy заменяет файлы внутри ровно одного приложения — того, что названо его bundle ID. Он не может трогать другие приложения: все целевые пути относительны контейнера этого приложения, а пакеты с абсолютными путями или «..» отклоняются целиком.",
        "A MobileGestalt tweak app for iOS 26/27, built on the open-source projects credited below. Use at your own risk — tweaks modify system files.": "Приложение твиков MobileGestalt для iOS 26/27, созданное на основе проектов с открытым исходным кодом, указанных ниже. Используйте на свой страх и риск — твики изменяют системные файлы.",
        "A MobileGestalt tweak tool for iOS 26 & 27 — unlock your device's hidden features without a jailbreak, powered by the worse_query sandbox escape.": "Инструмент твиков MobileGestalt для iOS 26 и 27 — откройте скрытые функции устройства без джейлбрейка, на основе worse_query sandbox escape.",
        "A bundle ID is required — it names the one app this package may touch.": "Требуется bundle ID — он называет единственное приложение, которое может трогать этот пакет.",
        "A package is ONE .zip file containing a manifest.json at its top level plus the payload files it names. The Package Builder exports that zip (save it in Files); Deploy imports it, resolves the target itself from the manifest, and applies it — no location picking, the destinations come from the zip.": "Пакет — это ОДИН файл .zip, содержащий manifest.json в корне и файлы полезной нагрузки, указанные в нём. Package Builder экспортирует этот zip (сохраните его в Files); Deploy импортирует его, сам определяет цель из манифеста и применяет — без выбора расположения, назначения берутся из zip.",
        "A partial restore can affect photos and videos. Back them up first — optional, you can skip it.": "Частичное восстановление может затронуть фото и видео. Сначала сделайте их резервную копию — необязательно, можно пропустить.",
        "A respring is required before a new wallpaper appears in the gallery.": "Перед появлением новых обоев в галерее требуется Respring.",
        "A signed IPA only works on the device registered in its profile.": "Подписанный IPA работает только на устройстве, зарегистрированном в его профиле.",
        "A snapshot is also created automatically at every Apply, containing the state that Apply just produced. The Original backup is created once, the first time MobileGestalt is read successfully.": "Снимок также создаётся автоматически при каждом Apply и содержит состояние, которое только что создал Apply. Оригинальная резервная копия создаётся один раз — при первом успешном чтении MobileGestalt.",
        "A whitelisted bundle id (and its App Groups) or exact path is never locked by Lock All. Newly whitelisted targets are restored writable right away. SMZDM is whitelisted by default — its splash cache is known to crash the app when locked.": "Bundle id из белого списка (и его App Groups) или точный путь никогда не блокируются функцией Lock All. Вновь добавленные в белый список цели сразу восстанавливаются как доступные для записи. SMZDM в белом списке по умолчанию — известно, что блокировка его кэша заставки приводит к сбою приложения.",
        "AI Cache": "Кэш ИИ",
        "APFS vault: clonefile staging, zero extra space, atomic restore with rollback. ZIP backup: the same three folders as one .zip file, restored by merging in place.": "Хранилище APFS: подготовка через clonefile, без дополнительного места, атомарное восстановление с откатом. ZIP-резервная копия: те же три папки в одном файле .zip, восстанавливается слиянием на месте.",
        "About this feature": "Об этой функции",
