        "All upstream projects remain under their respective licenses. WorkTweaks only repackages and extends them; full credit belongs to the original authors above.": "Все сторонние проекты остаются под своими лицензиями. WorkTweaks лишь переупаковывает и расширяет их; все заслуги принадлежат исходным авторам, указанным выше.",
