        "Disable Dynamic Island System": "Отключить систему Dynamic Island",
        "Disables the Dynamic Island system completely — not just hiding it. Key: SBSuppressDynamicIslandCompletely in the managed com.apple.springboard.plist (set = 1).": "Полностью отключает систему Dynamic Island — а не просто скрывает её. Ключ: SBSuppressDynamicIslandCompletely в управляемом com.apple.springboard.plist (значение = 1).",
