        "Drag to move, pinch to zoom. The skin is saved at 1536×969.": "Перетаскивайте для перемещения, щипайте для масштабирования. Скин сохраняется в размере 1536×969.",
        "Dual SIM: primary is the line used for data, secondary is the other line.": "Dual SIM: основная — линия, используемая для данных, дополнительная — другая линия.",
        "Dynamic Island": "Dynamic Island",
        "Each wallpaper in the package is copied into PosterBoard's data store under a fresh identifier, so it can never clash with an existing wallpaper. A respring is required before a new wallpaper appears in the gallery.": "Каждые обои в пакете копируются в хранилище данных PosterBoard под новым идентификатором, поэтому они никогда не конфликтуют с существующими обоями. Перед появлением новых обоев в галерее требуется Respring.",
