        "Edit Value": "Редактировать значение",
        "Edit in Theme Creator": "Редактировать в Theme Creator",
        "Edits replace byte values only — the file's length never changes. A backup of the original is saved before the first edit.": "Правки заменяют только значения байтов — длина файла никогда не меняется. Резервная копия оригинала сохраняется перед первой правкой.",
        "Elements": "Элементы",
        "Eligibility": "Допустимость",
        "Empty": "Пусто",
        "Enter this PIN in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks.": "Введите этот PIN в «Настройки» › «Конфиденциальность и безопасность» › «Режим разработчика» › «Pair with WorkTweaks».",
        "Enumerating containers with pathleak — this can take a while.": "Перечисление контейнеров с помощью pathleak — это может занять некоторое время.",
        "Enumeration": "Перечисление",
        "Error -1 means the signed app cannot access its App Group container. Diagnostics reads the groups from your signed provisioning profile and probes them all. If it reports no signed groups, the IPA was signed without an App Group and must be re-signed with one — no name typed here can fix that.": "Ошибка -1 означает, что подписанное приложение не может получить доступ к контейнеру своего App Group. Диагностика читает группы из вашего подписанного provisioning profile и проверяет их все. Если подписанных групп не обнаружено, IPA был подписан без App Group и должен быть переподписан с ним — никакое имя, введённое здесь, это не исправит.",
        "Escape": "Escape",
        "Every menu that was applied, newest first. This is a history log — clearing it only clears the list, it does not undo anything.": "Каждое применённое меню, сначала самые новые. Это журнал истории — его очистка очищает только список, она ничего не отменяет.",
        "Exact path": "Точный путь",
        "Expired %@ — reinstall the app first.": "Истёк %@ — сначала переустановите приложение.",
        "Expires soon — %@. Stage now, reinstall before it ends.": "Скоро истекает срок — %@. Подготовьте сейчас, переустановите до истечения.",
        "Export": "Экспорт",
        "Export Selected (%d)": "Экспорт выбранных (%d)",
        "Export ZIP": "Экспорт ZIP",
        "Export the signed IPA and install it with ESign (or any IPA installer).": "Экспортируйте подписанный IPA и установите его с помощью ESign (или любого другого установщика IPA).",
        "Exported as .m4a files with their original titles, zipped to this app's Documents/VoiceMemosExports. The recordings database is only ever read — never written.": "Экспортированы в виде файлов .m4a с исходными названиями, упакованы в архив в Documents/VoiceMemosExports этого приложения. База данных записей только читается — никогда не записывается.",
        "Exporting…": "Экспорт…",
        "Extra": "Дополнительно",
        "Fake-Supervision Residue": "Остатки поддельной супервизии",
        "Fast mode selected: only targets %@ with %@.": "Выбран быстрый режим: только цели %@ с %@.",
        "File": "Файл",
        "Filename": "Имя файла",
        "Files & Sharing": "Файлы и обмен",
        "Files (%d)": "Файлы (%d)",
        "Files in ConfigurationProfiles": "Файлы в ConfigurationProfiles",
        "Files in theme": "Файлы в теме",
        "First Bytes": "Первые байты",
        "Fix Apple Intelligence": "Исправить Apple Intelligence",
        "Fix Apple Intelligence Here!": "Исправить Apple Intelligence здесь!",
        "Fix Status Bar": "Исправить строку состояния",
        "Fix Status Bar!": "Исправить строку состояния!",
        "Flash": "Flash",
        "Flash & Language Target": "Цель Flash и язык",
        "Flash Log (%d lines)": "Журнал Flash (%d строк)",
        "Flash Selected Cards": "Прошить выбранные карты",
        "Flash Theme to iPhone": "Прошить тему на iPhone",
        "Flashing Theme…": "Прошивка темы…",
        "Flashing needs a pairing file and the VPN tunnel. Pair first and connect the VPN in Sandbox → Utilities → Get Pairing File + VPN Status, then come back here.": "Для прошивки нужен файл pairing и VPN-туннель. Сначала выполните pairing и подключите VPN в Sandbox → Utilities → Get Pairing File + VPN Status, затем вернитесь сюда.",
        "Flashing needs a pairing file. Pair this iPhone first in Sandbox → Utilities → Get Pairing File.": "Для прошивки нужен файл pairing. Сначала выполните pairing этого iPhone в Sandbox → Utilities → Get Pairing File.",
        "Flashing needs the VPN tunnel. Open the Local Dev VPN app and connect first.": "Для прошивки нужен VPN-туннель. Откройте приложение Local Dev VPN и сначала подключитесь.",
        "Flashing…": "Прошивка…",
        "Folder name": "Имя папки",
        "Follow for updates, demos and new tweaks.": "Подпишитесь, чтобы следить за обновлениями, демо и новыми твиками.",
        "Font Weight / Style": "Начертание / стиль шрифта",
        "Footnote": "Footnote",
        "Footnote Updated": "Footnote обновлена",
        "Footnote text": "Текст footnote",
        "For AppGroup scope, the target is the App Group identifier (for example group.com.example) — type it here.": "Для области AppGroup целью является идентификатор App Group (например, group.com.example) — введите его здесь.",
        "Force-close the Wallet app from the App Switcher after flashing to see the new card art.": "После прошивки принудительно закройте приложение Wallet через переключатель приложений, чтобы увидеть новое оформление карт.",
        "Forces the label shown (5G, 5G+, 5G UC, LTE, …). Limited — the label is display-only.": "Принудительно задаёт отображаемую метку (5G, 5G+, 5G UC, LTE, …). Ограничено — метка только для отображения.",
        "Free Apple ID installs expire after about 7 days — reinstall with iLoader to renew.": "Установки с бесплатным Apple ID истекают примерно через 7 дней — переустановите с помощью iLoader, чтобы продлить.",
        "Freed %@": "Освобождено %@",
        "Genuine MDM": "Настоящий MDM",
        "Get Pairing + VPN Tunnel": "Получить Pairing + VPN-туннель",
        "Get Pairing File": "Получить файл Pairing",
        "Get Pairing File + Local Dev VPN tunnel — the on-device pairing Airlift uses to reach the device.": "Получить файл Pairing + туннель Local Dev VPN — pairing на устройстве, который Airlift использует для доступа к устройству.",
        "Get Pairing File + VPN Status": "Получить файл Pairing + статус VPN",
        "Get Started": "Начать",
        "Go to Sandbox Tab": "Перейти на вкладку Sandbox",
        "Go to the Apply/Revert section and tap Apply, then Respring. When the respring finishes, restart your iPhone.": "Перейдите в раздел Apply/Revert и нажмите Apply, затем Respring. Когда respring завершится, перезагрузите iPhone.",
        "Go to the Sandbox tab and turn on Start Tweaks Feature to unlock the Tweaks tab.": "Перейдите на вкладку Sandbox и включите Start Tweaks Feature, чтобы разблокировать вкладку Tweaks.",
        "Good to Know": "Полезно знать",
        "Grant refused — size unknown.": "Доступ отклонён — размер неизвестен.",
        "Granting sandbox access…": "Предоставление доступа к песочнице…",
        "Guide A — Install with iLoader (Desktop)": "Руководство A — установка с помощью iLoader (компьютер)",
        "Guide B — Sign with Signed Apps (Mobile)": "Руководство B — подпись с помощью Signed Apps (мобильное устройство)",
        "Guide C — Turn On New Siri AI": "Руководство C — включение нового Siri AI",
        "Harden": "Усилить",
        "Hardware-Oriented Features": "Функции, связанные с оборудованием",
        "Health %.1f%%": "Здоровье %.1f%%",
        "Hex Editor": "Hex-редактор",
        "Hide Alarm icon": "Скрыть значок будильника",
        "Hide Location icon": "Скрыть значок геолокации",
        "Hide Status Bar Icons": "Скрыть значки строки состояния",
        "Hide VPN icon": "Скрыть значок VPN",
        "History": "История",
        "ISO date (e.g. 2026-11-24T15:30:00Z) or yyyy-MM-dd HH:mm:ss.": "Дата в формате ISO (напр., 2026-11-24T15:30:00Z) или yyyy-MM-dd HH:mm:ss.",
        "Identifiers from the App Data container scan — the same list Deploy resolves Application targets against.": "Идентификаторы из сканирования контейнеров App Data — тот же список, по которому Deploy определяет цели Application.",
        "Idle": "Простой",
        "If iOS asks, enable Developer Mode (Settings → Privacy & Security → Developer Mode) and trust the developer profile.": "Если iOS попросит, включите режим разработчика (Settings → Privacy & Security → Developer Mode) и доверьте профилю разработчика.",
        "If you update or downgrade to a supported build, WorkTweaks will open normally.": "Если вы обновитесь или откатитесь до поддерживаемой сборки, WorkTweaks откроется как обычно.",
        "Import": "Импорт",
        "Import .tendies Package…": "Импорт пакета .tendies…",
        "Import Failed": "Импорт не удался",
        "Import Package…": "Импорт пакета…",
        "Import Pairing File": "Импорт файла Pairing",
        "Import ZIP Backup…": "Импорт ZIP-резервной копии…",
        "Imported": "Импортировано",
        "In the Tweaks tab, Apple Intelligence section, turn on Apple Intelligence and Siri AI Cache Patch. The cache patch is the Filza line-104 edit (one CacheData byte, 0x00 to 0x02) — done here, no Filza needed.": "На вкладке Tweaks, в разделе Apple Intelligence, включите Apple Intelligence и Siri AI Cache Patch. Патч кэша — это правка Filza в строке 104 (один байт CacheData, с 0x00 на 0x02) — делается здесь, Filza не нужна.",
        "Individual Keys": "Отдельные ключи",
        "Install tab → Provisioning: fill in the fields below, tap Provision, and wait for \"profile OK\". Your Team ID is shown in the app's Certificates tab.": "Вкладка Install → Provisioning: заполните поля ниже, нажмите Provision и дождитесь \"profile OK\". Ваш Team ID показан на вкладке Certificates приложения.",
        "Installation": "Установка",
        "Installed Profiles": "Установленные профили",
        "Installed any other way, the signed profile leaves the App Group out — and without it, the tweaks can't run. Tap Tutorials below for both step-by-step guides.": "При установке любым другим способом подписанный профиль не включает App Group — а без него твики не работают. Нажмите Tutorials ниже, чтобы увидеть оба пошаговых руководства.",
        "Installing into PosterBoard…": "Установка в PosterBoard…",
        "Internal": "Внутренние",
        "Jetsam & Crash": "Jetsam и сбои",
        "Jetsam & Crash lists the reports iOS writes when it kills an app for memory (Jetsam, bug_type 298), when an app crashes (309), or on a watchdog / kernel panic (210). Open a report to see why it died, share the full file, or clean all reports to free space.": "В Jetsam & Crash перечислены отчёты, которые iOS записывает, когда завершает приложение из-за нехватки памяти (Jetsam, bug_type 298), когда приложение падает (309) или при срабатывании watchdog / панике ядра (210). Откройте отчёт, чтобы узнать, почему оно завершилось, поделитесь полным файлом или очистите все отчёты, чтобы освободить место.",
        "Key": "Ключ",
