        "Open Mobile Gestalt.plist": "Открыть Mobile Gestalt.plist",
        "Manual edit needed": "Требуется ручное редактирование",
        "The Siri byte is flipped (0x02) — the patch is on.": "Байт Siri изменён (0x02) — патч включён.",
        "The Siri byte is 0x00 — the patch is off.": "Байт Siri равен 0x00 — патч выключен.",
        "The patch pattern matches more than once, so the automatic patch refuses to guess — edit the Siri line by hand.": "Шаблон патча совпал несколько раз, поэтому автоматический патч отказывается угадывать — отредактируйте строку Siri вручную.",
        "The patch was found, but not on line 104 — open the viewer to see its line.": "Патч найден, но не в строке 104 — откройте просмотрщик, чтобы увидеть его строку.",
        "The patch line was not found in this file — check the Mobile Gestalt.plist viewer.": "Строка патча не найдена в этом файле — проверьте просмотрщик Mobile Gestalt.plist.",
        "CacheData is missing from MobileGestalt.": "CacheData отсутствует в MobileGestalt.",
        "This is the same text Filza shows for this file. CacheData is the long base64 block; its lines are 51 bytes each. The Siri line is highlighted.": "Это тот же текст, который Filza показывает для этого файла. CacheData — длинный блок base64; каждая строка — 51 байт. Строка Siri выделена.",
        "Siri line: line %d": "Строка Siri: строка %d",
        "On this device the Siri line is line %d, not 104 — the guide's line number varies by device.": "На этом устройстве строка Siri — строка %d, а не 104 — номер строки в руководстве зависит от устройства.",
        "No matches": "Нет совпадений",
        "%d of %d matches": "%d из %d совпадений",
        "%d matches": "%d совпадений",
        "Going back discards unsaved edits.": "Возврат отменит несохранённые правки.",
        "Restore the pristine backup made before the first save?": "Восстановить исходную резервную копию, созданную перед первым сохранением?",
        "Pristine backup restored.": "Исходная резервная копия восстановлена.",
        "Unapplied changes in the Tweaks tab will be lost when you save here — Apply them first.": "Неприменённые изменения на вкладке Tweaks будут потеряны при сохранении здесь — сначала примените их.",
        "Saved — the Siri patch is now %@.": "Сохранено — патч Siri теперь %@.",
        "Saved — the file was written, but the Siri line does not match the patch shape.": "Сохранено — файл записан, но строка Siri не соответствует форме патча.",
        "A pristine backup is made before the first save, and only CacheData changes are written.": "Перед первым сохранением создаётся исходная резервная копия, и записываются только изменения CacheData.",
        "Save the edited file?": "Сохранить отредактированный файл?",
        "MobileGestalt could not be loaded.": "Не удалось загрузить MobileGestalt.",
        "Reload MobileGestalt": "Перезагрузить MobileGestalt",
        "Loading MobileGestalt.plist…": "Загрузка MobileGestalt.plist…",
        "Open \"Mobile Gestalt.plist\" in the Tweaks tab (below the Siri AI Cache Patch card), then tap \"Open with Text Editor\".": "Откройте «Mobile Gestalt.plist» на вкладке Tweaks (под карточкой Siri AI Cache Patch), затем нажмите «Open with Text Editor».",
        "Use the find field to jump to line 104 — the viewer shows the exact Siri line number for this device.": "Используйте поле поиска, чтобы перейти к строке 104 — просмотрщик покажет точный номер строки Siri для этого устройства.",
        "On that line, change the 30th base64 character from A to g (this flips CacheData byte 21 from 0x00 to 0x02). To turn the patch off again, change it back from g to A. Then tap Save — a pristine backup is made before the first save.": "В этой строке измените 30-й символ base64 с A на g (это переключит 21-й байт CacheData с 0x00 на 0x02). Чтобы снова выключить патч, верните с g на A. Затем нажмите Save — перед первым сохранением создаётся исходная резервная копия.",
        "Then turn on Apple Intelligence and the Charge Limit Menu toggle, set Spoofing to iPhone 17 Pro, Apply, respring and restart — Join Waitlist should appear in Settings > Apple Intelligence & Siri.": "Затем включите Apple Intelligence и переключатель Charge Limit Menu, установите Spoofing на iPhone 17 Pro, нажмите Apply, выполните respring и перезагрузите устройство — кнопка Join Waitlist появится в «Настройки» > «Apple Intelligence и Siri».",
        "Turn on the Apple Intelligence toggle and the Charge Limit Menu toggle (Add feature section).": "Включите переключатели Apple Intelligence и Charge Limit Menu (раздел Add feature).",

        "Edit the Siri line": "Редактировать строку Siri",
        "Change one character on the Siri line to flip the patch — you don't need to read the whole file.": "Измените один символ в строке Siri, чтобы переключить патч — читать весь файл не нужно.",
        "View file lines": "Просмотреть строки файла",
        "Packages by Adnan.120hz — tap one to install it into its app, or save its zip in Files.": "Пакеты от Adnan.120hz — нажмите на пакет, чтобы установить его в приложение, или сохранить его zip в Files.",
        "Save to Files": "Сохранить в Files",
        "Installed": "Установлено",
        "Installed on %@": "Установлено %@",
        "No packages could be loaded from the app bundle.": "Не удалось загрузить пакеты из app bundle.",



        "Install complete — patched (revision 7). Signed with your certificate — ready to launch.": "Установка завершена — пропатчено (ревизия 7). Подписано твоим сертификатом — готово к запуску.",
        "Install complete — patched (revision 7). No certificate imported, so it cannot launch yet.": "Установка завершена — пропатчено (ревизия 7). Сертификат не импортирован, поэтому запуск пока невозможен.",

