        ", thermal table %@": "، جدول الحرارة %@",
        "1 card": "بطاقة واحدة",
        "1. Open the Translate app, delete the downloaded English (US) language, then download it again.\n2. Go to Settings > General > Language & Region, change the region from United States to another country, then change it back to United States.\n3. Turn off Low Power Mode (Settings > Battery).\n4. Connect to Wi-Fi (and keep your iPhone charging) while Apple Intelligence finishes downloading.": "1. افتح تطبيق Translate، واحذف لغة English (US) التي تم تنزيلها، ثم نزلها مجددا.\n2. انتقل إلى Settings > General > Language & Region، وغير المنطقة من United States إلى بلد آخر، ثم أعد تغييرها إلى United States.\n3. أوقف وضع Low Power Mode (Settings > Battery).\n4. اتصل بشبكة Wi-Fi (وأبق iPhone قيد الشحن) بينما يكمل Apple Intelligence التنزيل.",
        "1. Tap Scan Cards above.": "1. اضغط على «مسح البطاقات» أعلاه.",
        "1. Use the iPhone 16 Pro subtype.\n2. Settings > Appearance > Display Zoom > Large Text, then go Back and set Text Size to Small (optional).": "1. استخدم النوع الفرعي iPhone 16 Pro.\n2. انتقل إلى Settings > Appearance > Display Zoom > Large Text، ثم ارجع واضبط Text Size على Small (اختياري).",
        "2. On this iPhone, double-click the Side button (Apple Pay), authenticate with Face ID, and tap your card.": "2. على هذا iPhone، انقر نقرا مزدوجا على الزر الجانبي (Apple Pay)، وصادق باستخدام Face ID، ثم اضغط على بطاقتك.",
        "3. Your card will appear here automatically!": "3. ستظهر بطاقتك هنا تلقائيا!",
        "A .tendies package is a ZIP archive containing one or more wallpaper descriptors: loose descriptor folders, a descriptors folder, or a container layout mirroring PosterBoard's data store (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Stored and deflated ZIP entries are supported — the same reader Deploy uses; encrypted and ZIP64 archives are rejected.": "حزمة .tendies هي أرشيف ZIP يحتوي على واصف خلفية واحد أو أكثر: مجلدات واصفات منفصلة، أو مجلد descriptors، أو تخطيط حاوية يحاكي مخزن بيانات PosterBoard (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). وتدعم إدخالات ZIP المخزنة والمضغوطة — وهو القارئ نفسه الذي يستخدمه Deploy؛ أما الأرشيفات المشفرة وأرشيفات ZIP64 فترفض.",
        "A Deploy package replaces files inside exactly one app — the app named by its bundle ID. It cannot touch any other app: every target path is relative to that app's container, and packages with absolute or \"..\" paths are rejected whole.": "تستبدل حزمة Deploy الملفات داخل تطبيق واحد بالضبط — وهو التطبيق المسمى بمعرف حزمته. ولا يمكنها أن تلمس أي تطبيق آخر: فكل مسار هدف نسبي بالنسبة إلى حاوية ذلك التطبيق، وترفض الحزم ذات المسارات المطلقة أو \"..\" كاملة.",
        "A MobileGestalt tweak app for iOS 26/27, built on the open-source projects credited below. Use at your own risk — tweaks modify system files.": "تطبيق تعديلات MobileGestalt لنظام iOS 26/27، مبني على المشاريع مفتوحة المصدر المذكورة أدناه. استخدمه على مسؤوليتك الخاصة — فالتعديلات تغير ملفات النظام.",
        "A MobileGestalt tweak tool for iOS 26 & 27 — unlock your device's hidden features without a jailbreak, powered by the worse_query sandbox escape.": "أداة تعديلات MobileGestalt لنظامي iOS 26 و27 — افتح الميزات المخفية في جهازك دون جيلبريك، مدعومة بهروب الحماية worse_query.",
        "A bundle ID is required — it names the one app this package may touch.": "معرف الحزمة مطلوب — فهو يحدد التطبيق الوحيد الذي قد تلمسه هذه الحزمة.",
        "A package is ONE .zip file containing a manifest.json at its top level plus the payload files it names. The Package Builder exports that zip (save it in Files); Deploy imports it, resolves the target itself from the manifest, and applies it — no location picking, the destinations come from the zip.": "الحزمة هي ملف .zip واحد يحتوي على manifest.json في مستواه الأعلى إضافة إلى ملفات الحمولة التي يسميها. يصدر Package Builder ذلك الملف المضغوط (احفظه في Files)؛ ويستورده Deploy، ويحدد الهدف بنفسه من البيان، ويطبقه — دون اختيار موقع، فالوجهات تأتي من الملف المضغوط.",
        "A partial restore can affect photos and videos. Back them up first — optional, you can skip it.": "قد تؤثر الاستعادة الجزئية على الصور والفيديوهات. انسخها احتياطيا أولا — هذا اختياري، ويمكنك تخطيه.",
        "A respring is required before a new wallpaper appears in the gallery.": "يلزم إعادة تشغيل الواجهة قبل ظهور خلفية جديدة في المعرض.",
        "A signed IPA only works on the device registered in its profile.": "لا يعمل ملف IPA الموقع إلا على الجهاز المسجل في ملفه التعريفي.",
        "A snapshot is also created automatically at every Apply, containing the state that Apply just produced. The Original backup is created once, the first time MobileGestalt is read successfully.": "يتم أيضا إنشاء لقطة تلقائيا عند كل تطبيق، تحتوي على الحالة التي أنتجها التطبيق للتو. أما النسخة الاحتياطية الأصلية فتنشأ مرة واحدة، في أول مرة تقرأ فيها MobileGestalt بنجاح.",
        "A whitelisted bundle id (and its App Groups) or exact path is never locked by Lock All. Newly whitelisted targets are restored writable right away. SMZDM is whitelisted by default — its splash cache is known to crash the app when locked.": "لا يقفل «قفل الكل» أبدا معرف حزمة مدرج في القائمة البيضاء (ومجموعات تطبيقاته) أو مسارا دقيقا. وتستعاد أهداف القائمة البيضاء الجديدة قابلة للكتابة فورا. SMZDM مدرج في القائمة البيضاء افتراضيا — فمن المعروف أن ذاكرة التخزين المؤقت لشاشة البداية الخاصة به تعطل التطبيق عند قفلها.",
        "AI Cache": "ذاكرة التخزين المؤقت للذكاء الاصطناعي",
        "APFS vault: clonefile staging, zero extra space, atomic restore with rollback. ZIP backup: the same three folders as one .zip file, restored by merging in place.": "مخزن APFS: تجهيز عبر clonefile، دون مساحة إضافية، واستعادة ذرية مع التراجع. النسخة الاحتياطية ZIP: المجلدات الثلاثة نفسها في ملف .zip واحد، تستعاد بالدمج في مكانها.",
