        "Before anything is written, every file that already exists is backed up (see Deploy History). Existing files are then replaced in place; new files are created.": "قبل كتابة أي شيء، يتم نسخ كل ملف موجود احتياطيا (انظر Deploy History). ثم تستبدل الملفات الموجودة في مكانها؛ وتنشأ الملفات الجديدة.",
        "Blocked — pairing / VPN not ready": "محظور — الاقتران / VPN غير جاهز",
        "Both need a pairing file first: Sandbox → Utilities → Get Pairing File. A loopback VPN (Local Dev VPN) is strongly recommended while flashing.": "يحتاج كلاهما إلى ملف اقتران أولا: Sandbox → Utilities → Get Pairing File. وينصح بشدة باستخدام VPN حلقي (Local Dev VPN) أثناء التثبيت.",
        "Browse Files": "تصفح الملفات",
        "Build": "الإصدار",
