        "Building still wallpaper…": "جار إنشاء الخلفية الثابتة…",
        "Builds a PosterBoard wallpaper on-device from your photo or video — the same descriptor format as an imported .tendies package, installed and listed exactly like one.": "ينشئ خلفية PosterBoard على الجهاز من صورتك أو فيديوك — بنفس تنسيق الواصف المستخدم في حزمة .tendies المستوردة، وتثبت وتدرج تماما مثلها.",
        "Built on the worse_query core system by ForceQuit OS, with CacheExtra key knowledge from mond by rooootdev (AGPL-3.0).": "مبني على نظام worse_query الأساسي من ForceQuit OS، مع معرفة مفاتيح CacheExtra من mond للمطور rooootdev (AGPL-3.0).",
        "Bundle ID": "معرف الحزمة",
