        "Cache Locations": "مواقع ذاكرة التخزين المؤقت",
        "Cache lives in two places inside an app's data container: Library/Caches and tmp. Only the contents of those two folders are deleted — the folders themselves stay, and Documents and the rest of Library are never touched.": "توجد ذاكرة التخزين المؤقت في مكانين داخل حاوية بيانات التطبيق: Library/Caches وtmp. ولا تحذف إلا محتويات هذين المجلدين — أما المجلدان أنفسهما فيبقيان، ولا تمس Documents وبقية Library أبدا.",
