        "Certificates tab: create your certificate if needed. A free team can hold only one active development certificate — if creation fails with error 7460, revoke an old unused certificate there first.": "تبويب Certificates: أنشئ شهادتك عند الحاجة. لا يمكن للفريق المجاني أن يحمل سوى شهادة تطوير نشطة واحدة — فإذا فشل الإنشاء مع الخطأ 7460، فألغ أولا شهادة قديمة غير مستخدمة من هناك.",
