        "Connect your iPhone to power, connect to Wi-Fi, and leave the Settings → General → iPhone Storage tab open for about 1 hour while the model downloads.": "وصل iPhone بالطاقة، واتصل بشبكة Wi-Fi، واترك تبويب Settings → General → iPhone Storage مفتوحا نحو ساعة أثناء تنزيل النموذج.",
