        "Containers are enumerated with the fork's pathleak scan — the kernel refuses a grant on the container root itself, so there is no faster way to list them.": "يتم سرد الحاويات عبر فحص pathleak الخاص بالنسخة المعدلة — فالنواة ترفض منح إذن على جذر الحاوية نفسه، لذا لا توجد طريقة أسرع لسردها.",
