        "Disable Dynamic Island": "تعطيل Dynamic Island",
        "Disable Dynamic Island System": "تعطيل نظام Dynamic Island",
        "Disables the Dynamic Island system completely — not just hiding it. Key: SBSuppressDynamicIslandCompletely in the managed com.apple.springboard.plist (set = 1).": "يعطل نظام Dynamic Island تماما — لا يخفيه فقط. المفتاح: SBSuppressDynamicIslandCompletely في الملف المدار com.apple.springboard.plist (عينه = 1).",
        "Do not reboot! Your MobileGestalt.plist seems to be %@.": "لا تعد التشغيل! يبدو أن ملف MobileGestalt.plist الخاص بك هو %@.",
        "Done": "تم",
        "Download the WorkTweaks IPA from GitHub.": "نزل ملف WorkTweaks IPA من GitHub.",
        "Download the latest WorkTweaks IPA from the GitHub Releases page.": "نزل أحدث ملف WorkTweaks IPA من صفحة GitHub Releases.",
        "Drag to move, pinch to zoom. The skin is saved at 1536×969.": "اسحب للنقل، وقرص للتكبير. يحفظ الغلاف بأبعاد 1536×969.",
        "Dual SIM: primary is the line used for data, secondary is the other line.": "شريحتان: الأساسية هي الخط المستخدم للبيانات، والثانوية هي الخط الآخر.",
        "Dynamic Island": "Dynamic Island",
        "Each wallpaper in the package is copied into PosterBoard's data store under a fresh identifier, so it can never clash with an existing wallpaper. A respring is required before a new wallpaper appears in the gallery.": "تنسخ كل خلفية في الحزمة إلى مخزن بيانات PosterBoard تحت معرف جديد، فلا تتعارض أبدا مع خلفية موجودة. ويلزم إعادة تشغيل الواجهة قبل ظهور خلفية جديدة في المعرض.",
        "Edit": "تحرير",
