        "Edit Package": "تحرير الحزمة",
        "Edit Value": "تحرير القيمة",
        "Edit in Theme Creator": "تحرير في Theme Creator",
        "Edits replace byte values only — the file's length never changes. A backup of the original is saved before the first edit.": "تستبدل التعديلات قيم البايتات فقط — ولا يتغير طول الملف أبدا. وتحفظ نسخة احتياطية من الأصل قبل أول تعديل.",
        "Elements": "العناصر",
        "Eligibility": "الأهلية",
        "Empty": "فارغ",
        "Enter this PIN in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks.": "أدخل رقم PIN هذا في Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks.",
        "Enumerating containers with pathleak — this can take a while.": "جار سرد الحاويات عبر pathleak — قد يستغرق هذا بعض الوقت.",
        "Enumeration": "السرد",
        "Error -1 means the signed app cannot access its App Group container. Diagnostics reads the groups from your signed provisioning profile and probes them all. If it reports no signed groups, the IPA was signed without an App Group and must be re-signed with one — no name typed here can fix that.": "يعني الخطأ -1 أن التطبيق الموقع لا يمكنه الوصول إلى حاوية App Group الخاصة به. تقرأ التشخيصات المجموعات من ملف التوفير الموقع وتختبرها جميعا. فإذا أفادت بعدم وجود مجموعات موقعة، فهذا يعني أن ملف IPA وقع دون App Group ويجب إعادة توقيعه مع واحدة — ولا يمكن لأي اسم تكتبه هنا أن يصلح ذلك.",
        "Escape": "الهروب",
        "Every menu that was applied, newest first. This is a history log — clearing it only clears the list, it does not undo anything.": "كل قائمة تم تطبيقها، الأحدث أولا. هذا سجل — مسحه يمسح القائمة فقط، ولا يتراجع عن أي شيء.",
        "Exact path": "المسار الدقيق",
        "Expired %@ — reinstall the app first.": "انتهت صلاحيته %@ — أعد تثبيت التطبيق أولا.",
        "Expires soon — %@. Stage now, reinstall before it ends.": "تنتهي صلاحيته قريبا — %@. جهز الآن، وأعد التثبيت قبل انتهائها.",
        "Export": "تصدير",
        "Export Selected (%d)": "تصدير المحدد (%d)",
        "Export ZIP": "تصدير ZIP",
        "Export the signed IPA and install it with ESign (or any IPA installer).": "صدر ملف IPA الموقع وثبته باستخدام ESign (أو أي مثبت IPA).",
        "Exported as .m4a files with their original titles, zipped to this app's Documents/VoiceMemosExports. The recordings database is only ever read — never written.": "تصدر كملفات .m4a بعناوينها الأصلية، مضغوطة في Documents/VoiceMemosExports الخاص بهذا التطبيق. ولا تقرأ قاعدة بيانات التسجيلات أبدا إلا للقراءة — ولا تكتب أبدا.",
        "Exporting…": "جار التصدير…",
