        "Flash Theme to iPhone": "تثبيت السمة على iPhone",
        "Flashing Theme…": "جار تثبيت السمة…",
        "Flashing needs a pairing file and the VPN tunnel. Pair first and connect the VPN in Sandbox → Utilities → Get Pairing File + VPN Status, then come back here.": "يحتاج التثبيت إلى ملف اقتران ونفق VPN. اقترن أولا واتصل بشبكة VPN في Sandbox → Utilities → Get Pairing File + VPN Status، ثم عد إلى هنا.",
        "Flashing needs a pairing file. Pair this iPhone first in Sandbox → Utilities → Get Pairing File.": "يحتاج التثبيت إلى ملف اقتران. اقترن بهذا iPhone أولا في Sandbox → Utilities → Get Pairing File.",
        "Flashing needs the VPN tunnel. Open the Local Dev VPN app and connect first.": "يحتاج التثبيت إلى نفق VPN. افتح تطبيق Local Dev VPN واتصل أولا.",
        "Flashing…": "جار التثبيت…",
        "Folder name": "اسم المجلد",
        "Follow for updates, demos and new tweaks.": "تابع للحصول على التحديثات والعروض والتعديلات الجديدة.",
        "Font Weight / Style": "سمك الخط / النمط",
