        "Footnote Updated": "تم تحديث الحاشية",
        "Footnote text": "نص الحاشية",
        "For AppGroup scope, the target is the App Group identifier (for example group.com.example) — type it here.": "في نطاق AppGroup، يكون الهدف معرف App Group (مثل group.com.example) — اكتبه هنا.",
        "Force-close the Wallet app from the App Switcher after flashing to see the new card art.": "أغلق تطبيق Wallet قسرا من App Switcher بعد التثبيت لرؤية العمل الفني الجديد للبطاقة.",
        "Forces the label shown (5G, 5G+, 5G UC, LTE, …). Limited — the label is display-only.": "يفرض التسمية المعروضة (5G، و5G+، و5G UC، وLTE، …). محدود — التسمية للعرض فقط.",
        "Free Apple ID installs expire after about 7 days — reinstall with iLoader to renew.": "تنتهي صلاحية عمليات التثبيت باستخدام Apple ID مجاني بعد نحو 7 أيام — أعد التثبيت باستخدام iLoader للتجديد.",
        "Freed %@": "تم تحرير %@",
