        "Get Pairing File": "الحصول على ملف الاقتران",
        "Get Pairing File + Local Dev VPN tunnel — the on-device pairing Airlift uses to reach the device.": "ملف الاقتران + نفق Local Dev VPN — الاقتران على الجهاز الذي يستخدمه Airlift للوصول إلى الجهاز.",
