        "Go to the Apply/Revert section and tap Apply, then Respring. When the respring finishes, restart your iPhone.": "انتقل إلى قسم التطبيق/التراجع واضغط على «تطبيق»، ثم «إعادة تشغيل الواجهة». وعند انتهاء إعادة تشغيل الواجهة، أعد تشغيل iPhone.",
        "Go to the Sandbox tab and turn on Start Tweaks Feature to unlock the Tweaks tab.": "انتقل إلى تبويب Sandbox وفعل «بدء ميزة التعديلات» لفتح تبويب Tweaks.",
