        "History": "السجل",
        "ISO date (e.g. 2026-11-24T15:30:00Z) or yyyy-MM-dd HH:mm:ss.": "تاريخ ISO (مثل 2026-11-24T15:30:00Z) أو yyyy-MM-dd HH:mm:ss.",
        "Identifiers from the App Data container scan — the same list Deploy resolves Application targets against.": "معرفات من فحص حاوية App Data — وهي القائمة نفسها التي يطابق Deploy أهداف Application معها.",
        "Idle": "خامل",
        "If iOS asks, enable Developer Mode (Settings → Privacy & Security → Developer Mode) and trust the developer profile.": "إذا طلب iOS ذلك، فعل وضع المطور (Settings → Privacy & Security → Developer Mode) وثق بملف تعريف المطور.",
        "If you update or downgrade to a supported build, WorkTweaks will open normally.": "إذا حدثت أو خفضت إلى بنية مدعومة، فسيفتح WorkTweaks بشكل طبيعي.",
        "Import": "استيراد",
        "Import .tendies Package…": "استيراد حزمة .tendies…",
        "Import Failed": "فشل الاستيراد",
        "Import Package…": "استيراد حزمة…",
        "Import Pairing File": "استيراد ملف الاقتران",
        "Import ZIP Backup…": "استيراد نسخة ZIP احتياطية…",
        "Imported": "تم الاستيراد",
        "In the Tweaks tab, Apple Intelligence section, turn on Apple Intelligence and Siri AI Cache Patch. The cache patch is the Filza line-104 edit (one CacheData byte, 0x00 to 0x02) — done here, no Filza needed.": "في تبويب Tweaks، قسم Apple Intelligence، فعل Apple Intelligence و«تصحيح ذاكرة Siri AI المؤقتة». إن تصحيح الذاكرة المؤقتة هو تعديل السطر 104 في Filza (بايت CacheData واحد، من 0x00 إلى 0x02) — وينجز هنا، دون الحاجة إلى Filza.",
        "Individual Keys": "مفاتيح فردية",
        "Install tab → Provisioning: fill in the fields below, tap Provision, and wait for \"profile OK\". Your Team ID is shown in the app's Certificates tab.": "تبويب Install ← Provisioning: املأ الحقول أدناه، واضغط على Provision، وانتظر «profile OK». يظهر Team ID الخاص بك في تبويب Certificates داخل التطبيق.",
        "Installation": "التثبيت",
        "Installed Profiles": "ملفات التعريف المثبتة",
        "Installed any other way, the signed profile leaves the App Group out — and without it, the tweaks can't run. Tap Tutorials below for both step-by-step guides.": "إذا ثبت بأي طريقة أخرى، يستبعد الملف التعريفي الموقع App Group — وبدونها لا يمكن للتعديلات أن تعمل. اضغط على Tutorials أدناه للاطلاع على الدليلين خطوة بخطوة.",
        "Installing into PosterBoard…": "جار التثبيت في PosterBoard…",
        "Internal": "داخلي",
        "Jetsam & Crash": "Jetsam والأعطال",
        "Jetsam & Crash lists the reports iOS writes when it kills an app for memory (Jetsam, bug_type 298), when an app crashes (309), or on a watchdog / kernel panic (210). Open a report to see why it died, share the full file, or clean all reports to free space.": "يسرد «Jetsam والأعطال» التقارير التي يكتبها iOS عندما ينهي تطبيقا بسبب الذاكرة (Jetsam، bug_type 298)، أو عند تعطل تطبيق (309)، أو عند حدوث مراقبة / ذعر نواة (210). افتح تقريرا لتعرف سبب موته، أو شارك الملف كاملا، أو نظف كل التقارير لتحرير مساحة.",
        "Key": "المفتاح",
