        "Lock Screen Footnote": "حاشية شاشة القفل",
        "Lock Screen Footnote is unavailable": "حاشية شاشة القفل غير متاحة",
        "Lock Screen Preview": "معاينة شاشة القفل",
        "Locked folders are read-only (0555) with a sentinel file inside; config files are emptied and locked (0444). A Weak Lock is a locked folder missing its sentinel — tap Harden to add it.": "المجلدات المقفلة للقراءة فقط (0555) مع ملف حارس بداخلها؛ وتفرغ ملفات التكوين وتقفل (0444). أما القفل الضعيف فهو مجلد مقفل ينقصه ملف الحارس — اضغط على «تعزيز» لإضافته.",
        "Locks every target below that still needs action. Whitelisted targets are always skipped.": "يقفل كل هدف أدناه لا يزال يحتاج إلى إجراء. وتتخطى أهداف القائمة البيضاء دائما.",
