        "Name": "الاسم",
        "Nested dictionaries, arrays and Data are shown read-only — the editor never rewrites a structure it cannot show.": "تعرض القواميس والمصفوفات والبيانات المتداخلة للقراءة فقط — فالمحرر لا يعيد كتابة بنية لا يستطيع عرضها.",
        "Network Type Label": "تسمية نوع الشبكة",
        "Network label (Primary)": "تسمية الشبكة (الأساسية)",
        "Network label (Secondary)": "تسمية الشبكة (الثانوية)",
        "Network type": "نوع الشبكة",
        "Never share your certificate .p12 file with anyone — it contains your private signing key.": "لا تشارك ملف شهادتك .p12 مع أي شخص أبدا — فهو يحتوي على مفتاح التوقيع الخاص بك.",
        "New Package": "حزمة جديدة",
        "New Row": "صف جديد",
        "New UI": "واجهة جديدة",
        "No": "لا",
        "No AI cache targets were found.": "لم يتم العثور على أهداف لذاكرة الذكاء الاصطناعي المؤقتة.",
        "No Cards Detected Yet": "لم يتم اكتشاف بطاقات بعد",
        "No Jailbreak": "دون جيلبريك",
        "No ad targets found yet. Tap Scan above.": "لم يتم العثور على أهداف إعلانات بعد. اضغط على «مسح» أعلاه.",
        "No backed-up photos or videos yet. Use \"Backup Your Photos & Videos Here!\" first.": "لا توجد صور أو فيديوهات منسوخة احتياطيا بعد. استخدم «Backup Your Photos & Videos Here!» أولا.",
        "No containers were found, so there is nothing to clean.": "لم يتم العثور على حاويات، لذا لا يوجد ما يمكن تنظيفه.",
        "No deploys yet. When a package is deployed, the files it replaced are backed up here with a receipt, ready to restore.": "لا توجد عمليات نشر بعد. عند نشر حزمة، تنسخ الملفات التي استبدلتها احتياطيا هنا مع إيصال، جاهزة للاستعادة.",
        "No diagnostic reports found — nothing has been killed or crashed recently, or the reports were already cleaned.": "لم يتم العثور على تقارير تشخيصية — فلم ينه أو يتعطل أي شيء مؤخرا، أو أن التقارير نظفت بالفعل.",
        "No files yet.": "لا توجد ملفات بعد.",
        "No installable profile records were found in this directory.": "لم يتم العثور على سجلات ملفات تعريف قابلة للتثبيت في هذا الدليل.",
        "No pairing file saved yet.": "لم يحفظ ملف اقتران بعد.",
        "No pairing file yet. Pair this iPhone first in Sandbox → Utilities → Get Pairing File — scanning and flashing need it.": "لا يوجد ملف اقتران بعد. اقترن بهذا iPhone أولا في Sandbox → Utilities → Get Pairing File — فالمسح والتثبيت يحتاجان إليه.",
        "No recordings were found in the Voice Memos database.": "لم يتم العثور على تسجيلات في قاعدة بيانات Voice Memos.",
        "No regular files found in this container.": "لم يتم العثور على ملفات عادية في هذه الحاوية.",
        "No scan yet. The scan starts automatically; if it does not, open App Data once, or type the bundle ID by hand.": "لم يبدأ الفحص بعد. يبدأ الفحص تلقائيا؛ وإذا لم يبدأ، فافتح App Data مرة واحدة، أو اكتب معرف الحزمة يدويا.",
        "No skin — tap Set Skin below": "لا يوجد غلاف — اضغط على «تعيين الغلاف» أدناه",
        "No snapshots yet. Apply some tweaks or tap Back Up Now.": "لا توجد لقطات بعد. طبق بعض التعديلات أو اضغط على «نسخ احتياطي الآن».",
        "No stored packages yet. Build one with New Package, or import an existing .deploy / .zip / folder package to edit it here.": "لا توجد حزم مخزنة بعد. أنشئ واحدة باستخدام «حزمة جديدة»، أو استورد حزمة .deploy / .zip / مجلد موجودة لتحريرها هنا.",
        "No thermal events found in the powerlog.": "لم يتم العثور على أحداث حرارية في powerlog.",
        "No third-party apps found.": "لم يتم العثور على تطبيقات طرف ثالث.",
        "No tweaks match \"%@\".": "لا توجد تعديلات تطابق \"%@\".",
        "No wallpapers imported yet. Wallpapers imported here are listed so you can remove them again — wallpapers added any other way are never touched.": "لم تستورد خلفيات بعد. تدرج الخلفيات المستوردة هنا لتتمكن من إزالتها مجددا — أما الخلفيات المضافة بأي طريقة أخرى فلا تمس أبدا.",
        "Nominal capacity": "السعة الاسمية",
        "Not Supervised": "غير خاضع للإشراف",
        "Not connected.": "غير متصل.",
        "Not loaded": "غير محمل",
        "Not measured yet": "لم يقس بعد",
        "Not present in this app": "غير موجود في هذا التطبيق",
        "Not present in this backup": "غير موجود في هذه النسخة الاحتياطية",
        "Not set": "غير معين",
        "Nothing applied yet.": "لم يطبق شيء بعد.",
        "Nothing staged yet.": "لم يجهز شيء بعد.",
        "Nothing was written — the stored manifest is unchanged.": "لم يكتب أي شيء — فالبيان المخزن لم يتغير.",
        "Nothing was written.": "لم يكتب أي شيء.",
        "Notice": "ملاحظة",
        "Numbers only.": "أرقام فقط.",
        "OK": "موافق",
        "Off": "إيقاف",
        "Off in this backup": "متوقف في هذه النسخة الاحتياطية",
        "Old UI": "واجهة قديمة",
        "On": "تشغيل",
        "On a computer, download iLoader from iloader.app — the official site only — and open it.": "على جهاز كمبيوتر، نزل iLoader من iloader.app — من الموقع الرسمي فقط — وافتحه.",
        "On in this backup": "مفعل في هذه النسخة الاحتياطية",
        "One of the destination paths is invalid.": "أحد مسارات الوجهة غير صالح.",
        "Only files under Library/Caches inside the listed targets are deleted. AI models are never touched, and caches regenerate when the apps run again.": "لا تحذف إلا الملفات الموجودة ضمن Library/Caches داخل الأهداف المدرجة. ولا تمس نماذج الذكاء الاصطناعي أبدا، وتتجدد ذاكرات التخزين المؤقت عند تشغيل التطبيقات مجددا.",
        "Only spoof your device model if you want to download Apple Intelligence. This may break Face ID. If you decide to unspoof and want to keep Apple Intelligence, do NOT re-enter the Apple Intelligence & Siri menu in Settings.": "انتحل طراز جهازك فقط إذا أردت تنزيل Apple Intelligence. قد يؤدي هذا إلى تعطيل Face ID. وإذا قررت إلغاء الانتحال وأردت الاحتفاظ ب Apple Intelligence، فلا تعد إلى قائمة Apple Intelligence & Siri في Settings.",
        "Only the listed .ips / .crash / .panic files under DiagnosticReports (and Retired) are ever deleted. The folders themselves are kept, and nothing else is touched.": "لا تحذف أبدا إلا ملفات .ips / .crash / .panic المدرجة ضمن DiagnosticReports (وRetired). أما المجلدات نفسها فتبقى، ولا يمس أي شيء آخر.",
        "Open App Data first so the container scan runs, then come back — or tap Rescan.": "افتح App Data أولا ليبدأ فحص الحاوية، ثم عد — أو اضغط على «إعادة الفحص».",
        "Open Settings → Apple Intelligence & Siri and tap Join Waitlist. Wait about 15 minutes for it to be accepted.": "افتح Settings → Apple Intelligence & Siri واضغط على Join Waitlist. وانتظر نحو 15 دقيقة حتى يتم قبولك.",
        "Open Signed Apps and sign in with your Apple ID.": "افتح Signed Apps وسجل الدخول باستخدام Apple ID.",
        "Open Source": "مفتوح المصدر",
        "Open Tutorials": "فتح الدروس",
        "Open WorkTweaks and you're done.": "افتح WorkTweaks وستنتهي.",
        "Open as Property List": "فتح كقائمة خصائص",
        "Open as SQLite Database": "فتح كقاعدة بيانات SQLite",
        "Open the Local Dev VPN app and connect. The tunnel shows as a utun interface on 10.7.x.x (gateway 10.7.0.1).": "افتح تطبيق Local Dev VPN واتصل. يظهر النفق كواجهة utun على 10.7.x.x (البوابة 10.7.0.1).",
        "Opening the configuration profiles…": "جار فتح ملفات التعريف…",
        "Opening the database…": "جار فتح قاعدة البيانات…",
        "Opens an empty editor; the file is created when you save.": "يفتح محررا فارغا؛ وينشأ الملف عند الحفظ.",
        "Opens the database as editable tables, with a backup taken before the first save. Close the owning app before editing.": "يفتح قاعدة البيانات كجداول قابلة للتحرير، مع نسخة احتياطية قبل أول حفظ. أغلق التطبيق المالك قبل التحرير.",
        "Opens the property list as an editable key/type/value table, with a backup taken before the first save.": "يفتح قائمة الخصائص كجدول مفتاح/نوع/قيمة قابل للتحرير، مع نسخة احتياطية قبل أول حفظ.",
        "Optional label": "تسمية اختيارية",
        "Organization: %@": "المؤسسة: %@",
        "Original": "الأصلية",
        "Original (%d)": "الأصلية (%d)",
        "PIN": "PIN",
        "Package": "الحزمة",
        "Package Builder": "منشئ الحزم",
        "Package Format": "تنسيق الحزمة",
        "Packages you build or import are stored on this device, in WorkTweaks' own container. Tap a package to edit it. Deploy runs it through the same preview, resolve and backup flow as a picked package.": "تخزن الحزم التي تنشئها أو تستوردها على هذا الجهاز، في حاوية WorkTweaks الخاصة. اضغط على حزمة لتحريرها. ويشغل Deploy الحزمة عبر تدفق المعاينة والمطابقة والنسخ الاحتياطي نفسه المتبع مع الحزمة المختارة.",
        "Pair This iPhone": "اقتران هذا iPhone",
        "Pairing & Airlift": "الاقتران وAirlift",
        "Pairing cancelled.": "تم إلغاء الاقتران.",
        "Pairing file": "ملف الاقتران",
        "Pairing file imported.": "تم استيراد ملف الاقتران.",
        "Pairing file removed.": "تمت إزالة ملف الاقتران.",
        "Pairing file saved to the app.": "تم حفظ ملف الاقتران في التطبيق.",
        "Parsed from the .plist files in the ConfigurationProfiles directory. This page never installs or removes a profile.": "محلل من ملفات .plist في دليل ConfigurationProfiles. لا تثبت هذه الصفحة أي ملف تعريف ولا تزيله أبدا.",
        "Partial — some icons may still show. Hidden through the archive's suppressed identifiers.": "جزئي — قد تظهر بعض الأيقونات. تخفى عبر المعرفات المكبوتة في الأرشيف.",
        "Partially Supported": "مدعوم جزئيا",
        "Partially Supported iOS • %@": "iOS مدعوم جزئيا • %@",
        "Passcode Theme": "سمة رمز المرور",
        "Passcode Themes": "سمات رمز المرور",
        "Passcode theme applied": "تم تطبيق سمة رمز المرور",
        "Paste card hash": "الصق بصمة البطاقة",
        "Path Enumeration": "سرد المسارات",
        "Paths must be relative, non-empty and contain no \"..\" component.": "يجب أن تكون المسارات نسبية وغير فارغة وألا تحتوي على المكون \"..\".",
        "Payload files are copied into the package. Add File accepts any file — a .plist is added as a payload, and a .zip is unpacked, each file inside becoming a payload with its destination defaulting to its path inside the archive. Destinations are relative paths only; absolute paths and \"..\" are rejected, exactly like an imported package.": "تنسخ ملفات الحمولة إلى الحزمة. يقبل «إضافة ملف» أي ملف — فملف .plist يضاف كحمولة، وملف .zip يفك ضغطه، ويصبح كل ملف بداخله حمولة بوجهة افتراضية هي مساره داخل الأرشيف. الوجهات مسارات نسبية فقط؛ وترفض المسارات المطلقة و\"..\"، تماما كما في الحزمة المستوردة.",
        "Persist after reboot": "الاستمرار بعد إعادة التشغيل",
        "Photo Library": "مكتبة الصور",
        "Photo chosen — tap to change": "تم اختيار الصورة — اضغط للتغيير",
        "Photos & Videos": "الصور والفيديوهات",
        "Pick Target App": "اختر التطبيق الهدف",
        "Pick an app": "اختر تطبيقا",
        "Pick an app to see its cache and clean it.": "اختر تطبيقا لرؤية ذاكرته المؤقتة وتنظيفها.",
        "Pick from App Data scan…": "اختر من فحص App Data…",
        "Pick the WorkTweaks IPA, set the Signing Bundle ID field to the same identifier, then tap Sign IPA.": "اختر ملف WorkTweaks IPA، واضبط حقل Signing Bundle ID على المعرف نفسه، ثم اضغط على Sign IPA.",
        "Pick the photos and videos you want to keep, then Save. They are copied into the BackUP_Data folder inside the app. Optional — you can skip this.": "اختر الصور والفيديوهات التي تريد الاحتفاظ بها، ثم اضغط على «حفظ». تنسخ إلى مجلد BackUP_Data داخل التطبيق. اختياري — يمكنك تخطي هذا.",
        "Plays a soft sound when you tap menus and features. Respects the silent switch.": "يشغل صوتا خفيفا عند الضغط على القوائم والميزات. ويحترم مفتاح الصامت.",
        "Please Install It the Right Way": "يرجى تثبيته بالطريقة الصحيحة",
        "PosterBoard Data": "بيانات PosterBoard",
        "PosterBoard Updated": "تم تحديث PosterBoard",
        "PosterBoard is unavailable": "PosterBoard غير متاح",
        "Power": "الطاقة",
        "Prepare Share": "تحضير المشاركة",
        "Preparing the container scan…": "جار تحضير فحص الحاوية…",
        "Preview (first 128 KB)": "معاينة (أول 128 KB)",
        "Probe Again": "إعادة الفحص",
        "Probing cache sizes…": "جار فحص أحجام ذاكرة التخزين المؤقت…",
        "Raw max capacity": "السعة القصوى الخام",
        "Read": "قراءة",
        "Read Powerlog": "قراءة Powerlog",
        "Read complete%@%@.": "اكتملت القراءة%@%@.",
        "Read-only mode — the grant did not include write access, so Clean All is disabled.": "وضع القراءة فقط — فالإذن لم يشمل الوصول للكتابة، لذا فإن «تنظيف الكل» معطل.",
        "Read-only: the powerlog is cloned into this app's temp folder and inspected there. Nothing is ever written to the system database. Some iOS 26 firmware restricts the powerlog sandbox token; iOS 27 reads fully.": "للقراءة فقط: يستنسخ powerlog إلى مجلد temp الخاص بهذا التطبيق ويفحص هناك. ولا يكتب أي شيء أبدا في قاعدة بيانات النظام. وتقيد بعض إصدارات iOS 26 الثابتة رمز sandbox الخاص ب powerlog؛ أما iOS 27 فيقرأه كاملا.",
        "Reading the configuration profiles…": "جار قراءة ملفات التعريف…",
        "Reading the property list…": "جار قراءة قائمة الخصائص…",
        "Reading the recordings database…": "جار قراءة قاعدة بيانات التسجيلات…",
        "Reading video frames…": "جار قراءة إطارات الفيديو…",
        "Reading…": "جار القراءة…",
        "Rebooting now might cause a bootloop. Try pressing 'Revert Tweaks'.": "قد تؤدي إعادة التشغيل الآن إلى حلقة إقلاع. جرب الضغط على «Revert Tweaks».",
        "Recent Requests": "الطلبات الأخيرة",
        "Recent samples (%d)": "العينات الأخيرة (%d)",
        "Reference": "المرجع",
        "Reference & Patch Files": "المراجع وملفات التصحيح",
        "Reference — APFS save-vault idea (clonefile staging, atomic swap with rollback).": "مرجع — فكرة مخزن حفظ APFS (تجهيز clonefile، وتبديل ذري مع التراجع).",
        "Reference — PosterBoard wallpaper format the maker was verified against.": "مرجع — تنسيق خلفية PosterBoard الذي تم التحقق من المنشئ مقابله.",
        "Reference — Splash Ad Cache Lock mechanism (ad SDK cache lock, save vault, diagnostics, Wi-Fi file sharing, Voice Memos export, AI cache probes).": "مرجع — آلية Splash Ad Cache Lock (قفل ذاكرة SDK الإعلانية المؤقتة، ومخزن الحفظ، والتشخيصات، ومشاركة الملفات عبر Wi-Fi، وتصدير Voice Memos، وفحوصات ذاكرة الذكاء الاصطناعي المؤقتة).",
        "Reference — cache data cleaner": "مرجع — منظف بيانات ذاكرة التخزين المؤقت",
        "Reference — turn on new Siri AI (CacheData line edit + device spoof)": "مرجع — تشغيل Siri AI الجديد (تعديل سطر CacheData + انتحال الجهاز)",
        "Reference — video-to-wallpaper (CAML) builder used by the PosterBoard wallpaper maker.": "مرجع — منشئ تحويل الفيديو إلى خلفية (CAML) الذي يستخدمه منشئ خلفيات PosterBoard.",
        "Refresh": "تحديث",
        "Refresh Status": "تحديث الحالة",
        "Region suffix (e.g. PA/A)": "لاحقة المنطقة (مثل PA/A)",
        "Release": "تحرير",
        "Release Sandbox Extension": "تحرير امتداد Sandbox",
        "Remove": "إزالة",
        "Remove / Unload Theme": "إزالة / إلغاء تحميل السمة",
        "Remove Footnote": "إزالة الحاشية",
        "Remove Pairing File": "إزالة ملف الاقتران",
        "Report": "التقرير",
        "Reports": "التقارير",
        "Reports (%d)": "التقارير (%d)",
        "Requires iOS %.1f+": "يتطلب iOS %.1f+",
        "Rescan": "إعادة الفحص",
        "Reset": "إعادة تعيين",
        "Resolve Target": "مطابقة الهدف",
        "Resolving the target container…": "جار مطابقة الحاوية الهدف…",
        "Respring": "إعادة تشغيل الواجهة",
        "Respring did not trigger on this device.": "لم تفعل إعادة تشغيل الواجهة على هذا الجهاز.",
        "Restart Device": "إعادة تشغيل الجهاز",
        "Restart Required": "إعادة التشغيل مطلوبة",
        "Restore": "استعادة",
        "Restore (%d)": "استعادة (%d)",
        "Restore Backup": "استعادة النسخة الاحتياطية",
        "Restore Everything": "استعادة كل شيء",
        "Restore Result — %d succeeded, %d failed": "نتيجة الاستعادة — نجح %d، وفشل %d",
        "Restore a ZIP backup": "استعادة نسخة ZIP احتياطية",
        "Restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "لا تدخل تغييرات الاستعادة حيز التنفيذ إلا بعد إعادة تشغيل كاملة للجهاز — فإعادة تشغيل الواجهة لا تكفي. واختيار «لاحقا» يؤجلها فقط؛ وتبقى التغييرات معلقة حتى تعيد التشغيل.",
        "Restore into…": "استعادة إلى…",
        "Restore swaps the staged copy into the app's current container and rolls back if anything fails. Release a snapshot only after you verified the restore in the app.": "تستبدل الاستعادة النسخة المجهزة في الحاوية الحالية للتطبيق وتتراجع إذا فشل أي شيء. ولا تحرر اللقطة إلا بعد التحقق من الاستعادة في التطبيق.",
        "Restore the backup?": "استعادة النسخة الاحتياطية؟",
        "Restore this entire backup?": "استعادة هذه النسخة الاحتياطية بالكامل؟",
        "Restoring ZIP…": "جار استعادة ZIP…",
        "Restoring the backup failed — the details are in the Log.": "فشلت استعادة النسخة الاحتياطية — التفاصيل في Log.",
        "Restoring writes each backed-up file back in place. Files the deploy created (they did not exist before) are deleted again.": "تعيد الاستعادة كتابة كل ملف منسوخ احتياطيا في مكانه. أما الملفات التي أنشأها النشر (ولم تكن موجودة من قبل) فتحذف مجددا.",
        "Restoring…": "جار الاستعادة…",
        "Result — %d succeeded, %d failed": "النتيجة — نجح %d، وفشل %d",
        "Retry Flash": "إعادة التثبيت",
        "Retry Flash Theme": "إعادة تثبيت السمة",
        "Revert": "تراجع",
        "Revert Tweaks": "التراجع عن التعديلات",
        "Revert all tweaks?": "التراجع عن كل التعديلات؟",
        "Revert and restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "لا تدخل تغييرات التراجع والاستعادة حيز التنفيذ إلا بعد إعادة تشغيل كاملة للجهاز — فإعادة تشغيل الواجهة لا تكفي. واختيار «لاحقا» يؤجلها فقط؛ وتبقى التغييرات معلقة حتى تعيد التشغيل.",
        "Rewrites the entire MobileGestalt.plist from this backup. A device restart is required after restoring.": "يعيد كتابة ملف MobileGestalt.plist بالكامل من هذه النسخة الاحتياطية. ويلزم إعادة تشغيل الجهاز بعد الاستعادة.",
        "Running": "قيد التشغيل",
        "Sampled": "تم أخذ عينة",
        "Sandbox access denied": "تم رفض الوصول إلى Sandbox",
        "Sandbox extension is ready (directory grant held).": "امتداد Sandbox جاهز (تم الاحتفاظ بإذن الدليل).",
        "Save": "حفظ",
        "Save .passthm": "حفظ .passthm",
        "Save App Group ID": "حفظ معرف App Group",
        "Save Vault": "مخزن الحفظ",
        "Saved": "تم الحفظ",
        "Saved %d of %d to BackUP_Data.": "تم حفظ %d من %d في BackUP_Data.",
        "Saved: %@": "تم الحفظ: %@",
        "Saves the package, then shares ONE .zip file — save it in Files. Deploy imports that zip and applies it without asking for locations.": "يحفظ الحزمة، ثم يشارك ملف .zip واحدا — احفظه في Files. ويستورد Deploy ذلك الملف المضغوط ويطبقه دون أن يسأل عن المواقع.",
        "Saving %d of %d (%d%%)": "جار حفظ %d من %d (%d%%)",
        "Saving applies the edits to the database through SQLite, takes a backup of the original first, then writes the edited file back in place. Close the owning app before saving — a running app can overwrite your edits.": "يطبق الحفظ التعديلات على قاعدة البيانات عبر SQLite، وينسخ الأصل احتياطيا أولا، ثم يعيد كتابة الملف المعدل في مكانه. أغلق التطبيق المالك قبل الحفظ — فقد يستبدل التطبيق قيد التشغيل تعديلاتك.",
        "Saving rebuilds the property list from this table, takes a backup of the original first, then writes it back in place. Close the owning app before saving — a running app can overwrite your edits.": "يعيد الحفظ بناء قائمة الخصائص من هذا الجدول، وينسخ الأصل احتياطيا أولا، ثم يعيد كتابته في مكانه. أغلق التطبيق المالك قبل الحفظ — فقد يستبدل التطبيق قيد التشغيل تعديلاتك.",
        "Saving writes the file in place and verifies the result by re-reading it.": "يكتب الحفظ الملف في مكانه ويتحقق من النتيجة بإعادة قراءته.",
        "Saving writes the file in place, under the container's sandbox extension.": "يكتب الحفظ الملف في مكانه، ضمن امتداد sandbox الخاص بالحاوية.",
        "Saving…": "جار الحفظ…",
        "Scan": "مسح",
        "Scan Cards": "مسح البطاقات",
        "Scan for Ad Targets": "مسح أهداف الإعلانات",
        "Scanning %@…": "جار مسح %@…",
        "Scanning…": "جار المسح…",
        "Scope": "النطاق",
        "Search": "بحث",
        "Search tweaks": "بحث في التعديلات",
        "Secondary bars: %d": "الأشرطة الثانوية: %d",
        "Secondary carrier name (max 64)": "اسم شركة الاتصالات الثانوية (بحد أقصى 64)",
        "Secondary network type": "نوع الشبكة الثانوية",
        "Sections": "الأقسام",
        "Select All": "تحديد الكل",
        "Select None": "إلغاء التحديد",
        "Select at least one card and attach a skin image to it before flashing.": "حدد بطاقة واحدة على الأقل وأرفق بها صورة غلاف قبل التثبيت.",
        "Selected app": "التطبيق المحدد",
        "Server": "الخادم",
        "Set NULL": "تعيين NULL",
        "Set Skin": "تعيين الغلاف",
        "Set Skin for All Cards…": "تعيين الغلاف لكل البطاقات…",
        "Set the Spoofing picker (under Apple Intelligence) to iPhone 17 Pro (iPhone18,1).": "اضبط منتقي الانتحال (ضمن Apple Intelligence) على iPhone 17 Pro (iPhone18,1).",
        "Sets how many bars are drawn. Static — it does not follow the real signal.": "يحدد عدد الأشرطة المرسومة. ثابت — لا يتبع الإشارة الحقيقية.",
        "Share %@": "مشاركة %@",
        "Share Contents": "مشاركة المحتويات",
        "Share Full Report": "مشاركة التقرير الكامل",
        "Showing the first %@ of %@ rows — the editor is for targeted edits, not bulk dumps.": "يعرض أول %@ من %@ صفا — فالمحرر للتعديلات المحددة، وليس للتفريغ الجماعي.",
        "Shows the battery percentage in the status bar. Key: SBShowBatteryPercentage in com.apple.springboard.plist.": "يعرض نسبة البطارية في شريط الحالة. المفتاح: SBShowBatteryPercentage في com.apple.springboard.plist.",
        "Sign In": "تسجيل الدخول",
        "Signal Bars": "أشرطة الإشارة",
        "Signal bars (Primary)": "أشرطة الإشارة (الأساسية)",
        "Signal bars (Secondary)": "أشرطة الإشارة (الثانوية)",
        "Single-file shorthand: instead of \"files\", give \"relativePath\" and \"file\". \"scope\" is Application (bundleID = the app's bundle ID), AppGroup (bundleID = the group identifier, e.g. group.com.example) or InternalDaemon. ZIP archives may use stored or deflated entries; encrypted and ZIP64 archives are not supported. Older .deploy archives and plain folders still import.": "اختصار الملف الواحد: بدلا من «files»، قدم «relativePath» و«file». ويكون «scope» هو Application (bundleID = معرف حزمة التطبيق)، أو AppGroup (bundleID = معرف المجموعة، مثل group.com.example)، أو InternalDaemon. وقد تستخدم أرشيفات ZIP إدخالات مخزنة أو مضغوطة؛ أما الأرشيفات المشفرة وأرشيفات ZIP64 فغير مدعومة. ولا تزال أرشيفات .deploy القديمة والمجلدات العادية تستورد.",
        "Size": "الحجم",
        "Sizes are measured by walking each folder. An app recreates cache as it runs, so the size grows back over time.": "تقاس الأحجام بالمرور على كل مجلد. ويعيد التطبيق إنشاء ذاكرة التخزين المؤقت أثناء تشغيله، فيعود الحجم للنمو مع الوقت.",
        "Sizes are probed read-only (depth 4). Delete Cache removes only files under Library/Caches inside these targets — the AI models live elsewhere and are never touched.": "تفحص الأحجام للقراءة فقط (عمق 4). ولا يزيل «حذف ذاكرة التخزين المؤقت» إلا الملفات ضمن Library/Caches داخل هذه الأهداف — فنماذج الذكاء الاصطناعي موجودة في مكان آخر ولا تمس أبدا.",
        "Snapshots": "اللقطات",
        "Software-Oriented Features": "الميزات المتعلقة بالبرمجيات",
        "Some tweaks — especially Apple Intelligence — only take effect after a full restart, not a respring.": "لا تدخل بعض التعديلات — وخاصة Apple Intelligence — حيز التنفيذ إلا بعد إعادة تشغيل كاملة، لا بعد إعادة تشغيل الواجهة.",
        "Something went wrong": "حدث خطأ ما",
        "Sound Effects": "المؤثرات الصوتية",
        "Splash Ad Cache Lock": "قفل ذاكرة إعلانات شاشة البداية المؤقتة",
        "Splash Ad Cache Lock finds the folders ad SDKs use to cache splash (launch) ads, empties them, and locks them read-only so the app cannot rebuild its splash-ad cache. Locks apply only to third-party app folders — never to system folders, Documents, or the app itself.": "يجد «قفل ذاكرة إعلانات شاشة البداية المؤقتة» المجلدات التي تستخدمها حزم SDK الإعلانية لتخزين إعلانات شاشة البداية (الإطلاق) مؤقتا، ويفرغها، ويقفلها للقراءة فقط حتى لا يتمكن التطبيق من إعادة بناء ذاكرته المؤقتة لإعلانات شاشة البداية. وتطبق الأقفال على مجلدات تطبيقات الطرف الثالث فقط — وليس على مجلدات النظام أو Documents أو التطبيق نفسه أبدا.",
        "Spoofing": "الانتحال",
        "SpringBoard loads the wallpaper store when it starts — respring or restart to see the change in the wallpaper gallery.": "يحمل SpringBoard مخزن الخلفيات عند بدئه — أعد تشغيل الواجهة أو أعد التشغيل لرؤية التغيير في معرض الخلفيات.",
        "SpringBoard reads the footnote when it starts — respring or restart to see it on the Lock Screen.": "يقرأ SpringBoard الحاشية عند بدئه — أعد تشغيل الواجهة أو أعد التشغيل لرؤيتها على شاشة القفل.",
        "Stage an app's Documents, Library/Preferences and Library/Application Support (never Caches) before its 7-day certificate expires. After reinstall, the data is restored into the app's new container — matched by bundle id, not the old container UUID.": "جهز مجلدات Documents وLibrary/Preferences وLibrary/Application Support الخاصة بتطبيق (وليس Caches أبدا) قبل انتهاء صلاحية شهادته ذات الأيام السبعة. وبعد إعادة التثبيت، تستعاد البيانات إلى الحاوية الجديدة للتطبيق — بمطابقة معرف الحزمة، لا UUID الحاوية القديم.",
        "Stage copies into the APFS vault (no extra space). ZIP backup copies first, then zips — for very large apps use the APFS vault. Both refuse while the app is still writing its database.": "ينسخ التجهيز إلى مخزن APFS (دون مساحة إضافية). أما النسخة الاحتياطية ZIP فتنسخ أولا ثم تضغط — وللتطبيقات الكبيرة جدا استخدم مخزن APFS. ويرفض كلاهما بينما لا يزال التطبيق يكتب قاعدة بياناته.",
        "Stage into APFS Vault": "التجهيز في مخزن APFS",
        "Staged %@: %d file(s), %@. Verified against the source.": "تم تجهيز %@: %d ملف، %@. تم التحقق منه مقابل المصدر.",
        "Staged snapshots": "اللقطات المجهزة",
        "Staging…": "جار التجهيز…",
        "Start Server": "بدء الخادم",
        "Start Tweaks Feature": "بدء ميزة التعديلات",
        "Start the server to get its address.": "ابدأ الخادم للحصول على عنوانه.",
        "Still writing (%d active WAL file(s)) — close the app first": "لا يزال يكتب (%d ملف WAL نشط) — أغلق التطبيق أولا",
        "Stop Scan": "إيقاف المسح",
        "Stop Server": "إيقاف الخادم",
        "Stopped": "متوقف",
        "Stored as text.": "مخزن كنص.",
        "Subtype": "النوع الفرعي",
        "Supervision": "الإشراف",
        "Support": "الدعم",
        "Supported": "مدعوم",
        "Supported iOS Versions": "إصدارات iOS المدعومة",
        "Supported iOS • %@": "iOS مدعوم • %@",
        "Swift implementation of the respring web view (via mond / jailbreak.party).": "تنفيذ Swift لعرض الويب الخاص بإعادة تشغيل الواجهة (عبر mond / jailbreak.party).",
        "System": "النظام",
        "System Caches": "ذاكرات التخزين المؤقت للنظام",
        "System Language": "لغة النظام",
        "Table": "الجدول",
        "Tap Read Powerlog to load the latest battery samples.": "اضغط على «قراءة Powerlog» لتحميل أحدث عينات البطارية.",
        "Tap Refresh to list the diagnostic reports.": "اضغط على «تحديث» لسرد التقارير التشخيصية.",
        "Tap a key to assign a custom image.": "اضغط على مفتاح لتعيين صورة مخصصة.",
        "Target": "الهدف",
        "Target Path": "مسار الهدف",
        "Target container": "الحاوية الهدف",
        "That file is not a pairing file.": "هذا الملف ليس ملف اقتران.",
        "The App Data scan is still running — ad targets appear once it finishes.": "لا يزال فحص App Data قيد التشغيل — وتظهر أهداف الإعلانات عند انتهائه.",
        "The CacheExtra key knowledge — the tweak-key research the WorkTweaks tweak catalog is built on.": "معرفة مفاتيح CacheExtra — البحث في مفاتيح التعديلات الذي بني عليه كتالوج تعديلات WorkTweaks.",
        "The Voice Memos container is found through the App Data scan.": "يعثر على حاوية Voice Memos عبر فحص App Data.",
        "The ZIP must be a Save Vault backup (it carries a BackupManifest.plist). Files merge in place; system bundle ids are blocked.": "يجب أن يكون ملف ZIP نسخة احتياطية من Save Vault (فهو يحمل BackupManifest.plist). وتدمج الملفات في مكانها؛ أما معرفات حزم النظام فمحظورة.",
        "The backup of the original file couldn't be written, so nothing was saved.": "تعذرت كتابة النسخة الاحتياطية من الملف الأصلي، فلم يحفظ أي شيء.",
        "The browser asks for these credentials once, then remembers them for the session.": "يطلب المتصفح بيانات الاعتماد هذه مرة واحدة، ثم يتذكرها للجلسة.",
        "The bundle ID is not a valid identifier.": "معرف الحزمة ليس معرفا صالحا.",
        "The bundle ID of the one app this package may touch. Pick it from the App Data container scan, or type it.": "معرف حزمة التطبيق الوحيد الذي قد تلمسه هذه الحزمة. اختره من فحص حاوية App Data، أو اكتبه.",
        "The container scan found no containers.": "لم يعثر فحص الحاوية على أي حاويات.",
        "The container scan is shared with App Data and runs once per app session.": "فحص الحاوية مشترك مع App Data ويعمل مرة واحدة لكل جلسة تطبيق.",
        "The container scan runs once per session.": "يعمل فحص الحاوية مرة واحدة لكل جلسة.",
        "The core system: the sandbox escape and MobileGestalt access this whole app is built on.": "النظام الأساسي: الهروب من الحماية والوصول إلى MobileGestalt اللذان بني عليهما هذا التطبيق بالكامل.",
        "The current MobileGestalt will be entirely replaced with this %@ backup.": "سيستبدل MobileGestalt الحالي بالكامل بنسخة %@ الاحتياطية هذه.",
        "The current file is overwritten in place with the backup taken before the first byte edit.": "يستبدل الملف الحالي في مكانه بالنسخة الاحتياطية المأخوذة قبل أول تعديل بايت.",
        "The developer's GitHub profile.": "ملف المطور على GitHub.",
        "The directory is empty.": "الدليل فارغ.",
        "The entry is removed from the property list on the next Save.": "يزال الإدخال من قائمة الخصائص عند الحفظ التالي.",
        "The file couldn't be read under the container's sandbox extension — the details are in the Log. Nothing was written to it.": "تعذرت قراءة الملف ضمن امتداد sandbox الخاص بالحاوية — التفاصيل في Log. ولم يكتب فيه أي شيء.",
        "The file-based CacheData pattern method used by Enable iPadOS Mode (MobileGestaltCacheDataTweak).": "طريقة نمط CacheData المستندة إلى الملفات التي يستخدمها «تمكين وضع iPadOS» (MobileGestaltCacheDataTweak).",
        "The original identifiers are already registered to another developer account, which is why the Team ID suffix is required.": "المعرفات الأصلية مسجلة بالفعل لحساب مطور آخر، ولهذا يلزم لاحقة Team ID.",
        "The package could not be exported.": "تعذر تصدير الحزمة.",
        "The package store is unavailable (the App Group container did not resolve).": "مخزن الحزم غير متاح (تعذرت مطابقة حاوية App Group).",
        "The pairing file + Local Dev VPN tunnel are the transport Airlift uses to reach the device. Green = ready, gray = not ready.": "ملف الاقتران + نفق Local Dev VPN هما وسيلة النقل التي يستخدمها Airlift للوصول إلى الجهاز. الأخضر = جاهز، والرمادي = غير جاهز.",
        "The pathleak scan reads inodes one by one — this can take a few minutes.": "يقرأ فحص pathleak العقد واحدة تلو الأخرى — وقد يستغرق هذا بضع دقائق.",
        "The picked file could not be copied into the package.": "تعذر نسخ الملف المختار إلى الحزمة.",
        "The row is deleted from the database on the next Save.": "يحذف الصف من قاعدة البيانات عند الحفظ التالي.",
        "The sandbox extension for this container's directory was refused — the result code is in the Log.": "رفض امتداد sandbox الخاص بدليل هذه الحاوية — ورمز النتيجة في Log.",
        "The scan of %@ found no containers. The scan's baseline and counts are in the Log.": "لم يعثر فحص %@ على أي حاويات. وخط الأساس والعدادات الخاصة بالفحص في Log.",
        "The server shares this app's Documents folder only — SaveVaultBackups, staged vaults and uploads. Nothing outside it is ever served. Keep this page open while transferring: the server stops when you leave the page or the app goes to the background.": "لا يشارك الخادم إلا مجلد Documents الخاص بهذا التطبيق — SaveVaultBackups والمخازن المجهزة والرفوعات. ولا يقدم أي شيء خارجه أبدا. أبق هذه الصفحة مفتوحة أثناء النقل: يتوقف الخادم عند مغادرتك الصفحة أو انتقال التطبيق إلى الخلفية.",
        "The staging vault lives in this app's Documents and does NOT survive uninstalling WorkTweaks. Verify a restore in the app first, then release the vault.": "يوجد مخزن التجهيز في Documents الخاص بهذا التطبيق ولا يبقى بعد إلغاء تثبيت WorkTweaks. تحقق من الاستعادة في التطبيق أولا، ثم حرر المخزن.",
        "The stored package is removed. Files it already deployed, and its Deploy History receipts, are not touched.": "تزال الحزمة المخزنة. أما الملفات التي نشرتها بالفعل وإيصالات Deploy History الخاصة بها فلا تمس.",
        "Theme Information": "معلومات السمة",
        "Thermal history (%d)": "السجل الحراري (%d)",
        "These are the photos and videos in the BackUP_Data folder. Select the ones to restore, then Restore opens the share sheet — tap Save to Photos there.": "هذه هي الصور والفيديوهات الموجودة في مجلد BackUP_Data. حدد ما تريد استعادته، ثم يفتح «استعادة» ورقة المشاركة — اضغط على «حفظ في الصور» هناك.",
        "This app is free software under the GNU AGPL v3 license, following the licenses of the projects above.": "هذا التطبيق برنامج حر بموجب ترخيص GNU AGPL v3، وفقا لتراخيص المشاريع أعلاه.",
        "This app's own repository — issues and contributions welcome.": "مستودع هذا التطبيق الخاص — نرحب بالبلاغات والمساهمات.",
        "This deletes only the listed .ips / .crash / .panic files. The folders are kept.": "يحذف هذا فقط ملفات .ips / .crash / .panic المدرجة. وتبقى المجلدات.",
        "This device right now": "هذا الجهاز الآن",
        "This file isn't UTF-8 text, so it can't be edited as text. It can be edited byte-by-byte in the hex editor below.": "هذا الملف ليس نصا بترميز UTF-8، لذا لا يمكن تحريره كنص. ويمكن تحريره بايتا بايتا في محرر Hex أدناه.",
        "This file isn't UTF-8 text, so it can't be edited here. Nothing is ever written to it from this page.": "هذا الملف ليس نصا بترميز UTF-8، لذا لا يمكن تحريره هنا. ولا يكتب فيه أي شيء أبدا من هذه الصفحة.",
        "This iOS Version Isn't Supported": "إصدار iOS هذا غير مدعوم",
        "This is NOT an adblock: locking only stops ad assets landing on disk. Ads downloaded live over the network when the app opens can still appear.": "هذا ليس مانع إعلانات: فالقفل يمنع فقط وصول أصول الإعلانات إلى القرص. أما الإعلانات التي تنزل مباشرة عبر الشبكة عند فتح التطبيق فقد تظهر.",
        "This is the container's system-managed metadata file. iOS doesn't allow other processes to read its contents, so it can't be opened or edited here.": "هذا ملف البيانات الوصفية الخاص بالحاوية والذي يديره النظام. لا يسمح iOS لعمليات أخرى بقراءة محتوياته، لذا لا يمكن فتحه أو تحريره هنا.",
        "This only clears the list. It does not undo anything that was applied.": "هذا يمسح القائمة فقط. ولا يتراجع عن أي شيء تم تطبيقه.",
        "This only makes the Join Waitlist button appear. The Siri AI model may still refuse to download — that part is not solved by this method yet.": "هذا يجعل زر Join Waitlist يظهر فقط. وقد يرفض نموذج Siri AI التنزيل — فهذا الجزء لم تحله هذه الطريقة بعد.",
        "This package was rejected": "رفضت هذه الحزمة",
        "This permanently deletes the contents of %@ in %@ (%@). The folders themselves stay in place.": "يحذف هذا نهائيا محتويات %@ في %@ (%@). وتبقى المجلدات نفسها في مكانها.",
        "This property list has no top-level entries.": "لا تحتوي قائمة الخصائص هذه على إدخالات في المستوى الأعلى.",
        "This removes the wallpaper imported from %@ — its descriptor folder is deleted from PosterBoard's data store.": "يزيل هذا الخلفية المستوردة من %@ — ويحذف مجلد الواصف الخاص بها من مخزن بيانات PosterBoard.",
        "This restores the MobileGestalt backup saved on first launch (SavedGestalt.plist).": "يستعيد هذا النسخة الاحتياطية من MobileGestalt المحفوظة عند أول تشغيل (SavedGestalt.plist).",
        "This table has no columns to edit.": "لا يحتوي هذا الجدول على أعمدة للتحرير.",
        "Total CacheExtra keys": "إجمالي مفاتيح CacheExtra",
        "True health": "الصحة الحقيقية",
        "Try Again": "إعادة المحاولة",
        "Turn on the Charge Limit Menu toggle (Add feature section).": "فعل مبدل قائمة حد الشحن (قسم «إضافة ميزة»).",
        "Tutorials": "الدروس",
        "Tweaks": "التعديلات",
        "Tweaks Applied": "التعديلات المطبقة",
        "Tweaks UI": "واجهة التعديلات",
        "Tweaks are locked": "التعديلات مقفلة",
        "Two ways to get a pairing file: Pair This iPhone (iOS 27 only) shows a 6-digit PIN — approve it in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. Or import a pairing file (.plist) from your computer manually. The pairing file is saved in the app.": "طريقتان للحصول على ملف اقتران: يعرض «اقتران هذا iPhone» (iOS 27 فقط) رقم PIN من 6 أرقام — وافق عليه في Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. أو استورد ملف اقتران (.plist) من جهاز الكمبيوتر يدويا. ويحفظ ملف الاقتران في التطبيق.",
        "Type": "النوع",
        "Type the region suffix as shown in Settings > General > About, e.g. PA/A or LL/A. It changes the Model Number suffix after Apply.": "اكتب لاحقة المنطقة كما تظهر في Settings > General > About، مثل PA/A أو LL/A. فهي تغير لاحقة رقم الطراز بعد التطبيق.",
        "Type: %@ (%@). %@": "النوع: %@ (%@). %@",
        "Type: %@. %@": "النوع: %@. %@",
        "Universal mode flashes ~600 files for all languages & Bold text. Selecting a specific language (e.g. Ukrainian) speeds up flashing dramatically.": "يثبت الوضع العام نحو 600 ملف لكل اللغات والنص العريض. ويؤدي اختيار لغة محددة (مثل الأوكرانية) إلى تسريع التثبيت بشكل كبير.",
        "Unknown time": "وقت غير معروف",
        "Unlock": "فتح",
        "Unlocks the Tweaks tab. Turn this on to start using tweaks.": "يفتح تبويب Tweaks. فعل هذا لبدء استخدام التعديلات.",
        "Unsupported": "غير مدعوم",
        "Unsupported iOS • %@": "iOS غير مدعوم • %@",
        "Use Skin": "استخدام الغلاف",
        "Username": "اسم المستخدم",
        "Utilities": "الأدوات",
        "VPN Tunnel": "نفق VPN",
        "VPN tunnel is off. Open the Local Dev VPN app and connect — flashing needs it.": "نفق VPN متوقف. افتح تطبيق Local Dev VPN واتصل — فالتثبيت يحتاجه.",
        "Valid until %@": "صالح حتى %@",
        "Value": "القيمة",
        "Value: %@": "القيمة: %@",
        "Version %@": "الإصدار %@",
        "Video": "فيديو",
        "Video chosen (%.1f s) — tap to change": "تم اختيار الفيديو (%.1f ث) — اضغط للتغيير",
        "Videos use the first 12 seconds. Photos become a single still frame.": "تستخدم الفيديوهات أول 12 ثانية. وتصبح الصور إطارا ثابتا واحدا.",
        "View Full License & Credits": "عرض الترخيص والفضل الكامل",
        "Voice Memos": "المذكرات الصوتية",
        "Voice Memos & AI Cache": "المذكرات الصوتية وذاكرة الذكاء الاصطناعي المؤقتة",
        "Voltage": "الجهد",
        "WARNING: These tweaks can break features on your device or softbrick it if misused. After Apply you choose Respring or Restart; Revert and Backup restores require a full device restart.": "تحذير: قد تعطل هذه التعديلات ميزات على جهازك أو تتلفه برمجيا إذا أسيء استخدامها. وبعد التطبيق تختار إعادة تشغيل الواجهة أو إعادة التشغيل؛ أما التراجع واستعادة النسخ الاحتياطية فيتطلبان إعادة تشغيل كاملة للجهاز.",
        "Waiting for the App Data scan…": "جار انتظار فحص App Data…",
        "Wallet Cards": "بطاقات المحفظة",
        "Wallpaper": "الخلفية",
        "Wallpaper name": "اسم الخلفية",
        "Warning": "تحذير",
        "Warning: raw byte edits have no structure validation — a wrong byte can corrupt this file or the owning app's data. A backup of the original is saved before the first edit.": "تحذير: لا تخضع تعديلات البايت الخام لأي تحقق من البنية — فبايت خاطئ قد يتلف هذا الملف أو بيانات التطبيق المالك. وتحفظ نسخة احتياطية من الأصل قبل أول تعديل.",
        "WeChat accounts": "حسابات WeChat",
        "Welcome to WorkTweaks": "مرحبا بك في WorkTweaks",
        "What this does": "ماذا يفعل هذا",
        "When enabled, MobileGestalt is written in-place on the same inode, which (hopefully) prevents iOS from regenerating the cache on reboot. Disable to use atomic file replacement instead.": "عند التفعيل، تكتب MobileGestalt في مكانها على نفس العقدة، مما يمنع iOS (على أمل) من إعادة توليد ذاكرة التخزين المؤقت عند إعادة التشغيل. عطلها لاستخدام استبدال الملف الذري بدلا من ذلك.",
        "Where it goes": "إلى أين يذهب",
        "Whitelist": "القائمة البيضاء",
        "Whitelisted": "مدرج في القائمة البيضاء",
        "Whole numbers only.": "أعداد صحيحة فقط.",
        "Wi-Fi File Sharing": "مشاركة الملفات عبر Wi-Fi",
        "WorkTweaks is free software under the GNU Affero General Public License v3.0. The core (worse_query) is GPL-3.0, but the CacheExtra key knowledge from mond and the CacheData method from Nugget are AGPL-3.0 — GPLv3 code may be combined into an AGPLv3 work, and the AGPL terms then cover the combined work as a whole.": "WorkTweaks برنامج حر بموجب ترخيص GNU Affero General Public License v3.0. النواة (worse_query) هي GPL-3.0، لكن معرفة مفاتيح CacheExtra من mond وطريقة CacheData من Nugget هما AGPL-3.0 — ويجوز دمج كود GPLv3 في عمل AGPLv3، وتغطي شروط AGPL عندئذ العمل المدمج ككل.",
        "WorkTweaks must be installed with iLoader, or by signing the IPA with Signed Apps, so that its App Group works correctly.": "يجب تثبيت WorkTweaks باستخدام iLoader، أو بتوقيع ملف IPA باستخدام Signed Apps، حتى تعمل App Group الخاصة به بشكل صحيح.",
        "WorkTweaks only works when its App Group is part of the signing profile. Guides A and B make sure that happens — pick the one that fits you. Guide C turns on the new Siri AI.": "لا يعمل WorkTweaks إلا عندما تكون App Group الخاصة به جزءا من ملف التوقيع. ويضمن الدليلان أ وب حدوث ذلك — اختر ما يناسبك. أما الدليل ج فيشغل Siri AI الجديد.",
        "WorkTweaks v3.0 only opens on the builds listed above: the app checks your device's build at launch, and any other build gets the \"not supported\" screen instead of the app. On iOS 18 and iOS 26, only App Data and Airlift are supported (partial support). Developed and tested on iOS 27.0.1 (24A446).": "لا يفتح WorkTweaks v3.0 إلا على البنيات المدرجة أعلاه: يتحقق التطبيق من بنية جهازك عند الإطلاق، وأي بنية أخرى تحصل على شاشة «غير مدعوم» بدلا من التطبيق. وعلى iOS 18 وiOS 26، لا يدعم إلا App Data وAirlift (دعم جزئي). تم التطوير والاختبار على iOS 27.0.1 (24A446).",
        "Works on iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 and later patched the exploit).": "يعمل على iOS 18.0 – 27.2 beta 2 (وقد رقع iOS 27.2 beta 3 والإصدارات الأحدث الثغرة).",
        "Write Method": "طريقة الكتابة",
        "Write access available — Clean All can delete the listed reports.": "الوصول للكتابة متاح — ويمكن ل «تنظيف الكل» حذف التقارير المدرجة.",
        "Writes SharedDeviceConfiguration.plist in place, keeping every other key in the file. SpringBoard reads the file when it starts, so a respring or restart is needed to see the change.": "يكتب SharedDeviceConfiguration.plist في مكانه، مع الاحتفاظ بكل مفتاح آخر في الملف. يقرأ SpringBoard الملف عند بدئه، لذا يلزم إعادة تشغيل الواجهة أو إعادة التشغيل لرؤية التغيير.",
        "Writing or verifying the file failed — the details are in the Log.": "فشلت كتابة الملف أو التحقق منه — التفاصيل في Log.",
        "Writing the file failed — the details are in the Log.": "فشلت كتابة الملف — التفاصيل في Log.",
        "Writing the footnote failed — the details are in the Log.": "فشلت كتابة الحاشية — التفاصيل في Log.",
        "Yes": "نعم",
        "You can add multiple hashes at once — separate them with spaces, commas, or newlines.": "يمكنك إضافة عدة بصمات دفعة واحدة — افصل بينها بمسافات أو فواصل أو أسطر جديدة.",
        "Your All BackUP Files Here!": "كل ملفات BackUP الخاصة بك هنا!",
        "Your device is running **%@**. WorkTweaks v2.0 only runs on the builds listed below, so the app can't open on this version.": "يعمل جهازك بنظام **%@**. لا يعمل WorkTweaks v2.0 إلا على البنيات المدرجة أدناه، لذا لا يمكن للتطبيق أن يفتح على هذا الإصدار.",
        "ZIP backup saved: %@. Share it to Files before you uninstall anything.": "تم حفظ النسخة الاحتياطية ZIP: %@. شاركها إلى Files قبل إلغاء تثبيت أي شيء.",
        "empty": "فارغ",
        "iOS Version": "إصدار iOS",
        "iPadOS Features": "ميزات iPadOS",
        "invalid": "غير صالح",
        "the CacheExtra key knowledge behind the tweak catalog": "معرفة مفاتيح CacheExtra الكامنة وراء كتالوج التعديلات",
        "the file-based CacheData method (iPadOS Mode)": "طريقة CacheData المستندة إلى الملفات (وضع iPadOS)",
        "the package": "الحزمة",
        "the respring technique (jailbreak.party)": "تقنية إعادة تشغيل الواجهة (jailbreak.party)",
        "true or false.": "صحيح أو خطأ.",
        "v3.0 checks your device's build at launch and only opens on the supported builds. The full version & build list lives in License & Credits.": "يتحقق v3.0 من بنية جهازك عند الإطلاق ولا يفتح إلا على البنيات المدعومة. وتوجد قائمة الإصدارات والبنيات الكاملة في «الترخيص والفضل».",
        "worse_query — the core system (sandbox escape)": "worse_query — النظام الأساسي (الهروب من الحماية)",
        "Meet the Developer": "تعرف على المطور",
        "WorkTweaks is built by Adnan — find him on GitHub and TikTok.": "بنى Adnan تطبيق WorkTweaks — تجده على GitHub وTikTok.",
        "Features": "الميزات",
        "Everything in WorkTweaks, at a glance.": "كل ما في WorkTweaks، في لمحة.",
        "Tweaks & System": "التعديلات والنظام",
        "Files & Data": "الملفات والبيانات",
        "Look & Feel": "المظهر والإحساس",
        "Setup & More": "الإعداد والمزيد",
        "Free and open source — the projects below made it possible.": "مجاني ومفتوح المصدر — المشاريع أدناه جعلت ذلك ممكنا.",
        "Credits": "الفضل",
        "Next": "التالي",
        "Sandbox Escape": "الهروب من Sandbox",
        "PosterBoard": "PosterBoard",
        "SQLite / plist editor": "محرر SQLite / plist",
        "Airlift": "Airlift",
        "Languages": "اللغات",
        "24 catalog tweaks — Dynamic Island, iPadOS Mode, custom region and more.": "24 تعديلا في الكتالوج — Dynamic Island، ووضع iPadOS، والمنطقة المخصصة، والمزيد.",
        "Reach system folders the sandbox normally hides.": "الوصول إلى مجلدات النظام التي تخفيها الحماية عادة.",
        "Browse any app's container, edit files, and build portable patches.": "تصفح حاوية أي تطبيق، وحرر الملفات، وأنشئ تصحيحات محمولة.",
        "Make lock-screen wallpapers from your photos and videos.": "أنشئ خلفيات شاشة القفل من صورك وفيديوهاتك.",
        "Free space by cleaning app caches, safely.": "حرر مساحة بتنظيف ذاكرات التطبيقات المؤقتة، بأمان.",
        "Lock ad splash-screen caches so apps open without the splash ad.": "اقفل ذاكرات إعلانات شاشة البداية المؤقتة حتى تفتح التطبيقات دون إعلان البداية.",
        "Back up an app's save data and restore it after a reinstall.": "انسخ بيانات حفظ التطبيق احتياطيا واستعدها بعد إعادة التثبيت.",
        "Battery health, cycle count and temperature — read-only.": "صحة البطارية وعدد الدورات ودرجة الحرارة — للقراءة فقط.",
        "See why apps were killed, with crash logs you can delete.": "اعرف لماذا أنهيت التطبيقات، مع سجلات أعطال يمكنك حذفها.",
        "Share files with your PC over Wi-Fi, protected by a PIN.": "شارك الملفات مع جهاز الكمبيوتر عبر Wi-Fi، محمية برقم PIN.",
        "Edit app databases and preference files in place.": "حرر قواعد بيانات التطبيقات وملفات التفضيلات في مكانها.",
        "List installed profiles, read-only — no fake supervision.": "اعرض ملفات التعريف المثبتة، للقراءة فقط — دون إشراف مزيف.",
        "Export voice memos and check Apple Intelligence cache size.": "صدر المذكرات الصوتية وتحقق من حجم ذاكرة Apple Intelligence المؤقتة.",
        "Flash passcode themes and wallet card skins over the pairing tunnel.": "ثبت سمات رمز المرور وأغلفة بطاقات المحفظة عبر نفق الاقتران.",
        "Pair this iPhone on-device and unlock Airlift.": "اقترن بهذا iPhone على الجهاز وافتح Airlift.",
        "Snapshots of your tweaks, plus All Data Backup for photos and videos.": "لقطات لتعديلاتك، إضافة إلى نسخ كل البيانات احتياطيا للصور والفيديوهات.",
        "Every action, logged — send it when something goes wrong.": "كل إجراء، مسجل — أرسله عند حدوث خطأ.",
        "English, Indonesian, Chinese, Vietnamese and Russian — the UI follows you.": "الإنجليزية والإندونيسية والصينية والفيتنامية والروسية — تتبعك الواجهة.",
        "Open with Text Editor": "فتح بمحرر النصوص",
        "Read Tutorial": "قراءة الدليل",
        "Jump to Siri line": "الانتقال إلى سطر Siri",
        "Restore Pristine Backup": "استعادة النسخة الاحتياطية الأصلية",
        "Find…": "بحث…",
        "Go to line": "الانتقال إلى سطر",
        "Line number": "رقم السطر",
        "Go": "انتقال",
        "View and edit the file with line numbers.": "اعرض الملف وحرره مع أرقام الأسطر.",
        "Open Mobile Gestalt.plist": "فتح Mobile Gestalt.plist",
        "Manual edit needed": "يلزم تعديل يدوي",
        "The Siri byte is flipped (0x02) — the patch is on.": "بايت Siri مقلوب (0x02) — التصحيح مفعل.",
        "The Siri byte is 0x00 — the patch is off.": "بايت Siri هو 0x00 — التصحيح متوقف.",
        "The patch pattern matches more than once, so the automatic patch refuses to guess — edit the Siri line by hand.": "يتطابق نمط التصحيح أكثر من مرة، لذا يرفض التصحيح التلقائي التخمين — حرر سطر Siri يدويا.",
        "The patch was found, but not on line 104 — open the viewer to see its line.": "تم العثور على التصحيح، لكن ليس في السطر 104 — افتح العارض لرؤية سطره.",
        "The patch line was not found in this file — check the Mobile Gestalt.plist viewer.": "لم يتم العثور على سطر التصحيح في هذا الملف — تحقق من عارض Mobile Gestalt.plist.",
        "CacheData is missing from MobileGestalt.": "CacheData مفقودة من MobileGestalt.",
        "This is the same text Filza shows for this file. CacheData is the long base64 block; its lines are 51 bytes each. The Siri line is highlighted.": "هذا هو النص نفسه الذي يعرضه Filza لهذا الملف. CacheData هي كتلة base64 الطويلة؛ وتتكون أسطرها من 51 بايتا لكل سطر. وسطر Siri مميز.",
        "Siri line: line %d": "سطر Siri: السطر %d",
        "On this device the Siri line is line %d, not 104 — the guide's line number varies by device.": "على هذا الجهاز، سطر Siri هو السطر %d، وليس 104 — فرقم السطر في الدليل يختلف حسب الجهاز.",
        "No matches": "لا توجد مطابقات",
        "%d of %d matches": "%d من %d مطابقة",
        "%d matches": "%d مطابقة",
        "Going back discards unsaved edits.": "الرجوع يتجاهل التعديلات غير المحفوظة.",
        "Restore the pristine backup made before the first save?": "استعادة النسخة الاحتياطية الأصلية التي أنشئت قبل أول حفظ؟",
        "Pristine backup restored.": "تمت استعادة النسخة الاحتياطية الأصلية.",
        "Unapplied changes in the Tweaks tab will be lost when you save here — Apply them first.": "ستفقد التغييرات غير المطبقة في تبويب Tweaks عند الحفظ هنا — طبقها أولا.",
        "Saved — the Siri patch is now %@.": "تم الحفظ — أصبح تصحيح Siri الآن %@.",
        "Saved — the file was written, but the Siri line does not match the patch shape.": "تم الحفظ — كتب الملف، لكن سطر Siri لا يطابق شكل التصحيح.",
        "A pristine backup is made before the first save, and only CacheData changes are written.": "تنشأ نسخة احتياطية أصلية قبل أول حفظ، ولا تكتب إلا تغييرات CacheData.",
        "Save the edited file?": "حفظ الملف المعدل؟",
        "MobileGestalt could not be loaded.": "تعذر تحميل MobileGestalt.",
        "Reload MobileGestalt": "إعادة تحميل MobileGestalt",
        "Loading MobileGestalt.plist…": "جار تحميل MobileGestalt.plist…",
        "Open \"Mobile Gestalt.plist\" in the Tweaks tab (below the Siri AI Cache Patch card), then tap \"Open with Text Editor\".": "افتح «Mobile Gestalt.plist» في تبويب Tweaks (أسفل بطاقة Siri AI Cache Patch)، ثم اضغط على «Open with Text Editor».",
        "Use the find field to jump to line 104 — the viewer shows the exact Siri line number for this device.": "استخدم حقل البحث للانتقال إلى السطر 104 — يعرض العارض رقم سطر Siri الدقيق لهذا الجهاز.",
        "On that line, change the 30th base64 character from A to g (this flips CacheData byte 21 from 0x00 to 0x02). To turn the patch off again, change it back from g to A. Then tap Save — a pristine backup is made before the first save.": "في ذلك السطر، غير الحرف الثلاثين من base64 من A إلى g (فيقلب هذا بايت CacheData رقم 21 من 0x00 إلى 0x02). ولإيقاف التصحيح مجددا، أعد تغييره من g إلى A. ثم اضغط على «حفظ» — تنشأ نسخة احتياطية أصلية قبل أول حفظ.",
        "Then turn on Apple Intelligence and the Charge Limit Menu toggle, set Spoofing to iPhone 17 Pro, Apply, respring and restart — Join Waitlist should appear in Settings > Apple Intelligence & Siri.": "ثم فعل Apple Intelligence ومبدل قائمة حد الشحن، واضبط الانتحال على iPhone 17 Pro، وطبق، وأعد تشغيل الواجهة وأعد التشغيل — وينبغي أن يظهر Join Waitlist في Settings > Apple Intelligence & Siri.",
        "Turn on the Apple Intelligence toggle and the Charge Limit Menu toggle (Add feature section).": "فعل مبدل Apple Intelligence ومبدل قائمة حد الشحن (قسم «إضافة ميزة»).",
        "Edit the Siri line": "تحرير سطر Siri",
        "Change one character on the Siri line to flip the patch — you don't need to read the whole file.": "غير حرفا واحدا في سطر Siri لقلب التصحيح — لا حاجة لقراءة الملف كاملا.",
        "View file lines": "عرض أسطر الملف",
        "Packages by Adnan.120hz — tap one to install it into its app, or save its zip in Files.": "حزم من Adnan.120hz — اضغط على واحدة لتثبيتها في تطبيقها، أو احفظ ملفها المضغوط في Files.",
        "Save to Files": "حفظ في Files",
        "Installed": "مثبت",
        "Installed on %@": "مثبت في %@",
        "No packages could be loaded from the app bundle.": "تعذر تحميل أي حزم من حزمة التطبيق.",
        "Install complete — patched (revision 7). Signed with your certificate — ready to launch.": "اكتمل التثبيت — مصحح (المراجعة 7). موقع بشهادتك — جاهز للتشغيل.",
        "Install complete — patched (revision 7). No certificate imported, so it cannot launch yet.": "اكتمل التثبيت — مصحح (المراجعة 7). لم تستورد شهادة، لذا لا يمكنه التشغيل بعد.",
        "Contacting Apple…": "جار الاتصال ب Apple…",
        "Validating two-factor code…": "جار التحقق من رمز العاملين…",
        "Creating certificate…": "جار إنشاء الشهادة…",
        "Automatic": "تلقائي",
        "Attach and detach": "إرفاق وفصل",
        "Universal": "عام",
        "Legacy": "قديم",
        "Geode": "Geode",
        "If Siri is stuck on 'Adding support for Siri is in progress' with the model already downloaded, that is a different problem — this method does not fix it.": "إذا كان Siri عالقا على «Adding support for Siri is in progress» مع تنزيل النموذج بالفعل، فهذه مشكلة مختلفة — لا تحلها هذه الطريقة.",



