    // pt-BR
    static let ptBR: [String: String] = [
        " and ": " e ",
        " — battery table %@": " — tabela de bateria %@",
        "%@ — %@": "%@ — %@",
        "%@ — %d file(s)": "%@ — %d arquivo(s)",
        "%@ — from %@": "%@ — de %@",
        "%@ • %@ • %@ • %d file": "%@ • %@ • %@ • %d arquivo",
        "%@ • %@ • %@ • %d files": "%@ • %@ • %@ • %d arquivos",
        "%@ • %@ • %d file": "%@ • %@ • %d arquivo",
        "%@ • %@ • %d files": "%@ • %@ • %d arquivos",
        "%d active tweaks · %d CacheExtra keys": "%d tweaks ativos · %d chaves CacheExtra",
        "%d bytes — length-preserving edits only: byte values can change, the file's length never does.": "%d bytes — apenas edições que preservam o tamanho: os valores dos bytes podem mudar, o tamanho do arquivo nunca muda.",
        "%d cards": "%d cartões",
        "%d character(s). The text appears in small type at the bottom of the Lock Screen. Leave it empty and tap Apply Footnote to remove the footnote.": "%d caractere(s). O texto aparece em letras pequenas na parte inferior da Tela de Bloqueio. Deixe em branco e toque em Aplicar Nota de Rodapé para remover a nota.",
        "%d cycles": "%d ciclos",
        "%d file(s) examined — the scan walks the whole container, so large apps take a while.": "%d arquivo(s) examinados — a verificação percorre todo o contêiner, então apps grandes demoram um pouco.",
        "%d file(s) in BackUP_Data.": "%d arquivo(s) em BackUP_Data.",
        "%d file(s) • %@ total • %@ in Caches": "%d arquivo(s) • %@ no total • %@ em Caches",
        "%d file(s) • %@ • staged %@": "%d arquivo(s) • %@ • preparado %@",
        "%d item": "%d item",
        "%d item(s) removed, %d could not be removed (in use or protected).": "%d item(ns) removido(s), %d não puderam ser removidos (em uso ou protegidos).",
        "%d item(s) removed.": "%d item(ns) removido(s).",
        "%d items": "%d itens",
        "%d keys": "%d chaves",
        "%d largest file(s) — %@ in the top %d.": "%d maior(es) arquivo(s) — %@ entre os %d maiores.",
        "%d of %d": "%d de %d",
        "%d row(s).": "%d linha(s).",
        "%d selected": "%d selecionado(s)",
        "%d to lock": "%d para bloquear",
        ", thermal table %@": ", tabela térmica %@",
        "1 card": "1 cartão",
        "1. Open the Translate app, delete the downloaded English (US) language, then download it again.\n2. Go to Settings > General > Language & Region, change the region from United States to another country, then change it back to United States.\n3. Turn off Low Power Mode (Settings > Battery).\n4. Connect to Wi-Fi (and keep your iPhone charging) while Apple Intelligence finishes downloading.": "1. Abra o app Traduzir, apague o idioma inglês (EUA) baixado e baixe-o novamente.\n2. Vá em Ajustes > Geral > Idioma e Região, mude a região de Estados Unidos para outro país e depois volte para Estados Unidos.\n3. Desative o Modo Pouca Energia (Ajustes > Bateria).\n4. Conecte-se ao Wi-Fi (e mantenha o iPhone carregando) enquanto o Apple Intelligence termina de baixar.",
        "1. Tap Scan Cards above.": "1. Toque em Verificar Cartões acima.",
        "1. Use the iPhone 16 Pro subtype.\n2. Settings > Appearance > Display Zoom > Large Text, then go Back and set Text Size to Small (optional).": "1. Use o subtipo iPhone 16 Pro.\n2. Ajustes > Aparência > Zoom da Tela > Texto Grande e, em seguida, volte e defina Tamanho do Texto como Pequeno (opcional).",
        "2. On this iPhone, double-click the Side button (Apple Pay), authenticate with Face ID, and tap your card.": "2. Neste iPhone, clique duas vezes no botão lateral (Apple Pay), autentique-se com o Face ID e toque no seu cartão.",
        "3. Your card will appear here automatically!": "3. Seu cartão aparecerá aqui automaticamente!",
        "A .tendies package is a ZIP archive containing one or more wallpaper descriptors: loose descriptor folders, a descriptors folder, or a container layout mirroring PosterBoard's data store (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Stored and deflated ZIP entries are supported — the same reader Deploy uses; encrypted and ZIP64 archives are rejected.": "Um pacote .tendies é um arquivo ZIP com um ou mais descritores de papel de parede: pastas de descritores soltas, uma pasta descriptors ou um layout de contêiner que espelha o armazenamento de dados do PosterBoard (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Entradas ZIP armazenadas e compactadas são suportadas — o mesmo leitor que o Deploy usa; arquivos criptografados e ZIP64 são rejeitados.",
        "A Deploy package replaces files inside exactly one app — the app named by its bundle ID. It cannot touch any other app: every target path is relative to that app's container, and packages with absolute or \"..\" paths are rejected whole.": "Um pacote Deploy substitui arquivos dentro de exatamente um app — o app identificado pelo seu bundle ID. Ele não pode tocar em nenhum outro app: todos os caminhos de destino são relativos ao contêiner desse app, e pacotes com caminhos absolutos ou \"..\" são rejeitados por inteiro.",
        "A MobileGestalt tweak app for iOS 26/27, built on the open-source projects credited below. Use at your own risk — tweaks modify system files.": "Um app de tweaks MobileGestalt para iOS 26/27, feito com base nos projetos de código aberto creditados abaixo. Use por sua conta e risco — os tweaks modificam arquivos do sistema.",
        "A MobileGestalt tweak tool for iOS 26 & 27 — unlock your device's hidden features without a jailbreak, powered by the worse_query sandbox escape.": "Uma ferramenta de tweaks MobileGestalt para iOS 26 e 27 — desbloqueie os recursos ocultos do seu dispositivo sem jailbreak, com o escape de sandbox worse_query.",
        "A bundle ID is required — it names the one app this package may touch.": "É necessário um bundle ID — ele identifica o único app que este pacote pode tocar.",
        "A package is ONE .zip file containing a manifest.json at its top level plus the payload files it names. The Package Builder exports that zip (save it in Files); Deploy imports it, resolves the target itself from the manifest, and applies it — no location picking, the destinations come from the zip.": "Um pacote é UM arquivo .zip contendo um manifest.json no nível superior, além dos arquivos de conteúdo que ele nomeia. O Criador de Pacotes exporta esse zip (salve-o no Arquivos); o Deploy o importa, resolve o destino a partir do manifesto e o aplica — sem escolher local, os destinos vêm do zip.",
        "A partial restore can affect photos and videos. Back them up first — optional, you can skip it.": "Uma restauração parcial pode afetar fotos e vídeos. Faça backup deles primeiro — é opcional, você pode pular.",
        "A respring is required before a new wallpaper appears in the gallery.": "É necessário um respring antes que um novo papel de parede apareça na galeria.",
        "A signed IPA only works on the device registered in its profile.": "Um IPA assinado só funciona no dispositivo registrado no seu perfil.",
        "A snapshot is also created automatically at every Apply, containing the state that Apply just produced. The Original backup is created once, the first time MobileGestalt is read successfully.": "Um snapshot também é criado automaticamente a cada Aplicar, contendo o estado que o Aplicar acabou de produzir. O backup Original é criado uma única vez, na primeira vez em que o MobileGestalt é lido com sucesso.",
        "A whitelisted bundle id (and its App Groups) or exact path is never locked by Lock All. Newly whitelisted targets are restored writable right away. SMZDM is whitelisted by default — its splash cache is known to crash the app when locked.": "Um bundle id na lista de permissões (e seus App Groups) ou um caminho exato nunca é bloqueado pelo Bloquear Tudo. Alvos recém-adicionados à lista voltam a ser graváveis na hora. O SMZDM já vem na lista por padrão — seu cache de splash pode travar o app quando bloqueado.",
        "AI Cache": "Cache de IA",
        "APFS vault: clonefile staging, zero extra space, atomic restore with rollback. ZIP backup: the same three folders as one .zip file, restored by merging in place.": "Cofre APFS: preparo com clonefile, zero espaço extra, restauração atômica com reversão. Backup ZIP: as mesmas três pastas em um único arquivo .zip, restaurado por mesclagem no local.",
        "About this feature": "Sobre este recurso",
