        "Backup and receipt saved under DeployBackups/%@ — restore it any time from Deploy History.": "Backup e recibo salvos em DeployBackups/%@ — restaure a qualquer momento no Histórico do Deploy.",
        "Bars: %d": "Barras: %d",
        "Battery": "Bateria",
        "Battery & Thermal": "Bateria e Térmico",
        "Battery & Thermal reads the system powerlog database: battery level, true health (raw max vs design capacity), cycle count, cell temperature, and thermal history. Values come from the latest samples in the log, newest first.": "Bateria e Térmico lê o banco de dados powerlog do sistema: nível da bateria, saúde real (máximo bruto vs. capacidade de projeto), contagem de ciclos, temperatura da célula e histórico térmico. Os valores vêm das amostras mais recentes do registro, das mais novas para as mais antigas.",
        "Battery Percentage": "Porcentagem da Bateria",
        "Before anything is written, every file that already exists is backed up (see Deploy History). Existing files are then replaced in place; new files are created.": "Antes de qualquer escrita, todos os arquivos existentes recebem backup (veja o Histórico do Deploy). Os arquivos existentes são então substituídos no local; arquivos novos são criados.",
        "Blocked — pairing / VPN not ready": "Bloqueado — pareamento / VPN não prontos",
        "Both need a pairing file first: Sandbox → Utilities → Get Pairing File. A loopback VPN (Local Dev VPN) is strongly recommended while flashing.": "Ambos precisam primeiro de um arquivo de pareamento: Sandbox → Utilitários → Obter Arquivo de Pareamento. Uma VPN de loopback (Local Dev VPN) é fortemente recomendada durante a gravação.",
