        "Built on the worse_query core system by ForceQuit OS, with CacheExtra key knowledge from mond by rooootdev (AGPL-3.0).": "Feito com base no sistema principal worse_query, de ForceQuit OS, com conhecimento de chaves CacheExtra do mond, de rooootdev (AGPL-3.0).",
