        "Cache Locations": "Locais de Cache",
        "Cache lives in two places inside an app's data container: Library/Caches and tmp. Only the contents of those two folders are deleted — the folders themselves stay, and Documents and the rest of Library are never touched.": "O cache fica em dois lugares dentro do contêiner de dados de um app: Library/Caches e tmp. Somente o conteúdo dessas duas pastas é apagado — as pastas permanecem, e Documentos e o restante de Library nunca são tocados.",
