        "Disable Dynamic Island System": "Desativar Sistema Dynamic Island",
        "Disables the Dynamic Island system completely — not just hiding it. Key: SBSuppressDynamicIslandCompletely in the managed com.apple.springboard.plist (set = 1).": "Desativa o sistema Dynamic Island por completo — não apenas o oculta. Chave: SBSuppressDynamicIslandCompletely no com.apple.springboard.plist gerenciado (definir = 1).",
        "Do not reboot! Your MobileGestalt.plist seems to be %@.": "Não reinicie! Seu MobileGestalt.plist parece estar %@.",
        "Done": "Concluído",
        "Download the WorkTweaks IPA from GitHub.": "Baixe o IPA do WorkTweaks no GitHub.",
        "Download the latest WorkTweaks IPA from the GitHub Releases page.": "Baixe o IPA mais recente do WorkTweaks na página de Releases do GitHub.",
        "Drag to move, pinch to zoom. The skin is saved at 1536×969.": "Arraste para mover, pinça para ampliar. A capa é salva em 1536×969.",
        "Dual SIM: primary is the line used for data, secondary is the other line.": "Dual SIM: a principal é a linha usada para dados, a secundária é a outra linha.",
        "Dynamic Island": "Dynamic Island",
        "Each wallpaper in the package is copied into PosterBoard's data store under a fresh identifier, so it can never clash with an existing wallpaper. A respring is required before a new wallpaper appears in the gallery.": "Cada papel de parede do pacote é copiado para o armazenamento de dados do PosterBoard com um novo identificador, para nunca conflitar com um papel de parede existente. É necessário um respring antes que um novo papel de parede apareça na galeria.",
        "Edit": "Editar",
        "Edit Bytes": "Editar Bytes",
        "Edit Cell": "Editar Célula",
        "Edit Package": "Editar Pacote",
        "Edit Value": "Editar Valor",
        "Edit in Theme Creator": "Editar no Criador de Temas",
        "Edits replace byte values only — the file's length never changes. A backup of the original is saved before the first edit.": "As edições substituem apenas os valores dos bytes — o tamanho do arquivo nunca muda. Um backup do original é salvo antes da primeira edição.",
        "Elements": "Elementos",
        "Eligibility": "Elegibilidade",
        "Empty": "Vazio",
        "Enter this PIN in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks.": "Digite este PIN em Ajustes › Privacidade e Segurança › Modo de Desenvolvedor › Parear com o WorkTweaks.",
        "Enumerating containers with pathleak — this can take a while.": "Listando contêineres com pathleak — isso pode demorar um pouco.",
        "Enumeration": "Enumeração",
        "Error -1 means the signed app cannot access its App Group container. Diagnostics reads the groups from your signed provisioning profile and probes them all. If it reports no signed groups, the IPA was signed without an App Group and must be re-signed with one — no name typed here can fix that.": "O erro -1 significa que o app assinado não consegue acessar seu contêiner de App Group. O Diagnóstico lê os grupos do seu perfil de provisionamento assinado e testa todos eles. Se ele informar que não há grupos assinados, o IPA foi assinado sem um App Group e precisa ser reassinado com um — nenhum nome digitado aqui pode corrigir isso.",
        "Escape": "Escape",
        "Every menu that was applied, newest first. This is a history log — clearing it only clears the list, it does not undo anything.": "Cada menu que foi aplicado, do mais recente ao mais antigo. Isto é um registro de histórico — limpá-lo apenas limpa a lista, não desfaz nada.",
        "Exact path": "Caminho exato",
        "Expired %@ — reinstall the app first.": "Expirado em %@ — reinstale o app primeiro.",
        "Expires soon — %@. Stage now, reinstall before it ends.": "Expira em breve — %@. Prepare agora, reinstale antes que termine.",
        "Export": "Exportar",
        "Export Selected (%d)": "Exportar Selecionados (%d)",
        "Export ZIP": "Exportar ZIP",
        "Export the signed IPA and install it with ESign (or any IPA installer).": "Exporte o IPA assinado e instale-o com o ESign (ou qualquer instalador de IPA).",
        "Exported as .m4a files with their original titles, zipped to this app's Documents/VoiceMemosExports. The recordings database is only ever read — never written.": "Exportado como arquivos .m4a com seus títulos originais, compactados em Documents/VoiceMemosExports deste app. O banco de dados de gravações é apenas lido — nunca escrito.",
        "Exporting…": "Exportando…",
        "Extra": "Extra",
        "Fake-Supervision Residue": "Resíduo de Supervisão Falsa",
        "Fast mode selected: only targets %@ with %@.": "Modo rápido selecionado: apenas alvos %@ com %@.",
