        "Flash Log (%d lines)": "Registro de Gravação (%d linhas)",
        "Flash Selected Cards": "Gravar Cartões Selecionados",
        "Flash Theme to iPhone": "Gravar Tema no iPhone",
        "Flashing Theme…": "Gravando Tema…",
        "Flashing needs a pairing file and the VPN tunnel. Pair first and connect the VPN in Sandbox → Utilities → Get Pairing File + VPN Status, then come back here.": "A gravação precisa de um arquivo de pareamento e do túnel VPN. Pareie primeiro e conecte a VPN em Sandbox → Utilitários → Obter Arquivo de Pareamento + Status da VPN, depois volte aqui.",
        "Flashing needs a pairing file. Pair this iPhone first in Sandbox → Utilities → Get Pairing File.": "A gravação precisa de um arquivo de pareamento. Pareie este iPhone primeiro em Sandbox → Utilitários → Obter Arquivo de Pareamento.",
        "Flashing needs the VPN tunnel. Open the Local Dev VPN app and connect first.": "A gravação precisa do túnel VPN. Abra o app Local Dev VPN e conecte-se primeiro.",
        "Flashing…": "Gravando…",
        "Folder name": "Nome da pasta",
        "Follow for updates, demos and new tweaks.": "Siga para atualizações, demonstrações e novos tweaks.",
        "Font Weight / Style": "Peso / Estilo da Fonte",
        "Footnote": "Nota de Rodapé",
        "Footnote Updated": "Nota de Rodapé Atualizada",
        "Footnote text": "Texto da nota de rodapé",
        "For AppGroup scope, the target is the App Group identifier (for example group.com.example) — type it here.": "Para o escopo AppGroup, o alvo é o identificador do App Group (por exemplo, group.com.example) — digite-o aqui.",
        "Force-close the Wallet app from the App Switcher after flashing to see the new card art.": "Feche à força o app Carteira no Seletor de Apps após a gravação para ver a nova arte do cartão.",
        "Forces the label shown (5G, 5G+, 5G UC, LTE, …). Limited — the label is display-only.": "Força o rótulo exibido (5G, 5G+, 5G UC, LTE, …). Limitado — o rótulo é apenas de exibição.",
        "Free Apple ID installs expire after about 7 days — reinstall with iLoader to renew.": "Instalações com ID Apple gratuito expiram após cerca de 7 dias — reinstale com o iLoader para renovar.",
        "Freed %@": "Liberado %@",
        "Genuine MDM": "MDM Genuíno",
        "Get Pairing + VPN Tunnel": "Obter Pareamento + Túnel VPN",
        "Get Pairing File": "Obter Arquivo de Pareamento",
        "Get Pairing File + Local Dev VPN tunnel — the on-device pairing Airlift uses to reach the device.": "Obter Arquivo de Pareamento + túnel Local Dev VPN — o pareamento no dispositivo que o Airlift usa para alcançar o dispositivo.",
        "Get Pairing File + VPN Status": "Obter Arquivo de Pareamento + Status da VPN",
        "Get Started": "Começar",
        "Go to Sandbox Tab": "Ir para a Aba Sandbox",
        "Go to the Apply/Revert section and tap Apply, then Respring. When the respring finishes, restart your iPhone.": "Vá para a seção Aplicar/Reverter e toque em Aplicar, depois em Respring. Quando o respring terminar, reinicie seu iPhone.",
        "Go to the Sandbox tab and turn on Start Tweaks Feature to unlock the Tweaks tab.": "Vá para a aba Sandbox e ative Iniciar Recurso de Tweaks para desbloquear a aba Tweaks.",
