        "ISO date (e.g. 2026-11-24T15:30:00Z) or yyyy-MM-dd HH:mm:ss.": "Data ISO (ex.: 2026-11-24T15:30:00Z) ou yyyy-MM-dd HH:mm:ss.",
        "Identifiers from the App Data container scan — the same list Deploy resolves Application targets against.": "Identificadores da verificação de contêineres de Dados do App — a mesma lista com a qual o Deploy resolve alvos de Aplicativo.",
        "Idle": "Inativo",
        "If iOS asks, enable Developer Mode (Settings → Privacy & Security → Developer Mode) and trust the developer profile.": "Se o iOS pedir, ative o Modo de Desenvolvedor (Ajustes → Privacidade e Segurança → Modo de Desenvolvedor) e confie no perfil do desenvolvedor.",
        "If you update or downgrade to a supported build, WorkTweaks will open normally.": "Se você atualizar ou rebaixar para um build suportado, o WorkTweaks abrirá normalmente.",
        "Import": "Importar",
        "Import .tendies Package…": "Importar Pacote .tendies…",
