        "Import Pairing File": "Importar Arquivo de Pareamento",
        "Import ZIP Backup…": "Importar Backup ZIP…",
        "Imported": "Importado",
        "In the Tweaks tab, Apple Intelligence section, turn on Apple Intelligence and Siri AI Cache Patch. The cache patch is the Filza line-104 edit (one CacheData byte, 0x00 to 0x02) — done here, no Filza needed.": "Na aba Tweaks, seção Apple Intelligence, ative Apple Intelligence e Siri AI Cache Patch. O patch de cache é a edição da linha 104 do Filza (um byte de CacheData, de 0x00 para 0x02) — feita aqui, sem precisar do Filza.",
        "Individual Keys": "Chaves Individuais",
        "Install tab → Provisioning: fill in the fields below, tap Provision, and wait for \"profile OK\". Your Team ID is shown in the app's Certificates tab.": "Aba Instalar → Provisionamento: preencha os campos abaixo, toque em Provisionar e aguarde \"profile OK\". Seu Team ID é exibido na aba Certificados do app.",
        "Installation": "Instalação",
        "Installed Profiles": "Perfis Instalados",
        "Installed any other way, the signed profile leaves the App Group out — and without it, the tweaks can't run. Tap Tutorials below for both step-by-step guides.": "Instalado de qualquer outra forma, o perfil assinado deixa o App Group de fora — e sem ele, os tweaks não funcionam. Toque em Tutoriais abaixo para ver os dois guias passo a passo.",
        "Installing into PosterBoard…": "Instalando no PosterBoard…",
        "Internal": "Interno",
        "Jetsam & Crash": "Jetsam e Crash",
        "Jetsam & Crash lists the reports iOS writes when it kills an app for memory (Jetsam, bug_type 298), when an app crashes (309), or on a watchdog / kernel panic (210). Open a report to see why it died, share the full file, or clean all reports to free space.": "Jetsam e Crash lista os relatórios que o iOS escreve quando encerra um app por memória (Jetsam, bug_type 298), quando um app trava (309) ou em um watchdog / kernel panic (210). Abra um relatório para ver por que ele morreu, compartilhe o arquivo completo ou limpe todos os relatórios para liberar espaço.",
