        "Lock Screen Footnote": "Nota de Rodapé da Tela de Bloqueio",
        "Lock Screen Footnote is unavailable": "Nota de Rodapé da Tela de Bloqueio indisponível",
        "Lock Screen Preview": "Pré-visualização da Tela de Bloqueio",
        "Locked folders are read-only (0555) with a sentinel file inside; config files are emptied and locked (0444). A Weak Lock is a locked folder missing its sentinel — tap Harden to add it.": "Pastas bloqueadas são somente leitura (0555) com um arquivo sentinela dentro; arquivos de configuração são esvaziados e bloqueados (0444). Um Bloqueio Fraco é uma pasta bloqueada sem seu sentinela — toque em Reforçar para adicioná-lo.",
        "Locks every target below that still needs action. Whitelisted targets are always skipped.": "Bloqueia todos os alvos abaixo que ainda precisam de ação. Alvos na lista de permissões são sempre ignorados.",
        "Log": "Log",
        "Loop (forwards and backwards)": "Loop (para frente e para trás)",
