        "Name": "Nome",
        "Nested dictionaries, arrays and Data are shown read-only — the editor never rewrites a structure it cannot show.": "Dicionários aninhados, arrays e Data são exibidos somente para leitura — o editor nunca reescreve uma estrutura que não consegue mostrar.",
        "Network Type Label": "Rótulo do Tipo de Rede",
