        "Network label (Secondary)": "Rótulo da rede (Secundária)",
        "Network type": "Tipo de rede",
        "Never share your certificate .p12 file with anyone — it contains your private signing key.": "Nunca compartilhe seu arquivo de certificado .p12 com ninguém — ele contém sua chave privada de assinatura.",
        "New Package": "Novo Pacote",
        "New Row": "Nova Linha",
