        "No": "Não",
        "No AI cache targets were found.": "Nenhum alvo de cache de IA foi encontrado.",
        "No Cards Detected Yet": "Nenhum Cartão Detectado Ainda",
        "No Jailbreak": "Sem Jailbreak",
        "No ad targets found yet. Tap Scan above.": "Nenhum alvo de anúncio encontrado ainda. Toque em Verificar acima.",
        "No backed-up photos or videos yet. Use \"Backup Your Photos & Videos Here!\" first.": "Ainda não há fotos ou vídeos com backup. Use \"Faça Backup das Suas Fotos e Vídeos Aqui!\" primeiro.",
        "No containers were found, so there is nothing to clean.": "Nenhum contêiner foi encontrado, então não há nada para limpar.",
        "No deploys yet. When a package is deployed, the files it replaced are backed up here with a receipt, ready to restore.": "Ainda não há deploys. Quando um pacote é implantado, os arquivos que ele substituiu recebem backup aqui com um recibo, prontos para restaurar.",
        "No diagnostic reports found — nothing has been killed or crashed recently, or the reports were already cleaned.": "Nenhum relatório de diagnóstico encontrado — nada foi encerrado ou travou recentemente, ou os relatórios já foram limpos.",
        "No files yet.": "Ainda não há arquivos.",
        "No installable profile records were found in this directory.": "Nenhum registro de perfil instalável foi encontrado neste diretório.",
        "No pairing file saved yet.": "Nenhum arquivo de pareamento salvo ainda.",
        "No pairing file yet. Pair this iPhone first in Sandbox → Utilities → Get Pairing File — scanning and flashing need it.": "Ainda não há arquivo de pareamento. Pareie este iPhone primeiro em Sandbox → Utilitários → Obter Arquivo de Pareamento — a verificação e a gravação precisam dele.",
        "No recordings were found in the Voice Memos database.": "Nenhuma gravação foi encontrada no banco de dados do Gravador de Voz.",
        "No regular files found in this container.": "Nenhum arquivo comum encontrado neste contêiner.",
        "No scan yet. The scan starts automatically; if it does not, open App Data once, or type the bundle ID by hand.": "Ainda não há verificação. A verificação começa automaticamente; se não começar, abra Dados do App uma vez ou digite o bundle ID manualmente.",
        "No skin — tap Set Skin below": "Sem capa — toque em Definir Capa abaixo",
        "No snapshots yet. Apply some tweaks or tap Back Up Now.": "Ainda não há snapshots. Aplique alguns tweaks ou toque em Fazer Backup Agora.",
        "No stored packages yet. Build one with New Package, or import an existing .deploy / .zip / folder package to edit it here.": "Ainda não há pacotes armazenados. Crie um com Novo Pacote ou importe um pacote .deploy / .zip / pasta existente para editá-lo aqui.",
        "No thermal events found in the powerlog.": "Nenhum evento térmico encontrado no powerlog.",
        "No third-party apps found.": "Nenhum app de terceiros encontrado.",
        "No tweaks match \"%@\".": "Nenhum tweak corresponde a \"%@\".",
        "No wallpapers imported yet. Wallpapers imported here are listed so you can remove them again — wallpapers added any other way are never touched.": "Ainda não há papéis de parede importados. Os papéis de parede importados aqui são listados para que você possa removê-los novamente — papéis de parede adicionados de qualquer outra forma nunca são tocados.",
        "Nominal capacity": "Capacidade nominal",
