        "Not present in this backup": "Não presente neste backup",
        "Not set": "Não definido",
        "Nothing applied yet.": "Nada aplicado ainda.",
        "Nothing staged yet.": "Nada preparado ainda.",
        "Nothing was written — the stored manifest is unchanged.": "Nada foi escrito — o manifesto armazenado não mudou.",
        "Nothing was written.": "Nada foi escrito.",
        "Notice": "Aviso",
        "Numbers only.": "Somente números.",
        "OK": "OK",
        "Off": "Desligado",
        "Off in this backup": "Desligado neste backup",
        "Old UI": "IU Antiga",
        "On": "Ligado",
        "On a computer, download iLoader from iloader.app — the official site only — and open it.": "No computador, baixe o iLoader em iloader.app — somente o site oficial — e abra-o.",
        "On in this backup": "Ligado neste backup",
        "One of the destination paths is invalid.": "Um dos caminhos de destino é inválido.",
        "Only files under Library/Caches inside the listed targets are deleted. AI models are never touched, and caches regenerate when the apps run again.": "Somente arquivos em Library/Caches dentro dos alvos listados são excluídos. Os modelos de IA nunca são tocados, e os caches são regenerados quando os apps rodam novamente.",
        "Only spoof your device model if you want to download Apple Intelligence. This may break Face ID. If you decide to unspoof and want to keep Apple Intelligence, do NOT re-enter the Apple Intelligence & Siri menu in Settings.": "Falsifique o modelo do seu dispositivo apenas se quiser baixar o Apple Intelligence. Isso pode quebrar o Face ID. Se decidir desfazer a falsificação e quiser manter o Apple Intelligence, NÃO entre novamente no menu Apple Intelligence e Siri em Ajustes.",
        "Only the listed .ips / .crash / .panic files under DiagnosticReports (and Retired) are ever deleted. The folders themselves are kept, and nothing else is touched.": "Somente os arquivos .ips / .crash / .panic listados em DiagnosticReports (e Retired) são excluídos. As pastas são mantidas e nada mais é tocado.",
        "Open App Data first so the container scan runs, then come back — or tap Rescan.": "Abra Dados do App primeiro para que a verificação de contêineres rode, depois volte — ou toque em Verificar Novamente.",
        "Open Settings → Apple Intelligence & Siri and tap Join Waitlist. Wait about 15 minutes for it to be accepted.": "Abra Ajustes → Apple Intelligence e Siri e toque em Entrar na Lista de Espera. Aguarde cerca de 15 minutos para ser aceito.",
        "Open Signed Apps and sign in with your Apple ID.": "Abra o Signed Apps e entre com seu ID Apple.",
        "Open Source": "Código Aberto",
        "Open Tutorials": "Abrir Tutoriais",
        "Open WorkTweaks and you're done.": "Abra o WorkTweaks e pronto.",
        "Open as Property List": "Abrir como Lista de Propriedades",
        "Open as SQLite Database": "Abrir como Banco de Dados SQLite",
        "Open the Local Dev VPN app and connect. The tunnel shows as a utun interface on 10.7.x.x (gateway 10.7.0.1).": "Abra o app Local Dev VPN e conecte-se. O túnel aparece como uma interface utun em 10.7.x.x (gateway 10.7.0.1).",
        "Opening the configuration profiles…": "Abrindo os perfis de configuração…",
        "Opening the database…": "Abrindo o banco de dados…",
        "Opens an empty editor; the file is created when you save.": "Abre um editor vazio; o arquivo é criado quando você salva.",
        "Opens the database as editable tables, with a backup taken before the first save. Close the owning app before editing.": "Abre o banco de dados como tabelas editáveis, com um backup feito antes do primeiro salvamento. Feche o app dono antes de editar.",
        "Opens the property list as an editable key/type/value table, with a backup taken before the first save.": "Abre a lista de propriedades como uma tabela editável de chave/tipo/valor, com um backup feito antes do primeiro salvamento.",
        "Optional label": "Rótulo opcional",
        "Organization: %@": "Organização: %@",
        "Original": "Original",
        "Original (%d)": "Original (%d)",
