        "Package": "Pacote",
        "Package Builder": "Criador de Pacotes",
        "Package Format": "Formato do Pacote",
        "Packages you build or import are stored on this device, in WorkTweaks' own container. Tap a package to edit it. Deploy runs it through the same preview, resolve and backup flow as a picked package.": "Os pacotes que você cria ou importa são armazenados neste dispositivo, no próprio contêiner do WorkTweaks. Toque em um pacote para editá-lo. O Deploy o executa com o mesmo fluxo de pré-visualização, resolução e backup de um pacote escolhido.",
        "Pair This iPhone": "Parear Este iPhone",
        "Pairing & Airlift": "Pareamento e Airlift",
        "Pairing cancelled.": "Pareamento cancelado.",
        "Pairing file": "Arquivo de pareamento",
        "Pairing file imported.": "Arquivo de pareamento importado.",
        "Pairing file removed.": "Arquivo de pareamento removido.",
        "Pairing file saved to the app.": "Arquivo de pareamento salvo no app.",
        "Parsed from the .plist files in the ConfigurationProfiles directory. This page never installs or removes a profile.": "Analisado a partir dos arquivos .plist no diretório ConfigurationProfiles. Esta página nunca instala nem remove um perfil.",
        "Partial — some icons may still show. Hidden through the archive's suppressed identifiers.": "Parcial — alguns ícones ainda podem aparecer. Ocultos por meio dos identificadores suprimidos do arquivo.",
        "Partially Supported": "Parcialmente Suportado",
        "Partially Supported iOS • %@": "iOS Parcialmente Suportado • %@",
        "Passcode Theme": "Tema de Código",
        "Passcode Themes": "Temas de Código",
        "Passcode theme applied": "Tema de código aplicado",
        "Paste card hash": "Colar hash do cartão",
        "Path Enumeration": "Enumeração de Caminhos",
        "Paths must be relative, non-empty and contain no \"..\" component.": "Os caminhos devem ser relativos, não vazios e não conter o componente \"..\".",
        "Payload files are copied into the package. Add File accepts any file — a .plist is added as a payload, and a .zip is unpacked, each file inside becoming a payload with its destination defaulting to its path inside the archive. Destinations are relative paths only; absolute paths and \"..\" are rejected, exactly like an imported package.": "Os arquivos de conteúdo são copiados para o pacote. Adicionar Arquivo aceita qualquer arquivo — um .plist é adicionado como conteúdo, e um .zip é descompactado, cada arquivo dentro dele se tornando um conteúdo com destino padrão igual ao seu caminho dentro do arquivo. Os destinos são apenas caminhos relativos; caminhos absolutos e \"..\" são rejeitados, exatamente como em um pacote importado.",
        "Persist after reboot": "Persistir após reiniciar",
        "Photo Library": "Biblioteca de Fotos",
        "Photo chosen — tap to change": "Foto escolhida — toque para alterar",
        "Photos & Videos": "Fotos e Vídeos",
        "Pick Target App": "Escolher App de Destino",
        "Pick an app": "Escolha um app",
        "Pick an app to see its cache and clean it.": "Escolha um app para ver seu cache e limpá-lo.",
        "Pick from App Data scan…": "Escolher na verificação de Dados do App…",
        "Pick the WorkTweaks IPA, set the Signing Bundle ID field to the same identifier, then tap Sign IPA.": "Escolha o IPA do WorkTweaks, defina o campo Signing Bundle ID com o mesmo identificador e toque em Assinar IPA.",
        "Pick the photos and videos you want to keep, then Save. They are copied into the BackUP_Data folder inside the app. Optional — you can skip this.": "Escolha as fotos e os vídeos que deseja manter e toque em Salvar. Eles são copiados para a pasta BackUP_Data dentro do app. Opcional — você pode pular.",
        "Plays a soft sound when you tap menus and features. Respects the silent switch.": "Reproduz um som suave quando você toca em menus e recursos. Respeita o botão de silenciar.",
        "Please Install It the Right Way": "Instale-o do Jeito Certo",
        "PosterBoard Data": "Dados do PosterBoard",
        "PosterBoard Updated": "PosterBoard Atualizado",
        "PosterBoard is unavailable": "PosterBoard indisponível",
        "Power": "Energia",
        "Prepare Share": "Preparar Compartilhamento",
        "Preparing the container scan…": "Preparando a verificação de contêineres…",
        "Preview (first 128 KB)": "Pré-visualização (primeiros 128 KB)",
        "Probe Again": "Testar Novamente",
        "Probing cache sizes…": "Testando tamanhos de cache…",
        "Raw max capacity": "Capacidade máxima bruta",
        "Read": "Ler",
