        "Read complete%@%@.": "Leitura concluída%@%@.",
        "Read-only mode — the grant did not include write access, so Clean All is disabled.": "Modo somente leitura — a concessão não incluiu acesso de escrita, então Limpar Tudo está desativado.",
        "Read-only: the powerlog is cloned into this app's temp folder and inspected there. Nothing is ever written to the system database. Some iOS 26 firmware restricts the powerlog sandbox token; iOS 27 reads fully.": "Somente leitura: o powerlog é clonado para a pasta temporária deste app e inspecionado lá. Nada é escrito no banco de dados do sistema. Alguns firmwares do iOS 26 restringem o token de sandbox do powerlog; o iOS 27 lê por completo.",
        "Reading the configuration profiles…": "Lendo os perfis de configuração…",
        "Reading the property list…": "Lendo a lista de propriedades…",
        "Reading the recordings database…": "Lendo o banco de dados de gravações…",
        "Reading video frames…": "Lendo quadros do vídeo…",
        "Reading…": "Lendo…",
        "Rebooting now might cause a bootloop. Try pressing 'Revert Tweaks'.": "Reiniciar agora pode causar um bootloop. Tente tocar em 'Reverter Tweaks'.",
        "Recent Requests": "Solicitações Recentes",
        "Recent samples (%d)": "Amostras recentes (%d)",
        "Reference": "Referência",
        "Reference & Patch Files": "Arquivos de Referência e Patch",
        "Reference — APFS save-vault idea (clonefile staging, atomic swap with rollback).": "Referência — ideia de cofre de saves APFS (preparo com clonefile, troca atômica com reversão).",
        "Reference — PosterBoard wallpaper format the maker was verified against.": "Referência — formato de papel de parede PosterBoard com o qual o criador foi verificado.",
        "Reference — Splash Ad Cache Lock mechanism (ad SDK cache lock, save vault, diagnostics, Wi-Fi file sharing, Voice Memos export, AI cache probes).": "Referência — mecanismo Splash Ad Cache Lock (bloqueio de cache de SDK de anúncios, cofre de saves, diagnóstico, compartilhamento de arquivos por Wi-Fi, exportação de Gravações de Voz, sondas de cache de IA).",
        "Reference — cache data cleaner": "Referência — limpador de dados de cache",
        "Reference — turn on new Siri AI (CacheData line edit + device spoof)": "Referência — ativar a nova Siri com IA (edição de linha CacheData + falsificação de dispositivo)",
        "Reference — video-to-wallpaper (CAML) builder used by the PosterBoard wallpaper maker.": "Referência — construtor de vídeo para papel de parede (CAML) usado pelo criador de papéis de parede PosterBoard.",
        "Refresh": "Atualizar",
