        "Respring": "Respring",
        "Respring did not trigger on this device.": "O respring não foi acionado neste dispositivo.",
        "Restart Device": "Reiniciar Dispositivo",
        "Restart Required": "Reinicialização Necessária",
        "Restore": "Restaurar",
        "Restore (%d)": "Restaurar (%d)",
        "Restore Backup": "Restaurar Backup",
        "Restore Everything": "Restaurar Tudo",
        "Restore Result — %d succeeded, %d failed": "Resultado da Restauração — %d com sucesso, %d com falha",
        "Restore a ZIP backup": "Restaurar um backup ZIP",
        "Restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "As alterações de restauração só entram em vigor após uma reinicialização completa do dispositivo — um respring não basta. Escolher Depois apenas adia; as alterações ficam pendentes até você reiniciar.",
        "Restore into…": "Restaurar em…",
        "Restore swaps the staged copy into the app's current container and rolls back if anything fails. Release a snapshot only after you verified the restore in the app.": "A restauração troca a cópia preparada para o contêiner atual do app e reverte se algo falhar. Libere um snapshot somente depois de verificar a restauração no app.",
        "Restore the backup?": "Restaurar o backup?",
        "Restore this entire backup?": "Restaurar todo este backup?",
        "Restoring ZIP…": "Restaurando ZIP…",
        "Restoring the backup failed — the details are in the Log.": "Falha ao restaurar o backup — os detalhes estão no Log.",
        "Restoring writes each backed-up file back in place. Files the deploy created (they did not exist before) are deleted again.": "A restauração escreve cada arquivo com backup de volta no local. Arquivos que o deploy criou (que não existiam antes) são excluídos novamente.",
        "Restoring…": "Restaurando…",
        "Result — %d succeeded, %d failed": "Resultado — %d com sucesso, %d com falha",
        "Retry Flash": "Tentar Gravar Novamente",
        "Retry Flash Theme": "Tentar Gravar Tema Novamente",
        "Revert": "Reverter",
        "Revert Tweaks": "Reverter Tweaks",
        "Revert all tweaks?": "Reverter todos os tweaks?",
        "Revert and restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "As alterações de reversão e restauração só entram em vigor após uma reinicialização completa do dispositivo — um respring não basta. Escolher Depois apenas adia; as alterações ficam pendentes até você reiniciar.",
        "Rewrites the entire MobileGestalt.plist from this backup. A device restart is required after restoring.": "Reescreve todo o MobileGestalt.plist a partir deste backup. É necessário reiniciar o dispositivo após restaurar.",
        "Running": "Em execução",
        "Sampled": "Amostrado",
        "Sandbox access denied": "Acesso ao sandbox negado",
        "Sandbox extension is ready (directory grant held).": "Extensão de sandbox pronta (concessão de diretório mantida).",
        "Save": "Salvar",
        "Save .passthm": "Salvar .passthm",
        "Save App Group ID": "Salvar ID do App Group",
        "Save Vault": "Cofre de Saves",
        "Saved": "Salvo",
        "Saved %d of %d to BackUP_Data.": "Salvo(s) %d de %d em BackUP_Data.",
        "Saved: %@": "Salvo: %@",
        "Saves the package, then shares ONE .zip file — save it in Files. Deploy imports that zip and applies it without asking for locations.": "Salva o pacote e compartilha UM arquivo .zip — salve-o no Arquivos. O Deploy importa esse zip e o aplica sem pedir locais.",
        "Saving %d of %d (%d%%)": "Salvando %d de %d (%d%%)",
        "Saving applies the edits to the database through SQLite, takes a backup of the original first, then writes the edited file back in place. Close the owning app before saving — a running app can overwrite your edits.": "Ao salvar, as edições são aplicadas ao banco de dados via SQLite, um backup do original é feito primeiro e o arquivo editado é escrito de volta no local. Feche o app dono antes de salvar — um app em execução pode sobrescrever suas edições.",
        "Saving rebuilds the property list from this table, takes a backup of the original first, then writes it back in place. Close the owning app before saving — a running app can overwrite your edits.": "Ao salvar, a lista de propriedades é reconstruída a partir desta tabela, um backup do original é feito primeiro e ela é escrita de volta no local. Feche o app dono antes de salvar — um app em execução pode sobrescrever suas edições.",
        "Saving writes the file in place and verifies the result by re-reading it.": "Ao salvar, o arquivo é escrito no local e o resultado é verificado ao lê-lo novamente.",
        "Saving writes the file in place, under the container's sandbox extension.": "Ao salvar, o arquivo é escrito no local, sob a extensão de sandbox do contêiner.",
        "Saving…": "Salvando…",
        "Scan": "Verificar",
        "Scan Cards": "Verificar Cartões",
        "Scan for Ad Targets": "Verificar Alvos de Anúncios",
        "Scanning %@…": "Verificando %@…",
        "Scanning…": "Verificando…",
        "Scope": "Escopo",
        "Search": "Buscar",
        "Search tweaks": "Buscar tweaks",
        "Secondary bars: %d": "Barras secundárias: %d",
        "Secondary carrier name (max 64)": "Nome da operadora secundária (máx. 64)",
        "Secondary network type": "Tipo de rede secundária",
        "Sections": "Seções",
        "Select All": "Selecionar Tudo",
        "Select None": "Não Selecionar Nenhum",
        "Select at least one card and attach a skin image to it before flashing.": "Selecione pelo menos um cartão e anexe uma imagem de capa a ele antes de gravar.",
        "Selected app": "App selecionado",
        "Server": "Servidor",
        "Set NULL": "Definir NULL",
        "Set Skin": "Definir Capa",
        "Set Skin for All Cards…": "Definir Capa para Todos os Cartões…",
        "Set the Spoofing picker (under Apple Intelligence) to iPhone 17 Pro (iPhone18,1).": "Defina o seletor de Falsificação (em Apple Intelligence) para iPhone 17 Pro (iPhone18,1).",
        "Sets how many bars are drawn. Static — it does not follow the real signal.": "Define quantas barras são desenhadas. Estático — não acompanha o sinal real.",
        "Share %@": "Compartilhar %@",
        "Share Contents": "Compartilhar Conteúdo",
        "Share Full Report": "Compartilhar Relatório Completo",
        "Showing the first %@ of %@ rows — the editor is for targeted edits, not bulk dumps.": "Exibindo as primeiras %@ de %@ linhas — o editor é para edições pontuais, não para despejos em massa.",
        "Shows the battery percentage in the status bar. Key: SBShowBatteryPercentage in com.apple.springboard.plist.": "Mostra a porcentagem da bateria na barra de status. Chave: SBShowBatteryPercentage em com.apple.springboard.plist.",
        "Sign In": "Entrar",
        "Signal Bars": "Barras de Sinal",
        "Signal bars (Primary)": "Barras de sinal (Principal)",
        "Signal bars (Secondary)": "Barras de sinal (Secundária)",
        "Single-file shorthand: instead of \"files\", give \"relativePath\" and \"file\". \"scope\" is Application (bundleID = the app's bundle ID), AppGroup (bundleID = the group identifier, e.g. group.com.example) or InternalDaemon. ZIP archives may use stored or deflated entries; encrypted and ZIP64 archives are not supported. Older .deploy archives and plain folders still import.": "Atalho de arquivo único: em vez de \"files\", forneça \"relativePath\" e \"file\". \"scope\" é Application (bundleID = o bundle ID do app), AppGroup (bundleID = o identificador do grupo, ex.: group.com.example) ou InternalDaemon. Arquivos ZIP podem usar entradas armazenadas ou compactadas; arquivos criptografados e ZIP64 não são suportados. Arquivos .deploy antigos e pastas comuns ainda podem ser importados.",
        "Size": "Tamanho",
        "Sizes are measured by walking each folder. An app recreates cache as it runs, so the size grows back over time.": "Os tamanhos são medidos percorrendo cada pasta. Um app recria o cache enquanto roda, então o tamanho volta a crescer com o tempo.",
        "Sizes are probed read-only (depth 4). Delete Cache removes only files under Library/Caches inside these targets — the AI models live elsewhere and are never touched.": "Os tamanhos são testados somente para leitura (profundidade 4). Excluir Cache remove apenas arquivos em Library/Caches dentro desses alvos — os modelos de IA ficam em outro lugar e nunca são tocados.",
        "Snapshots": "Snapshots",
        "Software-Oriented Features": "Recursos Orientados a Software",
        "Some tweaks — especially Apple Intelligence — only take effect after a full restart, not a respring.": "Alguns tweaks — especialmente o Apple Intelligence — só entram em vigor após uma reinicialização completa, não um respring.",
        "Something went wrong": "Algo deu errado",
        "Sound Effects": "Efeitos Sonoros",
        "Splash Ad Cache Lock": "Splash Ad Cache Lock",
        "Splash Ad Cache Lock finds the folders ad SDKs use to cache splash (launch) ads, empties them, and locks them read-only so the app cannot rebuild its splash-ad cache. Locks apply only to third-party app folders — never to system folders, Documents, or the app itself.": "O Splash Ad Cache Lock encontra as pastas que os SDKs de anúncios usam para armazenar em cache anúncios de splash (abertura), esvazia-as e as bloqueia como somente leitura para que o app não consiga reconstruir seu cache de anúncios de splash. Os bloqueios se aplicam apenas a pastas de apps de terceiros — nunca a pastas do sistema, Documentos ou ao próprio app.",
        "Spoofing": "Falsificação",
        "SpringBoard loads the wallpaper store when it starts — respring or restart to see the change in the wallpaper gallery.": "O SpringBoard carrega a loja de papéis de parede quando inicia — faça respring ou reinicie para ver a alteração na galeria de papéis de parede.",
        "SpringBoard reads the footnote when it starts — respring or restart to see it on the Lock Screen.": "O SpringBoard lê a nota de rodapé quando inicia — faça respring ou reinicie para vê-la na Tela de Bloqueio.",
        "Stage an app's Documents, Library/Preferences and Library/Application Support (never Caches) before its 7-day certificate expires. After reinstall, the data is restored into the app's new container — matched by bundle id, not the old container UUID.": "Prepare os Documentos, Library/Preferences e Library/Application Support de um app (nunca Caches) antes que seu certificado de 7 dias expire. Após a reinstalação, os dados são restaurados no novo contêiner do app — combinados pelo bundle id, não pelo UUID do contêiner antigo.",
        "Stage copies into the APFS vault (no extra space). ZIP backup copies first, then zips — for very large apps use the APFS vault. Both refuse while the app is still writing its database.": "O preparo copia para o cofre APFS (sem espaço extra). O backup ZIP copia primeiro e depois compacta — para apps muito grandes, use o cofre APFS. Ambos recusam enquanto o app ainda estiver escrevendo seu banco de dados.",
        "Stage into APFS Vault": "Preparar no Cofre APFS",
        "Staged %@: %d file(s), %@. Verified against the source.": "Preparado %@: %d arquivo(s), %@. Verificado com a fonte.",
        "Staged snapshots": "Snapshots preparados",
        "Staging…": "Preparando…",
        "Start Server": "Iniciar Servidor",
        "Start Tweaks Feature": "Iniciar Recurso de Tweaks",
        "Start the server to get its address.": "Inicie o servidor para obter seu endereço.",
        "Still writing (%d active WAL file(s)) — close the app first": "Ainda escrevendo (%d arquivo(s) WAL ativo(s)) — feche o app primeiro",
        "Stop Scan": "Parar Verificação",
        "Stop Server": "Parar Servidor",
        "Stopped": "Parado",
        "Stored as text.": "Armazenado como texto.",
        "Subtype": "Subtipo",
        "Supervision": "Supervisão",
        "Support": "Suporte",
        "Supported": "Suportado",
        "Supported iOS Versions": "Versões do iOS Suportadas",
        "Supported iOS • %@": "iOS Suportado • %@",
        "Swift implementation of the respring web view (via mond / jailbreak.party).": "Implementação em Swift da visualização web de respring (via mond / jailbreak.party).",
        "System": "Sistema",
        "System Caches": "Caches do Sistema",
        "System Language": "Idioma do Sistema",
        "Table": "Tabela",
        "Tap Read Powerlog to load the latest battery samples.": "Toque em Ler Powerlog para carregar as amostras mais recentes da bateria.",
        "Tap Refresh to list the diagnostic reports.": "Toque em Atualizar para listar os relatórios de diagnóstico.",
        "Tap a key to assign a custom image.": "Toque em uma chave para atribuir uma imagem personalizada.",
        "Target": "Alvo",
        "Target Path": "Caminho de Destino",
        "Target container": "Contêiner de destino",
        "That file is not a pairing file.": "Esse arquivo não é um arquivo de pareamento.",
        "The App Data scan is still running — ad targets appear once it finishes.": "A verificação de Dados do App ainda está em execução — os alvos de anúncios aparecem quando ela terminar.",
        "The CacheExtra key knowledge — the tweak-key research the WorkTweaks tweak catalog is built on.": "O conhecimento de chaves CacheExtra — a pesquisa de chaves de tweak na qual o catálogo de tweaks do WorkTweaks se baseia.",
        "The Voice Memos container is found through the App Data scan.": "O contêiner do Gravador de Voz é encontrado pela verificação de Dados do App.",
        "The ZIP must be a Save Vault backup (it carries a BackupManifest.plist). Files merge in place; system bundle ids are blocked.": "O ZIP deve ser um backup do Cofre de Saves (ele contém um BackupManifest.plist). Os arquivos são mesclados no local; bundle ids do sistema são bloqueados.",
        "The backup of the original file couldn't be written, so nothing was saved.": "O backup do arquivo original não pôde ser escrito, então nada foi salvo.",
        "The browser asks for these credentials once, then remembers them for the session.": "O navegador pede essas credenciais uma vez e depois as lembra durante a sessão.",
        "The bundle ID is not a valid identifier.": "O bundle ID não é um identificador válido.",
        "The bundle ID of the one app this package may touch. Pick it from the App Data container scan, or type it.": "O bundle ID do único app que este pacote pode tocar. Escolha-o na verificação de contêineres de Dados do App ou digite-o.",
        "The container scan found no containers.": "A verificação de contêineres não encontrou nenhum contêiner.",
        "The container scan is shared with App Data and runs once per app session.": "A verificação de contêineres é compartilhada com Dados do App e roda uma vez por sessão do app.",
        "The container scan runs once per session.": "A verificação de contêineres roda uma vez por sessão.",
        "The core system: the sandbox escape and MobileGestalt access this whole app is built on.": "O sistema principal: o escape de sandbox e o acesso ao MobileGestalt nos quais todo este app se baseia.",
        "The current MobileGestalt will be entirely replaced with this %@ backup.": "O MobileGestalt atual será totalmente substituído por este backup %@.",
        "The current file is overwritten in place with the backup taken before the first byte edit.": "O arquivo atual é sobrescrito no local com o backup feito antes da primeira edição de byte.",
        "The developer's GitHub profile.": "O perfil do desenvolvedor no GitHub.",
        "The directory is empty.": "O diretório está vazio.",
        "The entry is removed from the property list on the next Save.": "A entrada é removida da lista de propriedades no próximo Salvar.",
        "The file couldn't be read under the container's sandbox extension — the details are in the Log. Nothing was written to it.": "O arquivo não pôde ser lido sob a extensão de sandbox do contêiner — os detalhes estão no Log. Nada foi escrito nele.",
        "The file-based CacheData pattern method used by Enable iPadOS Mode (MobileGestaltCacheDataTweak).": "O método de padrão CacheData baseado em arquivo usado por Ativar Modo iPadOS (MobileGestaltCacheDataTweak).",
        "The original identifiers are already registered to another developer account, which is why the Team ID suffix is required.": "Os identificadores originais já estão registrados em outra conta de desenvolvedor, por isso o sufixo Team ID é necessário.",
        "The package could not be exported.": "O pacote não pôde ser exportado.",
        "The package store is unavailable (the App Group container did not resolve).": "O armazenamento de pacotes está indisponível (o contêiner do App Group não foi resolvido).",
        "The pairing file + Local Dev VPN tunnel are the transport Airlift uses to reach the device. Green = ready, gray = not ready.": "O arquivo de pareamento + túnel Local Dev VPN são o transporte que o Airlift usa para alcançar o dispositivo. Verde = pronto, cinza = não pronto.",
        "The pathleak scan reads inodes one by one — this can take a few minutes.": "A verificação pathleak lê inodes um por um — isso pode levar alguns minutos.",
        "The picked file could not be copied into the package.": "O arquivo escolhido não pôde ser copiado para o pacote.",
        "The row is deleted from the database on the next Save.": "A linha é excluída do banco de dados no próximo Salvar.",
        "The sandbox extension for this container's directory was refused — the result code is in the Log.": "A extensão de sandbox para o diretório deste contêiner foi recusada — o código de resultado está no Log.",
        "The scan of %@ found no containers. The scan's baseline and counts are in the Log.": "A verificação de %@ não encontrou contêineres. A linha de base e as contagens da verificação estão no Log.",
        "The server shares this app's Documents folder only — SaveVaultBackups, staged vaults and uploads. Nothing outside it is ever served. Keep this page open while transferring: the server stops when you leave the page or the app goes to the background.": "O servidor compartilha apenas a pasta Documentos deste app — SaveVaultBackups, cofres preparados e uploads. Nada fora dela é servido. Mantenha esta página aberta durante a transferência: o servidor para quando você sai da página ou o app vai para o segundo plano.",
        "The staging vault lives in this app's Documents and does NOT survive uninstalling WorkTweaks. Verify a restore in the app first, then release the vault.": "O cofre de preparo fica nos Documentos deste app e NÃO sobrevive à desinstalação do WorkTweaks. Verifique uma restauração no app primeiro e depois libere o cofre.",
        "The stored package is removed. Files it already deployed, and its Deploy History receipts, are not touched.": "O pacote armazenado é removido. Os arquivos que ele já implantou e seus recibos do Histórico do Deploy não são tocados.",
        "Theme Information": "Informações do Tema",
        "Thermal history (%d)": "Histórico térmico (%d)",
        "These are the photos and videos in the BackUP_Data folder. Select the ones to restore, then Restore opens the share sheet — tap Save to Photos there.": "Estas são as fotos e os vídeos na pasta BackUP_Data. Selecione os que deseja restaurar e toque em Restaurar para abrir a folha de compartilhamento — toque em Salvar em Fotos lá.",
        "This app is free software under the GNU AGPL v3 license, following the licenses of the projects above.": "Este app é software livre sob a licença GNU AGPL v3, seguindo as licenças dos projetos acima.",
        "This app's own repository — issues and contributions welcome.": "O próprio repositório deste app — problemas e contribuições são bem-vindos.",
        "This deletes only the listed .ips / .crash / .panic files. The folders are kept.": "Isto exclui apenas os arquivos .ips / .crash / .panic listados. As pastas são mantidas.",
        "This device right now": "Este dispositivo agora",
        "This file isn't UTF-8 text, so it can't be edited as text. It can be edited byte-by-byte in the hex editor below.": "Este arquivo não é texto UTF-8, então não pode ser editado como texto. Ele pode ser editado byte por byte no editor hex abaixo.",
        "This file isn't UTF-8 text, so it can't be edited here. Nothing is ever written to it from this page.": "Este arquivo não é texto UTF-8, então não pode ser editado aqui. Nada é escrito nele a partir desta página.",
        "This iOS Version Isn't Supported": "Esta Versão do iOS Não É Suportada",
        "This is NOT an adblock: locking only stops ad assets landing on disk. Ads downloaded live over the network when the app opens can still appear.": "Isto NÃO é um bloqueador de anúncios: o bloqueio apenas impede que recursos de anúncios cheguem ao disco. Anúncios baixados ao vivo pela rede quando o app abre ainda podem aparecer.",
        "This is the container's system-managed metadata file. iOS doesn't allow other processes to read its contents, so it can't be opened or edited here.": "Este é o arquivo de metadados gerenciado pelo sistema do contêiner. O iOS não permite que outros processos leiam seu conteúdo, então ele não pode ser aberto nem editado aqui.",
        "This only clears the list. It does not undo anything that was applied.": "Isto apenas limpa a lista. Não desfaz nada que foi aplicado.",
        "This only makes the Join Waitlist button appear. The Siri AI model may still refuse to download — that part is not solved by this method yet.": "Isto apenas faz o botão Entrar na Lista de Espera aparecer. O modelo de IA da Siri ainda pode se recusar a baixar — essa parte ainda não foi resolvida por este método.",
        "This package was rejected": "Este pacote foi rejeitado",
        "This permanently deletes the contents of %@ in %@ (%@). The folders themselves stay in place.": "Isto exclui permanentemente o conteúdo de %@ em %@ (%@). As pastas permanecem no lugar.",
        "This property list has no top-level entries.": "Esta lista de propriedades não tem entradas de nível superior.",
        "This removes the wallpaper imported from %@ — its descriptor folder is deleted from PosterBoard's data store.": "Isto remove o papel de parede importado de %@ — sua pasta de descritores é excluída do armazenamento de dados do PosterBoard.",
        "This restores the MobileGestalt backup saved on first launch (SavedGestalt.plist).": "Isto restaura o backup do MobileGestalt salvo na primeira abertura (SavedGestalt.plist).",
        "This table has no columns to edit.": "Esta tabela não tem colunas para editar.",
