        "Two ways to get a pairing file: Pair This iPhone (iOS 27 only) shows a 6-digit PIN — approve it in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. Or import a pairing file (.plist) from your computer manually. The pairing file is saved in the app.": "Duas formas de obter um arquivo de pareamento: Parear Este iPhone (somente iOS 27) mostra um PIN de 6 dígitos — aprove-o em Ajustes › Privacidade e Segurança › Modo de Desenvolvedor › Parear com o WorkTweaks. Ou importe manualmente um arquivo de pareamento (.plist) do seu computador. O arquivo de pareamento é salvo no app.",
        "Type": "Tipo",
        "Type the region suffix as shown in Settings > General > About, e.g. PA/A or LL/A. It changes the Model Number suffix after Apply.": "Digite o sufixo de região conforme mostrado em Ajustes > Geral > Sobre, ex.: PA/A ou LL/A. Ele altera o sufixo do Número do Modelo após Aplicar.",
