        "Voltage": "Voltagem",
        "WARNING: These tweaks can break features on your device or softbrick it if misused. After Apply you choose Respring or Restart; Revert and Backup restores require a full device restart.": "AVISO: Estes tweaks podem quebrar recursos do seu dispositivo ou deixá-lo em softbrick se usados incorretamente. Após Aplicar, você escolhe Respring ou Reiniciar; as restaurações de Reverter e Backup exigem uma reinicialização completa do dispositivo.",
