        "Wallet Cards": "Cartões da Carteira",
        "Wallpaper": "Papel de Parede",
        "Wallpaper name": "Nome do papel de parede",
        "Warning": "Aviso",
        "Warning: raw byte edits have no structure validation — a wrong byte can corrupt this file or the owning app's data. A backup of the original is saved before the first edit.": "Aviso: edições brutas de bytes não têm validação de estrutura — um byte errado pode corromper este arquivo ou os dados do app dono. Um backup do original é salvo antes da primeira edição.",
        "WeChat accounts": "Contas do WeChat",
        "Welcome to WorkTweaks": "Bem-vindo ao WorkTweaks",
        "What this does": "O que isto faz",
        "When enabled, MobileGestalt is written in-place on the same inode, which (hopefully) prevents iOS from regenerating the cache on reboot. Disable to use atomic file replacement instead.": "Quando ativado, o MobileGestalt é escrito no local, no mesmo inode, o que (espera-se) impede o iOS de regenerar o cache ao reiniciar. Desative para usar a substituição atômica de arquivo.",
        "Where it goes": "Para onde vai",
        "Whitelist": "Lista de Permissões",
        "Whitelisted": "Na lista de permissões",
        "Whole numbers only.": "Somente números inteiros.",
        "Wi-Fi File Sharing": "Compartilhamento de Arquivos por Wi-Fi",
        "WorkTweaks is free software under the GNU Affero General Public License v3.0. The core (worse_query) is GPL-3.0, but the CacheExtra key knowledge from mond and the CacheData method from Nugget are AGPL-3.0 — GPLv3 code may be combined into an AGPLv3 work, and the AGPL terms then cover the combined work as a whole.": "O WorkTweaks é software livre sob a GNU Affero General Public License v3.0. O núcleo (worse_query) é GPL-3.0, mas o conhecimento de chaves CacheExtra do mond e o método CacheData do Nugget são AGPL-3.0 — código GPLv3 pode ser combinado em uma obra AGPLv3, e os termos da AGPL passam a cobrir a obra combinada como um todo.",
        "WorkTweaks must be installed with iLoader, or by signing the IPA with Signed Apps, so that its App Group works correctly.": "O WorkTweaks deve ser instalado com o iLoader ou assinando o IPA com o Signed Apps, para que seu App Group funcione corretamente.",
        "WorkTweaks only works when its App Group is part of the signing profile. Guides A and B make sure that happens — pick the one that fits you. Guide C turns on the new Siri AI.": "O WorkTweaks só funciona quando seu App Group faz parte do perfil de assinatura. Os Guias A e B garantem isso — escolha o que serve para você. O Guia C ativa a nova Siri com IA.",
        "WorkTweaks v3.0 only opens on the builds listed above: the app checks your device's build at launch, and any other build gets the \"not supported\" screen instead of the app. On iOS 18 and iOS 26, only App Data and Airlift are supported (partial support). Developed and tested on iOS 27.0.1 (24A446).": "O WorkTweaks v3.0 só abre nos builds listados acima: o app verifica o build do seu dispositivo na abertura, e qualquer outro build recebe a tela \"não suportado\" em vez do app. No iOS 18 e no iOS 26, apenas Dados do App e Airlift são suportados (suporte parcial). Desenvolvido e testado no iOS 27.0.1 (24A446).",
        "Works on iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 and later patched the exploit).": "Funciona no iOS 18.0 – 27.2 beta 2 (o iOS 27.2 beta 3 e posteriores corrigiram o exploit).",
        "Write Method": "Método de Escrita",
        "Write access available — Clean All can delete the listed reports.": "Acesso de escrita disponível — Limpar Tudo pode excluir os relatórios listados.",
        "Writes SharedDeviceConfiguration.plist in place, keeping every other key in the file. SpringBoard reads the file when it starts, so a respring or restart is needed to see the change.": "Escreve SharedDeviceConfiguration.plist no local, mantendo todas as outras chaves do arquivo. O SpringBoard lê o arquivo quando inicia, então é necessário um respring ou reinício para ver a alteração.",
        "Writing or verifying the file failed — the details are in the Log.": "Falha ao escrever ou verificar o arquivo — os detalhes estão no Log.",
        "Writing the file failed — the details are in the Log.": "Falha ao escrever o arquivo — os detalhes estão no Log.",
        "Writing the footnote failed — the details are in the Log.": "Falha ao escrever a nota de rodapé — os detalhes estão no Log.",
        "Yes": "Sim",
        "You can add multiple hashes at once — separate them with spaces, commas, or newlines.": "Você pode adicionar vários hashes de uma vez — separe-os com espaços, vírgulas ou quebras de linha.",
        "Your All BackUP Files Here!": "Todos os Seus Arquivos de Backup Aqui!",
        "Your device is running **%@**. WorkTweaks v2.0 only runs on the builds listed below, so the app can't open on this version.": "Seu dispositivo está rodando **%@**. O WorkTweaks v2.0 só roda nos builds listados abaixo, então o app não pode abrir nesta versão.",
