        "The Siri byte is flipped (0x02) — the patch is on.": "O byte da Siri foi invertido (0x02) — o patch está ativado.",
        "The Siri byte is 0x00 — the patch is off.": "O byte da Siri é 0x00 — o patch está desativado.",
        "The patch pattern matches more than once, so the automatic patch refuses to guess — edit the Siri line by hand.": "O padrão do patch corresponde mais de uma vez, então o patch automático se recusa a adivinhar — edite a linha da Siri manualmente.",
        "The patch was found, but not on line 104 — open the viewer to see its line.": "O patch foi encontrado, mas não na linha 104 — abra o visualizador para ver sua linha.",
