        "This is the same text Filza shows for this file. CacheData is the long base64 block; its lines are 51 bytes each. The Siri line is highlighted.": "Este é o mesmo texto que o Filza mostra para este arquivo. CacheData é o longo bloco base64; suas linhas têm 51 bytes cada. A linha da Siri está destacada.",
        "Siri line: line %d": "Linha da Siri: linha %d",
        "On this device the Siri line is line %d, not 104 — the guide's line number varies by device.": "Neste dispositivo, a linha da Siri é a linha %d, não 104 — o número da linha do guia varia por dispositivo.",
