        "Unapplied changes in the Tweaks tab will be lost when you save here — Apply them first.": "Alterações não aplicadas na aba Tweaks serão perdidas quando você salvar aqui — aplique-as primeiro.",
        "Saved — the Siri patch is now %@.": "Salvo — o patch da Siri agora está %@.",
        "Saved — the file was written, but the Siri line does not match the patch shape.": "Salvo — o arquivo foi escrito, mas a linha da Siri não corresponde ao formato do patch.",
        "A pristine backup is made before the first save, and only CacheData changes are written.": "Um backup original é feito antes do primeiro salvamento, e somente alterações de CacheData são escritas.",
        "Save the edited file?": "Salvar o arquivo editado?",
