        "%d active tweaks · %d CacheExtra keys": "%d tweaks activos · %d claves CacheExtra",
        "%d bytes — length-preserving edits only: byte values can change, the file's length never does.": "%d bytes — solo ediciones que conservan la longitud: los valores de los bytes pueden cambiar, la longitud del archivo nunca cambia.",
        "%d cards": "%d tarjetas",
        "%d character(s). The text appears in small type at the bottom of the Lock Screen. Leave it empty and tap Apply Footnote to remove the footnote.": "%d carácter(es). El texto aparece en letra pequeña en la parte inferior de la pantalla de bloqueo. Déjalo vacío y toca Aplicar nota al pie para eliminar la nota.",
        "%d cycles": "%d ciclos",
        "%d file(s) examined — the scan walks the whole container, so large apps take a while.": "%d archivo(s) examinados — el análisis recorre todo el contenedor, así que las apps grandes tardan un rato.",
