        ", thermal table %@": ", tabla térmica %@",
        "1 card": "1 tarjeta",
        "1. Open the Translate app, delete the downloaded English (US) language, then download it again.\n2. Go to Settings > General > Language & Region, change the region from United States to another country, then change it back to United States.\n3. Turn off Low Power Mode (Settings > Battery).\n4. Connect to Wi-Fi (and keep your iPhone charging) while Apple Intelligence finishes downloading.": "1. Abre la app Traducir, elimina el idioma inglés (EE. UU.) descargado y descárgalo de nuevo.\n2. Ve a Ajustes > General > Idioma y región, cambia la región de Estados Unidos a otro país y luego vuelve a Estados Unidos.\n3. Desactiva el modo de bajo consumo (Ajustes > Batería).\n4. Conéctate a Wi-Fi (y mantén el iPhone cargando) mientras Apple Intelligence termina de descargarse.",
        "1. Tap Scan Cards above.": "1. Toca Escanear tarjetas arriba.",
        "1. Use the iPhone 16 Pro subtype.\n2. Settings > Appearance > Display Zoom > Large Text, then go Back and set Text Size to Small (optional).": "1. Usa el subtipo iPhone 16 Pro.\n2. Ajustes > Apariencia > Zoom de pantalla > Texto grande y luego vuelve atrás y ajusta el tamaño del texto a Pequeño (opcional).",
        "2. On this iPhone, double-click the Side button (Apple Pay), authenticate with Face ID, and tap your card.": "2. En este iPhone, pulsa dos veces el botón lateral (Apple Pay), autentícate con Face ID y toca tu tarjeta.",
        "3. Your card will appear here automatically!": "3. ¡Tu tarjeta aparecerá aquí automáticamente!",
        "A .tendies package is a ZIP archive containing one or more wallpaper descriptors: loose descriptor folders, a descriptors folder, or a container layout mirroring PosterBoard's data store (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Stored and deflated ZIP entries are supported — the same reader Deploy uses; encrypted and ZIP64 archives are rejected.": "Un paquete .tendies es un archivo ZIP que contiene uno o más descriptores de fondo de pantalla: carpetas de descriptores sueltas, una carpeta de descriptores o una estructura de contenedor que refleja el almacén de datos de PosterBoard (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Se admiten entradas ZIP almacenadas y comprimidas — el mismo lector que usa Deploy; los archivos cifrados y ZIP64 se rechazan.",
        "A Deploy package replaces files inside exactly one app — the app named by its bundle ID. It cannot touch any other app: every target path is relative to that app's container, and packages with absolute or \"..\" paths are rejected whole.": "Un paquete Deploy reemplaza archivos dentro de exactamente una app — la app nombrada por su bundle ID. No puede tocar ninguna otra app: cada ruta de destino es relativa al contenedor de esa app, y los paquetes con rutas absolutas o \"..\" se rechazan por completo.",
        "A MobileGestalt tweak app for iOS 26/27, built on the open-source projects credited below. Use at your own risk — tweaks modify system files.": "Una app de tweaks MobileGestalt para iOS 26/27, basada en los proyectos de código abierto acreditados abajo. Úsala bajo tu propio riesgo — los tweaks modifican archivos del sistema.",
        "A MobileGestalt tweak tool for iOS 26 & 27 — unlock your device's hidden features without a jailbreak, powered by the worse_query sandbox escape.": "Una herramienta de tweaks MobileGestalt para iOS 26 y 27 — desbloquea las funciones ocultas de tu dispositivo sin jailbreak, con el escape de sandbox worse_query.",
        "A bundle ID is required — it names the one app this package may touch.": "Se requiere un bundle ID — nombra la única app que este paquete puede tocar.",
        "A package is ONE .zip file containing a manifest.json at its top level plus the payload files it names. The Package Builder exports that zip (save it in Files); Deploy imports it, resolves the target itself from the manifest, and applies it — no location picking, the destinations come from the zip.": "Un paquete es UN archivo .zip que contiene un manifest.json en su nivel superior más los archivos de carga que nombra. Package Builder exporta ese zip (guárdalo en Archivos); Deploy lo importa, resuelve el destino por sí mismo desde el manifiesto y lo aplica — no hay que elegir ubicaciones, los destinos vienen del zip.",
        "A partial restore can affect photos and videos. Back them up first — optional, you can skip it.": "Una restauración parcial puede afectar a las fotos y los videos. Haz una copia de seguridad primero — es opcional, puedes omitirlo.",
        "A respring is required before a new wallpaper appears in the gallery.": "Se requiere un respring antes de que aparezca un fondo de pantalla nuevo en la galería.",
        "A signed IPA only works on the device registered in its profile.": "Un IPA firmado solo funciona en el dispositivo registrado en su perfil.",
        "A snapshot is also created automatically at every Apply, containing the state that Apply just produced. The Original backup is created once, the first time MobileGestalt is read successfully.": "También se crea una instantánea automáticamente en cada Aplicar, con el estado que Aplicar acaba de producir. La copia de seguridad Original se crea una sola vez, la primera vez que MobileGestalt se lee correctamente.",
        "A whitelisted bundle id (and its App Groups) or exact path is never locked by Lock All. Newly whitelisted targets are restored writable right away. SMZDM is whitelisted by default — its splash cache is known to crash the app when locked.": "Un bundle id en la lista blanca (y sus App Groups) o una ruta exacta nunca se bloquea con Bloquear todo. Los destinos recién añadidos a la lista blanca se restauran como escribibles de inmediato. SMZDM está en la lista blanca por defecto — se sabe que su caché de splash hace fallar la app cuando se bloquea.",
        "AI Cache": "Caché de IA",
        "APFS vault: clonefile staging, zero extra space, atomic restore with rollback. ZIP backup: the same three folders as one .zip file, restored by merging in place.": "Bóveda APFS: preparación con clonefile, cero espacio extra, restauración atómica con reversión. Copia ZIP: las mismas tres carpetas en un solo archivo .zip, restauradas fusionando en su lugar.",
        "About this feature": "Acerca de esta función",
