        "Backup Photos & Videos": "Copia de seguridad de fotos y videos",
        "Backup Your Photos & Videos Here!": "¡Haz una copia de seguridad de tus fotos y videos aquí!",
        "Backup and receipt saved under DeployBackups/%@ — restore it any time from Deploy History.": "Copia de seguridad y recibo guardados en DeployBackups/%@ — restáuralos cuando quieras desde el historial de Deploy.",
        "Bars: %d": "Barras: %d",
        "Battery": "Batería",
        "Battery & Thermal": "Batería y temperatura",
        "Battery & Thermal reads the system powerlog database: battery level, true health (raw max vs design capacity), cycle count, cell temperature, and thermal history. Values come from the latest samples in the log, newest first.": "Batería y temperatura lee la base de datos powerlog del sistema: nivel de batería, salud real (máximo real frente a capacidad de diseño), recuento de ciclos, temperatura de la celda e historial térmico. Los valores provienen de las muestras más recientes del registro, de la más nueva a la más antigua.",
        "Battery Percentage": "Porcentaje de batería",
        "Before anything is written, every file that already exists is backed up (see Deploy History). Existing files are then replaced in place; new files are created.": "Antes de escribir nada, se hace una copia de seguridad de cada archivo que ya existe (ver historial de Deploy). Los archivos existentes se reemplazan en su lugar; los archivos nuevos se crean.",
        "Blocked — pairing / VPN not ready": "Bloqueado — emparejamiento / VPN no listos",
        "Both need a pairing file first: Sandbox → Utilities → Get Pairing File. A loopback VPN (Local Dev VPN) is strongly recommended while flashing.": "Ambos necesitan primero un archivo de emparejamiento: Sandbox → Utilities → Obtener archivo de emparejamiento. Se recomienda encarecidamente una VPN de loopback (Local Dev VPN) mientras flasheas.",
        "Browse Files": "Explorar archivos",
        "Build": "Compilación",
        "Build & Install Wallpaper": "Crear e instalar fondo de pantalla",
