        "Builds a PosterBoard wallpaper on-device from your photo or video — the same descriptor format as an imported .tendies package, installed and listed exactly like one.": "Crea un fondo de pantalla PosterBoard en el dispositivo a partir de tu foto o video — el mismo formato de descriptor que un paquete .tendies importado, instalado y listado exactamente igual.",
        "Built on the worse_query core system by ForceQuit OS, with CacheExtra key knowledge from mond by rooootdev (AGPL-3.0).": "Basado en el sistema central worse_query de ForceQuit OS, con conocimiento de claves CacheExtra de mond por rooootdev (AGPL-3.0).",
