        "Cache Locations": "Ubicaciones de caché",
        "Cache lives in two places inside an app's data container: Library/Caches and tmp. Only the contents of those two folders are deleted — the folders themselves stay, and Documents and the rest of Library are never touched.": "La caché vive en dos lugares dentro del contenedor de datos de una app: Library/Caches y tmp. Solo se elimina el contenido de esas dos carpetas — las carpetas se quedan, y Documentos y el resto de Library nunca se tocan.",
