        "Certificates tab: create your certificate if needed. A free team can hold only one active development certificate — if creation fails with error 7460, revoke an old unused certificate there first.": "Pestaña Certificados: crea tu certificado si es necesario. Un equipo gratuito solo puede tener un certificado de desarrollo activo — si la creación falla con el error 7460, revoca primero allí un certificado antiguo sin usar.",
