        "Connect your iPhone by USB, then sign in with your Apple ID in iLoader.": "Conecta tu iPhone por USB y luego inicia sesión con tu Apple ID en iLoader.",
        "Connect your iPhone to power, connect to Wi-Fi, and leave the Settings → General → iPhone Storage tab open for about 1 hour while the model downloads.": "Conecta tu iPhone a la corriente, conéctate a Wi-Fi y deja abierta la pestaña Ajustes → General → Almacenamiento del iPhone durante aproximadamente 1 hora mientras se descarga el modelo.",
