        "Dynamic Island": "Dynamic Island",
        "Each wallpaper in the package is copied into PosterBoard's data store under a fresh identifier, so it can never clash with an existing wallpaper. A respring is required before a new wallpaper appears in the gallery.": "Cada fondo de pantalla del paquete se copia en el almacén de datos de PosterBoard con un identificador nuevo, así que nunca puede chocar con un fondo existente. Se requiere un respring antes de que aparezca un fondo nuevo en la galería.",
