        "Enumerating containers with pathleak — this can take a while.": "Enumerando contenedores con pathleak — esto puede tardar un rato.",
        "Enumeration": "Enumeración",
        "Error -1 means the signed app cannot access its App Group container. Diagnostics reads the groups from your signed provisioning profile and probes them all. If it reports no signed groups, the IPA was signed without an App Group and must be re-signed with one — no name typed here can fix that.": "El error -1 significa que la app firmada no puede acceder a su contenedor de App Group. El diagnóstico lee los grupos de tu perfil de aprovisionamiento firmado y los prueba todos. Si indica que no hay grupos firmados, el IPA se firmó sin un App Group y debe firmarse de nuevo con uno — ningún nombre escrito aquí puede solucionarlo.",
        "Escape": "Escape",
        "Every menu that was applied, newest first. This is a history log — clearing it only clears the list, it does not undo anything.": "Cada menú aplicado, del más reciente al más antiguo. Esto es un registro de historial — borrarlo solo borra la lista, no deshace nada.",
        "Exact path": "Ruta exacta",
        "Expired %@ — reinstall the app first.": "Caducado %@ — reinstala la app primero.",
        "Expires soon — %@. Stage now, reinstall before it ends.": "Caduca pronto — %@. Prepara ahora, reinstala antes de que termine.",
        "Export": "Exportar",
        "Export Selected (%d)": "Exportar seleccionados (%d)",
        "Export ZIP": "Exportar ZIP",
        "Export the signed IPA and install it with ESign (or any IPA installer).": "Exporta el IPA firmado e instálalo con ESign (o cualquier instalador de IPA).",
        "Exported as .m4a files with their original titles, zipped to this app's Documents/VoiceMemosExports. The recordings database is only ever read — never written.": "Exportados como archivos .m4a con sus títulos originales, comprimidos en Documents/VoiceMemosExports de esta app. La base de datos de grabaciones solo se lee — nunca se escribe.",
        "Exporting…": "Exportando…",
        "Extra": "Extra",
        "Fake-Supervision Residue": "Residuo de supervisión falsa",
        "Fast mode selected: only targets %@ with %@.": "Modo rápido seleccionado: solo objetivos %@ con %@.",
        "File": "Archivo",
        "Filename": "Nombre de archivo",
        "Files & Sharing": "Archivos y uso compartido",
        "Files (%d)": "Archivos (%d)",
        "Files in ConfigurationProfiles": "Archivos en ConfigurationProfiles",
        "Files in theme": "Archivos en el tema",
        "First Bytes": "Primeros bytes",
        "Fix Apple Intelligence": "Reparar Apple Intelligence",
        "Fix Apple Intelligence Here!": "¡Repara Apple Intelligence aquí!",
        "Fix Status Bar": "Reparar barra de estado",
        "Fix Status Bar!": "¡Repara la barra de estado!",
        "Flash": "Flashear",
        "Flash & Language Target": "Destino de flasheo e idioma",
        "Flash Log (%d lines)": "Registro de flasheo (%d líneas)",
        "Flash Selected Cards": "Flashear tarjetas seleccionadas",
        "Flash Theme to iPhone": "Flashear tema al iPhone",
        "Flashing Theme…": "Flasheando tema…",
        "Flashing needs a pairing file and the VPN tunnel. Pair first and connect the VPN in Sandbox → Utilities → Get Pairing File + VPN Status, then come back here.": "El flasheo necesita un archivo de emparejamiento y el túnel VPN. Empareja primero y conecta la VPN en Sandbox → Utilities → Obtener archivo de emparejamiento + Estado de VPN, y luego vuelve aquí.",
        "Flashing needs a pairing file. Pair this iPhone first in Sandbox → Utilities → Get Pairing File.": "El flasheo necesita un archivo de emparejamiento. Empareja este iPhone primero en Sandbox → Utilities → Obtener archivo de emparejamiento.",
        "Flashing needs the VPN tunnel. Open the Local Dev VPN app and connect first.": "El flasheo necesita el túnel VPN. Abre la app Local Dev VPN y conéctate primero.",
        "Flashing…": "Flasheando…",
        "Folder name": "Nombre de carpeta",
        "Follow for updates, demos and new tweaks.": "Sígueme para recibir actualizaciones, demostraciones y nuevos tweaks.",
        "Font Weight / Style": "Peso / estilo de fuente",
        "Footnote": "Nota al pie",
        "Footnote Updated": "Nota al pie actualizada",
        "Footnote text": "Texto de la nota al pie",
        "For AppGroup scope, the target is the App Group identifier (for example group.com.example) — type it here.": "Para el ámbito AppGroup, el objetivo es el identificador del App Group (por ejemplo, group.com.example) — escríbelo aquí.",
        "Force-close the Wallet app from the App Switcher after flashing to see the new card art.": "Cierra forzadamente la app Wallet desde el selector de apps después de flashear para ver el nuevo arte de la tarjeta.",
        "Forces the label shown (5G, 5G+, 5G UC, LTE, …). Limited — the label is display-only.": "Fuerza la etiqueta mostrada (5G, 5G+, 5G UC, LTE, …). Limitado — la etiqueta es solo de visualización.",
        "Free Apple ID installs expire after about 7 days — reinstall with iLoader to renew.": "Las instalaciones con Apple ID gratuito caducan después de unos 7 días — reinstala con iLoader para renovar.",
        "Freed %@": "Liberado %@",
        "Genuine MDM": "MDM genuino",
        "Get Pairing + VPN Tunnel": "Obtener emparejamiento + túnel VPN",
        "Get Pairing File": "Obtener archivo de emparejamiento",
        "Get Pairing File + Local Dev VPN tunnel — the on-device pairing Airlift uses to reach the device.": "Archivo de emparejamiento + túnel Local Dev VPN — el emparejamiento en el dispositivo que Airlift usa para llegar al dispositivo.",
        "Get Pairing File + VPN Status": "Obtener archivo de emparejamiento + Estado de VPN",
        "Get Started": "Empezar",
        "Go to Sandbox Tab": "Ir a la pestaña Sandbox",
        "Go to the Apply/Revert section and tap Apply, then Respring. When the respring finishes, restart your iPhone.": "Ve a la sección Aplicar/Revertir y toca Aplicar, luego Respring. Cuando termine el respring, reinicia tu iPhone.",
        "Go to the Sandbox tab and turn on Start Tweaks Feature to unlock the Tweaks tab.": "Ve a la pestaña Sandbox y activa Iniciar función de tweaks para desbloquear la pestaña Tweaks.",
        "Good to Know": "Conviene saber",
        "Grant refused — size unknown.": "Concesión rechazada — tamaño desconocido.",
        "Granting sandbox access…": "Concediendo acceso de sandbox…",
        "Guide A — Install with iLoader (Desktop)": "Guía A — Instalar con iLoader (escritorio)",
        "Guide B — Sign with Signed Apps (Mobile)": "Guía B — Firmar con Signed Apps (móvil)",
        "Guide C — Turn On New Siri AI": "Guía C — Activar la nueva Siri con IA",
        "Harden": "Endurecer",
        "Hardware-Oriented Features": "Funciones orientadas al hardware",
        "Health %.1f%%": "Salud %.1f%%",
        "Hex Editor": "Editor hexadecimal",
        "Hide Alarm icon": "Ocultar icono de alarma",
        "Hide Location icon": "Ocultar icono de ubicación",
        "Hide Status Bar Icons": "Ocultar iconos de la barra de estado",
        "Hide VPN icon": "Ocultar icono de VPN",
        "History": "Historial",
        "ISO date (e.g. 2026-11-24T15:30:00Z) or yyyy-MM-dd HH:mm:ss.": "Fecha ISO (p. ej., 2026-11-24T15:30:00Z) o yyyy-MM-dd HH:mm:ss.",
        "Identifiers from the App Data container scan — the same list Deploy resolves Application targets against.": "Identificadores del análisis de contenedores de Datos de la app — la misma lista con la que Deploy resuelve los objetivos de aplicación.",
        "Idle": "Inactivo",
        "If iOS asks, enable Developer Mode (Settings → Privacy & Security → Developer Mode) and trust the developer profile.": "Si iOS lo pide, activa el Modo de desarrollador (Ajustes → Privacidad y seguridad → Modo de desarrollador) y confía en el perfil de desarrollador.",
        "If you update or downgrade to a supported build, WorkTweaks will open normally.": "Si actualizas o bajas a una compilación compatible, WorkTweaks se abrirá normalmente.",
        "Import": "Importar",
        "Import .tendies Package…": "Importar paquete .tendies…",
        "Import Failed": "Error de importación",
        "Import Package…": "Importar paquete…",
        "Import Pairing File": "Importar archivo de emparejamiento",
        "Import ZIP Backup…": "Importar copia de seguridad ZIP…",
        "Imported": "Importado",
        "In the Tweaks tab, Apple Intelligence section, turn on Apple Intelligence and Siri AI Cache Patch. The cache patch is the Filza line-104 edit (one CacheData byte, 0x00 to 0x02) — done here, no Filza needed.": "En la pestaña Tweaks, sección Apple Intelligence, activa Apple Intelligence y el parche de caché de Siri con IA. El parche de caché es la edición de la línea 104 de Filza (un byte de CacheData, de 0x00 a 0x02) — se hace aquí, sin necesidad de Filza.",
        "Individual Keys": "Claves individuales",
        "Install tab → Provisioning: fill in the fields below, tap Provision, and wait for \"profile OK\". Your Team ID is shown in the app's Certificates tab.": "Pestaña Instalar → Aprovisionamiento: completa los campos de abajo, toca Aprovisionar y espera a \"profile OK\". Tu Team ID se muestra en la pestaña Certificados de la app.",
        "Installation": "Instalación",
        "Installed Profiles": "Perfiles instalados",
        "Installed any other way, the signed profile leaves the App Group out — and without it, the tweaks can't run. Tap Tutorials below for both step-by-step guides.": "Instalado de cualquier otra forma, el perfil firmado deja fuera el App Group — y sin él, los tweaks no pueden ejecutarse. Toca Tutoriales abajo para ver ambas guías paso a paso.",
        "Installing into PosterBoard…": "Instalando en PosterBoard…",
        "Internal": "Interno",
        "Jetsam & Crash": "Jetsam y fallos",
        "Jetsam & Crash lists the reports iOS writes when it kills an app for memory (Jetsam, bug_type 298), when an app crashes (309), or on a watchdog / kernel panic (210). Open a report to see why it died, share the full file, or clean all reports to free space.": "Jetsam y fallos muestra los informes que iOS escribe cuando termina una app por memoria (Jetsam, bug_type 298), cuando una app falla (309) o por watchdog / kernel panic (210). Abre un informe para ver por qué murió, comparte el archivo completo o limpia todos los informes para liberar espacio.",
