        "Lock Screen Preview": "Vista previa de la pantalla de bloqueo",
        "Locked folders are read-only (0555) with a sentinel file inside; config files are emptied and locked (0444). A Weak Lock is a locked folder missing its sentinel — tap Harden to add it.": "Las carpetas bloqueadas son de solo lectura (0555) con un archivo centinela dentro; los archivos de configuración se vacían y se bloquean (0444). Un bloqueo débil es una carpeta bloqueada sin su centinela — toca Endurecer para añadirlo.",
        "Locks every target below that still needs action. Whitelisted targets are always skipped.": "Bloquea todos los objetivos de abajo que aún necesiten acción. Los objetivos en la lista blanca siempre se omiten.",
        "Log": "Log",
        "Loop (forwards and backwards)": "Bucle (hacia adelante y hacia atrás)",
