        "Name": "Nombre",
        "Nested dictionaries, arrays and Data are shown read-only — the editor never rewrites a structure it cannot show.": "Los diccionarios anidados, arrays y Data se muestran como solo lectura — el editor nunca reescribe una estructura que no puede mostrar.",
        "Network Type Label": "Etiqueta de tipo de red",
