        "Network label (Secondary)": "Etiqueta de red (secundario)",
        "Network type": "Tipo de red",
        "Never share your certificate .p12 file with anyone — it contains your private signing key.": "Nunca compartas tu archivo de certificado .p12 con nadie — contiene tu clave privada de firma.",
        "New Package": "Nuevo paquete",
        "New Row": "Nueva fila",
        "New UI": "Nueva interfaz",
        "No": "No",
        "No AI cache targets were found.": "No se encontraron objetivos de caché de IA.",
        "No Cards Detected Yet": "Aún no se detectaron tarjetas",
        "No Jailbreak": "Sin jailbreak",
        "No ad targets found yet. Tap Scan above.": "Aún no se encontraron objetivos de anuncios. Toca Escanear arriba.",
        "No backed-up photos or videos yet. Use \"Backup Your Photos & Videos Here!\" first.": "Aún no hay fotos ni videos con copia de seguridad. Usa primero \"¡Haz una copia de seguridad de tus fotos y videos aquí!\".",
        "No containers were found, so there is nothing to clean.": "No se encontraron contenedores, así que no hay nada que limpiar.",
        "No deploys yet. When a package is deployed, the files it replaced are backed up here with a receipt, ready to restore.": "Aún no hay despliegues. Cuando se despliega un paquete, los archivos que reemplazó se respaldan aquí con un recibo, listos para restaurar.",
        "No diagnostic reports found — nothing has been killed or crashed recently, or the reports were already cleaned.": "No se encontraron informes de diagnóstico — nada se ha terminado ni ha fallado recientemente, o los informes ya se limpiaron.",
        "No files yet.": "Aún no hay archivos.",
        "No installable profile records were found in this directory.": "No se encontraron registros de perfiles instalables en este directorio.",
        "No pairing file saved yet.": "Aún no se ha guardado ningún archivo de emparejamiento.",
        "No pairing file yet. Pair this iPhone first in Sandbox → Utilities → Get Pairing File — scanning and flashing need it.": "Aún no hay archivo de emparejamiento. Empareja este iPhone primero en Sandbox → Utilities → Obtener archivo de emparejamiento — el análisis y el flasheo lo necesitan.",
        "No recordings were found in the Voice Memos database.": "No se encontraron grabaciones en la base de datos de Notas de voz.",
        "No regular files found in this container.": "No se encontraron archivos normales en este contenedor.",
        "No scan yet. The scan starts automatically; if it does not, open App Data once, or type the bundle ID by hand.": "Aún no hay análisis. El análisis comienza automáticamente; si no lo hace, abre Datos de la app una vez o escribe el bundle ID a mano.",
        "No skin — tap Set Skin below": "Sin skin — toca Establecer skin abajo",
        "No snapshots yet. Apply some tweaks or tap Back Up Now.": "Aún no hay instantáneas. Aplica algunos tweaks o toca Hacer copia ahora.",
        "No stored packages yet. Build one with New Package, or import an existing .deploy / .zip / folder package to edit it here.": "Aún no hay paquetes guardados. Crea uno con Nuevo paquete o importa un paquete .deploy / .zip / carpeta existente para editarlo aquí.",
        "No thermal events found in the powerlog.": "No se encontraron eventos térmicos en el powerlog.",
        "No third-party apps found.": "No se encontraron apps de terceros.",
        "No tweaks match \"%@\".": "Ningún tweak coincide con \"%@\".",
        "No wallpapers imported yet. Wallpapers imported here are listed so you can remove them again — wallpapers added any other way are never touched.": "Aún no se han importado fondos de pantalla. Los fondos importados aquí se listan para que puedas eliminarlos de nuevo — los fondos añadidos de cualquier otra forma nunca se tocan.",
        "Nominal capacity": "Capacidad nominal",
        "Not Supervised": "No supervisado",
