        "Not present in this backup": "No presente en esta copia de seguridad",
        "Not set": "No establecido",
        "Nothing applied yet.": "Aún no se ha aplicado nada.",
        "Nothing staged yet.": "Aún no hay nada preparado.",
        "Nothing was written — the stored manifest is unchanged.": "No se escribió nada — el manifiesto guardado no cambió.",
        "Nothing was written.": "No se escribió nada.",
        "Notice": "Aviso",
        "Numbers only.": "Solo números.",
        "OK": "OK",
        "Off": "Desactivado",
        "Off in this backup": "Desactivado en esta copia de seguridad",
        "Old UI": "Interfaz antigua",
        "On": "Activado",
        "On a computer, download iLoader from iloader.app — the official site only — and open it.": "En una computadora, descarga iLoader desde iloader.app — solo el sitio oficial — y ábrelo.",
        "On in this backup": "Activado en esta copia de seguridad",
        "One of the destination paths is invalid.": "Una de las rutas de destino no es válida.",
        "Only files under Library/Caches inside the listed targets are deleted. AI models are never touched, and caches regenerate when the apps run again.": "Solo se eliminan los archivos en Library/Caches dentro de los objetivos listados. Los modelos de IA nunca se tocan y las cachés se regeneran cuando las apps vuelven a ejecutarse.",
        "Only spoof your device model if you want to download Apple Intelligence. This may break Face ID. If you decide to unspoof and want to keep Apple Intelligence, do NOT re-enter the Apple Intelligence & Siri menu in Settings.": "Suplanta el modelo de tu dispositivo solo si quieres descargar Apple Intelligence. Esto puede romper Face ID. Si decides dejar de suplantar y quieres conservar Apple Intelligence, NO vuelvas a entrar en el menú Apple Intelligence y Siri en Ajustes.",
        "Only the listed .ips / .crash / .panic files under DiagnosticReports (and Retired) are ever deleted. The folders themselves are kept, and nothing else is touched.": "Solo se eliminan los archivos .ips / .crash / .panic listados en DiagnosticReports (y Retired). Las carpetas se conservan y no se toca nada más.",
        "Open App Data first so the container scan runs, then come back — or tap Rescan.": "Abre primero Datos de la app para que se ejecute el análisis de contenedores y luego vuelve — o toca Volver a escanear.",
        "Open Settings → Apple Intelligence & Siri and tap Join Waitlist. Wait about 15 minutes for it to be accepted.": "Abre Ajustes → Apple Intelligence y Siri y toca Unirse a la lista de espera. Espera unos 15 minutos hasta que se acepte.",
        "Open Signed Apps and sign in with your Apple ID.": "Abre Signed Apps e inicia sesión con tu Apple ID.",
        "Open Source": "Código abierto",
        "Open Tutorials": "Abrir tutoriales",
        "Open WorkTweaks and you're done.": "Abre WorkTweaks y listo.",
        "Open as Property List": "Abrir como lista de propiedades",
        "Open as SQLite Database": "Abrir como base de datos SQLite",
        "Open the Local Dev VPN app and connect. The tunnel shows as a utun interface on 10.7.x.x (gateway 10.7.0.1).": "Abre la app Local Dev VPN y conéctate. El túnel aparece como una interfaz utun en 10.7.x.x (puerta de enlace 10.7.0.1).",
        "Opening the configuration profiles…": "Abriendo los perfiles de configuración…",
        "Opening the database…": "Abriendo la base de datos…",
        "Opens an empty editor; the file is created when you save.": "Abre un editor vacío; el archivo se crea cuando guardas.",
        "Opens the database as editable tables, with a backup taken before the first save. Close the owning app before editing.": "Abre la base de datos como tablas editables, con una copia de seguridad antes del primer guardado. Cierra la app propietaria antes de editar.",
        "Opens the property list as an editable key/type/value table, with a backup taken before the first save.": "Abre la lista de propiedades como una tabla editable de clave/tipo/valor, con una copia de seguridad antes del primer guardado.",
        "Optional label": "Etiqueta opcional",
        "Organization: %@": "Organización: %@",
        "Original": "Original",
        "Original (%d)": "Original (%d)",
        "PIN": "PIN",
        "Package": "Paquete",
        "Package Builder": "Creador de paquetes",
        "Package Format": "Formato de paquete",
        "Packages you build or import are stored on this device, in WorkTweaks' own container. Tap a package to edit it. Deploy runs it through the same preview, resolve and backup flow as a picked package.": "Los paquetes que creas o importas se guardan en este dispositivo, en el propio contenedor de WorkTweaks. Toca un paquete para editarlo. Deploy lo ejecuta con el mismo flujo de vista previa, resolución y copia de seguridad que un paquete elegido.",
        "Pair This iPhone": "Emparejar este iPhone",
        "Pairing & Airlift": "Emparejamiento y Airlift",
        "Pairing cancelled.": "Emparejamiento cancelado.",
        "Pairing file": "Archivo de emparejamiento",
        "Pairing file imported.": "Archivo de emparejamiento importado.",
        "Pairing file removed.": "Archivo de emparejamiento eliminado.",
        "Pairing file saved to the app.": "Archivo de emparejamiento guardado en la app.",
        "Parsed from the .plist files in the ConfigurationProfiles directory. This page never installs or removes a profile.": "Analizado a partir de los archivos .plist del directorio ConfigurationProfiles. Esta página nunca instala ni elimina un perfil.",
        "Partial — some icons may still show. Hidden through the archive's suppressed identifiers.": "Parcial — algunos iconos aún pueden aparecer. Ocultos mediante los identificadores suprimidos del archivo.",
        "Partially Supported": "Parcialmente compatible",
        "Partially Supported iOS • %@": "iOS parcialmente compatible • %@",
        "Passcode Theme": "Tema de código",
        "Passcode Themes": "Temas de código",
        "Passcode theme applied": "Tema de código aplicado",
        "Paste card hash": "Pegar hash de tarjeta",
        "Path Enumeration": "Enumeración de rutas",
        "Paths must be relative, non-empty and contain no \"..\" component.": "Las rutas deben ser relativas, no vacías y no contener el componente \"..\".",
        "Payload files are copied into the package. Add File accepts any file — a .plist is added as a payload, and a .zip is unpacked, each file inside becoming a payload with its destination defaulting to its path inside the archive. Destinations are relative paths only; absolute paths and \"..\" are rejected, exactly like an imported package.": "Los archivos de carga se copian en el paquete. Añadir archivo acepta cualquier archivo — un .plist se añade como carga y un .zip se descomprime, y cada archivo dentro se convierte en una carga con su destino por defecto en su ruta dentro del archivo. Los destinos son solo rutas relativas; las rutas absolutas y \"..\" se rechazan, exactamente igual que en un paquete importado.",
        "Persist after reboot": "Persistir tras el reinicio",
        "Photo Library": "Fototeca",
        "Photo chosen — tap to change": "Foto elegida — toca para cambiar",
        "Photos & Videos": "Fotos y videos",
        "Pick Target App": "Elegir app de destino",
        "Pick an app": "Elige una app",
        "Pick an app to see its cache and clean it.": "Elige una app para ver su caché y limpiarla.",
        "Pick from App Data scan…": "Elegir del análisis de Datos de la app…",
        "Pick the WorkTweaks IPA, set the Signing Bundle ID field to the same identifier, then tap Sign IPA.": "Elige el IPA de WorkTweaks, establece el campo Signing Bundle ID con el mismo identificador y luego toca Firmar IPA.",
        "Pick the photos and videos you want to keep, then Save. They are copied into the BackUP_Data folder inside the app. Optional — you can skip this.": "Elige las fotos y videos que quieres conservar y luego Guarda. Se copian en la carpeta BackUP_Data dentro de la app. Opcional — puedes omitirlo.",
        "Plays a soft sound when you tap menus and features. Respects the silent switch.": "Reproduce un sonido suave cuando tocas menús y funciones. Respeta el interruptor de silencio.",
        "Please Install It the Right Way": "Instálalo de la forma correcta",
        "PosterBoard Data": "Datos de PosterBoard",
        "PosterBoard Updated": "PosterBoard actualizado",
        "PosterBoard is unavailable": "PosterBoard no está disponible",
        "Power": "Energía",
        "Prepare Share": "Preparar para compartir",
        "Preparing the container scan…": "Preparando el análisis de contenedores…",
        "Preview (first 128 KB)": "Vista previa (primeros 128 KB)",
        "Probe Again": "Probar de nuevo",
        "Probing cache sizes…": "Comprobando tamaños de caché…",
        "Raw max capacity": "Capacidad máxima real",
        "Read": "Leer",
        "Read Powerlog": "Leer powerlog",
        "Read complete%@%@.": "Lectura completa%@%@.",
        "Read-only mode — the grant did not include write access, so Clean All is disabled.": "Modo de solo lectura — la concesión no incluía acceso de escritura, así que Limpiar todo está desactivado.",
        "Read-only: the powerlog is cloned into this app's temp folder and inspected there. Nothing is ever written to the system database. Some iOS 26 firmware restricts the powerlog sandbox token; iOS 27 reads fully.": "Solo lectura: el powerlog se clona en la carpeta temporal de esta app y se inspecciona allí. Nunca se escribe nada en la base de datos del sistema. Algunos firmwares de iOS 26 restringen el token de sandbox del powerlog; iOS 27 lee por completo.",
        "Reading the configuration profiles…": "Leyendo los perfiles de configuración…",
        "Reading the property list…": "Leyendo la lista de propiedades…",
        "Reading the recordings database…": "Leyendo la base de datos de grabaciones…",
        "Reading video frames…": "Leyendo fotogramas del video…",
        "Reading…": "Leyendo…",
        "Rebooting now might cause a bootloop. Try pressing 'Revert Tweaks'.": "Reiniciar ahora podría causar un bootloop. Intenta pulsar 'Revertir tweaks'.",
        "Recent Requests": "Solicitudes recientes",
        "Recent samples (%d)": "Muestras recientes (%d)",
        "Reference": "Referencia",
        "Reference & Patch Files": "Archivos de referencia y parches",
        "Reference — APFS save-vault idea (clonefile staging, atomic swap with rollback).": "Referencia — idea de bóveda de guardado APFS (preparación con clonefile, intercambio atómico con reversión).",
        "Reference — PosterBoard wallpaper format the maker was verified against.": "Referencia — formato de fondo de pantalla PosterBoard con el que se verificó el creador.",
        "Reference — Splash Ad Cache Lock mechanism (ad SDK cache lock, save vault, diagnostics, Wi-Fi file sharing, Voice Memos export, AI cache probes).": "Referencia — mecanismo de bloqueo de caché de anuncios splash (bloqueo de caché de SDK de anuncios, bóveda de guardado, diagnóstico, uso compartido de archivos por Wi-Fi, exportación de Notas de voz, sondas de caché de IA).",
        "Reference — cache data cleaner": "Referencia — limpiador de datos de caché",
        "Reference — turn on new Siri AI (CacheData line edit + device spoof)": "Referencia — activar la nueva Siri con IA (edición de línea CacheData + suplantación de dispositivo)",
        "Reference — video-to-wallpaper (CAML) builder used by the PosterBoard wallpaper maker.": "Referencia — creador de video a fondo de pantalla (CAML) usado por el creador de fondos de PosterBoard.",
        "Refresh": "Actualizar",
