        "Resolve Target": "Resolver destino",
        "Resolving the target container…": "Resolviendo el contenedor de destino…",
        "Respring": "Respring",
        "Respring did not trigger on this device.": "El respring no se activó en este dispositivo.",
        "Restart Device": "Reiniciar dispositivo",
        "Restart Required": "Reinicio necesario",
        "Restore": "Restaurar",
        "Restore (%d)": "Restaurar (%d)",
        "Restore Backup": "Restaurar copia de seguridad",
        "Restore Everything": "Restaurar todo",
        "Restore Result — %d succeeded, %d failed": "Resultado de la restauración — %d correctos, %d fallidos",
        "Restore a ZIP backup": "Restaurar una copia de seguridad ZIP",
        "Restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "Los cambios de restauración solo surten efecto tras un reinicio completo del dispositivo — un respring no basta. Elegir Más tarde solo lo pospone; los cambios quedan pendientes hasta que reinicies.",
        "Restore into…": "Restaurar en…",
        "Restore swaps the staged copy into the app's current container and rolls back if anything fails. Release a snapshot only after you verified the restore in the app.": "La restauración intercambia la copia preparada por el contenedor actual de la app y revierte si algo falla. Libera una instantánea solo después de haber verificado la restauración en la app.",
        "Restore the backup?": "¿Restaurar la copia de seguridad?",
        "Restore this entire backup?": "¿Restaurar toda esta copia de seguridad?",
        "Restoring ZIP…": "Restaurando ZIP…",
        "Restoring the backup failed — the details are in the Log.": "La restauración de la copia de seguridad falló — los detalles están en el Log.",
        "Restoring writes each backed-up file back in place. Files the deploy created (they did not exist before) are deleted again.": "La restauración escribe cada archivo respaldado de nuevo en su lugar. Los archivos que creó el despliegue (que no existían antes) se eliminan de nuevo.",
        "Restoring…": "Restaurando…",
        "Result — %d succeeded, %d failed": "Resultado — %d correctos, %d fallidos",
        "Retry Flash": "Reintentar flasheo",
        "Retry Flash Theme": "Reintentar flasheo de tema",
        "Revert": "Revertir",
        "Revert Tweaks": "Revertir tweaks",
        "Revert all tweaks?": "¿Revertir todos los tweaks?",
        "Revert and restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "Los cambios de reversión y restauración solo surten efecto tras un reinicio completo del dispositivo — un respring no basta. Elegir Más tarde solo lo pospone; los cambios quedan pendientes hasta que reinicies.",
        "Rewrites the entire MobileGestalt.plist from this backup. A device restart is required after restoring.": "Reescribe todo el MobileGestalt.plist desde esta copia de seguridad. Se requiere reiniciar el dispositivo después de restaurar.",
        "Running": "En ejecución",
        "Sampled": "Muestreado",
        "Sandbox access denied": "Acceso de sandbox denegado",
        "Sandbox extension is ready (directory grant held).": "La extensión de sandbox está lista (concesión de directorio retenida).",
        "Save": "Guardar",
        "Save .passthm": "Guardar .passthm",
        "Save App Group ID": "Guardar ID de App Group",
        "Save Vault": "Bóveda de guardado",
        "Saved": "Guardado",
        "Saved %d of %d to BackUP_Data.": "Guardados %d de %d en BackUP_Data.",
        "Saved: %@": "Guardado: %@",
        "Saves the package, then shares ONE .zip file — save it in Files. Deploy imports that zip and applies it without asking for locations.": "Guarda el paquete y luego comparte UN archivo .zip — guárdalo en Archivos. Deploy importa ese zip y lo aplica sin pedir ubicaciones.",
        "Saving %d of %d (%d%%)": "Guardando %d de %d (%d%%)",
        "Saving applies the edits to the database through SQLite, takes a backup of the original first, then writes the edited file back in place. Close the owning app before saving — a running app can overwrite your edits.": "Al guardar se aplican las ediciones a la base de datos mediante SQLite, se hace primero una copia de seguridad del original y luego se escribe el archivo editado de nuevo en su lugar. Cierra la app propietaria antes de guardar — una app en ejecución puede sobrescribir tus ediciones.",
        "Saving rebuilds the property list from this table, takes a backup of the original first, then writes it back in place. Close the owning app before saving — a running app can overwrite your edits.": "Al guardar se reconstruye la lista de propiedades a partir de esta tabla, se hace primero una copia de seguridad del original y luego se escribe de nuevo en su lugar. Cierra la app propietaria antes de guardar — una app en ejecución puede sobrescribir tus ediciones.",
        "Saving writes the file in place and verifies the result by re-reading it.": "Al guardar se escribe el archivo en su lugar y se verifica el resultado volviéndolo a leer.",
        "Saving writes the file in place, under the container's sandbox extension.": "Al guardar se escribe el archivo en su lugar, bajo la extensión de sandbox del contenedor.",
        "Saving…": "Guardando…",
        "Scan": "Escanear",
        "Scan Cards": "Escanear tarjetas",
        "Scan for Ad Targets": "Buscar objetivos de anuncios",
        "Scanning %@…": "Escaneando %@…",
        "Scanning…": "Escaneando…",
        "Scope": "Ámbito",
        "Search": "Buscar",
        "Search tweaks": "Buscar tweaks",
        "Secondary bars: %d": "Barras secundarias: %d",
        "Secondary carrier name (max 64)": "Nombre de operador secundario (máx. 64)",
        "Secondary network type": "Tipo de red secundario",
        "Sections": "Secciones",
        "Select All": "Seleccionar todo",
        "Select None": "No seleccionar ninguno",
        "Select at least one card and attach a skin image to it before flashing.": "Selecciona al menos una tarjeta y adjúntale una imagen de skin antes de flashear.",
        "Selected app": "App seleccionada",
        "Server": "Servidor",
        "Set NULL": "Establecer NULL",
        "Set Skin": "Establecer skin",
        "Set Skin for All Cards…": "Establecer skin para todas las tarjetas…",
        "Set the Spoofing picker (under Apple Intelligence) to iPhone 17 Pro (iPhone18,1).": "Establece el selector de suplantación (en Apple Intelligence) en iPhone 17 Pro (iPhone18,1).",
        "Sets how many bars are drawn. Static — it does not follow the real signal.": "Establece cuántas barras se dibujan. Estático — no sigue la señal real.",
        "Share %@": "Compartir %@",
        "Share Contents": "Compartir contenido",
        "Share Full Report": "Compartir informe completo",
        "Showing the first %@ of %@ rows — the editor is for targeted edits, not bulk dumps.": "Mostrando las primeras %@ de %@ filas — el editor es para ediciones puntuales, no para volcados masivos.",
        "Shows the battery percentage in the status bar. Key: SBShowBatteryPercentage in com.apple.springboard.plist.": "Muestra el porcentaje de batería en la barra de estado. Clave: SBShowBatteryPercentage en com.apple.springboard.plist.",
        "Sign In": "Iniciar sesión",
        "Signal Bars": "Barras de señal",
        "Signal bars (Primary)": "Barras de señal (principal)",
        "Signal bars (Secondary)": "Barras de señal (secundario)",
        "Single-file shorthand: instead of \"files\", give \"relativePath\" and \"file\". \"scope\" is Application (bundleID = the app's bundle ID), AppGroup (bundleID = the group identifier, e.g. group.com.example) or InternalDaemon. ZIP archives may use stored or deflated entries; encrypted and ZIP64 archives are not supported. Older .deploy archives and plain folders still import.": "Abreviatura de un solo archivo: en lugar de \"files\", indica \"relativePath\" y \"file\". \"scope\" es Application (bundleID = el bundle ID de la app), AppGroup (bundleID = el identificador del grupo, p. ej., group.com.example) o InternalDaemon. Los archivos ZIP pueden usar entradas almacenadas o comprimidas; los archivos cifrados y ZIP64 no son compatibles. Los archivos .deploy antiguos y las carpetas simples aún se importan.",
        "Size": "Tamaño",
        "Sizes are measured by walking each folder. An app recreates cache as it runs, so the size grows back over time.": "Los tamaños se miden recorriendo cada carpeta. Una app recrea la caché mientras se ejecuta, así que el tamaño vuelve a crecer con el tiempo.",
        "Sizes are probed read-only (depth 4). Delete Cache removes only files under Library/Caches inside these targets — the AI models live elsewhere and are never touched.": "Los tamaños se comprueban en solo lectura (profundidad 4). Eliminar caché solo quita archivos en Library/Caches dentro de estos objetivos — los modelos de IA viven en otro lugar y nunca se tocan.",
        "Snapshots": "Instantáneas",
        "Software-Oriented Features": "Funciones orientadas al software",
        "Some tweaks — especially Apple Intelligence — only take effect after a full restart, not a respring.": "Algunos tweaks — especialmente Apple Intelligence — solo surten efecto tras un reinicio completo, no un respring.",
        "Something went wrong": "Algo salió mal",
        "Sound Effects": "Efectos de sonido",
        "Splash Ad Cache Lock": "Bloqueo de caché de anuncios splash",
        "Splash Ad Cache Lock finds the folders ad SDKs use to cache splash (launch) ads, empties them, and locks them read-only so the app cannot rebuild its splash-ad cache. Locks apply only to third-party app folders — never to system folders, Documents, or the app itself.": "El bloqueo de caché de anuncios splash encuentra las carpetas que los SDK de anuncios usan para almacenar en caché los anuncios splash (de inicio), las vacía y las bloquea como solo lectura para que la app no pueda reconstruir su caché de anuncios splash. Los bloqueos se aplican solo a carpetas de apps de terceros — nunca a carpetas del sistema, Documentos ni a la propia app.",
        "Spoofing": "Suplantación",
        "SpringBoard loads the wallpaper store when it starts — respring or restart to see the change in the wallpaper gallery.": "SpringBoard carga el almacén de fondos de pantalla cuando se inicia — haz respring o reinicia para ver el cambio en la galería de fondos.",
        "SpringBoard reads the footnote when it starts — respring or restart to see it on the Lock Screen.": "SpringBoard lee la nota al pie cuando se inicia — haz respring o reinicia para verla en la pantalla de bloqueo.",
        "Stage an app's Documents, Library/Preferences and Library/Application Support (never Caches) before its 7-day certificate expires. After reinstall, the data is restored into the app's new container — matched by bundle id, not the old container UUID.": "Prepara los Documentos, Library/Preferences y Library/Application Support de una app (nunca Caches) antes de que caduque su certificado de 7 días. Tras la reinstalación, los datos se restauran en el nuevo contenedor de la app — emparejados por bundle id, no por el UUID del contenedor antiguo.",
        "Stage copies into the APFS vault (no extra space). ZIP backup copies first, then zips — for very large apps use the APFS vault. Both refuse while the app is still writing its database.": "La preparación copia en la bóveda APFS (sin espacio extra). La copia ZIP copia primero y luego comprime — para apps muy grandes usa la bóveda APFS. Ambas se niegan mientras la app siga escribiendo en su base de datos.",
        "Stage into APFS Vault": "Preparar en la bóveda APFS",
        "Staged %@: %d file(s), %@. Verified against the source.": "Preparado %@: %d archivo(s), %@. Verificado con el origen.",
        "Staged snapshots": "Instantáneas preparadas",
        "Staging…": "Preparando…",
        "Start Server": "Iniciar servidor",
        "Start Tweaks Feature": "Iniciar función de tweaks",
        "Start the server to get its address.": "Inicia el servidor para obtener su dirección.",
        "Still writing (%d active WAL file(s)) — close the app first": "Aún escribiendo (%d archivo(s) WAL activos) — cierra la app primero",
        "Stop Scan": "Detener análisis",
        "Stop Server": "Detener servidor",
        "Stopped": "Detenido",
        "Stored as text.": "Guardado como texto.",
        "Subtype": "Subtipo",
        "Supervision": "Supervisión",
        "Support": "Soporte",
        "Supported": "Compatible",
        "Supported iOS Versions": "Versiones de iOS compatibles",
        "Supported iOS • %@": "iOS compatible • %@",
        "Swift implementation of the respring web view (via mond / jailbreak.party).": "Implementación en Swift de la vista web de respring (vía mond / jailbreak.party).",
        "System": "Sistema",
        "System Caches": "Cachés del sistema",
        "System Language": "Idioma del sistema",
        "Table": "Tabla",
        "Tap Read Powerlog to load the latest battery samples.": "Toca Leer powerlog para cargar las muestras de batería más recientes.",
        "Tap Refresh to list the diagnostic reports.": "Toca Actualizar para listar los informes de diagnóstico.",
        "Tap a key to assign a custom image.": "Toca una clave para asignar una imagen personalizada.",
        "Target": "Destino",
        "Target Path": "Ruta de destino",
        "Target container": "Contenedor de destino",
        "That file is not a pairing file.": "Ese archivo no es un archivo de emparejamiento.",
        "The App Data scan is still running — ad targets appear once it finishes.": "El análisis de Datos de la app aún está en curso — los objetivos de anuncios aparecen cuando termine.",
        "The CacheExtra key knowledge — the tweak-key research the WorkTweaks tweak catalog is built on.": "El conocimiento de claves CacheExtra — la investigación de claves de tweaks en la que se basa el catálogo de tweaks de WorkTweaks.",
        "The Voice Memos container is found through the App Data scan.": "El contenedor de Notas de voz se encuentra mediante el análisis de Datos de la app.",
        "The ZIP must be a Save Vault backup (it carries a BackupManifest.plist). Files merge in place; system bundle ids are blocked.": "El ZIP debe ser una copia de seguridad de Save Vault (lleva un BackupManifest.plist). Los archivos se fusionan en su lugar; los bundle ids del sistema están bloqueados.",
        "The backup of the original file couldn't be written, so nothing was saved.": "No se pudo escribir la copia de seguridad del archivo original, así que no se guardó nada.",
        "The browser asks for these credentials once, then remembers them for the session.": "El navegador pide estas credenciales una vez y luego las recuerda durante la sesión.",
        "The bundle ID is not a valid identifier.": "El bundle ID no es un identificador válido.",
        "The bundle ID of the one app this package may touch. Pick it from the App Data container scan, or type it.": "El bundle ID de la única app que este paquete puede tocar. Elígelo del análisis de contenedores de Datos de la app o escríbelo.",
        "The container scan found no containers.": "El análisis de contenedores no encontró contenedores.",
        "The container scan is shared with App Data and runs once per app session.": "El análisis de contenedores se comparte con Datos de la app y se ejecuta una vez por sesión de la app.",
        "The container scan runs once per session.": "El análisis de contenedores se ejecuta una vez por sesión.",
        "The core system: the sandbox escape and MobileGestalt access this whole app is built on.": "El sistema central: el escape de sandbox y el acceso a MobileGestalt en los que se basa toda esta app.",
        "The current MobileGestalt will be entirely replaced with this %@ backup.": "El MobileGestalt actual se reemplazará por completo con esta copia de seguridad %@.",
        "The current file is overwritten in place with the backup taken before the first byte edit.": "El archivo actual se sobrescribe en su lugar con la copia de seguridad tomada antes de la primera edición de bytes.",
        "The developer's GitHub profile.": "El perfil de GitHub del desarrollador.",
        "The directory is empty.": "El directorio está vacío.",
        "The entry is removed from the property list on the next Save.": "La entrada se elimina de la lista de propiedades en el próximo Guardar.",
        "The file couldn't be read under the container's sandbox extension — the details are in the Log. Nothing was written to it.": "No se pudo leer el archivo bajo la extensión de sandbox del contenedor — los detalles están en el Log. No se escribió nada en él.",
        "The file-based CacheData pattern method used by Enable iPadOS Mode (MobileGestaltCacheDataTweak).": "El método de patrón CacheData basado en archivos que usa Activar modo iPadOS (MobileGestaltCacheDataTweak).",
        "The original identifiers are already registered to another developer account, which is why the Team ID suffix is required.": "Los identificadores originales ya están registrados en otra cuenta de desarrollador, por eso se requiere el sufijo de Team ID.",
        "The package could not be exported.": "No se pudo exportar el paquete.",
        "The package store is unavailable (the App Group container did not resolve).": "El almacén de paquetes no está disponible (el contenedor de App Group no se resolvió).",
        "The pairing file + Local Dev VPN tunnel are the transport Airlift uses to reach the device. Green = ready, gray = not ready.": "El archivo de emparejamiento + el túnel Local Dev VPN son el transporte que Airlift usa para llegar al dispositivo. Verde = listo, gris = no listo.",
        "The pathleak scan reads inodes one by one — this can take a few minutes.": "El análisis pathleak lee los inodos uno por uno — esto puede tardar unos minutos.",
        "The picked file could not be copied into the package.": "No se pudo copiar el archivo elegido en el paquete.",
        "The row is deleted from the database on the next Save.": "La fila se elimina de la base de datos en el próximo Guardar.",
        "The sandbox extension for this container's directory was refused — the result code is in the Log.": "La extensión de sandbox para el directorio de este contenedor fue rechazada — el código de resultado está en el Log.",
        "The scan of %@ found no containers. The scan's baseline and counts are in the Log.": "El análisis de %@ no encontró contenedores. La línea base y los recuentos del análisis están en el Log.",
        "The server shares this app's Documents folder only — SaveVaultBackups, staged vaults and uploads. Nothing outside it is ever served. Keep this page open while transferring: the server stops when you leave the page or the app goes to the background.": "El servidor solo comparte la carpeta Documentos de esta app — SaveVaultBackups, bóvedas preparadas y cargas. Nunca se sirve nada fuera de ella. Mantén esta página abierta mientras transfieres: el servidor se detiene cuando sales de la página o la app pasa a segundo plano.",
        "The staging vault lives in this app's Documents and does NOT survive uninstalling WorkTweaks. Verify a restore in the app first, then release the vault.": "La bóveda de preparación vive en los Documentos de esta app y NO sobrevive a desinstalar WorkTweaks. Verifica primero una restauración en la app y luego libera la bóveda.",
        "The stored package is removed. Files it already deployed, and its Deploy History receipts, are not touched.": "El paquete guardado se elimina. Los archivos que ya desplegó y sus recibos del historial de Deploy no se tocan.",
        "Theme Information": "Información del tema",
        "Thermal history (%d)": "Historial térmico (%d)",
        "These are the photos and videos in the BackUP_Data folder. Select the ones to restore, then Restore opens the share sheet — tap Save to Photos there.": "Estas son las fotos y videos de la carpeta BackUP_Data. Selecciona los que quieres restaurar y luego Restaurar abre la hoja para compartir — toca Guardar en Fotos allí.",
        "This app is free software under the GNU AGPL v3 license, following the licenses of the projects above.": "Esta app es software libre bajo la licencia GNU AGPL v3, siguiendo las licencias de los proyectos de arriba.",
        "This app's own repository — issues and contributions welcome.": "El propio repositorio de esta app — problemas y contribuciones bienvenidos.",
        "This deletes only the listed .ips / .crash / .panic files. The folders are kept.": "Esto solo elimina los archivos .ips / .crash / .panic listados. Las carpetas se conservan.",
        "This device right now": "Este dispositivo ahora mismo",
        "This file isn't UTF-8 text, so it can't be edited as text. It can be edited byte-by-byte in the hex editor below.": "Este archivo no es texto UTF-8, así que no se puede editar como texto. Se puede editar byte a byte en el editor hexadecimal de abajo.",
        "This file isn't UTF-8 text, so it can't be edited here. Nothing is ever written to it from this page.": "Este archivo no es texto UTF-8, así que no se puede editar aquí. Nunca se escribe nada en él desde esta página.",
        "This iOS Version Isn't Supported": "Esta versión de iOS no es compatible",
        "This is NOT an adblock: locking only stops ad assets landing on disk. Ads downloaded live over the network when the app opens can still appear.": "Esto NO es un bloqueador de anuncios: el bloqueo solo impide que los recursos de anuncios lleguen al disco. Los anuncios descargados en vivo por la red cuando se abre la app aún pueden aparecer.",
        "This is the container's system-managed metadata file. iOS doesn't allow other processes to read its contents, so it can't be opened or edited here.": "Este es el archivo de metadatos gestionado por el sistema del contenedor. iOS no permite que otros procesos lean su contenido, así que no se puede abrir ni editar aquí.",
        "This only clears the list. It does not undo anything that was applied.": "Esto solo borra la lista. No deshace nada de lo aplicado.",
        "This only makes the Join Waitlist button appear. The Siri AI model may still refuse to download — that part is not solved by this method yet.": "Esto solo hace que aparezca el botón Unirse a la lista de espera. Es posible que el modelo de Siri con IA aún se niegue a descargarse — esa parte aún no se resuelve con este método.",
        "This package was rejected": "Este paquete fue rechazado",
        "This permanently deletes the contents of %@ in %@ (%@). The folders themselves stay in place.": "Esto elimina permanentemente el contenido de %@ en %@ (%@). Las carpetas se quedan en su lugar.",
        "This property list has no top-level entries.": "Esta lista de propiedades no tiene entradas de nivel superior.",
        "This removes the wallpaper imported from %@ — its descriptor folder is deleted from PosterBoard's data store.": "Esto elimina el fondo de pantalla importado de %@ — su carpeta de descriptores se elimina del almacén de datos de PosterBoard.",
        "This restores the MobileGestalt backup saved on first launch (SavedGestalt.plist).": "Esto restaura la copia de seguridad de MobileGestalt guardada en el primer inicio (SavedGestalt.plist).",
        "This table has no columns to edit.": "Esta tabla no tiene columnas para editar.",
        "Total CacheExtra keys": "Total de claves CacheExtra",
        "True health": "Salud real",
        "Try Again": "Intentar de nuevo",
        "Turn on the Charge Limit Menu toggle (Add feature section).": "Activa el interruptor del menú de límite de carga (sección Añadir función).",
        "Tutorials": "Tutoriales",
        "Tweaks": "Tweaks",
        "Tweaks Applied": "Tweaks aplicados",
        "Tweaks UI": "Interfaz de tweaks",
        "Tweaks are locked": "Los tweaks están bloqueados",
        "Two ways to get a pairing file: Pair This iPhone (iOS 27 only) shows a 6-digit PIN — approve it in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. Or import a pairing file (.plist) from your computer manually. The pairing file is saved in the app.": "Hay dos formas de obtener un archivo de emparejamiento: Emparejar este iPhone (solo iOS 27) muestra un PIN de 6 dígitos — apruébalo en Ajustes › Privacidad y seguridad › Modo de desarrollador › Emparejar con WorkTweaks. O importa manualmente un archivo de emparejamiento (.plist) desde tu computadora. El archivo de emparejamiento se guarda en la app.",
        "Type": "Tipo",
        "Type the region suffix as shown in Settings > General > About, e.g. PA/A or LL/A. It changes the Model Number suffix after Apply.": "Escribe el sufijo de región como se muestra en Ajustes > General > Información, p. ej., PA/A o LL/A. Cambia el sufijo del número de modelo después de Aplicar.",
        "Type: %@ (%@). %@": "Tipo: %@ (%@). %@",
        "Type: %@. %@": "Tipo: %@. %@",
        "Universal mode flashes ~600 files for all languages & Bold text. Selecting a specific language (e.g. Ukrainian) speeds up flashing dramatically.": "El modo universal flashea ~600 archivos para todos los idiomas y texto en negrita. Elegir un idioma específico (p. ej., ucraniano) acelera mucho el flasheo.",
