        "Voltage": "Voltaje",
        "WARNING: These tweaks can break features on your device or softbrick it if misused. After Apply you choose Respring or Restart; Revert and Backup restores require a full device restart.": "ADVERTENCIA: Estos tweaks pueden romper funciones de tu dispositivo o dejarlo inutilizable si se usan mal. Después de Aplicar eliges Respring o Reiniciar; las restauraciones de Revertir y Copia de seguridad requieren un reinicio completo del dispositivo.",
        "Waiting for the App Data scan…": "Esperando el análisis de Datos de la app…",
