        "Wallpaper": "Fondo de pantalla",
        "Wallpaper name": "Nombre del fondo de pantalla",
        "Warning": "Advertencia",
        "Warning: raw byte edits have no structure validation — a wrong byte can corrupt this file or the owning app's data. A backup of the original is saved before the first edit.": "Advertencia: las ediciones de bytes sin procesar no tienen validación de estructura — un byte incorrecto puede dañar este archivo o los datos de la app propietaria. Se guarda una copia de seguridad del original antes de la primera edición.",
        "WeChat accounts": "Cuentas de WeChat",
        "Welcome to WorkTweaks": "Te damos la bienvenida a WorkTweaks",
        "What this does": "Qué hace esto",
        "When enabled, MobileGestalt is written in-place on the same inode, which (hopefully) prevents iOS from regenerating the cache on reboot. Disable to use atomic file replacement instead.": "Cuando está activado, MobileGestalt se escribe en su lugar en el mismo inode, lo que (con suerte) evita que iOS regenere la caché al reiniciar. Desactívalo para usar en su lugar el reemplazo atómico de archivos.",
        "Where it goes": "Adónde va",
        "Whitelist": "Lista blanca",
        "Whitelisted": "En lista blanca",
        "Whole numbers only.": "Solo números enteros.",
        "Wi-Fi File Sharing": "Uso compartido de archivos por Wi-Fi",
        "WorkTweaks is free software under the GNU Affero General Public License v3.0. The core (worse_query) is GPL-3.0, but the CacheExtra key knowledge from mond and the CacheData method from Nugget are AGPL-3.0 — GPLv3 code may be combined into an AGPLv3 work, and the AGPL terms then cover the combined work as a whole.": "WorkTweaks es software libre bajo la Licencia Pública General Affero de GNU v3.0. El núcleo (worse_query) es GPL-3.0, pero el conocimiento de claves CacheExtra de mond y el método CacheData de Nugget son AGPL-3.0 — el código GPLv3 puede combinarse en una obra AGPLv3, y los términos AGPL cubren entonces la obra combinada en su conjunto.",
        "WorkTweaks must be installed with iLoader, or by signing the IPA with Signed Apps, so that its App Group works correctly.": "WorkTweaks debe instalarse con iLoader o firmando el IPA con Signed Apps, para que su App Group funcione correctamente.",
        "WorkTweaks only works when its App Group is part of the signing profile. Guides A and B make sure that happens — pick the one that fits you. Guide C turns on the new Siri AI.": "WorkTweaks solo funciona cuando su App Group forma parte del perfil de firma. Las guías A y B se aseguran de que así sea — elige la que te convenga. La guía C activa la nueva Siri con IA.",
        "WorkTweaks v3.0 only opens on the builds listed above: the app checks your device's build at launch, and any other build gets the \"not supported\" screen instead of the app. On iOS 18 and iOS 26, only App Data and Airlift are supported (partial support). Developed and tested on iOS 27.0.1 (24A446).": "WorkTweaks v3.0 solo se abre en las compilaciones listadas arriba: la app comprueba la compilación de tu dispositivo al iniciar, y cualquier otra compilación muestra la pantalla de \"no compatible\" en lugar de la app. En iOS 18 e iOS 26, solo Datos de la app y Airlift son compatibles (compatibilidad parcial). Desarrollado y probado en iOS 27.0.1 (24A446).",
        "Works on iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 and later patched the exploit).": "Funciona en iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 y posteriores corrigieron el exploit).",
        "Write Method": "Método de escritura",
        "Write access available — Clean All can delete the listed reports.": "Acceso de escritura disponible — Limpiar todo puede eliminar los informes listados.",
        "Writes SharedDeviceConfiguration.plist in place, keeping every other key in the file. SpringBoard reads the file when it starts, so a respring or restart is needed to see the change.": "Escribe SharedDeviceConfiguration.plist en su lugar, conservando todas las demás claves del archivo. SpringBoard lee el archivo cuando se inicia, así que se necesita un respring o reinicio para ver el cambio.",
        "Writing or verifying the file failed — the details are in the Log.": "La escritura o verificación del archivo falló — los detalles están en el Log.",
        "Writing the file failed — the details are in the Log.": "La escritura del archivo falló — los detalles están en el Log.",
        "Writing the footnote failed — the details are in the Log.": "La escritura de la nota al pie falló — los detalles están en el Log.",
        "Yes": "Sí",
        "You can add multiple hashes at once — separate them with spaces, commas, or newlines.": "Puedes añadir varios hashes a la vez — sepáralos con espacios, comas o saltos de línea.",
        "Your All BackUP Files Here!": "¡Todos tus archivos de copia de seguridad aquí!",
        "Your device is running **%@**. WorkTweaks v2.0 only runs on the builds listed below, so the app can't open on this version.": "Tu dispositivo ejecuta **%@**. WorkTweaks v2.0 solo se ejecuta en las compilaciones listadas abajo, así que la app no puede abrirse en esta versión.",
        "ZIP backup saved: %@. Share it to Files before you uninstall anything.": "Copia de seguridad ZIP guardada: %@. Compártela en Archivos antes de desinstalar nada.",
        "empty": "vacío",
