        "The Siri byte is flipped (0x02) — the patch is on.": "El byte de Siri está invertido (0x02) — el parche está activado.",
        "The Siri byte is 0x00 — the patch is off.": "El byte de Siri es 0x00 — el parche está desactivado.",
        "The patch pattern matches more than once, so the automatic patch refuses to guess — edit the Siri line by hand.": "El patrón del parche coincide más de una vez, así que el parche automático se niega a adivinar — edita la línea de Siri a mano.",
        "The patch was found, but not on line 104 — open the viewer to see its line.": "El parche se encontró, pero no en la línea 104 — abre el visor para ver su línea.",
        "The patch line was not found in this file — check the Mobile Gestalt.plist viewer.": "La línea del parche no se encontró en este archivo — revisa el visor de Mobile Gestalt.plist.",
        "CacheData is missing from MobileGestalt.": "Falta CacheData en MobileGestalt.",
        "This is the same text Filza shows for this file. CacheData is the long base64 block; its lines are 51 bytes each. The Siri line is highlighted.": "Este es el mismo texto que Filza muestra para este archivo. CacheData es el bloque largo en base64; sus líneas tienen 51 bytes cada una. La línea de Siri está resaltada.",
        "Siri line: line %d": "Línea de Siri: línea %d",
        "On this device the Siri line is line %d, not 104 — the guide's line number varies by device.": "En este dispositivo la línea de Siri es la línea %d, no la 104 — el número de línea de la guía varía según el dispositivo.",
        "No matches": "Sin coincidencias",
