        "No packages could be loaded from the app bundle.": "No se pudieron cargar paquetes desde el bundle de la app.",
        "Install complete — patched (revision 7). Signed with your certificate — ready to launch.": "Instalación completa — parcheado (revisión 7). Firmado con tu certificado — listo para lanzar.",
        "Install complete — patched (revision 7). No certificate imported, so it cannot launch yet.": "Instalación completa — parcheado (revisión 7). No se importó ningún certificado, así que aún no puede lanzarse.",
