    // fr
    static let fr: [String: String] = [
        " and ": " et ",
        " — battery table %@": " — table de batterie %@",
        "%@ — %@": "%@ — %@",
        "%@ — %d file(s)": "%@ — %d fichier(s)",
        "%@ — from %@": "%@ — de %@",
        "%@ • %@ • %@ • %d file": "%@ • %@ • %@ • %d fichier",
        "%@ • %@ • %@ • %d files": "%@ • %@ • %@ • %d fichiers",
        "%@ • %@ • %d file": "%@ • %@ • %d fichier",
        "%@ • %@ • %d files": "%@ • %@ • %d fichiers",
        "%d active tweaks · %d CacheExtra keys": "%d tweaks actifs · %d clés CacheExtra",
        "%d bytes — length-preserving edits only: byte values can change, the file's length never does.": "%d octets — modifications préservant la longueur uniquement : les valeurs des octets peuvent changer, la longueur du fichier, jamais.",
        "%d cards": "%d cartes",
        "%d character(s). The text appears in small type at the bottom of the Lock Screen. Leave it empty and tap Apply Footnote to remove the footnote.": "%d caractère(s). Le texte s'affiche en petits caractères en bas de l'écran de verrouillage. Laissez vide et touchez Appliquer la note pour supprimer la note.",
        "%d cycles": "%d cycles",
        "%d file(s) examined — the scan walks the whole container, so large apps take a while.": "%d fichier(s) examiné(s) — l'analyse parcourt tout le conteneur, les grosses apps prennent donc un moment.",
        "%d file(s) in BackUP_Data.": "%d fichier(s) dans BackUP_Data.",
        "%d file(s) • %@ total • %@ in Caches": "%d fichier(s) • %@ au total • %@ dans Caches",
        "%d file(s) • %@ • staged %@": "%d fichier(s) • %@ • préparé(s) %@",
        "%d item": "%d élément",
        "%d item(s) removed, %d could not be removed (in use or protected).": "%d élément(s) supprimé(s), %d n'ont pas pu être supprimés (en cours d'utilisation ou protégés).",
        "%d item(s) removed.": "%d élément(s) supprimé(s).",
        "%d items": "%d éléments",
        "%d keys": "%d clés",
        "%d largest file(s) — %@ in the top %d.": "%d fichier(s) le(s) plus volumineux — %@ dans les %d premiers.",
        "%d of %d": "%d sur %d",
        "%d row(s).": "%d ligne(s).",
        "%d selected": "%d sélectionné(s)",
        "%d to lock": "%d à verrouiller",
        ", thermal table %@": ", table thermique %@",
        "1 card": "1 carte",
        "1. Open the Translate app, delete the downloaded English (US) language, then download it again.\n2. Go to Settings > General > Language & Region, change the region from United States to another country, then change it back to United States.\n3. Turn off Low Power Mode (Settings > Battery).\n4. Connect to Wi-Fi (and keep your iPhone charging) while Apple Intelligence finishes downloading.": "1. Ouvrez l'app Traduire, supprimez la langue anglaise (États-Unis) téléchargée, puis téléchargez-la de nouveau.\n2. Allez dans Réglages > Général > Langue et région, changez la région des États-Unis vers un autre pays, puis remettez-la sur États-Unis.\n3. Désactivez le mode économie d'énergie (Réglages > Batterie).\n4. Connectez-vous au Wi-Fi (et laissez votre iPhone en charge) pendant qu'Apple Intelligence termine le téléchargement.",
        "1. Tap Scan Cards above.": "1. Touchez Analyser les cartes ci-dessus.",
        "1. Use the iPhone 16 Pro subtype.\n2. Settings > Appearance > Display Zoom > Large Text, then go Back and set Text Size to Small (optional).": "1. Utilisez le sous-type iPhone 16 Pro.\n2. Réglages > Apparence > Zoom d'affichage > Texte large, puis revenez en arrière et réglez la taille du texte sur Petite (facultatif).",
        "2. On this iPhone, double-click the Side button (Apple Pay), authenticate with Face ID, and tap your card.": "2. Sur cet iPhone, double-cliquez sur le bouton latéral (Apple Pay), authentifiez-vous avec Face ID, puis touchez votre carte.",
        "3. Your card will appear here automatically!": "3. Votre carte apparaîtra ici automatiquement !",
        "A .tendies package is a ZIP archive containing one or more wallpaper descriptors: loose descriptor folders, a descriptors folder, or a container layout mirroring PosterBoard's data store (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Stored and deflated ZIP entries are supported — the same reader Deploy uses; encrypted and ZIP64 archives are rejected.": "Un paquet .tendies est une archive ZIP contenant un ou plusieurs descripteurs de fond d'écran : des dossiers de descripteurs libres, un dossier descriptors, ou une disposition de conteneur reflétant le magasin de données de PosterBoard (Library/Application Support/PRBPosterExtensionDataStore/…/Extensions/…/descriptors). Les entrées ZIP stockées et déflatées sont prises en charge — le même lecteur que celui utilisé par Deploy ; les archives chiffrées et ZIP64 sont rejetées.",
        "A Deploy package replaces files inside exactly one app — the app named by its bundle ID. It cannot touch any other app: every target path is relative to that app's container, and packages with absolute or \"..\" paths are rejected whole.": "Un paquet Deploy remplace des fichiers dans exactement une app — l'app désignée par son identifiant de bundle. Il ne peut toucher aucune autre app : chaque chemin cible est relatif au conteneur de cette app, et les paquets contenant des chemins absolus ou « .. » sont rejetés dans leur intégralité.",
        "A MobileGestalt tweak app for iOS 26/27, built on the open-source projects credited below. Use at your own risk — tweaks modify system files.": "Une app de tweaks MobileGestalt pour iOS 26/27, basée sur les projets open source crédités ci-dessous. Utilisez-la à vos risques et périls — les tweaks modifient des fichiers système.",
        "A MobileGestalt tweak tool for iOS 26 & 27 — unlock your device's hidden features without a jailbreak, powered by the worse_query sandbox escape.": "Un outil de tweaks MobileGestalt pour iOS 26 et 27 — débloquez les fonctions cachées de votre appareil sans jailbreak, grâce à l'échappement de sandbox worse_query.",
        "A bundle ID is required — it names the one app this package may touch.": "Un identifiant de bundle est requis — il désigne la seule app que ce paquet peut toucher.",
        "A package is ONE .zip file containing a manifest.json at its top level plus the payload files it names. The Package Builder exports that zip (save it in Files); Deploy imports it, resolves the target itself from the manifest, and applies it — no location picking, the destinations come from the zip.": "Un paquet est UN fichier .zip contenant un manifest.json à sa racine ainsi que les fichiers de charge utile qu'il nomme. Le Package Builder exporte ce zip (enregistrez-le dans Fichiers) ; Deploy l'importe, résout la cible à partir du manifeste et l'applique — pas de choix d'emplacement, les destinations proviennent du zip.",
        "A partial restore can affect photos and videos. Back them up first — optional, you can skip it.": "Une restauration partielle peut affecter les photos et vidéos. Sauvegardez-les d'abord — c'est facultatif, vous pouvez passer cette étape.",
        "A respring is required before a new wallpaper appears in the gallery.": "Un respring est nécessaire avant qu'un nouveau fond d'écran apparaisse dans la galerie.",
        "A signed IPA only works on the device registered in its profile.": "Un IPA signé ne fonctionne que sur l'appareil enregistré dans son profil.",
        "A snapshot is also created automatically at every Apply, containing the state that Apply just produced. The Original backup is created once, the first time MobileGestalt is read successfully.": "Un instantané est également créé automatiquement à chaque Apply, contenant l'état que Apply vient de produire. La sauvegarde Originale est créée une seule fois, la première fois que MobileGestalt est lu avec succès.",
        "A whitelisted bundle id (and its App Groups) or exact path is never locked by Lock All. Newly whitelisted targets are restored writable right away. SMZDM is whitelisted by default — its splash cache is known to crash the app when locked.": "Un identifiant de bundle sur liste blanche (et ses App Groups) ou un chemin exact n'est jamais verrouillé par Verrouiller tout. Les cibles nouvellement ajoutées à la liste blanche redeviennent modifiables immédiatement. SMZDM est sur liste blanche par défaut — son cache de splash est connu pour faire planter l'app quand il est verrouillé.",
        "AI Cache": "Cache IA",
        "APFS vault: clonefile staging, zero extra space, atomic restore with rollback. ZIP backup: the same three folders as one .zip file, restored by merging in place.": "Coffre APFS : préparation par clonefile, zéro espace supplémentaire, restauration atomique avec retour en arrière. Sauvegarde ZIP : les trois mêmes dossiers dans un seul fichier .zip, restaurés par fusion sur place.",
        "About this feature": "À propos de cette fonction",
