        "All upstream projects remain under their respective licenses. WorkTweaks only repackages and extends them; full credit belongs to the original authors above.": "Tous les projets en amont restent sous leurs licences respectives. WorkTweaks ne fait que les reconditionner et les étendre ; tout le mérite revient aux auteurs originaux ci-dessus.",
