        "Apply custom card art to your Apple Wallet cards on-device. Scan for your cards, attach a skin image to each one, then flash.": "Appliquez des illustrations personnalisées à vos cartes Apple Wallet sur l'appareil. Analysez vos cartes, associez une image d'habillage à chacune, puis flashez.",
