        "Back Up Now": "Sauvegarder maintenant",
        "Back Up as ZIP": "Sauvegarder en ZIP",
        "BackUP_Data folder, inside the WorkTweaks folder (Documents). You can browse it in the Files app.": "Dossier BackUP_Data, dans le dossier WorkTweaks (Documents). Vous pouvez le parcourir dans l'app Fichiers.",
        "BackUP_Data is empty.": "BackUP_Data est vide.",
        "Backing up…": "Sauvegarde en cours…",
        "Backup": "Sauvegarde",
        "Backup Details": "Détails de la sauvegarde",
        "Backup Photos & Videos": "Sauvegarder photos et vidéos",
        "Backup Your Photos & Videos Here!": "Sauvegardez vos photos et vidéos ici !",
        "Backup and receipt saved under DeployBackups/%@ — restore it any time from Deploy History.": "Sauvegarde et reçu enregistrés sous DeployBackups/%@ — restaurez-les à tout moment depuis l'historique Deploy.",
        "Bars: %d": "Barres : %d",
        "Battery": "Batterie",
        "Battery & Thermal": "Batterie et thermique",
        "Battery & Thermal reads the system powerlog database: battery level, true health (raw max vs design capacity), cycle count, cell temperature, and thermal history. Values come from the latest samples in the log, newest first.": "Batterie et thermique lit la base de données powerlog du système : niveau de batterie, santé réelle (capacité max brute vs capacité nominale), nombre de cycles, température des cellules et historique thermique. Les valeurs proviennent des derniers échantillons du journal, du plus récent au plus ancien.",
        "Battery Percentage": "Pourcentage de batterie",
        "Before anything is written, every file that already exists is backed up (see Deploy History). Existing files are then replaced in place; new files are created.": "Avant toute écriture, chaque fichier existant est sauvegardé (voir l'historique Deploy). Les fichiers existants sont ensuite remplacés sur place ; les nouveaux fichiers sont créés.",
        "Blocked — pairing / VPN not ready": "Bloqué — jumelage / VPN non prêt",
        "Both need a pairing file first: Sandbox → Utilities → Get Pairing File. A loopback VPN (Local Dev VPN) is strongly recommended while flashing.": "Les deux nécessitent d'abord un fichier de jumelage : Sandbox → Utilities → Get Pairing File. Un VPN de bouclage (Local Dev VPN) est fortement recommandé pendant le flash.",
        "Browse Files": "Parcourir les fichiers",
        "Build": "Build",
        "Build & Install Wallpaper": "Créer et installer le fond d'écran",
        "Building still wallpaper…": "Création du fond d'écran fixe…",
        "Builds a PosterBoard wallpaper on-device from your photo or video — the same descriptor format as an imported .tendies package, installed and listed exactly like one.": "Crée un fond d'écran PosterBoard sur l'appareil à partir de votre photo ou vidéo — le même format de descripteur qu'un paquet .tendies importé, installé et répertorié exactement comme tel.",
        "Built on the worse_query core system by ForceQuit OS, with CacheExtra key knowledge from mond by rooootdev (AGPL-3.0).": "Basé sur le système central worse_query de ForceQuit OS, avec la connaissance des clés CacheExtra de mond par rooootdev (AGPL-3.0).",
        "Bundle ID": "Identifiant de bundle",
        "Bundle ID to whitelist": "Identifiant de bundle à mettre sur liste blanche",
