        "Cache Data Cleaner": "Nettoyeur de données de cache",
        "Cache Locations": "Emplacements du cache",
        "Cache lives in two places inside an app's data container: Library/Caches and tmp. Only the contents of those two folders are deleted — the folders themselves stay, and Documents and the rest of Library are never touched.": "Le cache se trouve à deux endroits dans le conteneur de données d'une app : Library/Caches et tmp. Seul le contenu de ces deux dossiers est supprimé — les dossiers eux-mêmes restent, et Documents ainsi que le reste de Library ne sont jamais touchés.",
