        "Connect your iPhone by USB, then sign in with your Apple ID in iLoader.": "Connectez votre iPhone en USB, puis connectez-vous avec votre identifiant Apple dans iLoader.",
        "Connect your iPhone to power, connect to Wi-Fi, and leave the Settings → General → iPhone Storage tab open for about 1 hour while the model downloads.": "Branchez votre iPhone sur secteur, connectez-vous au Wi-Fi et laissez l'onglet Réglages → Général → Stockage iPhone ouvert pendant environ 1 heure pendant le téléchargement du modèle.",
