        "Disable Dynamic Island": "Désactiver Dynamic Island",
        "Disable Dynamic Island System": "Désactiver le système Dynamic Island",
        "Disables the Dynamic Island system completely — not just hiding it. Key: SBSuppressDynamicIslandCompletely in the managed com.apple.springboard.plist (set = 1).": "Désactive complètement le système Dynamic Island — pas seulement sa dissimulation. Clé : SBSuppressDynamicIslandCompletely dans le fichier com.apple.springboard.plist géré (définie = 1).",
        "Do not reboot! Your MobileGestalt.plist seems to be %@.": "Ne redémarrez pas ! Votre MobileGestalt.plist semble être %@.",
        "Done": "Terminé",
        "Download the WorkTweaks IPA from GitHub.": "Téléchargez l'IPA WorkTweaks depuis GitHub.",
        "Download the latest WorkTweaks IPA from the GitHub Releases page.": "Téléchargez le dernier IPA WorkTweaks depuis la page GitHub Releases.",
        "Drag to move, pinch to zoom. The skin is saved at 1536×969.": "Glissez pour déplacer, pincez pour zoomer. L'habillage est enregistré en 1536×969.",
        "Dual SIM: primary is the line used for data, secondary is the other line.": "Double SIM : la ligne principale est celle utilisée pour les données, la secondaire est l'autre ligne.",
        "Dynamic Island": "Dynamic Island",
        "Each wallpaper in the package is copied into PosterBoard's data store under a fresh identifier, so it can never clash with an existing wallpaper. A respring is required before a new wallpaper appears in the gallery.": "Chaque fond d'écran du paquet est copié dans le magasin de données de PosterBoard sous un nouvel identifiant, pour ne jamais entrer en conflit avec un fond d'écran existant. Un respring est nécessaire avant qu'un nouveau fond d'écran apparaisse dans la galerie.",
        "Edit": "Modifier",
        "Edit Bytes": "Modifier les octets",
        "Edit Cell": "Modifier la cellule",
        "Edit Package": "Modifier le paquet",
        "Edit Value": "Modifier la valeur",
        "Edit in Theme Creator": "Modifier dans le créateur de thèmes",
        "Edits replace byte values only — the file's length never changes. A backup of the original is saved before the first edit.": "Les modifications remplacent uniquement les valeurs des octets — la longueur du fichier ne change jamais. Une sauvegarde de l'original est enregistrée avant la première modification.",
        "Elements": "Éléments",
        "Eligibility": "Éligibilité",
        "Empty": "Vide",
        "Enter this PIN in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks.": "Saisissez ce code PIN dans Réglages › Confidentialité et sécurité › Mode développeur › Jumeler avec WorkTweaks.",
        "Enumerating containers with pathleak — this can take a while.": "Énumération des conteneurs avec pathleak — cela peut prendre un moment.",
        "Enumeration": "Énumération",
        "Error -1 means the signed app cannot access its App Group container. Diagnostics reads the groups from your signed provisioning profile and probes them all. If it reports no signed groups, the IPA was signed without an App Group and must be re-signed with one — no name typed here can fix that.": "L'erreur -1 signifie que l'app signée ne peut pas accéder à son conteneur App Group. Le diagnostic lit les groupes de votre profil de provisionnement signé et les sonde tous. S'il ne signale aucun groupe signé, l'IPA a été signé sans App Group et doit être re-signé avec un — aucun nom saisi ici ne peut corriger cela.",
        "Escape": "Échappement",
        "Every menu that was applied, newest first. This is a history log — clearing it only clears the list, it does not undo anything.": "Chaque menu appliqué, du plus récent au plus ancien. C'est un journal d'historique — l'effacer ne fait qu'effacer la liste, cela n'annule rien.",
        "Exact path": "Chemin exact",
        "Expired %@ — reinstall the app first.": "Expiré %@ — réinstallez d'abord l'app.",
        "Expires soon — %@. Stage now, reinstall before it ends.": "Expire bientôt — %@. Préparez maintenant, réinstallez avant l'expiration.",
        "Export": "Exporter",
        "Export Selected (%d)": "Exporter la sélection (%d)",
        "Export ZIP": "Exporter en ZIP",
        "Export the signed IPA and install it with ESign (or any IPA installer).": "Exportez l'IPA signé et installez-le avec ESign (ou tout autre installateur d'IPA).",
        "Exported as .m4a files with their original titles, zipped to this app's Documents/VoiceMemosExports. The recordings database is only ever read — never written.": "Exportés en fichiers .m4a avec leurs titres d'origine, compressés dans Documents/VoiceMemosExports de cette app. La base de données des enregistrements est seulement lue — jamais écrite.",
        "Exporting…": "Exportation en cours…",
        "Extra": "Extra",
        "Fake-Supervision Residue": "Résidu de fausse supervision",
        "Fast mode selected: only targets %@ with %@.": "Mode rapide sélectionné : cible uniquement %@ avec %@.",
