        "Filename": "Nom de fichier",
        "Files & Sharing": "Fichiers et partage",
        "Files (%d)": "Fichiers (%d)",
        "Files in ConfigurationProfiles": "Fichiers dans ConfigurationProfiles",
        "Files in theme": "Fichiers du thème",
