        "Flash": "Flasher",
        "Flash & Language Target": "Cible de flash et de langue",
        "Flash Log (%d lines)": "Journal de flash (%d lignes)",
        "Flash Selected Cards": "Flasher les cartes sélectionnées",
        "Flash Theme to iPhone": "Flasher le thème sur l'iPhone",
        "Flashing Theme…": "Flash du thème en cours…",
        "Flashing needs a pairing file and the VPN tunnel. Pair first and connect the VPN in Sandbox → Utilities → Get Pairing File + VPN Status, then come back here.": "Le flash nécessite un fichier de jumelage et le tunnel VPN. Jumelez d'abord et connectez le VPN dans Sandbox → Utilities → Get Pairing File + VPN Status, puis revenez ici.",
        "Flashing needs a pairing file. Pair this iPhone first in Sandbox → Utilities → Get Pairing File.": "Le flash nécessite un fichier de jumelage. Jumelez d'abord cet iPhone dans Sandbox → Utilities → Get Pairing File.",
        "Flashing needs the VPN tunnel. Open the Local Dev VPN app and connect first.": "Le flash nécessite le tunnel VPN. Ouvrez l'app Local Dev VPN et connectez-vous d'abord.",
        "Flashing…": "Flash en cours…",
        "Folder name": "Nom du dossier",
        "Follow for updates, demos and new tweaks.": "Suivez-nous pour les mises à jour, les démos et les nouveaux tweaks.",
        "Font Weight / Style": "Graisse / style de police",
        "Footnote": "Note de bas de page",
        "Footnote Updated": "Note mise à jour",
        "Footnote text": "Texte de la note",
        "For AppGroup scope, the target is the App Group identifier (for example group.com.example) — type it here.": "Pour la portée AppGroup, la cible est l'identifiant de l'App Group (par exemple group.com.example) — saisissez-le ici.",
        "Force-close the Wallet app from the App Switcher after flashing to see the new card art.": "Forcez la fermeture de l'app Cartes depuis le sélecteur d'app après le flash pour voir la nouvelle illustration de carte.",
        "Forces the label shown (5G, 5G+, 5G UC, LTE, …). Limited — the label is display-only.": "Force le libellé affiché (5G, 5G+, 5G UC, LTE, …). Limité — le libellé est affiché uniquement.",
        "Free Apple ID installs expire after about 7 days — reinstall with iLoader to renew.": "Les installations avec un identifiant Apple gratuit expirent après environ 7 jours — réinstallez avec iLoader pour renouveler.",
        "Freed %@": "%@ libéré(s)",
