        "Get Pairing + VPN Tunnel": "Obtenir le jumelage + tunnel VPN",
        "Get Pairing File": "Obtenir le fichier de jumelage",
        "Get Pairing File + Local Dev VPN tunnel — the on-device pairing Airlift uses to reach the device.": "Fichier de jumelage + tunnel Local Dev VPN — le jumelage sur l'appareil qu'Airlift utilise pour atteindre l'appareil.",
        "Get Pairing File + VPN Status": "Fichier de jumelage + état du VPN",
        "Get Started": "Commencer",
        "Go to Sandbox Tab": "Aller à l'onglet Sandbox",
        "Go to the Apply/Revert section and tap Apply, then Respring. When the respring finishes, restart your iPhone.": "Allez à la section Appliquer/Annuler et touchez Appliquer, puis Respring. Une fois le respring terminé, redémarrez votre iPhone.",
        "Go to the Sandbox tab and turn on Start Tweaks Feature to unlock the Tweaks tab.": "Allez dans l'onglet Sandbox et activez Start Tweaks Feature pour déverrouiller l'onglet Tweaks.",
