        "History": "Historique",
        "ISO date (e.g. 2026-11-24T15:30:00Z) or yyyy-MM-dd HH:mm:ss.": "Date ISO (p. ex. 2026-11-24T15:30:00Z) ou yyyy-MM-dd HH:mm:ss.",
        "Identifiers from the App Data container scan — the same list Deploy resolves Application targets against.": "Identifiants issus de l'analyse des conteneurs App Data — la même liste par rapport à laquelle Deploy résout les cibles Application.",
        "Idle": "Inactif",
        "If iOS asks, enable Developer Mode (Settings → Privacy & Security → Developer Mode) and trust the developer profile.": "Si iOS le demande, activez le mode développeur (Réglages → Confidentialité et sécurité → Mode développeur) et faites confiance au profil développeur.",
        "If you update or downgrade to a supported build, WorkTweaks will open normally.": "Si vous mettez à jour ou rétrogradez vers un build pris en charge, WorkTweaks s'ouvrira normalement.",
        "Import": "Importer",
        "Import .tendies Package…": "Importer un paquet .tendies…",
        "Import Failed": "Importation échouée",
        "Import Package…": "Importer un paquet…",
        "Import Pairing File": "Importer un fichier de jumelage",
        "Import ZIP Backup…": "Importer une sauvegarde ZIP…",
        "Imported": "Importé",
        "In the Tweaks tab, Apple Intelligence section, turn on Apple Intelligence and Siri AI Cache Patch. The cache patch is the Filza line-104 edit (one CacheData byte, 0x00 to 0x02) — done here, no Filza needed.": "Dans l'onglet Tweaks, section Apple Intelligence, activez Apple Intelligence et Siri AI Cache Patch. Le correctif de cache est la modification de ligne 104 dans Filza (un octet CacheData, de 0x00 à 0x02) — faite ici, sans Filza.",
        "Individual Keys": "Clés individuelles",
        "Install tab → Provisioning: fill in the fields below, tap Provision, and wait for \"profile OK\". Your Team ID is shown in the app's Certificates tab.": "Onglet Install → Provisioning : remplissez les champs ci-dessous, touchez Provision, et attendez « profile OK ». Votre Team ID s'affiche dans l'onglet Certificates de l'app.",
        "Installation": "Installation",
        "Installed Profiles": "Profils installés",
        "Installed any other way, the signed profile leaves the App Group out — and without it, the tweaks can't run. Tap Tutorials below for both step-by-step guides.": "Installée autrement, le profil signé omet l'App Group — et sans lui, les tweaks ne peuvent pas fonctionner. Touchez Tutorials ci-dessous pour les deux guides pas à pas.",
        "Installing into PosterBoard…": "Installation dans PosterBoard…",
        "Internal": "Interne",
        "Jetsam & Crash": "Jetsam et crash",
        "Jetsam & Crash lists the reports iOS writes when it kills an app for memory (Jetsam, bug_type 298), when an app crashes (309), or on a watchdog / kernel panic (210). Open a report to see why it died, share the full file, or clean all reports to free space.": "Jetsam et crash répertorie les rapports qu'iOS écrit quand il tue une app pour cause de mémoire (Jetsam, bug_type 298), quand une app plante (309), ou lors d'un watchdog / kernel panic (210). Ouvrez un rapport pour voir pourquoi elle est morte, partagez le fichier complet, ou supprimez tous les rapports pour libérer de l'espace.",
