        "Lock Screen Preview": "Aperçu de l'écran de verrouillage",
        "Locked folders are read-only (0555) with a sentinel file inside; config files are emptied and locked (0444). A Weak Lock is a locked folder missing its sentinel — tap Harden to add it.": "Les dossiers verrouillés sont en lecture seule (0555) avec un fichier sentinelle à l'intérieur ; les fichiers de configuration sont vidés et verrouillés (0444). Un verrouillage faible est un dossier verrouillé sans sa sentinelle — touchez Renforcer pour l'ajouter.",
        "Locks every target below that still needs action. Whitelisted targets are always skipped.": "Verrouille chaque cible ci-dessous qui nécessite encore une action. Les cibles sur liste blanche sont toujours ignorées.",
