        "Name": "Nom",
        "Nested dictionaries, arrays and Data are shown read-only — the editor never rewrites a structure it cannot show.": "Les dictionnaires imbriqués, tableaux et Data s'affichent en lecture seule — l'éditeur ne réécrit jamais une structure qu'il ne peut pas afficher.",
