        "Network type": "Type de réseau",
        "Never share your certificate .p12 file with anyone — it contains your private signing key.": "Ne partagez jamais votre fichier de certificat .p12 avec qui que ce soit — il contient votre clé privée de signature.",
        "New Package": "Nouveau paquet",
        "New Row": "Nouvelle ligne",
        "New UI": "Nouvelle UI",
        "No": "Non",
        "No AI cache targets were found.": "Aucune cible de cache IA trouvée.",
        "No Cards Detected Yet": "Aucune carte détectée pour l'instant",
        "No Jailbreak": "Sans jailbreak",
        "No ad targets found yet. Tap Scan above.": "Aucune cible publicitaire trouvée pour l'instant. Touchez Analyser ci-dessus.",
        "No backed-up photos or videos yet. Use \"Backup Your Photos & Videos Here!\" first.": "Aucune photo ou vidéo sauvegardée pour l'instant. Utilisez d'abord « Backup Your Photos & Videos Here! ».",
        "No containers were found, so there is nothing to clean.": "Aucun conteneur trouvé, il n'y a donc rien à nettoyer.",
        "No deploys yet. When a package is deployed, the files it replaced are backed up here with a receipt, ready to restore.": "Aucun déploiement pour l'instant. Quand un paquet est déployé, les fichiers qu'il a remplacés sont sauvegardés ici avec un reçu, prêts à restaurer.",
        "No diagnostic reports found — nothing has been killed or crashed recently, or the reports were already cleaned.": "Aucun rapport de diagnostic trouvé — rien n'a été tué ou n'a planté récemment, ou les rapports ont déjà été nettoyés.",
        "No files yet.": "Aucun fichier pour l'instant.",
        "No installable profile records were found in this directory.": "Aucun enregistrement de profil installable trouvé dans ce répertoire.",
        "No pairing file saved yet.": "Aucun fichier de jumelage enregistré pour l'instant.",
        "No pairing file yet. Pair this iPhone first in Sandbox → Utilities → Get Pairing File — scanning and flashing need it.": "Pas encore de fichier de jumelage. Jumelez d'abord cet iPhone dans Sandbox → Utilities → Get Pairing File — l'analyse et le flash en ont besoin.",
        "No recordings were found in the Voice Memos database.": "Aucun enregistrement trouvé dans la base de données Dictaphone.",
        "No regular files found in this container.": "Aucun fichier ordinaire trouvé dans ce conteneur.",
        "No scan yet. The scan starts automatically; if it does not, open App Data once, or type the bundle ID by hand.": "Pas encore d'analyse. L'analyse démarre automatiquement ; sinon, ouvrez App Data une fois, ou saisissez l'identifiant de bundle à la main.",
        "No skin — tap Set Skin below": "Pas d'habillage — touchez Définir l'habillage ci-dessous",
        "No snapshots yet. Apply some tweaks or tap Back Up Now.": "Aucun instantané pour l'instant. Appliquez des tweaks ou touchez Sauvegarder maintenant.",
        "No stored packages yet. Build one with New Package, or import an existing .deploy / .zip / folder package to edit it here.": "Aucun paquet enregistré pour l'instant. Créez-en un avec Nouveau paquet, ou importez un paquet .deploy / .zip / dossier existant pour le modifier ici.",
        "No thermal events found in the powerlog.": "Aucun événement thermique trouvé dans le powerlog.",
        "No third-party apps found.": "Aucune app tierce trouvée.",
        "No tweaks match \"%@\".": "Aucun tweak ne correspond à « %@ ».",
        "No wallpapers imported yet. Wallpapers imported here are listed so you can remove them again — wallpapers added any other way are never touched.": "Aucun fond d'écran importé pour l'instant. Les fonds d'écran importés ici sont répertoriés pour que vous puissiez les supprimer à nouveau — les fonds d'écran ajoutés autrement ne sont jamais touchés.",
        "Nominal capacity": "Capacité nominale",
        "Not Supervised": "Non supervisé",
        "Not connected.": "Non connecté.",
        "Not loaded": "Non chargé",
        "Not measured yet": "Pas encore mesuré",
