        "Not set": "Non défini",
        "Nothing applied yet.": "Rien d'appliqué pour l'instant.",
        "Nothing staged yet.": "Rien de préparé pour l'instant.",
        "Nothing was written — the stored manifest is unchanged.": "Rien n'a été écrit — le manifeste enregistré est inchangé.",
        "Nothing was written.": "Rien n'a été écrit.",
        "Notice": "Remarque",
        "Numbers only.": "Chiffres uniquement.",
        "OK": "OK",
        "Off": "Désactivé",
        "Off in this backup": "Désactivé dans cette sauvegarde",
        "Old UI": "Ancienne UI",
        "On": "Activé",
        "On a computer, download iLoader from iloader.app — the official site only — and open it.": "Sur un ordinateur, téléchargez iLoader depuis iloader.app — le site officiel uniquement — puis ouvrez-le.",
        "On in this backup": "Activé dans cette sauvegarde",
        "One of the destination paths is invalid.": "L'un des chemins de destination est invalide.",
        "Only files under Library/Caches inside the listed targets are deleted. AI models are never touched, and caches regenerate when the apps run again.": "Seuls les fichiers sous Library/Caches dans les cibles répertoriées sont supprimés. Les modèles IA ne sont jamais touchés, et les caches se régénèrent quand les apps tournent à nouveau.",
        "Only spoof your device model if you want to download Apple Intelligence. This may break Face ID. If you decide to unspoof and want to keep Apple Intelligence, do NOT re-enter the Apple Intelligence & Siri menu in Settings.": "N'usurpez votre modèle d'appareil que si vous voulez télécharger Apple Intelligence. Cela peut casser Face ID. Si vous décidez d'annuler l'usurpation et de garder Apple Intelligence, ne rouvrez PAS le menu Apple Intelligence et Siri dans Réglages.",
        "Only the listed .ips / .crash / .panic files under DiagnosticReports (and Retired) are ever deleted. The folders themselves are kept, and nothing else is touched.": "Seuls les fichiers .ips / .crash / .panic répertoriés sous DiagnosticReports (et Retired) sont supprimés. Les dossiers eux-mêmes sont conservés, et rien d'autre n'est touché.",
        "Open App Data first so the container scan runs, then come back — or tap Rescan.": "Ouvrez d'abord App Data pour que l'analyse des conteneurs s'exécute, puis revenez — ou touchez Analyser à nouveau.",
        "Open Settings → Apple Intelligence & Siri and tap Join Waitlist. Wait about 15 minutes for it to be accepted.": "Ouvrez Réglages → Apple Intelligence et Siri et touchez Rejoindre la liste d'attente. Attendez environ 15 minutes pour que la demande soit acceptée.",
        "Open Signed Apps and sign in with your Apple ID.": "Ouvrez Signed Apps et connectez-vous avec votre identifiant Apple.",
        "Open Source": "Open Source",
        "Open Tutorials": "Ouvrir les tutoriels",
        "Open WorkTweaks and you're done.": "Ouvrez WorkTweaks et c'est terminé.",
        "Open as Property List": "Ouvrir comme liste de propriétés",
        "Open as SQLite Database": "Ouvrir comme base de données SQLite",
        "Open the Local Dev VPN app and connect. The tunnel shows as a utun interface on 10.7.x.x (gateway 10.7.0.1).": "Ouvrez l'app Local Dev VPN et connectez-vous. Le tunnel apparaît comme une interface utun sur 10.7.x.x (passerelle 10.7.0.1).",
        "Opening the configuration profiles…": "Ouverture des profils de configuration…",
        "Opening the database…": "Ouverture de la base de données…",
        "Opens an empty editor; the file is created when you save.": "Ouvre un éditeur vide ; le fichier est créé lors de l'enregistrement.",
        "Opens the database as editable tables, with a backup taken before the first save. Close the owning app before editing.": "Ouvre la base de données sous forme de tables modifiables, avec une sauvegarde effectuée avant le premier enregistrement. Fermez l'app propriétaire avant de modifier.",
        "Opens the property list as an editable key/type/value table, with a backup taken before the first save.": "Ouvre la liste de propriétés sous forme de tableau clé/type/valeur modifiable, avec une sauvegarde effectuée avant le premier enregistrement.",
        "Optional label": "Libellé facultatif",
        "Organization: %@": "Organisation : %@",
        "Original": "Original",
        "Original (%d)": "Original (%d)",
        "PIN": "Code PIN",
        "Package": "Paquet",
        "Package Builder": "Créateur de paquets",
        "Package Format": "Format de paquet",
        "Packages you build or import are stored on this device, in WorkTweaks' own container. Tap a package to edit it. Deploy runs it through the same preview, resolve and backup flow as a picked package.": "Les paquets que vous créez ou importez sont stockés sur cet appareil, dans le conteneur propre à WorkTweaks. Touchez un paquet pour le modifier. Deploy l'exécute via le même flux d'aperçu, de résolution et de sauvegarde qu'un paquet choisi.",
        "Pair This iPhone": "Jumeler cet iPhone",
        "Pairing & Airlift": "Jumelage et Airlift",
        "Pairing cancelled.": "Jumelage annulé.",
        "Pairing file": "Fichier de jumelage",
        "Pairing file imported.": "Fichier de jumelage importé.",
        "Pairing file removed.": "Fichier de jumelage supprimé.",
        "Pairing file saved to the app.": "Fichier de jumelage enregistré dans l'app.",
        "Parsed from the .plist files in the ConfigurationProfiles directory. This page never installs or removes a profile.": "Analysé à partir des fichiers .plist du répertoire ConfigurationProfiles. Cette page n'installe ni ne supprime jamais de profil.",
        "Partial — some icons may still show. Hidden through the archive's suppressed identifiers.": "Partiel — certaines icônes peuvent encore s'afficher. Masquées via les identifiants supprimés de l'archive.",
        "Partially Supported": "Partiellement pris en charge",
        "Partially Supported iOS • %@": "iOS partiellement pris en charge • %@",
        "Passcode Theme": "Thème de code",
        "Passcode Themes": "Thèmes de code",
        "Passcode theme applied": "Thème de code appliqué",
        "Paste card hash": "Coller le hash de carte",
        "Path Enumeration": "Énumération des chemins",
        "Paths must be relative, non-empty and contain no \"..\" component.": "Les chemins doivent être relatifs, non vides et ne contenir aucun composant « .. ».",
        "Payload files are copied into the package. Add File accepts any file — a .plist is added as a payload, and a .zip is unpacked, each file inside becoming a payload with its destination defaulting to its path inside the archive. Destinations are relative paths only; absolute paths and \"..\" are rejected, exactly like an imported package.": "Les fichiers de charge utile sont copiés dans le paquet. Ajouter un fichier accepte n'importe quel fichier — un .plist est ajouté comme charge utile, et un .zip est décompressé, chaque fichier qu'il contient devenant une charge utile dont la destination correspond par défaut à son chemin dans l'archive. Les destinations sont des chemins relatifs uniquement ; les chemins absolus et « .. » sont rejetés, exactement comme pour un paquet importé.",
        "Persist after reboot": "Persister après redémarrage",
        "Photo Library": "Photothèque",
        "Photo chosen — tap to change": "Photo choisie — touchez pour modifier",
        "Photos & Videos": "Photos et vidéos",
        "Pick Target App": "Choisir l'app cible",
        "Pick an app": "Choisir une app",
        "Pick an app to see its cache and clean it.": "Choisissez une app pour voir son cache et le nettoyer.",
        "Pick from App Data scan…": "Choisir depuis l'analyse App Data…",
        "Pick the WorkTweaks IPA, set the Signing Bundle ID field to the same identifier, then tap Sign IPA.": "Choisissez l'IPA WorkTweaks, définissez le champ Signing Bundle ID sur le même identifiant, puis touchez Sign IPA.",
        "Pick the photos and videos you want to keep, then Save. They are copied into the BackUP_Data folder inside the app. Optional — you can skip this.": "Choisissez les photos et vidéos à conserver, puis Enregistrer. Elles sont copiées dans le dossier BackUP_Data à l'intérieur de l'app. Facultatif — vous pouvez passer cette étape.",
        "Plays a soft sound when you tap menus and features. Respects the silent switch.": "Joue un son doux quand vous touchez les menus et les fonctions. Respecte le commutateur silencieux.",
        "Please Install It the Right Way": "Veuillez l'installer de la bonne façon",
