        "Probe Again": "Sondez à nouveau",
        "Probing cache sizes…": "Sondage des tailles de cache…",
        "Raw max capacity": "Capacité max brute",
        "Read": "Lire",
        "Read Powerlog": "Lire le powerlog",
        "Read complete%@%@.": "Lecture terminée%@%@.",
        "Read-only mode — the grant did not include write access, so Clean All is disabled.": "Mode lecture seule — l'autorisation n'incluait pas l'accès en écriture, donc Tout nettoyer est désactivé.",
        "Read-only: the powerlog is cloned into this app's temp folder and inspected there. Nothing is ever written to the system database. Some iOS 26 firmware restricts the powerlog sandbox token; iOS 27 reads fully.": "Lecture seule : le powerlog est cloné dans le dossier temporaire de cette app et inspecté là. Rien n'est jamais écrit dans la base de données système. Certains firmwares iOS 26 limitent le jeton sandbox du powerlog ; iOS 27 lit intégralement.",
        "Reading the configuration profiles…": "Lecture des profils de configuration…",
        "Reading the property list…": "Lecture de la liste de propriétés…",
        "Reading the recordings database…": "Lecture de la base de données des enregistrements…",
        "Reading video frames…": "Lecture des images vidéo…",
        "Reading…": "Lecture en cours…",
        "Rebooting now might cause a bootloop. Try pressing 'Revert Tweaks'.": "Redémarrer maintenant pourrait provoquer un bootloop. Essayez de toucher « Revert Tweaks ».",
        "Recent Requests": "Requêtes récentes",
        "Recent samples (%d)": "Échantillons récents (%d)",
        "Reference": "Référence",
        "Reference & Patch Files": "Fichiers de référence et correctifs",
        "Reference — APFS save-vault idea (clonefile staging, atomic swap with rollback).": "Référence — idée de coffre de sauvegarde APFS (préparation par clonefile, échange atomique avec retour en arrière).",
        "Reference — PosterBoard wallpaper format the maker was verified against.": "Référence — format de fond d'écran PosterBoard par rapport auquel le créateur a été vérifié.",
        "Reference — Splash Ad Cache Lock mechanism (ad SDK cache lock, save vault, diagnostics, Wi-Fi file sharing, Voice Memos export, AI cache probes).": "Référence — mécanisme Splash Ad Cache Lock (verrouillage du cache des SDK publicitaires, coffre de sauvegarde, diagnostics, partage de fichiers Wi-Fi, export Dictaphone, sondes de cache IA).",
        "Reference — cache data cleaner": "Référence — nettoyeur de données de cache",
        "Reference — turn on new Siri AI (CacheData line edit + device spoof)": "Référence — activer le nouvel IA Siri (modification de ligne CacheData + usurpation d'appareil)",
        "Reference — video-to-wallpaper (CAML) builder used by the PosterBoard wallpaper maker.": "Référence — constructeur vidéo-vers-fond d'écran (CAML) utilisé par le créateur de fonds d'écran PosterBoard.",
