        "Respring": "Respring",
        "Respring did not trigger on this device.": "Le respring ne s'est pas déclenché sur cet appareil.",
        "Restart Device": "Redémarrer l'appareil",
        "Restart Required": "Redémarrage requis",
        "Restore": "Restaurer",
        "Restore (%d)": "Restaurer (%d)",
        "Restore Backup": "Restaurer la sauvegarde",
        "Restore Everything": "Tout restaurer",
        "Restore Result — %d succeeded, %d failed": "Résultat de la restauration — %d réussie(s), %d échouée(s)",
        "Restore a ZIP backup": "Restaurer une sauvegarde ZIP",
        "Restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "Les restaurations ne prennent effet qu'après un redémarrage complet de l'appareil — un respring ne suffit pas. Choisir Plus tard ne fait que reporter ; les modifications restent en attente jusqu'au redémarrage.",
        "Restore into…": "Restaurer dans…",
        "Restore swaps the staged copy into the app's current container and rolls back if anything fails. Release a snapshot only after you verified the restore in the app.": "La restauration échange la copie préparée dans le conteneur actuel de l'app et revient en arrière si quelque chose échoue. Ne libérez un instantané qu'après avoir vérifié la restauration dans l'app.",
        "Restore the backup?": "Restaurer la sauvegarde ?",
        "Restore this entire backup?": "Restaurer toute cette sauvegarde ?",
        "Restoring ZIP…": "Restauration du ZIP…",
        "Restoring the backup failed — the details are in the Log.": "La restauration de la sauvegarde a échoué — les détails sont dans le Log.",
        "Restoring writes each backed-up file back in place. Files the deploy created (they did not exist before) are deleted again.": "La restauration réécrit chaque fichier sauvegardé à sa place. Les fichiers créés par le déploiement (qui n'existaient pas avant) sont supprimés à nouveau.",
        "Restoring…": "Restauration en cours…",
        "Result — %d succeeded, %d failed": "Résultat — %d réussie(s), %d échouée(s)",
        "Retry Flash": "Réessayer le flash",
        "Retry Flash Theme": "Réessayer le flash du thème",
        "Revert": "Annuler",
        "Revert Tweaks": "Annuler les tweaks",
        "Revert all tweaks?": "Annuler tous les tweaks ?",
        "Revert and restore changes only take effect after a full device restart — a respring is not enough. Choosing Later just postpones it; the changes stay pending until you restart.": "Les annulations et restaurations ne prennent effet qu'après un redémarrage complet de l'appareil — un respring ne suffit pas. Choisir Plus tard ne fait que reporter ; les modifications restent en attente jusqu'au redémarrage.",
        "Rewrites the entire MobileGestalt.plist from this backup. A device restart is required after restoring.": "Réécrit l'intégralité du MobileGestalt.plist à partir de cette sauvegarde. Un redémarrage de l'appareil est requis après la restauration.",
        "Running": "En cours",
        "Sampled": "Échantillonné",
        "Sandbox access denied": "Accès Sandbox refusé",
        "Sandbox extension is ready (directory grant held).": "L'extension Sandbox est prête (autorisation de répertoire détenue).",
        "Save": "Enregistrer",
        "Save .passthm": "Enregistrer .passthm",
        "Save App Group ID": "Enregistrer l'ID App Group",
        "Save Vault": "Coffre de sauvegarde",
        "Saved": "Enregistré",
        "Saved %d of %d to BackUP_Data.": "%d sur %d enregistré(s) dans BackUP_Data.",
        "Saved: %@": "Enregistré : %@",
        "Saves the package, then shares ONE .zip file — save it in Files. Deploy imports that zip and applies it without asking for locations.": "Enregistre le paquet, puis partage UN seul fichier .zip — enregistrez-le dans Fichiers. Deploy importe ce zip et l'applique sans demander d'emplacements.",
        "Saving %d of %d (%d%%)": "Enregistrement de %d sur %d (%d%%)",
        "Saving applies the edits to the database through SQLite, takes a backup of the original first, then writes the edited file back in place. Close the owning app before saving — a running app can overwrite your edits.": "L'enregistrement applique les modifications à la base de données via SQLite, effectue d'abord une sauvegarde de l'original, puis réécrit le fichier modifié sur place. Fermez l'app propriétaire avant d'enregistrer — une app en cours d'exécution peut écraser vos modifications.",
        "Saving rebuilds the property list from this table, takes a backup of the original first, then writes it back in place. Close the owning app before saving — a running app can overwrite your edits.": "L'enregistrement reconstruit la liste de propriétés à partir de ce tableau, effectue d'abord une sauvegarde de l'original, puis la réécrit sur place. Fermez l'app propriétaire avant d'enregistrer — une app en cours d'exécution peut écraser vos modifications.",
        "Saving writes the file in place and verifies the result by re-reading it.": "L'enregistrement écrit le fichier sur place et vérifie le résultat en le relisant.",
        "Saving writes the file in place, under the container's sandbox extension.": "L'enregistrement écrit le fichier sur place, sous l'extension sandbox du conteneur.",
        "Saving…": "Enregistrement en cours…",
        "Scan": "Analyser",
        "Scan Cards": "Analyser les cartes",
        "Scan for Ad Targets": "Rechercher les cibles publicitaires",
        "Scanning %@…": "Analyse de %@…",
        "Scanning…": "Analyse en cours…",
        "Scope": "Portée",
        "Search": "Rechercher",
        "Search tweaks": "Rechercher des tweaks",
        "Secondary bars: %d": "Barres secondaires : %d",
        "Secondary carrier name (max 64)": "Nom de l'opérateur secondaire (max 64)",
        "Secondary network type": "Type de réseau secondaire",
        "Sections": "Sections",
        "Select All": "Tout sélectionner",
        "Select None": "Ne rien sélectionner",
        "Select at least one card and attach a skin image to it before flashing.": "Sélectionnez au moins une carte et associez-lui une image d'habillage avant de flasher.",
        "Selected app": "App sélectionnée",
        "Server": "Serveur",
        "Set NULL": "Définir NULL",
        "Set Skin": "Définir l'habillage",
        "Set Skin for All Cards…": "Définir l'habillage pour toutes les cartes…",
        "Set the Spoofing picker (under Apple Intelligence) to iPhone 17 Pro (iPhone18,1).": "Réglez le sélecteur Spoofing (sous Apple Intelligence) sur iPhone 17 Pro (iPhone18,1).",
        "Sets how many bars are drawn. Static — it does not follow the real signal.": "Définit le nombre de barres dessinées. Statique — il ne suit pas le signal réel.",
        "Share %@": "Partager %@",
        "Share Contents": "Partager le contenu",
        "Share Full Report": "Partager le rapport complet",
        "Showing the first %@ of %@ rows — the editor is for targeted edits, not bulk dumps.": "Affichage des %@ premières lignes sur %@ — l'éditeur sert aux modifications ciblées, pas aux exports en masse.",
        "Shows the battery percentage in the status bar. Key: SBShowBatteryPercentage in com.apple.springboard.plist.": "Affiche le pourcentage de batterie dans la barre d'état. Clé : SBShowBatteryPercentage dans com.apple.springboard.plist.",
        "Sign In": "Se connecter",
        "Signal Bars": "Barres de signal",
        "Signal bars (Primary)": "Barres de signal (principales)",
        "Signal bars (Secondary)": "Barres de signal (secondaires)",
        "Single-file shorthand: instead of \"files\", give \"relativePath\" and \"file\". \"scope\" is Application (bundleID = the app's bundle ID), AppGroup (bundleID = the group identifier, e.g. group.com.example) or InternalDaemon. ZIP archives may use stored or deflated entries; encrypted and ZIP64 archives are not supported. Older .deploy archives and plain folders still import.": "Raccourci mono-fichier : au lieu de « files », indiquez « relativePath » et « file ». « scope » vaut Application (bundleID = l'identifiant de bundle de l'app), AppGroup (bundleID = l'identifiant du groupe, p. ex. group.com.example) ou InternalDaemon. Les archives ZIP peuvent utiliser des entrées stockées ou déflatées ; les archives chiffrées et ZIP64 ne sont pas prises en charge. Les anciennes archives .deploy et les dossiers simples s'importent toujours.",
        "Size": "Taille",
        "Sizes are measured by walking each folder. An app recreates cache as it runs, so the size grows back over time.": "Les tailles sont mesurées en parcourant chaque dossier. Une app recrée du cache en fonctionnant, donc la taille augmente à nouveau avec le temps.",
        "Sizes are probed read-only (depth 4). Delete Cache removes only files under Library/Caches inside these targets — the AI models live elsewhere and are never touched.": "Les tailles sont sondées en lecture seule (profondeur 4). Supprimer le cache ne retire que les fichiers sous Library/Caches dans ces cibles — les modèles IA se trouvent ailleurs et ne sont jamais touchés.",
        "Snapshots": "Instantanés",
        "Software-Oriented Features": "Fonctions orientées logiciel",
        "Some tweaks — especially Apple Intelligence — only take effect after a full restart, not a respring.": "Certains tweaks — en particulier Apple Intelligence — ne prennent effet qu'après un redémarrage complet, pas un respring.",
        "Something went wrong": "Quelque chose s'est mal passé",
        "Sound Effects": "Effets sonores",
        "Splash Ad Cache Lock": "Splash Ad Cache Lock",
        "Splash Ad Cache Lock finds the folders ad SDKs use to cache splash (launch) ads, empties them, and locks them read-only so the app cannot rebuild its splash-ad cache. Locks apply only to third-party app folders — never to system folders, Documents, or the app itself.": "Splash Ad Cache Lock trouve les dossiers que les SDK publicitaires utilisent pour mettre en cache les publicités de lancement (splash), les vide et les verrouille en lecture seule pour que l'app ne puisse pas reconstruire son cache de publicités splash. Les verrous s'appliquent uniquement aux dossiers d'apps tierces — jamais aux dossiers système, à Documents ou à l'app elle-même.",
        "Spoofing": "Usurpation",
        "SpringBoard loads the wallpaper store when it starts — respring or restart to see the change in the wallpaper gallery.": "SpringBoard charge le magasin de fonds d'écran au démarrage — faites un respring ou redémarrez pour voir le changement dans la galerie de fonds d'écran.",
        "SpringBoard reads the footnote when it starts — respring or restart to see it on the Lock Screen.": "SpringBoard lit la note au démarrage — faites un respring ou redémarrez pour la voir sur l'écran de verrouillage.",
        "Stage an app's Documents, Library/Preferences and Library/Application Support (never Caches) before its 7-day certificate expires. After reinstall, the data is restored into the app's new container — matched by bundle id, not the old container UUID.": "Préparez les Documents, Library/Preferences et Library/Application Support d'une app (jamais Caches) avant l'expiration de son certificat de 7 jours. Après la réinstallation, les données sont restaurées dans le nouveau conteneur de l'app — appariées par identifiant de bundle, et non par l'ancien UUID de conteneur.",
        "Stage copies into the APFS vault (no extra space). ZIP backup copies first, then zips — for very large apps use the APFS vault. Both refuse while the app is still writing its database.": "La préparation copie dans le coffre APFS (sans espace supplémentaire). La sauvegarde ZIP copie d'abord, puis compresse — pour les très grosses apps, utilisez le coffre APFS. Les deux refusent tant que l'app écrit encore dans sa base de données.",
        "Stage into APFS Vault": "Préparer dans le coffre APFS",
        "Staged %@: %d file(s), %@. Verified against the source.": "Préparé %@ : %d fichier(s), %@. Vérifié par rapport à la source.",
        "Staged snapshots": "Instantanés préparés",
        "Staging…": "Préparation en cours…",
        "Start Server": "Démarrer le serveur",
        "Start Tweaks Feature": "Activer la fonction Tweaks",
        "Start the server to get its address.": "Démarrez le serveur pour obtenir son adresse.",
        "Still writing (%d active WAL file(s)) — close the app first": "Écriture toujours en cours (%d fichier(s) WAL actif(s)) — fermez d'abord l'app",
        "Stop Scan": "Arrêter l'analyse",
        "Stop Server": "Arrêter le serveur",
        "Stopped": "Arrêté",
        "Stored as text.": "Enregistré sous forme de texte.",
        "Subtype": "Sous-type",
        "Supervision": "Supervision",
        "Support": "Assistance",
        "Supported": "Pris en charge",
        "Supported iOS Versions": "Versions iOS prises en charge",
        "Supported iOS • %@": "iOS pris en charge • %@",
        "Swift implementation of the respring web view (via mond / jailbreak.party).": "Implémentation Swift de la vue web de respring (via mond / jailbreak.party).",
        "System": "Système",
        "System Caches": "Caches système",
        "System Language": "Langue du système",
        "Table": "Table",
        "Tap Read Powerlog to load the latest battery samples.": "Touchez Lire le powerlog pour charger les derniers échantillons de batterie.",
        "Tap Refresh to list the diagnostic reports.": "Touchez Actualiser pour répertorier les rapports de diagnostic.",
        "Tap a key to assign a custom image.": "Touchez une clé pour attribuer une image personnalisée.",
        "Target": "Cible",
        "Target Path": "Chemin cible",
        "Target container": "Conteneur cible",
        "That file is not a pairing file.": "Ce fichier n'est pas un fichier de jumelage.",
        "The App Data scan is still running — ad targets appear once it finishes.": "L'analyse App Data est toujours en cours — les cibles publicitaires apparaissent une fois terminée.",
        "The CacheExtra key knowledge — the tweak-key research the WorkTweaks tweak catalog is built on.": "La connaissance des clés CacheExtra — la recherche sur les clés de tweaks sur laquelle repose le catalogue de tweaks de WorkTweaks.",
        "The Voice Memos container is found through the App Data scan.": "Le conteneur Dictaphone est trouvé via l'analyse App Data.",
        "The ZIP must be a Save Vault backup (it carries a BackupManifest.plist). Files merge in place; system bundle ids are blocked.": "Le ZIP doit être une sauvegarde Save Vault (il contient un BackupManifest.plist). Les fichiers fusionnent sur place ; les identifiants de bundle système sont bloqués.",
        "The backup of the original file couldn't be written, so nothing was saved.": "La sauvegarde du fichier d'origine n'a pas pu être écrite, donc rien n'a été enregistré.",
        "The browser asks for these credentials once, then remembers them for the session.": "Le navigateur demande ces identifiants une fois, puis s'en souvient pour la session.",
        "The bundle ID is not a valid identifier.": "L'identifiant de bundle n'est pas un identifiant valide.",
        "The bundle ID of the one app this package may touch. Pick it from the App Data container scan, or type it.": "L'identifiant de bundle de la seule app que ce paquet peut toucher. Choisissez-le dans l'analyse des conteneurs App Data, ou saisissez-le.",
        "The container scan found no containers.": "L'analyse des conteneurs n'a trouvé aucun conteneur.",
        "The container scan is shared with App Data and runs once per app session.": "L'analyse des conteneurs est partagée avec App Data et s'exécute une fois par session d'app.",
        "The container scan runs once per session.": "L'analyse des conteneurs s'exécute une fois par session.",
        "The core system: the sandbox escape and MobileGestalt access this whole app is built on.": "Le système central : l'échappement de sandbox et l'accès MobileGestalt sur lesquels repose toute cette app.",
        "The current MobileGestalt will be entirely replaced with this %@ backup.": "Le MobileGestalt actuel sera entièrement remplacé par cette sauvegarde %@.",
        "The current file is overwritten in place with the backup taken before the first byte edit.": "Le fichier actuel est écrasé sur place avec la sauvegarde effectuée avant la première modification d'octet.",
        "The developer's GitHub profile.": "Le profil GitHub du développeur.",
        "The directory is empty.": "Le répertoire est vide.",
        "The entry is removed from the property list on the next Save.": "L'entrée est supprimée de la liste de propriétés lors du prochain enregistrement.",
        "The file couldn't be read under the container's sandbox extension — the details are in the Log. Nothing was written to it.": "Le fichier n'a pas pu être lu sous l'extension sandbox du conteneur — les détails sont dans le Log. Rien n'y a été écrit.",
        "The file-based CacheData pattern method used by Enable iPadOS Mode (MobileGestaltCacheDataTweak).": "La méthode de motif CacheData basée sur les fichiers utilisée par Enable iPadOS Mode (MobileGestaltCacheDataTweak).",
        "The original identifiers are already registered to another developer account, which is why the Team ID suffix is required.": "Les identifiants d'origine sont déjà enregistrés sur un autre compte développeur, c'est pourquoi le suffixe Team ID est requis.",
        "The package could not be exported.": "Le paquet n'a pas pu être exporté.",
        "The package store is unavailable (the App Group container did not resolve).": "Le magasin de paquets est indisponible (le conteneur App Group n'a pas pu être résolu).",
        "The pairing file + Local Dev VPN tunnel are the transport Airlift uses to reach the device. Green = ready, gray = not ready.": "Le fichier de jumelage + le tunnel Local Dev VPN sont le transport qu'Airlift utilise pour atteindre l'appareil. Vert = prêt, gris = pas prêt.",
        "The pathleak scan reads inodes one by one — this can take a few minutes.": "L'analyse pathleak lit les inodes un par un — cela peut prendre quelques minutes.",
        "The picked file could not be copied into the package.": "Le fichier choisi n'a pas pu être copié dans le paquet.",
        "The row is deleted from the database on the next Save.": "La ligne est supprimée de la base de données lors du prochain enregistrement.",
        "The sandbox extension for this container's directory was refused — the result code is in the Log.": "L'extension sandbox pour le répertoire de ce conteneur a été refusée — le code de résultat est dans le Log.",
        "The scan of %@ found no containers. The scan's baseline and counts are in the Log.": "L'analyse de %@ n'a trouvé aucun conteneur. La base de référence et les nombres de l'analyse sont dans le Log.",
        "The server shares this app's Documents folder only — SaveVaultBackups, staged vaults and uploads. Nothing outside it is ever served. Keep this page open while transferring: the server stops when you leave the page or the app goes to the background.": "Le serveur partage uniquement le dossier Documents de cette app — SaveVaultBackups, coffres préparés et téléversements. Rien en dehors n'est jamais servi. Gardez cette page ouverte pendant le transfert : le serveur s'arrête quand vous quittez la page ou que l'app passe en arrière-plan.",
        "The staging vault lives in this app's Documents and does NOT survive uninstalling WorkTweaks. Verify a restore in the app first, then release the vault.": "Le coffre de préparation se trouve dans les Documents de cette app et ne survit PAS à la désinstallation de WorkTweaks. Vérifiez d'abord une restauration dans l'app, puis libérez le coffre.",
        "The stored package is removed. Files it already deployed, and its Deploy History receipts, are not touched.": "Le paquet enregistré est supprimé. Les fichiers qu'il a déjà déployés, ainsi que ses reçus d'historique Deploy, ne sont pas touchés.",
        "Theme Information": "Informations sur le thème",
        "Thermal history (%d)": "Historique thermique (%d)",
        "These are the photos and videos in the BackUP_Data folder. Select the ones to restore, then Restore opens the share sheet — tap Save to Photos there.": "Voici les photos et vidéos du dossier BackUP_Data. Sélectionnez celles à restaurer, puis Restaurer ouvre la feuille de partage — touchez Enregistrer dans Photos.",
        "This app is free software under the GNU AGPL v3 license, following the licenses of the projects above.": "Cette app est un logiciel libre sous la licence GNU AGPL v3, conformément aux licences des projets ci-dessus.",
        "This app's own repository — issues and contributions welcome.": "Le dépôt propre à cette app — problèmes et contributions bienvenus.",
        "This deletes only the listed .ips / .crash / .panic files. The folders are kept.": "Cela supprime uniquement les fichiers .ips / .crash / .panic répertoriés. Les dossiers sont conservés.",
        "This device right now": "Cet appareil, maintenant",
        "This file isn't UTF-8 text, so it can't be edited as text. It can be edited byte-by-byte in the hex editor below.": "Ce fichier n'est pas du texte UTF-8, il ne peut donc pas être modifié comme du texte. Il peut être modifié octet par octet dans l'éditeur hexadécimal ci-dessous.",
        "This file isn't UTF-8 text, so it can't be edited here. Nothing is ever written to it from this page.": "Ce fichier n'est pas du texte UTF-8, il ne peut donc pas être modifié ici. Rien n'y est jamais écrit depuis cette page.",
        "This iOS Version Isn't Supported": "Cette version d'iOS n'est pas prise en charge",
        "This is NOT an adblock: locking only stops ad assets landing on disk. Ads downloaded live over the network when the app opens can still appear.": "Ce n'est PAS un bloqueur de pubs : le verrouillage empêche seulement les ressources publicitaires d'atterrir sur le disque. Les pubs téléchargées en direct via le réseau quand l'app s'ouvre peuvent toujours apparaître.",
        "This is the container's system-managed metadata file. iOS doesn't allow other processes to read its contents, so it can't be opened or edited here.": "Ceci est le fichier de métadonnées géré par le système du conteneur. iOS ne permet pas à d'autres processus de lire son contenu, il ne peut donc pas être ouvert ou modifié ici.",
        "This only clears the list. It does not undo anything that was applied.": "Cela efface seulement la liste. Cela n'annule rien de ce qui a été appliqué.",
        "This only makes the Join Waitlist button appear. The Siri AI model may still refuse to download — that part is not solved by this method yet.": "Cela fait seulement apparaître le bouton Rejoindre la liste d'attente. Le modèle Siri IA peut toujours refuser de se télécharger — cette partie n'est pas encore résolue par cette méthode.",
        "This package was rejected": "Ce paquet a été rejeté",
        "This permanently deletes the contents of %@ in %@ (%@). The folders themselves stay in place.": "Cela supprime définitivement le contenu de %@ dans %@ (%@). Les dossiers eux-mêmes restent en place.",
        "This property list has no top-level entries.": "Cette liste de propriétés n'a aucune entrée de premier niveau.",
        "This removes the wallpaper imported from %@ — its descriptor folder is deleted from PosterBoard's data store.": "Cela supprime le fond d'écran importé depuis %@ — son dossier de descripteur est supprimé du magasin de données de PosterBoard.",
        "This restores the MobileGestalt backup saved on first launch (SavedGestalt.plist).": "Cela restaure la sauvegarde MobileGestalt enregistrée au premier lancement (SavedGestalt.plist).",
        "This table has no columns to edit.": "Cette table n'a aucune colonne à modifier.",
        "Total CacheExtra keys": "Nombre total de clés CacheExtra",
        "True health": "Santé réelle",
        "Try Again": "Réessayer",
        "Turn on the Charge Limit Menu toggle (Add feature section).": "Activez le commutateur Charge Limit Menu (section Add feature).",
        "Tutorials": "Tutoriels",
        "Tweaks": "Tweaks",
        "Tweaks Applied": "Tweaks appliqués",
        "Tweaks UI": "UI Tweaks",
        "Tweaks are locked": "Les tweaks sont verrouillés",
        "Two ways to get a pairing file: Pair This iPhone (iOS 27 only) shows a 6-digit PIN — approve it in Settings › Privacy & Security › Developer Mode › Pair with WorkTweaks. Or import a pairing file (.plist) from your computer manually. The pairing file is saved in the app.": "Deux façons d'obtenir un fichier de jumelage : Pair This iPhone (iOS 27 uniquement) affiche un code PIN à 6 chiffres — approuvez-le dans Réglages › Confidentialité et sécurité › Mode développeur › Jumeler avec WorkTweaks. Ou importez manuellement un fichier de jumelage (.plist) depuis votre ordinateur. Le fichier de jumelage est enregistré dans l'app.",
        "Type": "Type",
        "Type the region suffix as shown in Settings > General > About, e.g. PA/A or LL/A. It changes the Model Number suffix after Apply.": "Saisissez le suffixe de région tel qu'il apparaît dans Réglages > Général > Informations, p. ex. PA/A ou LL/A. Il modifie le suffixe du numéro de modèle après Apply.",
        "Type: %@ (%@). %@": "Type : %@ (%@). %@",
        "Type: %@. %@": "Type : %@. %@",
        "Universal mode flashes ~600 files for all languages & Bold text. Selecting a specific language (e.g. Ukrainian) speeds up flashing dramatically.": "Le mode universel flashe environ 600 fichiers pour toutes les langues et le texte en gras. Choisir une langue spécifique (p. ex. l'ukrainien) accélère considérablement le flash.",
        "Unknown time": "Heure inconnue",
        "Unlock": "Déverrouiller",
        "Unlocks the Tweaks tab. Turn this on to start using tweaks.": "Déverrouille l'onglet Tweaks. Activez ceci pour commencer à utiliser les tweaks.",
        "Unsupported": "Non pris en charge",
        "Unsupported iOS • %@": "iOS non pris en charge • %@",
        "Use Skin": "Utiliser l'habillage",
        "Username": "Nom d'utilisateur",
        "Utilities": "Utilitaires",
        "VPN Tunnel": "Tunnel VPN",
        "VPN tunnel is off. Open the Local Dev VPN app and connect — flashing needs it.": "Le tunnel VPN est désactivé. Ouvrez l'app Local Dev VPN et connectez-vous — le flash en a besoin.",
        "Valid until %@": "Valide jusqu'au %@",
        "Value": "Valeur",
        "Value: %@": "Valeur : %@",
        "Version %@": "Version %@",
        "Video": "Vidéo",
        "Video chosen (%.1f s) — tap to change": "Vidéo choisie (%.1f s) — touchez pour modifier",
        "Videos use the first 12 seconds. Photos become a single still frame.": "Les vidéos utilisent les 12 premières secondes. Les photos deviennent une seule image fixe.",
        "View Full License & Credits": "Voir la licence et les crédits complets",
        "Voice Memos": "Dictaphone",
        "Voice Memos & AI Cache": "Dictaphone et cache IA",
        "Voltage": "Tension",
        "WARNING: These tweaks can break features on your device or softbrick it if misused. After Apply you choose Respring or Restart; Revert and Backup restores require a full device restart.": "AVERTISSEMENT : ces tweaks peuvent casser des fonctions de votre appareil ou le briquer logiciellement s'ils sont mal utilisés. Après Apply, vous choisissez Respring ou Restart ; Revert et les restaurations de sauvegarde nécessitent un redémarrage complet de l'appareil.",
        "Waiting for the App Data scan…": "Attente de l'analyse App Data…",
        "Wallet Cards": "Cartes Wallet",
        "Wallpaper": "Fond d'écran",
        "Wallpaper name": "Nom du fond d'écran",
        "Warning": "Avertissement",
        "Warning: raw byte edits have no structure validation — a wrong byte can corrupt this file or the owning app's data. A backup of the original is saved before the first edit.": "Avertissement : les modifications brutes d'octets n'ont aucune validation de structure — un octet erroné peut corrompre ce fichier ou les données de l'app propriétaire. Une sauvegarde de l'original est enregistrée avant la première modification.",
        "WeChat accounts": "Comptes WeChat",
        "Welcome to WorkTweaks": "Bienvenue dans WorkTweaks",
        "What this does": "Ce que cela fait",
        "When enabled, MobileGestalt is written in-place on the same inode, which (hopefully) prevents iOS from regenerating the cache on reboot. Disable to use atomic file replacement instead.": "Quand c'est activé, MobileGestalt est écrit sur place sur le même inode, ce qui (espérons-le) empêche iOS de régénérer le cache au redémarrage. Désactivez pour utiliser le remplacement atomique de fichier à la place.",
        "Where it goes": "Où cela va",
        "Whitelist": "Liste blanche",
        "Whitelisted": "Sur liste blanche",
        "Whole numbers only.": "Nombres entiers uniquement.",
        "Wi-Fi File Sharing": "Partage de fichiers Wi-Fi",
        "WorkTweaks is free software under the GNU Affero General Public License v3.0. The core (worse_query) is GPL-3.0, but the CacheExtra key knowledge from mond and the CacheData method from Nugget are AGPL-3.0 — GPLv3 code may be combined into an AGPLv3 work, and the AGPL terms then cover the combined work as a whole.": "WorkTweaks est un logiciel libre sous la licence publique générale GNU Affero v3.0. Le cœur (worse_query) est GPL-3.0, mais la connaissance des clés CacheExtra de mond et la méthode CacheData de Nugget sont AGPL-3.0 — le code GPLv3 peut être combiné dans une œuvre AGPLv3, et les termes de l'AGPL couvrent alors l'œuvre combinée dans son ensemble.",
        "WorkTweaks must be installed with iLoader, or by signing the IPA with Signed Apps, so that its App Group works correctly.": "WorkTweaks doit être installé avec iLoader, ou en signant l'IPA avec Signed Apps, pour que son App Group fonctionne correctement.",
        "WorkTweaks only works when its App Group is part of the signing profile. Guides A and B make sure that happens — pick the one that fits you. Guide C turns on the new Siri AI.": "WorkTweaks ne fonctionne que lorsque son App Group fait partie du profil de signature. Les guides A et B s'assurent que c'est le cas — choisissez celui qui vous convient. Le guide C active le nouvel IA Siri.",
        "WorkTweaks v3.0 only opens on the builds listed above: the app checks your device's build at launch, and any other build gets the \"not supported\" screen instead of the app. On iOS 18 and iOS 26, only App Data and Airlift are supported (partial support). Developed and tested on iOS 27.0.1 (24A446).": "WorkTweaks v3.0 ne s'ouvre que sur les builds répertoriés ci-dessus : l'app vérifie le build de votre appareil au lancement, et tout autre build affiche l'écran « non pris en charge » au lieu de l'app. Sur iOS 18 et iOS 26, seuls App Data et Airlift sont pris en charge (prise en charge partielle). Développé et testé sur iOS 27.0.1 (24A446).",
        "Works on iOS 18.0 – 27.2 beta 2 (iOS 27.2 beta 3 and later patched the exploit).": "Fonctionne sur iOS 18.0 – 27.2 bêta 2 (iOS 27.2 bêta 3 et ultérieures ont corrigé l'exploit).",
        "Write Method": "Méthode d'écriture",
        "Write access available — Clean All can delete the listed reports.": "Accès en écriture disponible — Tout supprimer peut effacer les rapports répertoriés.",
        "Writes SharedDeviceConfiguration.plist in place, keeping every other key in the file. SpringBoard reads the file when it starts, so a respring or restart is needed to see the change.": "Écrit SharedDeviceConfiguration.plist sur place, en conservant toutes les autres clés du fichier. SpringBoard lit le fichier au démarrage, donc un respring ou un redémarrage est nécessaire pour voir le changement.",
        "Writing or verifying the file failed — the details are in the Log.": "L'écriture ou la vérification du fichier a échoué — les détails sont dans le Log.",
        "Writing the file failed — the details are in the Log.": "L'écriture du fichier a échoué — les détails sont dans le Log.",
        "Writing the footnote failed — the details are in the Log.": "L'écriture de la note a échoué — les détails sont dans le Log.",
        "Yes": "Oui",
        "You can add multiple hashes at once — separate them with spaces, commas, or newlines.": "Vous pouvez ajouter plusieurs hashs à la fois — séparez-les par des espaces, des virgules ou des sauts de ligne.",
        "Your All BackUP Files Here!": "Tous vos fichiers BackUP ici !",
        "Your device is running **%@**. WorkTweaks v2.0 only runs on the builds listed below, so the app can't open on this version.": "Votre appareil fonctionne sous **%@**. WorkTweaks v2.0 ne fonctionne que sur les builds répertoriés ci-dessous, l'app ne peut donc pas s'ouvrir sur cette version.",
        "ZIP backup saved: %@. Share it to Files before you uninstall anything.": "Sauvegarde ZIP enregistrée : %@. Partagez-la vers Fichiers avant de désinstaller quoi que ce soit.",
