        "24 catalog tweaks — Dynamic Island, iPadOS Mode, custom region and more.": "24 tweaks du catalogue — Dynamic Island, mode iPadOS, région personnalisée et plus.",
        "Reach system folders the sandbox normally hides.": "Atteignez les dossiers système que le sandbox masque normalement.",
        "Browse any app's container, edit files, and build portable patches.": "Parcourez le conteneur de n'importe quelle app, modifiez des fichiers et créez des correctifs portables.",
        "Make lock-screen wallpapers from your photos and videos.": "Créez des fonds d'écran de verrouillage à partir de vos photos et vidéos.",
        "Free space by cleaning app caches, safely.": "Libérez de l'espace en nettoyant les caches des apps, en toute sécurité.",
