        "View and edit the file with line numbers.": "Affichez et modifiez le fichier avec des numéros de ligne.",
        "Open Mobile Gestalt.plist": "Ouvrir Mobile Gestalt.plist",
        "Manual edit needed": "Modification manuelle nécessaire",
        "The Siri byte is flipped (0x02) — the patch is on.": "L'octet Siri est inversé (0x02) — le correctif est activé.",
        "The Siri byte is 0x00 — the patch is off.": "L'octet Siri est 0x00 — le correctif est désactivé.",
        "The patch pattern matches more than once, so the automatic patch refuses to guess — edit the Siri line by hand.": "Le motif du correctif correspond à plusieurs endroits, le correctif automatique refuse donc de deviner — modifiez la ligne Siri à la main.",
        "The patch was found, but not on line 104 — open the viewer to see its line.": "Le correctif a été trouvé, mais pas à la ligne 104 — ouvrez la visionneuse pour voir sa ligne.",
        "The patch line was not found in this file — check the Mobile Gestalt.plist viewer.": "La ligne du correctif n'a pas été trouvée dans ce fichier — vérifiez la visionneuse Mobile Gestalt.plist.",
        "CacheData is missing from MobileGestalt.": "CacheData est absent de MobileGestalt.",
        "This is the same text Filza shows for this file. CacheData is the long base64 block; its lines are 51 bytes each. The Siri line is highlighted.": "C'est le même texte que Filza affiche pour ce fichier. CacheData est le long bloc base64 ; ses lignes font 51 octets chacune. La ligne Siri est surlignée.",
        "Siri line: line %d": "Ligne Siri : ligne %d",
        "On this device the Siri line is line %d, not 104 — the guide's line number varies by device.": "Sur cet appareil, la ligne Siri est la ligne %d, et non 104 — le numéro de ligne du guide varie selon l'appareil.",
        "No matches": "Aucune correspondance",
        "%d of %d matches": "%d correspondance(s) sur %d",
        "%d matches": "%d correspondance(s)",
        "Going back discards unsaved edits.": "Revenir en arrière supprime les modifications non enregistrées.",
        "Restore the pristine backup made before the first save?": "Restaurer la sauvegarde d'origine effectuée avant le premier enregistrement ?",
        "Pristine backup restored.": "Sauvegarde d'origine restaurée.",
        "Unapplied changes in the Tweaks tab will be lost when you save here — Apply them first.": "Les modifications non appliquées dans l'onglet Tweaks seront perdues quand vous enregistrez ici — appliquez-les d'abord.",
        "Saved — the Siri patch is now %@.": "Enregistré — le correctif Siri est désormais %@.",
        "Saved — the file was written, but the Siri line does not match the patch shape.": "Enregistré — le fichier a été écrit, mais la ligne Siri ne correspond pas à la forme du correctif.",
        "A pristine backup is made before the first save, and only CacheData changes are written.": "Une sauvegarde d'origine est effectuée avant le premier enregistrement, et seules les modifications de CacheData sont écrites.",
        "Save the edited file?": "Enregistrer le fichier modifié ?",
        "MobileGestalt could not be loaded.": "MobileGestalt n'a pas pu être chargé.",
        "Reload MobileGestalt": "Recharger MobileGestalt",
        "Loading MobileGestalt.plist…": "Chargement de MobileGestalt.plist…",
        "Open \"Mobile Gestalt.plist\" in the Tweaks tab (below the Siri AI Cache Patch card), then tap \"Open with Text Editor\".": "Ouvrez « Mobile Gestalt.plist » dans l'onglet Tweaks (sous la carte Siri AI Cache Patch), puis touchez « Open with Text Editor ».",
        "Use the find field to jump to line 104 — the viewer shows the exact Siri line number for this device.": "Utilisez le champ de recherche pour aller à la ligne 104 — la visionneuse indique le numéro exact de la ligne Siri pour cet appareil.",
        "On that line, change the 30th base64 character from A to g (this flips CacheData byte 21 from 0x00 to 0x02). To turn the patch off again, change it back from g to A. Then tap Save — a pristine backup is made before the first save.": "Sur cette ligne, changez le 30e caractère base64 de A à g (cela inverse l'octet 21 de CacheData de 0x00 à 0x02). Pour désactiver à nouveau le correctif, remettez-le de g à A. Puis touchez Enregistrer — une sauvegarde d'origine est effectuée avant le premier enregistrement.",
        "Then turn on Apple Intelligence and the Charge Limit Menu toggle, set Spoofing to iPhone 17 Pro, Apply, respring and restart — Join Waitlist should appear in Settings > Apple Intelligence & Siri.": "Activez ensuite Apple Intelligence et le commutateur Charge Limit Menu, réglez Spoofing sur iPhone 17 Pro, Appliquer, respring et redémarrage — Rejoindre la liste d'attente devrait apparaître dans Réglages > Apple Intelligence et Siri.",
        "Turn on the Apple Intelligence toggle and the Charge Limit Menu toggle (Add feature section).": "Activez le commutateur Apple Intelligence et le commutateur Charge Limit Menu (section Add feature).",
        "Edit the Siri line": "Modifier la ligne Siri",
        "Change one character on the Siri line to flip the patch — you don't need to read the whole file.": "Changez un caractère sur la ligne Siri pour inverser le correctif — vous n'avez pas besoin de lire tout le fichier.",
        "View file lines": "Afficher les lignes du fichier",
        "Packages by Adnan.120hz — tap one to install it into its app, or save its zip in Files.": "Paquets par Adnan.120hz — touchez-en un pour l'installer dans son app, ou enregistrez son zip dans Fichiers.",
